P.entries["npc:lyria-du-lac"] = {n="Лірія Дю Лак",s="Лірія Дю Лак — людська наставниця воїнів у Ґолдширі в Лісі Елвінн. Усамітнившись одразу за сільською кузнею, вона муштрує бійців-новачків і веде молодих воїнів, що починають опановувати свої стійки та зброю.",h="Лірія Дю Лак — людська наставниця воїнів у Ґолдширі в Лісі Елвінн.",kw={"лірія дю лак","воїн","наставниця","ґолдшир","кузня","стійки"},ang={["class:Warrior"]="Для воїнів, щойно прибулих з Абатства Нортшира, Лірія Дю Лак — перша велика наставниця, яку ви зустрічаєте в Лісі Елвінн: вона допомагає відточити володіння стійками й тактику ближнього бою.",["faction:Alliance"]="Розташувавшись за кузнею Ґолдширу, Лірія дбає, щоб тутешні новобранці були здатні боронити серце Стормвінда від розбійників Дефіас і нападників-гнолів."},sec={{t="Наставниця воїнів Ґолдширу",b="Поки корчма «Лев'яча Гордість» у Ґолдширі гуде подорожніми, а коваль гатить по тутешніх виробах, Лірія Дю Лак тримається подвір'я за кузнею. Досвідчена у військовій дисципліні, вона служить Альянсу, навчаючи воїнів-початківців, щойно прибулих з Абатства Нортшира. Вона оцінює їхню готовність і знайомить з особливими бойовими прийомами, дбаючи, щоб ті, хто бере щит і клинок за Стормвінд, могли вистояти проти загроз, що насуваються на Ліс Елвінн."}},fp="12,231,28.500.0,30.129.0,39.154.0,33.164.0"}
P.entries["npc:ma-stonefield"] = {n="Ма Стоунфілд",s="Ма Стоунфілд — людська матріарх, що живе на Фермі Стоунфілдів у західному Лісі Елвінн. Стоячи просто перед родинною садибою поруч із Тітонькою Берніс, вона дає раду щоденним труднощам сільського життя серед сусідського суперництва й клопоту зі шкідниками.",h="Ма Стоунфілд — людська матріарх, що живе на Фермі Стоунфілдів у західному Лісі Елвінн.",kw={"ма стоунфілд","ферма стоунфілдів","принцеса","свиня","урожай","тітонька берніс"},ang={["faction:Alliance"]="Для шукачів пригод Альянсу, що досліджують Ліс Елвінн, допомога працьовитим господарям на кшталт Ма Стоунфілд береже сільськогосподарський хребет Стормвінда."},sec={{t="Клопоти садиби",b="Стоячи біля родинної хатини в південно-західному Лісі Елвінн, Ма Стоунфілд наглядає за садибою разом із «Тітонькою» Берніс Стоунфілд. Життя між сусідньою садибою Маклурів і довколишніми гарбузовими ділянками рідко буває мирним. Тутешні дикі вепри постійно загрожують родинним посівам, і жоден із них не дошкуляє так, як Принцеса — величезна призова льоха, сумнозвісна тим, що толочить поля й пожирає тяжко зароблений урожай."}},fp="13,264,18.438.0,21.166.0,31.138.0,44.163.0"}
P.entries["npc:magga"] = {n="Маґґа",s="Маґґа — орчиня, що мешкає в запорошеному поселенні Гострий Пагорб у Дуроторі. Стоячи біля жвавої таверни містечка, вона привітно зустрічає новоприбулих шукачів пригод Орди, що вибираються з Долини Випробувань.",h="Маґґа — орчиня, що мешкає в запорошеному поселенні Гострий Пагорб у Дуроторі.",kw={"маґґа","гострий пагорб","орчиня","корчма","ґроск","дуротар"},ang={["faction:Horde"]="Для нових новобранців, що лишають позаду суворі випробування Долини Випробувань, Маґґа — заспокійливе вітання в першому справжньому поселенні Дуротару."},sec={{t="Привітне обличчя в Гострому Пагорбі",b="Гострий Пагорб — перший справжній смак широкого світу для молодих орків і тролів Темного Списа, що виходять із Долини Випробувань. Маґґа, що стоїть одразу біля місцевої корчми, допомагає новоприбулим зорієнтуватися в заставі, знайомить їх із тутешніми зручностями та гостинністю Корчмаря Ґроска. Хоч вона тримається непомітно серед заклопотаних бійців і ремісників застави, саме вона допомагає скріпити маленьке поселення докупи."}},fp="5,239,30.421.0,13.156.0,46.166.0,28.145.0"}
P.entries["npc:magis-sparkmantle"] = {n="Маґіс Спаркмантл",s="Маґіс Спаркмантл — гном, наставник магів, що служить у Ґуральні Тандербрю в Хараносі. Він дає настанови й навчає заклиначів-початківців, які виходять із Долини Холодного Хребта в серце Дун Мороґу.",h="Маґіс Спаркмантл — гном, наставник магів, що служить у Ґуральні Тандербрю в Хараносі.",kw={"маґіс спаркмантл","маг","наставник","гном","ґуральня тандербрю","харанос","бінк"},ang={["class:Mage"]="Для магів Альянсу, що мандрують Дун Мороґом, Спаркмантл — важливий місцевий контакт для навчання заклять і скерування до ширших таємних мереж.",["race:Gnome"]="Гноми, вигнані з Гномреґану, часто покладаються на наставників на кшталт Спаркмантла, щоб їхні наукові й таємні традиції квітли й у житті серед дворфів."},sec={{t="Заклинач у ґуральні",b="Поки дворфи збираються в Ґуральні Тандербрю по ситний ель, Маґіс Спаркмантл забезпечує таємну присутність серед діжок і барил Хараноса. Гноми-маги часто тісно вливаються в життя своїх дворфійських союзників по всьому Дун Мороґу, і Спаркмантл — ключовий наставник для заклиначів-новачків, готових розширити теоретичне й практичне розуміння таємних мистецтв."},{t="Скеровуючи молодих чародіїв",b="Окрім навчання новачків базових заклять, Маґіс дбає, щоб перспективні учні зв'язалися з ширшими магічними колами. Коли маги переростають раннє місцеве навчання чи потребують особливих настанов, Спаркмантл скеровує їх далі — до колег на кшталт Бінк або наставників у головних осередках Альянсу."}},fp="17,224,31.369.0,25.350.0,25.132.0,37.107.0,60.222.0,40.173.0"}
P.entries["npc:magistrate-sevren"] = {n="Магістрат Севрен",s="Магістрат Севрен — головний управитель поселення Брілл у Галявинах Тірісфалю. Стоячи в ратуші, він організовує ранню оборону Відступників й скеровує прибулих звитяжців зміцнювати землі довкола Андерсіті.",h="Магістрат Севрен — головний управитель поселення Брілл у Галявинах Тірісфалю.",kw={"магістрат севрен","брілл","ратуша","відступники","андерсіті","могили","аґаманди"},ang={["faction:Horde"]="Союзники Орди, прибувши в Тірісфаль, побачать, як Севрен керує передовим упокоренням Галявин Тірісфалю від розбійників, решток Погибелі та бунтівних угруповань.",["race:Undead"]="Для щойно звільнених Відступників, що залишають Похоронний Подзвін, Магістрат Севрен — цивільне обличчя держави Сильвани; він дає вам перші великі доручення на захист батьківщини."},sec={{t="Магістрат Брілла",b="З ратуші Брілла Магістрат Севрен координує цивільну владу й стратегічні зусилля на землях одразу на північ від Андерсіті. Коли нові Відступники виходять у Галявини Тірісфалю, Севрен оцінює місцеві негаразди й висилає шукачів пригод відновлювати лад, убезпечувати зруйноване господарство та придушувати невідступні загрози, що чаяться в довколишніх пагорбах."},{t="Охорона могил",b="Головні турботи Севрена — збереження й повернення мертвих Тірісфалю. Місцеві грабіжники могил, гнилошкірі гноли й свавільна нежить порушують поховання, загрожуючи владі Сильвани Віндраннер, що лише утверджується. Севрен дбає, щоб прабатьківські гробниці — як-от Родинний Склеп Аґамандів — було повернуто, а дезертири чи непокірні сили не підривали владу Відступників в краї."}},fp="17,260,24.369.0,19.396.0,25.236.0,37.78.0,46.209.0,39.102.0,53.204.0,50.212.0"}
P.entries["npc:magni-bronzebeard"] = {n="Маґні Бронзбірд",s="Маґні Бронзбірд — Володар Айронфорджа, тан клану Бронзбірдів і правитель Хаз Модану. Неперевершений коваль і бувалий полководець Другої війни, він веде своє гірське королівство крізь горе й політичну напругу, водночас підтримуючи дворфську археологію по всьому Азероту.",h="Маґні Бронзбірд — Володар Айронфорджа, тан клану Бронзбірдів і правитель Хаз Модану.",kw={"маґні бронзбірд","король","айронфордж","хаз модан","ешбрінґер","ліга дослідників","дворфи"},ang={["faction:Alliance"]="Непохитний засновник Великого Альянсу разом із Лордероном і Стормвіндом, Маґні дає коаліції військову міць, інженерну майстерність і незламну вірність.",["profession:Blacksmithing"]="Маґні вважають одним із найвидатніших живих ковалів Азероту: саме він викував легендарний Ешбрінгер із потойбічного кристала біля Великого Ковадла Айронфорджа.",["race:Dwarf"]="Маґні — ваш беззаперечний володар і захисник Хаз Модану, який веде клан Бронзбірдів крізь зовнішні війни та внутрішні пошуки земляної спадщини вашого народу.",["race:Gnome"]="Король Маґні відкрив своє місто як прихисток для вцілілих із Гномреґану й підтримує тісну дружбу та технологічний союз із Великим Тінкером Меккаторком."},sec={{t="Володар Гори",b="Найстарший із трьох братів, Маґні змалку добре усвідомлював тягар, що чекав на нього під горою. Коли під час Другої війни вторглася Орда, він утримав Айронфордж за його неприступною брамою, а щойно облогу було знято, вийшов і присягнув Хаз Моданом Альянсу Лордерону. У мирні роки, що настали потім, Маґні прийняв у місто гномських союзників після падіння Гномреґану, давши прихисток під горою Великому Тінкеру Ґелбіну Меккаторку та його біженцям. Щоб об'єднати роз'єднані південне й північне королівства, Маґні попросив Меккаторка створити нечуване підземне диво — Глибинний трамвай, що сполучив Айронфордж просто зі Стормвіндом."},{t="Молот Помсти",b="За королівською поставою Маґні ховається глибока особиста трагедія. Під час Третьої війни з Нортренду надійшла звістка, що принц Артас Менетіл зрадив і вбив улюбленого молодшого брата Маґні — Мурадіна. Охоплений горем і гнівом, Маґні взявся за молот біля Великого Ковадла, коли верховний інквізитор Фербенкс та Александрос Моґрейн принесли йому кристал чистого осяйного Світла. Три дні без спочинку дворфський король вкладав у метал усе своє горе, лють і жагу помсти. Виготовлений клинок — Ешбрінгер — став найбільшим шедевром його життя, викуваним, щоб принести погибель Артасу й Погибелі."},{t="Розкопуючи минуле",b="За наказом Маґні дворфське суспільство здебільшого відвернулося від звичного промислового видобутку й зосередилося на розкопках давньої історії. Під враженням від дивних реліквій титанів, знайдених глибоко під землею, Маґні разом зі своїм братом Бранном Бронзбірдом заснував Лігу Дослідників. Нині дворфські розкопки всіяли континенти від Дун Мороґу до Калімдору, прагнучи розгадати таємницю того, як земляни стали сучасними дворфами. Та спокій удома лишається крихким: донька Маґні, принцеса Мойра, зникла — вважають, що її викрав ненависний клан Темного Заліза."}},fp="17,280,20.683.0,21.631.0,19.597.0,25.222.0,26.296.0,34.283.0,24.239.0,35.242.0,30.267.0"}
P.entries["npc:mai-ah"] = {n="Май'а",s="Май'а — тролиця з джунглів, наставниця магів у випаленому сонцем басейні Долини Випробувань у Дуроторі. Вона наставляє чародіїв-початківців серед тролів Темного Списа, які приходять у червоні каньйони відточувати владу над таємною магією. Молодим тролям, що ступають на шлях чародійства, вона дає перші настанови й уроки основ магії.",h="Май'а — тролиця з джунглів, наставниця магів у випаленому сонцем басейні Долини Випробувань у Дуроторі.",kw={"май'а","маг","наставниця","тролиця","долина випробувань","магія","дуротар"},ang={["class:Mage"]="Для чародіїв Темного Списа Май'а — початок магічного шляху: вона вчить дисципліни, потрібної, щоб плести вогонь, лід і таємну енергію під суворим сонцем Дуротару.",["race:Troll"]="Май'а дає молоді Темного Списа в Долині Випробувань культурне наставництво в мистецтві, яке рідко практикують їхні союзники-орки."},sec={{t="Наставниця таємної магії Лігва",b="Поки орки переважно віддають перевагу первісному поклику стихій або фізичній перевазі воїна, тролі Темного Списа мають рідкісний хист до вивчення таємної магії. Стоячи в Долині Випробувань, Май'а навчає молодих тролів-магів, що прибувають пройти обряди дорослішання. Вона приймає кандидатів із гліфічними письменами й починає надавати їхній хаотичній сирій силі форму дисциплінованих заклять, щоб вони здобули самовладання, потрібне, аби пережити небезпеки Дуротару."}},fp="6,368,24.501.0,14.245.0,58.314.0,46.263.0"}
P.entries["npc:mardant-strongoak"] = {n="Мардант Стронґоук",s="Мардант Стронґоук — наставник друїдів, нічний ельф, що мешкає в Алдрассилі в серці Тельдрассила. Він веде молодих друїдів у єднанні з духами природи й знайомить їх із таємницями Смарагдового Сну.",h="Мардант Стронґоук — наставник друїдів, нічний ельф, що мешкає в Алдрассилі в серці Тельдрассила.",kw={"мардант стронґоук","друїд","наставник","алдрассил","тельдрассил","смарагдовий сон","духи природи"},ang={["class:Druid"]="Для молодих друїдів — нічних ельфів Мардант Стронґоук — перший міст між буденним життям і священними обов'язками Кола Кенарія.",["race:NightElf"]="Перебуваючи в осерді Алдрассила, Мардант уособлює калдорейську відданість злагоді зі зростаючим живим світом Тельдрассила."},sec={{t="Учитель дикого краю",b="У вітті Алдрассила молоді нічні ельфи, що відчувають поклик дикої природи, звертаються до Марданта Стронґоука. Його головна справа — навчати новачків відкривати чуття духам природи, тлумачити їхнє бурмотіння й спрямовувати відновлювальну магію. Для тих, хто робить перші кроки як захисники дикого краю, він часто перший майстер, що відкриває неосяжну складність і прадавні небезпеки Смарагдового Сну."}},fp="17,222,23.414.0,25.182.0,30.166.0,35.112.0,26.169.0"}
P.entries["npc:marleth-barleybrew"] = {n="Марлет Барліб'ю",s="Марлет Барліб'ю — амбітна дворфійська броварка, що працює в Селі Брюнолл. Роздратована пануванням клану Тандербрю на місцевому пивному ринку, вона невпинно плете плани, щоб довести: вариво її родини краще за уславлений Громовий Ель Хараноса.",h="Марлет Барліб'ю — амбітна дворфійська броварка, що працює в Селі Брюнолл.",kw={"марлет барліб'ю","броварка","село брюнолл","барліброю","тандербрю","громовий ель","суперництво"},ang={["race:Dwarf"]="Для дворфів броварство — мистецтво, тісно пов'язане з престижем клану, тож ворожнеча Марлет із Тандербрю — справа запеклої родинної гордості."},sec={{t="Броварське суперництво",b="У Дун Мороґу до хмільного ставляться так само серйозно, як до сталі, а суперництво між родинами Барліброю й Тандербрю — легендарне. Марлет Барліб'ю обурює майже цілковита монополія, яку Раґнар Тандербрю та його рідня тримають із Ґуральні Тандербрю в Хараносі. Переконана, що її власне ремесло нітрохи не гірше, вона шукає хитрих способів передати барила Барліброю до рук корчемних відвідувачів. Замість відкритого конфлікту вона обирає дрібний підступ, наймаючи подорожніх, щоб ті потай підмінили цінні діжки елю Хараноса на її власні."}},fp="18,255,19.559.0,26.223.0,36.101.0,49.325.0,51.174.0"}
P.entries["npc:marryk-nurribit"] = {n="Маррік Нуррібіт",s="Маррік Нуррібіт — гном, наставник магів, що служить в Анвілмарі в Долині Холодного Хребта. Трохи більше прихильний до місцевого пива, ніж до суворої педагогіки, він знайомить гномських чародіїв-початківців з їхнім ремеслом, раз у раз випрошуючи зайву монету на випивку.",h="Маррік Нуррібіт — гном, наставник магів, що служить в Анвілмарі в Долині Холодного Хребта.",kw={"маррік нуррібіт","маг","наставник","гном","анвілмар","ель","гліфічний меморандум"},ang={["class:Mage"]="Для гномів-магів-початківців, що розпочинають шлях у Долині Холодного Хребта, Маррік — перший учитель, до якого ви звертаєтеся по основні закляття й ваш Гліфічний Меморандум.",["race:Gnome"]="Біженці, що знайшли прихисток у Дун Мороґу, знають Марріка як приклад гномського вченого, який надто вже добре пристосувався до дворфійської корчемної гостинності."},sec={{t="Таємні студії та ель",b="У теплі біля вогнища Анвілмара Маррік Нуррібіт дає таємні настанови молодим гномам, що роблять найперші кроки в магії. Хоч він і знається на таємних мистецтвах, поводиться він украй невимушено — часто здається, що його куди більше цікавить кухоль дворфійського елю й випрошування дрібних грошей у нових учнів, ніж муштра зі складними теоремами. Попри свої вади, Маррік гостро усвідомлює небезпеки за межами Долини Холодного Хребта й регулярно застерігає майбутніх заклиначів щодо радіоактивних і кишачих трогами жахіть полеглого Гномреґану."}},fp="15,261,22.589.0,23.175.0,47.191.0,38.197.0"}
P.entries["npc:marshal-dughan"] = {n="Маршал Дуґан",s="Маршал Дуґан — командир загону армії Стормвінда, розквартированого в Ґолдширі. Йому доручено захищати серце Лісу Елвінн, та його місцевий гарнізон розтягнутий до краю перед дедалі більшими вторгненнями кобольдів, гнолів і розбійників. Щоб убезпечити містечко на перехресті й навколишні ферми, він чимало покладається на вільних шукачів пригод.",h="Маршал Дуґан — командир загону армії Стормвінда, розквартированого в Ґолдширі.",kw={"маршал дуґан","маршал","ґолдшир","армія стормвінда","кобольди","гноли","ліс елвінн"},ang={["class:Warrior"]="Для бійців Дуґан утілює звичну дисципліну й логістичне напруження піхоти Стормвінда, що тримає лінію оборони попри нерівні сили.",["faction:Alliance"]="Маршал Дуґан — передова адміністративна влада Альянсу в Елвінні: він дає новоприбулим новобранцям перші військові доручення від імені Стормвінда."},sec={{t="Командир Перехрестя",b="Маршал Дуґан, що стоїть на видноті в Ґолдширі біля корчми «Лев'яча Гордість», несе важкий тягар: тримати Ліс Елвінн у безпеці, поки військові сили Стормвінда зайняті деінде. Навколишні ліси неухильно занепадають: копальні кишать поганню, гноли збираються на берегах річок, а розбійники дошкуляють мандрівникам на Королівському шляху. Маючи замало піхотинців під прямим командуванням, Дуґан організовує місцеву оборону, спрямовуючи новобранців зміцнювати застави й розвідувати спірні землі."},{t="Загрози на кожному кордоні",b="Найближчі клопоти Дуґана — навали кобольдів, що заполонили Копальню Фарґодіп і Яшмову копальню, загрожуючи важливому видобутку Ґолдшира. На заході гноли Річколапи на чолі з горезвісним Гоґґером тиснуть на Гарнізон Вестбрук. На сході Дуґанові доводиться розбиратися з донесеннями Вартового Томаса про лютих мурлоків, що вирізають патрулі вздовж річки. Даючи раду цим численним кризам із обмеженими силами, маршал повсякчас потребує здібних найманців."}},fp="14,358,27.516.0,23.494.0,22.220.0,75.308.0,53.277.1,55.311.0,40.237.0,45.244.0"}
P.entries["npc:marshal-mcbride"] = {n="Маршал Макбрайд",s="Маршал Дуглас Макбрайд — командир гарнізону Стормвінда при Абатстві Нортшира. Йому доручено оборону Долини Нортширу, і він кидає новоприбулих рекрутів проти навали кобольдів, що загрожує місцевим фермам і шахтам. Для новачків, які починають службу королівству Стормвінд, він — головна військова влада.",h="Маршал Дуглас Макбрайд — командир гарнізону Стормвінда при Абатстві Нортшира.",kw={"макбрайд","маршал макбрайд","нортшир","абатство нортшира","кобольди","шахта ехо-рідж"},sec={{t="Командир Нортшира",b="Маршал Дуглас Макбрайд стоїть просто біля Абатства Нортшира й уособлює пряму владу армії Стормвінда в цій тихій долині. Саме абатство — острівець віри й знань, але неспокій, що шириться королівством, розтягнув військові гарнізони до краю. Макбрайд мусить берегти мир і забезпечувати долину харчами та ресурсами, маючи лише жменьку присяжних вартових і потік зелених рекрутів, які приходять навчатися в майстрів абатства."},{t="Навала кобольдів",b="Найбільший клопіт Макбрайда — раптова зухвалість місцевої наволочі. Кобольди, що колись лише дошкуляли, заполонили довколишні ліси й захопили Шахту Ехо-Рідж — важливий для округи скарб. Регулярних солдатів, щоб їх вигнати, бракує, тож Макбрайд збирає паладинів, воїнів та інших новачків, щоб відтіснити підземних шкідників і з'ясувати масштаби навали, перш ніж вони геть задушать долину."}},fp="15,363,23.465.0,20.415.0,23.204.0,45.217.0,38.181.0,24.203.0,38.178.0,50.197.0"}
P.entries["npc:master-gadrin"] = {n="Майстер Ґадрін",s="Майстер Ґадрін — старий троль із джунглів і шанований знахар племені Темного Списа, що нині живе в Селі Сен'джин. Колись він разом із відступником-знахарем Залазаном навчав жерців і магів племені, а тепер очолює зусилля, щоб допомогти своєму вигнаному народові й зняти темне прокляття з їхнього вкраденого дому на Островах Відлуння.",h="Майстер Ґадрін — старий троль із джунглів і шанований знахар племені Темного Списа, що нині живе в Селі...",kw={"майстер ґадрін","знахар","троль","село сен'джин","темний спис","залазан","лоа","острови відлуння"},ang={["class:Mage"]="Ґадрін став першопрохідцем, навчаючи тролів Темного Списа таємних мистецтв після Третьої війни й доводячи, що троляча магія може сягати далеко за межі сирого обрядового моджо.",["class:Priest"]="Як старійшина, що навчав жерців Темного Списа спілкуватися з духами й лоа, Ґадрін утілює традиції тіні та віри тролів із джунглів.",["faction:Horde"]="Майстер Ґадрін — один із найдовіреніших радників Вол'джина: він пильно стежить за узбережжям Дуротару й попереджає Гострий Пагорб, коли темні культи загрожують молодій державі Дуротар.",["race:Troll"]="Для тролів Темного Списа Майстер Ґадрін — живий зв'язок із домом ваших предків і традиціями Сен'джина. Він поколіннями формував духовний провід вашого племені й по-батьківськи тужить через трагедію Островів Відлуння."},sec={{t="Наставник Темного Списа",b="Задовго до того, як Темний Спис прибув на Калімдор, Майстер Ґадрін був знахарем свого племені на прадавніх островах Південних Морів, де керував містичним навчанням цілих поколінь тролів Темного Списа."},{t="Зрада Залазана",b="Коли Темний Спис разом з Ордою оселився на Островах Відлуння, Ґадрін і молодий знахар Залазан разом керували містичним навчанням жерців і магів племені. На жаль, Залазан піддався божевіллю, сп'янілий від темних сил вуду, якими прагнув володіти. Відступник поневолив розум своїх одноплемінників і вигнав Вол'джина та непідкорених тролів Темного Списа на материк, у Дуротар. Нині Ґадрін живе в Селі Сен'джин і носить у серці скорботу від того, що колишній товариш став тиранічним чудовиськом; він невтомно працює, щоб упокоїти вбитих одноплемінників і покласти край пануванню Залазана."},{t="Хранитель прадавніх знань",b="Окрім кризи на Островах Відлуння, Ґадрін є одним із найбільших живих знавців тролячої духовності та знань про лоа в усій Орді. Учені, шамани й навіть Королівське Аптекарське Товариство шукають його поради щодо таємниць магії та алхімії. Коли дивні загрози на кшталт Палаючого Клинка торкаються Дуротару або далеким дослідникам потрібні забуті обряди — скажімо, розшифрувати прадавні таблички в Зул'Фарраку, щоб прикликати павучу лоа Шадру, — саме Ґадрін володіє знаннями, щоб створити потрібні зв'язування."}},fp="13,354,23.211.0,24.606.0,22.522.0,21.190.0,39.259.0,41.267.0,16.245.0,45.268.0,43.327.0"}
P.entries["npc:master-vornal"] = {n="Майстер Ворнал",s="Майстер Ворнал — літній троль із джунглів Темного Списа, що мешкає в Селі Сен'джин на південному узбережжі Дуротару. Попри похилий вік і великі знання алхімічних варив, він уперто відмовляється брати учнів.",h="Майстер Ворнал — літній троль із джунглів Темного Списа, що мешкає в Селі Сен'джин на південному узбережжі...",kw={"майстер ворнал","алхімія","сен'джин","розчинник","троль","дуротар"},ang={["profession:Herbalism"]="Ті, хто вправний із сирими травами, впізнають гостре око Ворнала на рідкісні каталізатори та їдкі природні реагенти, потрібні для його розчинників.",["race:Troll"]="Для тролів Темного Списа Майстер Ворнал утілює впертих літніх майстрів, які допомогли заснувати Село Сен'джин після того, як плем'я втекло зі свого острівного дому."},sec={{t="Упертий бровар Сен'джину",b="Майстер Ворнал — невід'ємна частина Села Сен'джин, відомий тим, що варить міцні напої та трунки для своїх побратимів із Темного Списа. Хоч вік помітно наздоганяє його, Ворнал лишається вкрай незалежним і вперто відмовляється навчати будь-яких учнів, воліючи змішувати свої ліки й леткі суміші лише власноруч."},{t="Розчинний дух",b="Ворнал час від часу доручає молодим шукачам пригод збирати їдкі чи незвичні складники з довколишніх земель, як-от сильнодійні матеріали для розчинників і сумішей. Хоч він радо винагороджує тих, хто йому допомагає, свої точні методи й рецепти він тримає під замком, маючи ремесло за справу самотню."}},fp="13,247,30.334.0,16.319.0,21.176.0,31.134.0,50.193.0,37.181.0"}
P.entries["npc:maxan-anvol"] = {n="Максан Анвол",s="Максан Анвол — дворфійський наставник жерців, що служить у Ґуральні Тандербрю в Хараносі. Відданий Святому Світлу, він веде дворфійських жерців-початківців, поки ті вчаться спрямовувати божественну силу серед морозного клімату Дун Мороґу. Він випробовує молодих послушників, щоб переконатися, що вони гідні носити церковне облачення.",h="Максан Анвол — дворфійський наставник жерців, що служить у Ґуральні Тандербрю в Хараносі.",kw={"максан анвол","жрець","наставник","святе світло","ґуральня тандербрю","харанос","облачення"},ang={["class:Priest"]="Максан — ваш ранній провідник у Дун Мороґу: він відкриває вам основи святої дисципліни, навчає расових молитов на кшталт Відчайдушної Молитви й вручає ваше перше офіційне церковне вбрання.",["faction:Alliance"]="Максан дбає про фізичну й духовну готовність горян і розвідників Альянсу, які стережуть Дун Мороґ від трогів, крижаних тролів і диких звірів.",["race:Dwarf"]="Утілюючи практичну побожність Айронфорджа, Максан укорінює дворфійську віру там, де люди справді збираються, — просто біля пивних барил Хараноса."},sec={{t="Жрець у шинку",b="Хоч може здатися дивним знайти висвяченого служителя Святого Світла в Ґуральні Тандербрю, дворфійській культурі це цілком пасує. Харанос — головний вузол між Долиною Холодного Хребта й Айронфорджем, і саме в місцевій корчмі природно збираються мандрівники, горяни й послушники. Максан дбає про духовний добробут селища поруч із кухлями стауту, пропонуючи молитви й пораду кожному, хто переступить поріг."},{t="Випробування вірних",b="Максан Анвол відповідає за перевірку жерців-новачків, перш ніж ті вирушать у широкий світ. Він доручає послушникам показати володіння основними цілющими молитвами на поранених захисниках Дун Мороґу. Тим, хто доводить свою відданість і практичну вправність, вручають перше справжнє жрецьке облачення, офіційно засвідчуючи їхнє визнане становище в Церкві Святого Світла."}},fp="11,322,19.445.0,20.399.0,29.164.0,28.218.0,49.282.0,41.243.0,32.178.0,34.188.0"}
P.entries["npc:maybell-maclure"] = {n="Мейбелл Маклур",s="Мейбелл Маклур — молода жінка, що живе на Виноградниках Маклюрів у Лісі Елвінн. Попри гірку, давню ворожнечу між її родиною та сусідами Стоунфілдами, вона потай закохалася в Томмі Джо Стоунфілда.",h="Мейбелл Маклур — молода жінка, що живе на Виноградниках Маклюрів у Лісі Елвінн.",kw={"мейбелл маклур","томмі джо","виноградники маклюрів","кохання","лікер невидимості","ворожнеча"},ang={["faction:Alliance"]="Для шукачів пригод Альянсу, що проходять Лісом Елвінн, роман Мейбелл — нагадування, що особисті біди й давні образи живуть навіть у серці королівства."},sec={{t="Нещасливе кохання на виноградниках",b="Життя на Виноградниках Маклюрів — це нескінченна праця й незгасна образа на сусідню родину Стоунфілдів. Між двома вогнями опинилася Мейбелл Маклур, яка глибоко закохалася в Томмі Джо Стоунфілда, молодого спадкоємця ворожої садиби. Розлучена з ним пильною ріднею й давньою родинною неприязню, Мейбелл відчайдушно шукає будь-якої нагоди передати Томмі Джо хоч слово подалі від цікавих очей своїх рідних."},{t="Зілля для справжнього кохання",b="Не маючи змоги відкрито перетнути межу між фермами, Мейбелл покладається на співчутливих подорожніх і настанови Бабусі Стоунфілд. З допомогою ґолдширського алхіміка Вільяма Пестла вариться лікер невидимості. Випивши цей заборонений трунок, Мейбелл може непомітно вислизнути із садиби Маклурів і вкрасти дорогоцінні хвилини з Томмі Джо на березі річки."}},fp="15,230,29.425.0,26.383.1,47.236.0,47.242.1,34.152.0,35.189.1"}
P.entries["npc:melithar-staghelm"] = {n="Мелітар Стаґгелм",s="Мелітар Стаґгелм — нічний ельф, що перебуває одразу за Алдрассилом у Тінедолі, стартовій долині Тельдрассила. Він допомагає молодим нічним ельфам — шукачам пригод на початку навчання, посилаючи їх до поблизьких учителів і залагоджуючи дрібні місцеві негаразди. Хоч він носить відоме прізвище Стаґгелм, як і Архідруїд Фандрал Стаґгелм, його точний зв'язок із провідним друїдом лишається непідтвердженим.",h="Мелітар Стаґгелм — нічний ельф, що перебуває одразу за Алдрассилом у Тінедолі, стартовій долині Тельдрассила.",kw={"мелітар стаґгелм","стаґгелм","алдрассил","тінедол","тельдрассил","фандрал стаґгелм","провідник"},ang={["race:NightElf"]="Для нічних ельфів, що починають подорож у Тінедолі, Мелітар — одна з найперших постатей, яких вони зустрічають, покинувши прихисток Алдрассила."},sec={{t="Провідник біля Алдрассила",b="Стоячи просто перед входом до великої гілки Алдрассила, Мелітар — одна з перших постатей, з якими стикаються нічні ельфи, виходячи у світ. Він спрямовує щойно пробуджену молодь із різними сигілами до відповідних класових наставників, щоб ті дістали належну науку бойових і містичних мистецтв. Окрім розпорядчих настанов, Мелітар пильнує найближчі угіддя Тінедолу і шукає помічників, щоб упоратися з бешкетливою тутешньою звіриною й дрібними бісуватими вторгненнями, що загрожують спокою святилища."},{t="Ім'я Стаґгелмів",b="Прізвище Стаґгелм неминуче привертає увагу, адже Архідруїд Фандрал Стаґгелм нині очолює Коло Кенарія в Дарнасусі після зникнення Малфуріона Стормрейджа у Смарагдовому Сні. Та Мелітар не вихваляється величним походженням і не говорить про свій рід. Чи він далекий родич шанованої родини Архідруїда, чи просто носить прадавнє калдорейське родове ім'я, Мелітар задовольняється скромними обов'язками біля коріння Алдрассила."}},fp="17,406,20.531.0,17.508.0,25.218.0,50.260.0,49.215.0,35.115.0"}
P.entries["npc:merissa-stilwell"] = {n="Мерісса Стілвелл",s="Мерісса Стілвелл — молода людська містянка, що живе при Абатстві Нортшира в Лісі Елвінн. Стоячи біля абатства, вона привітно зустрічає новачків, що навчаються в Долині Нортширу, і простягає їм руку допомоги.",h="Мерісса Стілвелл — молода людська містянка, що живе при Абатстві Нортшира в Лісі Елвінн.",kw={"мерісса стілвелл","нортшир","абатство нортшира","гостинність","новобранці","стілвелли"},ang={["faction:Alliance"]="Для новобранців Альянсу, що покидають затишну обитель Нортширу, Мерісса втілює теплу гостинність Елвінну, перш ніж дасться взнаки сувора дійсність загрози Дефіас."},sec={{t="Привітне обличчя в Нортширі",b="Стоячи біля Абатства Нортшира, Мерісса Стілвелл вітає новобранців, що прибувають у Долину Нортширу. Мандрівним новачкам вона пропонує просту гостинність і практичні поради щодо відпочинку й того, як тут усе влаштовано. Носячи прізвище, спільне з відомими ремісниками й господарями по всьому королівству — як-от коваль Джордан Стілвелл і захисниця Вестфолу Дафна Стілвелл, — вона лишається мирним тутешнім обличчям серед дедалі більшої напруги в королівстві."}},fp="16,219,30.449.0,24.144.0,34.74.0,57.222.0,39.106.0"}
P.entries["npc:milli-featherwhistle"] = {n="Міллі Фезервісл",s="Міллі Фезервісл — гномка, майстриня-інженерка механоступів, що працює на Складі Стілґрила в Дун Мороґу. Після падіння Гномреґану вона ретельно виготовляє власноруч і обслуговує механічних їздових птахів, яких так полюбляють її родичі. Свої дорогоцінні механічні творіння вона продає гномам і довіреним союзникам вигнанців Гномреґану.",h="Міллі Фезервісл — гномка, майстриня-інженерка механоступів, що працює на Складі Стілґрила в Дун Мороґу.",kw={"міллі фезервісл","механоступ","інженерка","гномка","склад стілґрила","меккаторк","вигнанці гномреґану"},ang={["faction:Alliance"]="Герої Альянсу, що здобули найвищу повагу Вигнанців Гномреґану, можуть звернутися до Міллі, щоб осідлати одного з найшвидших механічних скакунів Азероту.",["profession:Engineering"]="Механоступи Міллі — вершина великомасштабного гномського пересування, що поєднує гіроскопічні балансувальні блоки з потужними механічними кінцівками.",["race:Gnome"]="Міллі Фезервісл — провідна інженерка їздових механізмів вашого народу, яка несе далі технологічний геній Великого Тінкера Меккаторка навіть у вигнанні з вашого підземного дому."},sec={{t="Майстриня механоступів",b="Працюючи просто неба на пронизливому холоді Складу Стілґрила на схід від Хараноса, Міллі Фезервісл відповідає за постачання механічних скакунів переселеному люду Гномреґану. На відміну від живих звірів, яких воліють дворфи й нічні ельфи, Міллі збирає весь свій товар сама, особисто калібруючи шестерні, поршні й балансувальні гіроскопи, щоб кожен механічний птах бігав на повну потужність засніженими скелями Дун Мороґу."},{t="Спадок Меккаторка",b="Кожна рама й пружина в майстерні Міллі походить від креслень, які спершу накреслив Великий Тінкер Ґелбін Меккаторк. Хоча з роками Міллі додала сучасні поліпшення — полегшила шасі й удосконалила вихлопні отвори, — вона вірно дотримується основних схем Великого Тінкера. Її механічні дива доводять: навіть у вигнанні гномське технологічне честолюбство лишається геть незламним."}},fp="20,342,25.441.0,21.432.0,28.220.0,38.147.0,43.262.0,29.206.0,36.178.0,57.271.0"}
P.entries["npc:minor-manifestation-of-earth"] = {n="Малий Прояв Землі",s="Малий Прояв Землі — місцевий дух стихії, прив'язаний до священних каменів у Малгорі й Дуротарі. Невидимий для звичайного зору, він відкривається лише шаманам-початківцям, що випили священну Земляну Сапту, і дає грубий кварц, потрібний, щоб вирізьбити їхній найперший тотем землі.",h="Малий Прояв Землі — місцевий дух стихії, прив'язаний до священних каменів у Малгорі й Дуротарі.",kw={"малий прояв землі","дух землі","земляна сапта","камінь кодо","камінь духів","тотем землі","шаман"},ang={["class:Shaman"]="Кожен молодий шаман Орди мусить поєднатися з Малим Проявом Землі під дією Земляної Сапти, щоб здобути свій найперший тотем.",["race:Tauren"]="Молоді таурени йдуть на схід через Малгор до Каменя Кодо, щоб шукати єднання з цим проявом як частину своїх прабатьківських духовних випробувань."},sec={{t="Голос каменю",b="Духи землі живуть усюди під ґрунтом і камінням, та щоб говорити з ними, потрібен свідомий ритуал. Біля священних місць на кшталт Каменя Кодо в Малгорі й Каменя Духів у Дуротарі Малі Прояви Землі перебувають у незримому світі в оточенні ще менших стихійних присутностей. Лише посвячені, що випили Земляну Сапту — ритуальний напій, зварений шаманськими наставниками, — здатні підняти завісу між тілесним світом і стихіями. Коли його визнано, дух дарує благословення землі та шматок грубого кварцу — духовне осердя, потрібне новачкові, щоб виготовити Тотем Землі."}},fp="28,291,18.638.0,49.247.0,39.198.0,45.234.0,46.221.0"}
P.entries["npc:misha-tor-kren"] = {n="Міша Тор'крен",s="Міша Тор'крен — орчиня-мати, що мешкає на Фермі Тор'крена в західному Дуроторі, на південний схід від Громового Хребта. Змучена тривогою за зниклого сина Крона, вона просить перехожих мандрівників допомогти дізнатися його долю.",h="Міша Тор'крен — орчиня-мати, що мешкає на Фермі Тор'крена в західному Дуроторі, на південний схід від...",kw={"міша тор'крен","крон","ферма тор'крена","кроколіски","південна лють","мати","дуротар"},ang={["class:Hunter"]="Доля сина Міші показує, як небезпечно недооцінювати річкових хижаків, доки мисливець по-справжньому не опанував дику природу.",["race:Orc"]="Безрозсудне бажання Крона довести свою воїнську вправність на звірині Дуротару — сумне нагадування про високу ціну юнацької гордості."},sec={{t="Материнське чекання",b="Сховавшись край Громового Хребта, Міша Тор'крен порається на відлюдному хуторі й переживає найгірший страх кожного з батьків. Її син Крон подався на захід, до Річки Південної Люті, полювати на кроколісків і довести свою вправність — та так і не повернувся. Поки небезпеки прикордоння Дуротару розтягують сторожові вежі орків до межі, Міша лишається сама з надією на звістку про нього й відчайдушно шукає будь-кого, хто погодиться обшукати береги річки в пошуках слідів її хлопчика."},{t="Похмурий знак",b="Річка Південної Люті безжальна до молодих мисливців. Ті, хто прочісує її багнисті береги, неминуче дізнаються, що Крон став жертвою лютих річкових кроколісків. Повернення його врятованого амулета — єдине заспокоєння, яке може отримати Міша: гірке нагадування про жорстокі випробування, через які молоді орки доводять свою силу в суворих нетрях Калімдору."}},fp="14,221,16.444.0,12.345.1,22.124.0,26.140.0,36.147.1,38.130.0"}
P.entries["npc:moon-priestess-amara"] = {n="Місячна Жриця Амара",s="Місячна Жриця Амара — жриця, нічна ельфійка, що стоїть біля головної дороги на захід від Доланаара в Тельдрассилі. Оточена вірними охоронницями-мисливицями, вона пильнує лісові шляхи, що з'єднують серце гілки зі столицею — Дарнасусом.",h="Місячна Жриця Амара — жриця, нічна ельфійка, що стоїть біля головної дороги на захід від Доланаара в...",kw={"місячна жриця амара","жриця","сестринство елуни","доланаар","дарнасус","дорога","тельдрассил"},ang={["class:Priest"]="Як членкиня Сестринства Елуни Жриця Амара втілює нічноельфійську відданість Місячній Богині й слугує душпастиркою та духовною провідницею молодих послушників, що вирушають із Тінедолу.",["race:NightElf"]="Амара позначає важливу віху на вашому шляху від Доланаара, даючи настанови й доручення, що ведуть до великого міста Дарнасус."},sec={{t="Охоронниця лісових шляхів",b="Перебуваючи на тихому придорожньому посту на захід від Доланаара, Місячна Жриця Амара уособлює і духовну владу Сестринства Елуни, і практичну пильність, потрібну, щоб дороги Тельдрассила були безпечними. Вона подорожує й пильнує з двома супутницями-мисливицями, Нгемай і Яеліурою. Для подорожніх, що прямують на захід, Амара — провідна рука: вона спрямовує шукачів пригод дорогою до Дарнасуса, а тим, чий дух обтяжений, доручає шукати шляхів спокути."}},fp="20,252,25.480.0,28.270.0,38.122.0,41.174.0"}
P.entries["npc:morgan-the-collector"] = {n="Морґан Збирач",s="Морґан Збирач — високопоставлений агент Дефіас, що керує здирництвом і збором данини Братства по всьому Лісі Елвінн. Отаборившись на захопленій Гарбузовій Ділянці Брекуеллів, він координує місцеве злодійство просто під носом у варти Ґолдширу.",h="Морґан Збирач — високопоставлений агент Дефіас, що керує здирництвом і збором данини Братства по всьому Лісі...",kw={"морґан збирач","дефіас","гарбузова ділянка","перстень","гільдія каменярів","здирництво"},ang={["class:Rogue"]="Морґан показує, як організована злочинна дисципліна перетворює розрізнених злодіїв на дієвий підпільний синдикат, здатний фінансувати заколот.",["race:Human"]="Знищення Морґана — удар у відповідь зрадникам, що перетворили мирні ферми Стормвінда на укріплені бандитські лігва."},sec={{t="Данина Елвінну",b="Морґан заслужив своє прізвисько, витискаючи соки з віддалених ферм Лісу Елвінн від імені Братства Дефіас. Поки звичайні бандити чіпляються до подорожніх на дорогах, Морґан керує організованими здирствами й збирає крадену монету та припаси, щоб спрямувати їх углиб мережі Братства. Свій штаб він улаштував у будинку на Гарбузовій Ділянці Брекуеллів, оточивши себе вірними посіпаками, серед яких Сурена Каледон і Ерлан Драджмур."},{t="Перстень минулого",b="Справи Морґана — не прості вуличні злочини: він носить особливий перстень-печатку, що позначає його владу. Для слідчих у Ґолдширі цей перстень — твердий доказ, що пов'язує замаскованих злодіїв, які тероризують серце королівства, зі зганьбленою Гільдією Каменярів, що відбудувала Стормвінд після Другої війни. Здобутий перстень пробиває завісу таємниці над тим, хто насправді керує бандитами в лісах."}},fp="20,262,19.448.0,20.411.1,28.163.0,22.123.0,29.156.0,42.119.1"}
P.entries["npc:morin-cloudstalker"] = {n="Морін Клаудсталкер",s="Морін Клаудсталкер — тауренський розвідник, що вартує на дорозі, яка веде на схід від Села Бладгуф до Пусток у Малгорі. Пильнуючи рівнини, він стежить за місцевими торговими шляхами й розслідує загрози, що насуваються на тауренських мандрівників.",h="Морін Клаудсталкер — тауренський розвідник, що вартує на дорозі, яка веде на схід від Села Бладгуф до Пусток...",kw={"морін клаудсталкер","розвідник","село бладгуф","малгор","венчурна компанія","караван"},ang={["faction:Horde"]="Морін дає звитяжцям Орди першу нагоду захистити припаси й священні землі своїх нових тауренських союзників.",["race:Tauren"]="Для тауренів, що вирушають із Села Бладгуф у великий світ, Морін уособлює пильну оборону вашої батьківщини — і від зухвалих розбійників, і від корпоративних осквернителів."},sec={{t="Вартовий південного шляху",b="Ставши край ґрунтової дороги, що в'ється на схід до Пусток, Морін Клаудсталкер водночас розвідник і охоронець для подорожніх Малгору. Трав'янисті рівнини тут зазвичай мирні, але відкриття торгових шляхів і зрушення кордонів привабили пройдисвітів і розбійників небезпечно близько до серця тауренської батьківщини."},{t="Розслідування каравану",b="Розвідники Моріна нещодавно напали на караван Венчурної Компанії на північному березі Озера Кам'яного Бика й спалили його. Коли поблизу обгорілих возів помітили гоблінів-збирачів, він послав шукачів пригод оглянути вцілілі ящики з припасами й дізнатися, що саме везла Венчурна Компанія."},{t="Оборона від Венчурної Компанії",b="Окрім звичайних грабіжників, Моріна глибоко турбує промислова присутність Венчурної Компанії, що розгортає діяльність у Малгорі. Він спрямовує шукачів пригод з Орди, які проходять повз, на їхні лісозаготівлі та шахтарські застави й вказує на ключових ватажків — таких як Наглядач Фіззпрокет, — щоб зупинити спустошення природи, яке загрожує священним рівнинам."}},fp="18,266,29.343.0,25.268.0,29.346.1,36.128.0,32.152.0,46.232.0,48.212.0,25.124.0,44.94.0"}
P.entries["npc:mountaineer-barleybrew"] = {n="Горянин Барліброу",s="Горянин Барліброу — горянин Айронфорджа, що служить на Заставі Південної Брами в Дун Мороґу. Стережучи перевал, що веде на схід до Лох Модану, він покладається на ситне дворфійське вариво, щоб вартові лишалися пильними на лютому холоді.",h="Горянин Барліброу — горянин Айронфорджа, що служить на Заставі Південної Брами в Дун Мороґу.",kw={"горянин барліброу","горянин","застава південної брами","лох модан","варта","мерехтливий стаут","дун мороґ"},ang={["race:Dwarf"]="Для дворфів Барліброу втілює необхідну рівновагу між прикордонним обов'язком і міцним трунком, що тримає Каз Модан у безпеці."},sec={{t="Варта на східному перевалі",b="На Заставі Південної Брами, що стереже засніжену дорогу до Лох Модану, горянин Велларт Барліброу несе службу в прикордонній варті Айронфорджа. Як і багато горян, що служать на лютих вітрах Дун Мороґу, він цінує зміцнювальні властивості доброго дворфійського трунку. Носячи ім'я уславленого клану Барліброю, він допомагає доправляти партії міцного Мерехтливого Стауту до побратимів-вартових, яким потрібні тепло й витривалість під час довгих змін на гірських перевалах."}},fp="22,232,27.499.0,40.145.0,39.165.0,39.118.0"}
P.entries["npc:mountaineer-kadrell"] = {n="Горянин Кадрелл",s="Горянин Кадрелл — непохитний дворфійський вартовий, що стоїть навпроти Корчми «Міцний Лагер» у Телсамарі. Як ключова сполучна ланка серед горян Лох Модану, він координує розвідку, доставку припасів і оборону кордонів по всьому краю.",h="Горянин Кадрелл — непохитний дворфійський вартовий, що стоїть навпроти Корчми «Міцний Лагер» у Телсамарі.",kw={"горянин кадрелл","горянин","телсамар","лох модан","корчма міцний лагер","вартовий","розвідка"},ang={["faction:Alliance"]="Кадрелл покладається на мандрівників Альянсу, що проходять через Телсамар, щоб ті носили послання й допомагали далеким заставам горян, які борються з загрозами краю.",["race:Dwarf"]="Як член уславленого корпусу горян, Кадрелл утілює передову варту, що береже східні землі Айронфорджа від небезпек дикої природи."},sec={{t="Вартовий Телсамара",b="Стоячи на варті в людному поселенні Телсамар, Горянин Кадрелл — опора дворфійської оборони по всьому Лох Модану. Поки застави на околицях долини зносять невпинний тиск трогів, гнолів і тутешніх звірів, Кадрелл лишається в центрі містечка, щоб організовувати підкріплення, передавати накази й оцінювати польові звіти, які приносять мандрівні розвідники."},{t="Тримати зв'язок",b="Обов'язки Кадрелла часто передбачають підтримувати зв'язок між Телсамаром і віддаленими передовими позиціями. Чи то узгоджуючи дії з Горянином Стормпайком, чи то посилаючи шукачів пригод доповісти вартовим на кшталт Горянина Рокґара, Кадрелл дбає, щоб відокремлені застави, які стережуть гірські перевали, отримували життєво важливі припаси, підкріплення й оборонні відомості."}},fp="19,256,23.378.0,22.362.0,39.143.0,37.208.0,50.221.0,33.192.0"}
P.entries["npc:mountaineer-thalos"] = {n="Горянин Талос",s="Горянин Талос — дворфійський вартовий, що стоїть біля виходу з Долини Холодного Хребта на Перевал Холодного Кряжа. Йому доручено стерегти шлях, і він попереджає подорожніх про раптову навалу трогів, що забила тунель. Шукачі пригод із нагальними звітами з долини покладаються на нього, щоб безпечно дістатися Хараноса.",h="Горянин Талос — дворфійський вартовий, що стоїть біля виходу з Долини Холодного Хребта на Перевал Холодного...",kw={"горянин талос","горянин","перевал холодного кряжа","троги","вартовий","харанос","долина холодного хребта"},ang={["faction:Alliance"]="Талос підтримує зв'язок уздовж життєво важливого гірського коридору, що з'єднує оборонні сили долини з центральним командуванням Айронфорджа.",["race:Dwarf"]="Для молодих дворфів, що залишають колиску батьківщини, Талос — суворе нагадування: загроза трогів — не навчальна вправа, а облога, що тисне на самі пороги Айронфорджа.",["race:Gnome"]="Гноми, що вирушають із притулків біженців Гномреґану, бачать Талоса на варті біля головного наземного шляху, що спускається до Хараноса й Айронфорджа."},sec={{t="Вартовий Перевалу Холодного Кряжа",b="На засніженій межі, де Долина Холодного Хребта переходить у глибші скелі Дун Мороґу, Горянин Талос — перша лінія оборони для мандрівників, що залишають дворфійські навчальні угіддя. Перевал Холодного Кряжа став підступною тісниною, яку захопили ворожі троги, що вирили собі шлях з підземних глибин. Талос несе варту на холоді, застерігаючи неготових повернути назад і оцінюючи, чи досить у витривалих кур'єрів твердості, щоб пробитися до ширшого королівства."},{t="Контрольний пункт кур'єра",b="Коли Ґрелін Вайтбірд завершує свій звіт про пересування тролів Морозогривів у відлюдній долині, кур'єрові, що несе його до брата Сеніра в Харанос, кажуть поговорити з Горянином Талосом, перш ніж заходити до тунелю. Переконавшись, що шукач пригод здатен подолати заражений прохід, Талос скеровує його далі до Хараноса, де командири краю координують оборону Дун Мороґу. Його пильна присутність гарантує, що важливі відомості дійдуть до військових очільників Айронфорджа, а не згинуть у снігу."}},fp="18,308,26.499.0,22.529.0,26.194.0,49.215.0,47.175.0,54.285.0,47.186.0,56.191.0"}
P.entries["npc:mull-thunderhorn"] = {n="Малл Тандергорн",s="Малл Тандергорн — тауренський старійшина, що мешкає в Селі Бладгуф у Малгорі. Глибоко відданий Земній Матері та рівновазі землі, він наглядає за священними водяними криницями, розкиданими по рівнинах. Коли чужинці-визискувачі загрожують життєдайним водам краю, Малл проводить молодих тауренів через обряди очищення прабатьківських джерел.",h="Малл Тандергорн — тауренський старійшина, що мешкає в Селі Бладгуф у Малгорі.",kw={"малл тандергорн","старійшина","криниці","очищення","тотем","село бладгуф","малгор"},ang={["class:Druid"]="Друїди поділяють тривогу Малла, бо на власні очі бачать, як отруєні криниці руйнують рівновагу живого світу Малгору.",["class:Shaman"]="Шамани впізнають у Маллі опору на гармонію стихій: його тотеми очищення закликають духів предків, щоб зцілити води, роз'ятрені механічною жадобою.",["faction:Horde"]="Боротьба Малла підкреслює тертя Орди з такими незалежними хижими організаціями, як Венчурна Компанія, що без дозволу вигрібають багатства Калімдору.",["race:Tauren"]="Для тауренів Малл Тандергорн — це пам'ять племені та обов'язок перед предками; він веде молодих сміливців, що захищають священні рівнини від жадібних чужинців."},sec={{t="Хранитель священних вод",b="Стоячи на варті в Селі Бладгуф, Малл Тандергорн несе на собі тягар духовного добробуту Малгору. Кочові племена зібралися під рукою Верховного Вождя Кайрна Бладгуфа, щоб звести собі постійну домівку, та їхні землі вже в облозі жадібності й нерозважливого загарбання. Малл — духовна опора для молодих сміливців, що виходять із Табору Нарачі; він кличе їх берегти життєво важливі скарби предків."},{t="Отруєні криниці й Венчурна Компанія",b="Головна біда Малла — раптова хвороба, що шириться водами Малгору: криницями Вінтергуфів, Тандергорнів і Вайлдмейнів. Сліди цієї скверни ведуть до гоблінів Венчурної Компанії — безсовісного торгового підприємства, що вгризається в довколишні пагорби й зливає отруту в місцеві ґрунтові води. Малл доручає молодим тауренам виготовити особливі тотеми очищення й провести обряд біля кожної прабатьківської криниці, перш ніж зараза безповоротно просякне землю та її живність."}},fp="16,359,29.438.0,37.540.1,24.237.0,54.293.0,44.271.0,54.266.0,33.268.0,27.268.0"}
P.entries["npc:nori-pridedrift"] = {n="Норі Прайддріфт",s="Норі Прайддріфт — заповзятливий дворф, що розносить свій обпікаюче гарячий Ранковий Узвар засніженою Долиною Холодного Хребта. Він заробляє на життя, кидаючи виклик холоду, щоб постачати змерзлим горянам їхню ранкову підбадьорливу порцію, і часто наймає прудких новобранців розносити напій, поки той ще парує.",h="Норі Прайддріфт — заповзятливий дворф, що розносить свій обпікаюче гарячий Ранковий Узвар засніженою Долиною...",kw={"норі прайддріфт","ранковий узвар","дворф","кухоль","доставка","долина холодного хребта","гарячий напій"},ang={["profession:Cooking"]="Кулінари-мандрівники в Дун Мороґу цінують відданість Норі, який подає свій фірмовий напій обпікаюче гарячим попри крижане повітря довкола.",["race:Dwarf"]="Кожен дворф розуміє життєво важливу втіху від міцного напою на морозі, тож гарячий Ранковий Узвар Норі — жаданий гість на гірських постах варти."},sec={{t="Паруючий кухоль у снігу",b="Життя в Долині Холодного Хребта суворе й люто холодне, і ніщо не пробиває мороз так, як ковток Гарячого Ранкового Узвару. Норі Прайддріфт заробляє на життя тим, що варить і розносить цей гарячий, схожий на каву ранковий напій замерзлими заметами. Оскільки узвар треба пити ще обпікаючим, щоб повністю його оцінити, доставка — це перегони зі стихією. Норі часто наймає прудких кур'єрів бігти зі свіжими порціями до змерзлих вартових, перш ніж гірське повітря забере в напою тепло. Не менш важливий за сам узвар і його обмежений запас міцних кухлів, які він вимагає від своїх гінців повертати негайно."}},fp="15,301,26.649.0,23.186.0,26.211.0,29.207.0,48.181.0"}
P.entries["npc:novice-elreth"] = {n="Послушниця Елрет",s="Послушниця Елрет — нежить із Відступників, що перебуває в каплиці Похоронного Подзвону. Коли щойно підняті мерці прокидаються до другого життя, вона скеровує їх стати проти безтямної Погибелі, що никає сусідніми могилами, і подбати про трагічні наслідки чуми.",h="Послушниця Елрет — нежить із Відступників, що перебуває в каплиці Похоронного Подзвону.",kw={"послушниця елрет","каплиця","похоронний подзвін","погибель","семюел фіппс","відступники"},ang={["class:Priest"]="Стоячи на колишній святій землі Лордерону, Елрет утілює різкий, прагматичний перехід від святого поклоніння до похмурої потреби нежиті.",["race:Undead"]="Для свіжих Відступників, що видряпуються з могили, Послушниця Елрет пропонує перші практичні кроки до виживання, спрямовуючи холодну ненависть на безтямну Погибель."},sec={{t="Провідниця в церкві проклятих",b="У оскверненій каплиці Похоронного Подзвону Послушниця Елрет допомагає новопосталим мерцям, що силкуються осягнути своє жахливе пробудження. Замість піддаватися розпачу чи безтямному голоду Погибелі, Відступники мусять швидко згуртуватися, щоб убезпечити свою землю. Елрет дає щойно звільненим душам перші завдання: збирати могильний прах із безтямних трупів і давати раду недобиткам трагічного падіння Лордерону, зокрема й невідступній скорботі Семюела Фіппса та його покійної дружини Марли."}},fp="13,270,35.534.0,31.128.0,43.193.0,37.209.0,27.234.0"}
P.entries["npc:oben-rageclaw"] = {n="Обен Рейджклов",s="Обен Рейджклов — неприкаяний дух друїда, нічного ельфа, що блукає споганеними глибинами Курганного Лігва Бан'етіл у Тельдрассилі. Поки його дух тиняється в пастці курганного лігва, його сплячу тілесну оболонку підкорила огидна магія фурболгів.",h="Обен Рейджклов — неприкаяний дух друїда, нічного ельфа, що блукає споганеними глибинами Курганного Лігва...",kw={"обен рейджклов","друїд","дух","курганне лігво бан'етіл","вузлошкіри","фурболги","смарагдовий сон"},ang={["class:Druid"]="Доля Обена — болісне нагадування про вразливість друїдів під час трансу єднання зі Смарагдовим Сном, коли священні курганні лігва лишаються без захисту.",["race:NightElf"]="Споганення Обена Рейджклова фурболгами Вузлошкірів показує, як глибоко скверна вразила корінних мешканців і священні святилища Тельдрассила."},sec={{t="Споганений сон",b="Як і багато Друїдів Пазура, Обен Рейджклов усамітнився в підземному святилищі Курганного Лігва Бан'етіл, щоб єднатися з природою й блукати Смарагдовим Сном. Та коли тутешні фурболги Вузлошкірів піддалися скверні й заполонили кургани, Обен, занурений у транс, виявився цілком беззахисним. Замість просто вбити його, споганений шаман Вузлошкірів темними обрядами захопив владу над його непритомним смертним тілом, і витіснений дух лишився тинятися змученим привидом, нездатним ні відійти, ні прокинутися."},{t="Розрив із посудиною",b="Не маючи змоги відвоювати власну плоть із поневолення шамана, Обен покладається на мандрівників, що прокладають шлях небезпечними тунелями, аби ті поклали край його мукам. Лише знайшовши й знищивши його тіло-маріонетку, можна розірвати його смертні пута. Щойно викрадену посудину повалено, замучений привид Обена нарешті звільняється з підземної пітьми, щоб знайти вічний спокій у Смарагдовому Сні."}},fp="13,260,20.516.0,19.384.1,21.166.0,29.225.0,30.155.0,44.169.1"}
P.entries["npc:orgnil-soulscar"] = {n="Орґніл Соулскар",s="Орґніл Соулскар — орк-слідчий, що стоїть на Гострому Пагорбі в центральному Дуротарі. Він виконує роль неофіційного охоронця порядку, узгоджуючи оборону й розвідку проти внутрішніх загроз молодій державі. Найбільше його непокоїть тінь, яку кидає на каньйони Дуротару культ Палаючого Клинка.",h="Орґніл Соулскар — орк-слідчий, що стоїть на Гострому Пагорбі в центральному Дуротарі.",kw={"орґніл соулскар","слідчий","орк","гострий пагорб","палаючий клинок","культ","дуротар"},ang={["class:Warlock"]="Чорнокнижникам варто поводитися обережно поруч з Орґнілом, адже вся його увага зосереджена на тому, щоб вистежити й викорінити неконтрольоване демонічне скверніння в межах Дуротару.",["faction:Horde"]="Орґніл дбає, щоб, поки Орда дивиться назовні й будує нову державу, її серце не випорожнили зсередини культисти.",["race:Orc"]="Для молодих орків Орґніл — передова лінія проти демонічної зарази, що колись поневолила клани; він нагадує новобранцям, якої пильності вимагає чистота нової батьківщини."},sec={{t="Вартівник Гострого Пагорба",b="На Гострому Пагорбі Орґніл Соулскар узяв на себе похмурий обов'язок вистежувати підривну діяльність і підступні загрози по всьому Дуротару. Поки патрулі бійців дивляться назовні — на плацдарми Альянсу та загони кентаврів-нападників, — Орґніл зосереджений на гнилі, що визріває зсередини. Він збирає донесення розвідників з усього краю, складаючи докупи докази обрядового скверніння та потаємних зібрань."},{t="Полювання на рештки Ради Тіней",b="Головний клопіт Орґніла — таємне відродження культу Палаючого Клинка, чиї чорнокнижники ховаються в печерах на кшталт Череп-скелі. Знаючи, яке спустошення магія Скверни принесла орківському народові в минулих поколіннях, Орґніл не дозволить поклонінню демонам знову закріпитися біля Оргріммара. Він посилає довірених новобранців убивати культистів, збирати обрядові талісмани й радитися з місцевими відлюдниками та шаманами, як-от Марґоз, щоб зрозуміти, яка темна магія тут діє."}},fp="15,308,21.388.0,37.458.1,23.216.0,41.210.0,41.233.0,35.101.0,37.240.0,37.175.0"}
P.entries["npc:ormak-grimshot"] = {n="Ормак Ґрімшот",s="Ормак Ґрімшот — досвідчений орк, наставник мисливців у Залі Мисливця в Долині Честі Оргріммара. У супроводі вірного вовка Ґрімфанґа він навчає молодих мисливців Орди вистежування, стрільби та єднання з дикими звірами.",h="Ормак Ґрімшот — досвідчений орк, наставник мисливців у Залі Мисливця в Долині Честі Оргріммара.",kw={"ормак ґрімшот","мисливець","наставник","зала мисливця","долина честі","оргріммар","вовк"},ang={["class:Hunter"]="Ормак — необхідний наставник для мисливців Орди, що проводить їх крізь обов'язки приборкання й утримання вірного тваринного супутника.",["race:Orc"]="Відображаючи класичні орчі навички виживання, Ормак показує, як орки працюють пліч-о-пліч із вовками й тутешніми хижаками, боронячи Дуротар."},sec={{t="Майстер полювання",b="Ормак Ґрімшот, що стоїть у Залі Мисливця в Долині Честі, — наріжний камінь бойового вишколу слідопитів і стрільців Орди. Разом зі своїм супутником-вовком Ґрімфанґом Ормак передає основи дисципліни, потрібної, щоб вижити в суворих нетрях Калімдору. Оркам і тролям-мисливцям, що прибувають після випробувань у Дуроторі, він дає важливі настанови щодо священного мистецтва приборкання диких звірів і керування ними, щоб кожен мисливець створив тривкий зв'язок зі своїм тваринним партнером."}},fp="14,255,18.508.0,22.169.0,32.134.0,27.133.0,39.149.0"}
P.entries["npc:pilot-bellowfiz"] = {n="Пілот Беловфіз",s="Пілот Беловфіз, якого ласкаво звуть «Фіззером», — дворфійський водій, що служить на Складі Стілґрила в Дун Мороґу. Як член Облогової Бригади Айронфорджа, він відповідає за обслуговування й виведення в поле важких дворфійських бойових машин, зокрема власної облогової машини Джетстім.",h="Пілот Беловфіз, якого ласкаво звуть «Фіззером», — дворфійський водій, що служить на Складі Стілґрила в Дун...",kw={"пілот беловфіз","фіззер","джетстім","облогова бригада","склад стілґрила","облогова машина","дун мороґ"},ang={["profession:Engineering"]="Для дворфійських і гномських майстрів Беловфіз — вершина практичної польової інженерії: він тримає потужні облогові машини на ходу в крижаній гірській погоді.",["race:Dwarf"]="Беловфіз утілює гордість механізованих бригад Айронфорджа, показуючи інженерну майстерність і важку вогневу міць, що бережуть Каз Модан."},sec={{t="Володар Джетстіма",b="Пілот Беловфіз, що служить на Складі Стілґрила просто біля людних зал Айронфорджа, — механічний хребет дворфійського війська. Керуючи потужною облоговою машиною Джетстім, Беловфіз проводить дні, налаштовуючи деталі, добуваючи необхідні запчастини й тримаючи машину в бойовій готовності. Разом зі своїм товаришем Пілотом Стоунґіром Беловфіз без упину обговорює конструкції машин, броньові плити й потужність двигунів, пильнуючи, щоб механізована вогнева міць гірського королівства лишалася неперевершеною в усьому Каз Модані."}},fp="15,281,22.539.0,23.194.0,34.176.0,35.144.0,37.204.0"}
P.entries["npc:pilot-hammerfoot"] = {n="Пілот Гаммерфут",s="Пілот Гаммерфут — дворфійський пілот облогової машини з Облогової Бригади Айронфорджа, що служить біля гірських перевалів між Дун Мороґом і Лох Моданом. Стривожений за побратима-пілота, що зник у пагорбах, він шукає охочих шукачів пригод, щоб знайти друга й помститися за нього. Його присутність підкреслює небезпеки, з якими стикаються дворфи на високих альпійських хребтах.",h="Пілот Гаммерфут — дворфійський пілот облогової машини з Облогової Бригади Айронфорджа, що служить біля...",kw={"пілот гаммерфут","облогова бригада","гільдельве","дробкіготь","застава північної брами","помста","лох модан"},ang={["faction:Alliance"]="Допомога Гаммерфуту убезпечує важливі розвідувальні застави вздовж головного шляху, що з'єднує Дун Мороґ і Лох Модан.",["race:Dwarf"]="Гаммерфут утілює люте побратимство горян Айронфорджа, які не дозволять, щоб убивство полеглого брата лишилося без відповіді."},sec={{t="Очі в горах",b="Облогові машини Айронфорджа — гордість його Облогової Бригади, але вести їх суворою гірською місцевістю вкрай ризиковано. Пілот Гаммерфут, що служить на Заставі Північної Брами над кордоном між Дун Мороґом і Лох Моданом, стереже машини пілотів і пильнує гірські перевали. Коли пілот зникає, знайти його швидко стає першочерговою справою — особливо коли довколишніми пагорбами никають дикі звірі."},{t="Помста за товариша",b="Гаммерфут був близьким другом Пілота Морі Гільдельве, побратима-пілота облогової машини, який розбив свою машину на крутому схилі, коли двоє шукали рідкісну руду, а тоді пішов далі сам пішки. Дізнавшись, що Гільдельве на смерть пошматував Дробкіготь, величезний крижанокігтий ведмідь, Гаммерфут змінює буденну прикордонну варту на особисту помсту, вимагаючи відплати звірові, винному в смерті його друга."}},fp="16,346,21.428.0,18.424.1,24.215.0,36.132.0,54.223.0,33.238.0"}
P.entries["npc:pilot-stonegear"] = {n="Пілот Стоунґір",s="Пілот Стоунґір, на прізвисько «Стоун», — дворф, механік і водій Облогової Бригади Айронфорджа, що служить на Складі Стілґрила. Він керує грізною облоговою машиною Троллплоу й невтомно працює, щоб поліпшити її хід і броню. Шукачі пригод, що мандрують Дун Мороґом, часто допомагають йому добувати рідкісні матеріали, щоб його бойова машина лишалася боєздатною.",h="Пілот Стоунґір, на прізвисько «Стоун», — дворф, механік і водій Облогової Бригади Айронфорджа, що служить на...",kw={"пілот стоунґір","стоун","троллплоу","облогова бригада","склад стілґрила","облоговий танк","механік"},ang={["profession:Engineering"]="Інженери оцінять відданість Стоунґіра польовим доробкам Троллплоу, що врівноважують убивчу бойову ефективність з ергономікою для пілота.",["profession:Mining"]="Шахтарі постачають життєво важливі сирі руди й нестабільні підземні поклади, які потрібні Стоунґіру, щоб кувати посилене обшиття й боєприпаси.",["race:Dwarf"]="Стоунґір утілює дворфійську любов до важкої сталі, ревучих двигунів і трощення гірських ворогів під масивними залізними гусеницями.",["race:Gnome"]="Гноми, що працюють разом з Облоговою Бригадою, знаходять у Стоунґірі споріднену душу: він завжди радо майструє експериментальні конструкції й підвищує віддачу."},sec={{t="Володар Троллплоу",b="Серед гуркітливих котлів і брязкітливих гусениць Складу Стілґрила Пілот Стоунґір служить Айронфорджу як гордий водій Облогової Бригади. Його гордість і радість — Троллплоу, важкий облоговий танк, збудований, щоб трощити ворожі лави. Стоунґір ставиться до своєї машини серйозно, знаючи: у запалі бою життя водія цілком залежить від міцності шестерень, плит і тиску пари. Він невпинно шукає, як підвищити й бойову ефективність Троллплоу, і повсякденну придатність до життя його тісної кабіни."},{t="Винахідництво й металургія",b="Як і багато дворфійських та гномських механіків на складі, Стоунґір рідко вдовольняється заводськими характеристиками. У вільний час він часто сперечається про інженерні схеми з товаришами на кшталт Пілота Беловфіза й Пілота Гаммерфута. Чи то женучись за чутками про екзотичні руди, чи то вистежуючи нестабільні мінерали для посиленого обшиття й боєприпасів, Стоунґір покладається на завзятих новобранців, які вирушать у засніжену пустку й небезпечні печери Дун Мороґу по припаси."}},fp="15,364,23.524.0,24.475.0,23.221.0,33.138.0,22.211.0,41.175.0,35.200.0,36.252.0"}
P.entries["npc:priestess-anetta"] = {n="Жриця Анетта",s="Жриця Анетта — людська клірикиня Святого Світла, що служить в Абатстві Нортшира. Як член Братства Нортшира, вона доглядає поранених учнів і навчає новоприбулих жерців їхніх перших священних обрядів.",h="Жриця Анетта — людська клірикиня Святого Світла, що служить в Абатстві Нортшира.",kw={"жриця анетта","жрець","святе світло","абатство нортшира","цілителька","наставниця"},ang={["class:Priest"]="Для молодих людей-жерців, що починають у Нортширі, Жриця Анетта — ваша найперша наставниця: вона підтверджує ваше святе покликання й учить спілкуватися зі Світлом напряму.",["faction:Alliance"]="Анетта втілює незмінне духовне осердя Альянсу: вона дбає, щоб новобранці, поранені на захисті Долини Нортширу, вижили й продовжили боротьбу."},sec={{t="Опікунка вірних",b="Жрицю Анетту можна знайти на першому поверсі Абатства Нортшира, у його тихому бібліотечному крилі. Серед загрози бандитів Дефіас і кобольдів, що турбують долину, Анетта невтомно доглядає поранених новобранців, яких приносять з поля. Вона — опора Братства Нортшира: дбає, щоб ті, хто б'ється за абатство, відновлювалися тілом і духом милістю Святого Світла."},{t="Настанова жерцям-новачкам",b="Окрім обов'язків польової цілительки в обителі, Анетта — головна наставниця людей-жерців-початківців. Новачки, що приходять з освяченим листом-рекомендацією, шукають її, щоб опанувати основи віри: спрямовувати святі слова на зцілення плоті й випускати караюче сяйво, щоб відганяти зло. Під її проводом молоді послушники готуються нести Світло за усамітнені стіни Нортширу."}},fp="16,228,22.438.0,22.405.0,24.230.0,34.179.0,47.237.0,29.171.0"}
P.entries["npc:priestess-josetta"] = {n="Жриця Джозетта",s="Жриця Джозетта — людська наставниця жерців на верхньому поверсі корчми «Лев'яча Гордість» у Ґолдширі. Віддана тому, щоб вести новачків Святого Світла далі після їхніх перших випробувань у Нортширі, вона наставляє молодих жерців у вірі, відданості й практичному служінні.",h="Жриця Джозетта — людська наставниця жерців на верхньому поверсі корчми «Лев'яча Гордість» у Ґолдширі.",kw={"жриця джозетта","жрець","ґолдшир","лев'яча гордість","святе світло","наставниця"},ang={["class:Priest"]="Джозетта — важлива рання наставниця для молодих жерців, що покидають Нортшир: вона дає основне навчання заклинань і настанови, як утілити обітниці зцілення в практичне служіння.",["faction:Alliance"]="Джозетта зміцнює хребет Альянсу в Елвінні, дбаючи, щоб тутешні захисники мали духовну й цілющу підтримку, потрібну для охорони серця королівства.",["race:Human"]="Люди-жерці знайдуть у порадах Джозетти знайомі вчення Церкви Світла — вона допомагає посвятити їх у молитовні традиції предків."},sec={{t="Світоч у Ґолдширі",b="Поки багато хто зі святими обітницями проводить дні у величних соборах чи усамітнених монастирях, Жриця Джозетта служить просто серед простого люду Лісу Елвінн. Зі своїх скромних покоїв нагорі в гамірній корчмі «Лев'яча Гордість» вона дбає про духовне здоров'я подорожніх, вартових і тутешніх робітників, доводячи, що служіння Святому Світлу потребує присутності всюди, де серця шукають розради."},{t="Настанова молодим послушникам",b="Джозетта відіграє важливу роль для жерців-початківців, що завершили перше навчання в Абатстві Нортшира. Вона навчає їх практичної суті їхнього покликання, посилаючи в довколишню околицю допомагати пораненим вартовим і втішати стражденних. Через ці завдання вона наголошує: обов'язки клірика — не просто вивчити слова молитви, а діяльно спрямовувати Світло, щоб зцілювати зламаний світ."},{t="Тихий жаль",b="Попри непохитну відданість, Джозетта несе в собі тінь смутку щодо власного життєвого вибору. У юності їй забракло сміливості ступити на широкі дороги й дослідити Азерот — вона обрала безпеку знайомої землі. Хоч вона й задоволена своїм священним служінням у Ґолдширі, вона часто закликає молодих учнів, що переступають її поріг, бути сміливішими за неї й нести свою віру на далекі рубежі."}},fp="17,270,21.418.0,22.429.0,14.412.0,35.146.0,39.184.0,59.220.0,55.182.0,55.197.0,40.139.0"}
P.entries["npc:ragnar-thunderbrew"] = {n="Раґнар Тандербрю",s="Раґнар Тандербрю — дворфійський бровар і співвласник уславленої Ґуральні Тандербрю в Хараносі. Відомий по всьому Дун Мороґу тим, що подає фірмові Кабанячі ребра в пивному соусі своєї родини, він невпинно працює, щоб у людній корчмі всього вистачало, а відвідувачі лишалися задоволеними.",h="Раґнар Тандербрю — дворфійський бровар і співвласник уславленої Ґуральні Тандербрю в Хараносі.",kw={"раґнар тандербрю","бровар","ґуральня тандербрю","харанос","кабанячі ребра","корчма","ґрімбуз тандербрю"},ang={["profession:Cooking"]="Раґнар уславився родинним рецептом Кабанячих ребер у пивному соусі від Тандербрю, тож це корисне знайомство для кухарів-початківців, які прагнуть опанувати ситні дворфійські корчемні страви.",["race:Dwarf"]="Для дворфів, що проходять через Дун Мороґ, корчма Раґнара — дім удалині від дому, де подають найкращий ель і найкращі ребра, які лише може запропонувати клан."},sec={{t="Опора гостинності Хараноса",b="У Ґуральні Тандербрю в Хараносі Раґнар Тандербрю дбає про кулінарну славу закладу поряд із броварським ремеслом своєї родини. Ґуральня — центральне місце зустрічі для місцевих горян, мандрівних шукачів пригод і гномів-біженців, що тікають із Гномреґану. Головний його обов'язок — готувати уславлені родинні Кабанячі ребра в пивному соусі, ситну страву Дун Мороґу, тушковану в міцному дворфійському елі. Та підтримувати постачання стало важко: його звичний постачальник м'яса записався до Королівської армії, і Раґнар тепер залежить від мандрівних горян і мисливців, які приносять на кухню свіжі боки скельних вепрів."},{t="Спадок Тандербрю",b="Ім'я Тандербрю — синонім дворфійського хмільного й корчемної культури по всіх землях Айронфорджа. Раґнар тримає родинну ґуральню на ходу, відколи його старший брат Ґрімбуз Тандербрю кілька жнив тому зник у п'яному чаду, боронячи ревно бережену броварську спадщину родини від суперників на кшталт Барліброю. Серед неспокійних відвідувачів, зниклих ліній постачання й галасливих корчемних суперечок Раґнар твердо тримає руку на кранах, пильнуючи, щоб жоден мандрівник не покинув Харанос із порожнім кухлем чи порожнім шлунком."}},fp="18,264,32.668.0,22.541.0,26.187.0,36.187.0,47.197.0,36.131.0"}
P.entries["npc:razzle-sprysprocket"] = {n="Раззл Спрайспрокет",s="Раззл Спрайспрокет — гномський інженер і пілот, що мешкає в Хараносі в Дун Мороґу. Відомий технічним майструванням разом з Оззі Тоґлвольтом, він залучає мандрівників, щоб ті допомагали рятувати розкидані гномські механізми й деталі по засніжених пагорбах.",h="Раззл Спрайспрокет — гномський інженер і пілот, що мешкає в Хараносі в Дун Мороґу.",kw={"раззл спрайспрокет","гном","інженер","пілот","харанос","оззі тоґлвольт","гномреґан"},ang={["profession:Engineering"]="Інженери знайдуть у Раззлі споріднену душу: його проєкти показують тонку межу між блискучим гномським винаходом і вибуховим прорахунком.",["race:Gnome"]="Для гномів-вигнанців, що проходять через Дун Мороґ, Раззл утілює незгасний винахідницький дух і рішучість відбудувати й повернути втрачене після падіння Гномреґану."},sec={{t="Майстрування в Хараносі",b="Після трагедії в Гномреґані Раззл Спрайспрокет знайшов притулок серед заметів Дун Мороґу й облаштував майстерню в Хараносі. Уславлений серед колег як пілот-рекордсмен із хистом до тонких механічних деталей, Раззл працює разом з інженером Оззі Тоґлвольтом. Їхні зусилля часто спрямовані на повернення гіромеханізмів і зубчастих збірок, які загубили чи розтягли під час утечі з їхньої опроміненої батьківщини."},{t="Оборона майстерні",b="Життя в Дун Мороґу для гнома-винахідника далеко не мирне. Між дикими звірами замерзлих хребтів і набігами місцевих тролів Морозогривів експерименти Раззла часом призводили до хаотичних пригод — як-от коли він переплутав цокотливі бомби з годинниковим механізмом зі звичайними вибуховими снарядами. Попри такі інженерні халепи, він лишається відданим тому, щоб гномські пристрої працювали, а втрачені дива Гномреґану повернулися."}},fp="19,253,21.451.0,23.425.0,27.160.0,45.183.0,37.122.0,54.186.0"}
P.entries["npc:remy-two-times"] = {n="Ремі \"Двічі\"",s="Ремі «Двічі» — людський крамар, що нині живе в селищі Ґолдшир. Його батьківщина — Гори Редріджу, а впізнати його легко за дивною звичкою повторювати кінці речень. Він має ділові інтереси по всьому Лісі Елвінн: торгує товарами й платить шукачам пригод за сировину на кшталт золотого пилу.",h="Ремі «Двічі» — людський крамар, що нині живе в селищі Ґолдшир.",kw={"ремі двічі","крамар","ґолдшир","золотий пил","редрідж","мурлоки"},ang={["faction:Alliance"]="Для новобранців Альянсу, що прибувають у Ґолдшир, Ремі пропонує нескладні завдання, які допомагають усунути місцеві загрози й водночас дають швидку монету.",["profession:Mining"]="Рудокопи, що працюють у копальнях Фарґодіп і Яшмовій, часто перетинаються з Ремі, який залюбки торгується за золотий пил, зібраний у кобольдів, що там заполонили."},sec={{t="Крамар із дивною звичкою",b="Працюючи з Ґолдширу, Ремі «Двічі» — заповзятливий торговець, що прийшов на захід із суворих земель Гір Редріджу. Вірний своєму прізвиську, Ремі має характерну мовну звичку: повторює останні слова своїх речень, зазвичай двічі. Попри кумедну манеру мовлення, він лишається тямущим крамарем, що хоче заробити серед дедалі більших негараздів Лісу Елвінн і охоче укладає угоди з мандрівними шукачами пригод."},{t="Справи в неспокійних водах",b="Кобольди заполонили тутешні золоті копальні, агресивні мурлоки обсіли береги річок, і звичайна торгівля в Елвінні зазнала тяжких збитків. Ремі вбачає нагоду там, де інші бачать лихо: він доручає шукачам пригод приносити йому кисети золотого пилу, зібраного зі шкідників у копальнях, і стежить за підозрілими пересуваннями мурлоків біля Кришталевого Озера."}},fp="16,343,28.449.0,27.381.0,29.153.0,37.104.0,49.158.0,37.118.0"}
P.entries["npc:renee-lauer"] = {n="Рене Лауер",s="Рене Лауер — корчмарка Таверни «Шибеничний Кінець» у Бріллі, що дає притулок, їжу й питво мандрівникам, які проходять Галявинами Тірісфалю. За життя вона була ревною капітанкою Багряного Хрестового Походу, і її криваве минуле скінчилося контрударом Відступників, який забрав життя і їй, і її небожеві.",h="Рене Лауер — корчмарка Таверни «Шибеничний Кінець» у Бріллі, що дає притулок, їжу й питво мандрівникам, які...",kw={"рене лауер","корчмарка","таверна шибеничний кінець","багряний хрестовий похід","брілл","стефан"},ang={["race:Undead"]="Рене — суворе нагадування про те, як швидко людські фанатики Багряного Хрестового Походу можуть опинитися по той бік могили й скинути стару догму, звільнившись від життєвих омань."},sec={{t="Від фанатички до корчмарки",b="До свого нежиття Рене була успішною капітанкою: Багряний Хрестовий Похід був її домом і вірою. Переконана, що Лордерон належить суто живим і суто людям, вона без докорів сумління вбивала нелюдів. Її фанатизм обернувся крахом, коли родичі її жертв вистежили табір, щоб помститися. Хоч її небіж Стефан і втрутився, сутичка привернула увагу Леді Сильвани Віндраннер і Варіматраса. Військо Відступників стерло табір: Стефана вбили, а Рене підняли в нежитті. Вражена тим, як її похід накликав загибель на власну рідню, вона цілком покинула ратне життя й узялася тримати Таверну «Шибеничний Кінець», сповнена рішучості плекати, а не вбивати."},{t="Послання для живих",b="Замість шукати помсти Відступникам, які її вбили, Рене спрямовує свій жаль на фанатизм, що прирік її родину. Щоразу, коли полонені багряні хрестоносці чи мандрівники опиняються у Бріллі, вона ділиться своєю історією, застерігаючи їх від безглуздої ненависті. Догму Хрестового Походу вона бачить як нескінченне коло різанини, що гарантує лише горе. Фанатики рідко слухають її порад, та Рене не полишає спроб переконати їх, пропонуючи гостинність і терплячі слова і бранцям, і відвідувачам."}},fp="11,296,24.661.0,24.516.0,19.155.0,45.188.0,24.228.0,53.235.0,46.152.0"}
P.entries["npc:rezlak"] = {n="Резлак",s="Резлак — гоблін-підприємець і член Спілки Винахідників, що влаштувався на запорошених дорогах Дуротару на південь від Оргріммара. Він наймає мандрівних шукачів пригод, щоб повернути свої зниклі припаси й вичистити гнізда гарпій, які порушують зв'язок у краї.",h="Резлак — гоблін-підприємець і член Спілки Винахідників, що влаштувався на запорошених дорогах Дуротару на...",kw={"резлак","гоблін","спілка винахідників","гарпії","припаси","оргріммар","дуротар"},ang={["faction:Horde"]="Хоч Резлак стоїть просто за межами Оргріммара, він утілює суто ділові стосунки між нейтральними гоблінськими спілками та молодою Ордою.",["profession:Engineering"]="Як представник Спілки Винахідників, Резлак понад усе цінує механічну ефективність, практичні інструменти й урятовані деталі."},sec={{t="Прагматичний агент Спілки Винахідників",b="Умостившись біля доріг у каньйоні, що з'єднують Гострий Пагорб з Оргріммаром, Резлак представляє Спілку Винахідників — гоблінську спілку, зосереджену на інженерії, постачанні та промисловому прагматизмі. Резлака мало обходять фракційні тертя Калімдору, доки справи йдуть гладко. Коли люті гарпії Пилового Вітру напали на його вантажні каравани й порушили місцеві лінії зв'язку, Резлак лишився на місці, воліючи передоручити небезпечну роботу з винищення та повернення вантажу будь-якому перехожому, охочому заробити."}},fp="6,256,32.521.0,14.244.0,32.255.0,31.255.0,27.261.0"}
P.entries["npc:rhinag"] = {n="Рінаґ",s="Рінаґ — уражений отрутою троль із джунглів, що знайшов притулок у скромній оселі на Фермі Кам'яного Ікла в Дуроторі. Паралізований сильною отрутою тутешніх скорпіонів, він цілком залежить від перехожих мандрівників, які мають вчасно дістати йому ліки.",h="Рінаґ — уражений отрутою троль із джунглів, що знайшов притулок у скромній оселі на Фермі Кам'яного Ікла в...",kw={"рінаґ","скорпід","отрута","ферма кам'яного ікла","протиотрута","троль","дуротар"},ang={["race:Troll"]="Знайти родича, якого звалила тутешня звірина в посушливих пустках Дуротару, — суворе нагадування про випробування, що постають перед племенем Темного Списа, коли воно вибудовує дім поряд з Ордою."},sec={{t="Отруйна небезпека",b="Перетинаючи посушливі землі Дуротару, Рінаґ став жертвою лютого жала тутешнього Отрутохвостого Скорпіда. Здоланий сильною отрутою, він зумів доповзти до напівзруйнованого прихистку на Фермі Кам'яного Ікла. Знесилений і відрізаний від усіх, він може вижити лише завдяки комусь, хто пройде повз і матиме рішучість дістати протиотруту отрутохвоста, доки токсини не зробили свого."}},fp="6,233,16.386.0,14.158.0,26.106.0,21.204.0"}
P.entries["npc:ruul-eagletalon"] = {n="Руул Іглталон",s="Руул Іглталон — таурен, мешканець Села Бладгуф у Малгорі. Стоячи біля околиці поселення, він пильно стежить за місцевою звіриною, особливо за агресивними гарпіями Вітрофурій, що зазіхають на землі тауренів.",h="Руул Іглталон — таурен, мешканець Села Бладгуф у Малгорі.",kw={"руул іглталон","гарпії","вітряна лють","варта","село бладгуф","малгор"},ang={["race:Tauren"]="Руул уособлює практичну пильність, якої вимагають від шу'гало: новознайдений прихисток Малгору має лишатися безпечним від територіальних хижаків і крилатих нападників."},sec={{t="Сторож Бладгуфа",b="Руул Іглталон стоїть на варті в Селі Бладгуф і дбає про безпеку поселення, поки молоді сміливці прибувають із плато, де стоїть Табір Нарачі. Хоч Малгор — мирна батьківщина порівняно з посушливими просторами Пусток, територіальні хижаки й ворожі істоти постійно натискають на пасовища. Руул переймається загрозами, що блукають ближніми рівнинами, і зокрема направляє здібних мандрівників проти лютих гарпій Вітрофурій, які полюють на необачних кочівників і дичину."}},fp="15,235,20.473.0,23.154.0,60.156.0,35.125.0"}
P.entries["npc:rwag"] = {n="Рваґ",s="Рваґ — орк, наставник розбійників у Лігві, схованому в Долині Випробувань Дуротару. Він навчає новоприбулих орків і тролів мистецтва скрадання, хитрощів і брудного бою під пильним оком Орди.",h="Рваґ — орк, наставник розбійників у Лігві, схованому в Долині Випробувань Дуротару.",kw={"рваґ","розбійник","наставник","лігво","долина випробувань","нарток","скрадання"},ang={["class:Rogue"]="Для молодих орків і тролів-розбійників, що ступають у Долину Випробувань, Рваґ — найперший наставник в основах шахрайського ремесла, який навчає перших атакувальних прийомів і розгадування таємних шифрів.",["race:Orc"]="Рваґ утілює практичний, неприкрашений бік орчого виживання і доводить, що навіть у чесній новій Орді Тралла тіні й холодна сталь лишаються необхідними."},sec={{t="Тіні долини",b="Діючи глибоко в печері, відомій як Лігво, Рваґ вишколює розбійників-початківців, злодюжок і крадіїв, перш ніж ті вийдуть у широкий світ Дуротару. Поки нова Орда обстоює бойову честь і звитягу на полі бою, Рваґ розуміє, що хитрість, отрути й влучно встромлений кинджал лишаються безцінними знаряддями виживання в безжальній пустелі. Він пильно стежить за справами в Долині й плекає глибокі підозри щодо темних чаклунів, які також ховаються в печері, — надто щодо чорнокнижника Нартока."}},fp="4,229,21.514.0,12.159.0,22.152.0,48.195.0,30.220.0"}
P.entries["npc:sara-balloo"] = {n="Сара Баллу",s="Сара Баллу — убита горем дворфійська вдова, що мешкає у Військовому Кварталі Айронфорджа. Вона проводить дні в жалобі за покійним чоловіком, Саллі Баллу, чіпляючись за будь-яку згадку чи послання з його останніх днів служби.",h="Сара Баллу — убита горем дворфійська вдова, що мешкає у Військовому Кварталі Айронфорджа.",kw={"сара баллу","удова","саллі баллу","військовий квартал","айронфордж","король маґні бронзбірд","жалоба"},ang={["faction:Alliance"]="Принести звістку Сарі — означає дати розраду родині воїна Альянсу, показавши трагічні домашні реалії за битвами, що точаться по всьому Азероту.",["race:Dwarf"]="Для дворфів, що проходять через Військовий Квартал, Сара Баллу — болісне нагадування про особисту ціну, яку несуть родини, чиї рідні йдуть боронити Каз Модан."},sec={{t="Чування вдови",b="Серед людного Військового Кварталу Айронфорджа Сара Баллу — скорботний контраст до брязкоту зброї та бойових вправ. Її чоловік, Саллі Баллу, поліг у бою далеко від дому, лишивши її саму зі спогадами й невідступним горем. Для Сари розрада приходить лише через знайдені слова — останній лист, що несе відданість Саллі через гори з місця його загибелі."},{t="Поклик до пам'яті",b="Не бажаючи, щоб жертва її чоловіка тихо канула в забуття, Сара шукає більшого за просту втіху. Своїми щирими зверненнями вона просить Короля Маґні Бронзбірда подбати, щоб Саллі й подібних до нього полеглих воїнів офіційно вшанував і пам'ятав престол, аби ціна, яку платять звичайні дворфійські родини, ніколи не була забута."}},fp="11,223,15.401.0,21.343.1,19.132.0,29.121.0,29.148.1,38.163.1"}
P.entries["npc:sara-timberlain"] = {n="Сара Тімберлейн",s="Сара Тімберлейн — уміла кравчиня; її дім — Лісозаготівельний Табір Східної Долини на сході Лісу Елвінн. Відома винахідливим шиттям зі здобутих тканин, вона допомагає військовій справі, зшиваючи тканинний і шкіряний обладунок для війська Стормвінда.",h="Сара Тімберлейн — уміла кравчиня; її дім — Лісозаготівельний Табір Східної Долини на сході Лісу Елвінн.",kw={"сара тімберлейн","кравчиня","східна долина","льон","обладунок","бандани"},ang={["faction:Alliance"]="Віддалені поселення на кшталт Східної Долини напряму підтримують оборону королівства: тутешні ремісники постачають основний обладунок недостатньо забезпеченому війську Стормвінда.",["profession:Tailoring"]="Сара — зразок винахідливості прикордонних кравців: вона перетворює клапті грубого льону й бандитської тканини на практичний одяг на замовлення війська."},sec={{t="Шиття на рубежі",b="Біля маленької хатини на західному краю Лісозаготівельного Табору Східної Долини Сара Тімберлейн невтомно працює голкою й ниткою під стукіт сокир лісорубів. Попри віддаленість Східної Долини й нависання загрози від вовків і мурлоків, що никають довкола, вона дарує подорожнім гостинність і важливе ремесло. Її хист перетворювати клапті льону й здобуті бандани на міцне спорядження заслужив офіційне визнання: їй доручено постачати захисний тканинний і шкіряний обладунок просто війську Стормвінда."}},fp="15,251,26.559.0,23.216.0,33.171.0,41.222.0"}
P.entries["npc:seer-graytongue"] = {n="Віщун Ґрейтанг",s="Віщун Ґрейтанг — поважний старійшина тауренів і духовний провідник, що мешкає на Плато Червоної Хмари в Малгорі. Його пост — Табір Нарачі, де він випробовує молодих сміливців, які проходять свої найперші племінні випробування. Через такі ритуали, як Обряд Сили, він дбає, щоб молодь шанувала Матір-Землю, перш ніж ступити в широкий світ.",h="Віщун Ґрейтанг — поважний старійшина тауренів і духовний провідник, що мешкає на Плато Червоної Хмари в...",kw={"віщун ґрейтанг","старійшина","обряд сили","табір нарачі","плато червоної хмари","мати-земля"},ang={["class:Shaman"]="Духовні посвячені звертаються до старійшин на кшталт Ґрейтанга, щоб навчитися, як священний ритуал і випробування поєднують тілесну міць воїна з настановами предків.",["race:Tauren"]="Для молодих тауренів відвідини Віщуна Ґрейтанга — священний обряд посвяти, що поєднує особисту силу з вічними благословеннями Матері-Землі."},sec={{t="Провідник на плато",b="Віщун Ґрейтанг живе на Плато Червоної Хмари й служить раннім наставником для майбутніх сміливців і заклиначів із тауренів. Коли молоді шукачі пригод вирушають із Табору Нарачі, Ґрейтанг наглядає за ключовими кроками їхнього священного шляху, зокрема за Обрядами Матері-Землі. Випробовуючи їхню рішучість суворими рівнинами й небезпечними звірами Малгору, він прищеплює чесноти честі, терпіння й шани, які кожен справжній таурен має нести в доросле життя."}},fp="15,327,19.468.0,23.188.0,41.206.0,33.145.0"}
P.entries["npc:seer-ravenfeather"] = {n="Віщун Рейвенфезер",s="Віщун Рейвенфезер — наставниця шаманів із тауренів, що працює в Таборі Нарачі на Плато Червоної Хмари. Вона веде духовних учнів-початківців крізь їхні перші випробування, допомагаючи налаштуватися на голоси духів і землі Малгору.",h="Віщун Рейвенфезер — наставниця шаманів із тауренів, що працює в Таборі Нарачі на Плато Червоної Хмари.",kw={"віщун рейвенфезер","шаман","наставниця","поклик землі","сапта","табір нарачі","плато червоної хмари"},ang={["class:Shaman"]="Для молодих шаманів-тауренів Віщун Рейвенфезер — найперша провідниця в довгій подорожі, у якій вони вчаться єднатися зі стихіями й зв'язувати сили землі.",["race:Tauren"]="Як віщунка Табору Нарачі, вона уособлює глибоку духовну традицію, що є опорою суспільства тауренів, які облаштовуються на прабатьківській землі."},sec={{t="Провідниця на плато",b="Табір Нарачі — тихий прихисток, де Віщун Рейвенфезер терпляче навчає молодих тауренів, покликаних на шаманський шлях. Плато Червоної Хмари — священне місце випробувань, і Рейвенфезер дбає, щоб адепти-новачки зрозуміли свої обов'язки, перш ніж вирушити в ширші простори Малгору. Вона навчає їх засадничих обрядів, потрібних, щоб єднатися з силами стихій і шанувати Матір-Землю."},{t="Поклик стихій",b="Головний обов'язок Рейвенфезер — наглядати за першими духовними кроками шаманів-початківців і вести їх традиційним обрядом, відомим як Поклик Землі. Під її проводом посвячені готують церемоніальні сапти й шукають єднання з духами землі, що гніздяться в кам'яних виступах плато, — так кується зв'язок, що закріплює їхню стихійну магію."}},fp="17,232,19.436.0,24.353.0,25.158.0,43.156.0,35.124.0"}
P.entries["npc:senator-mehr-stonehallow"] = {n="Сенатор Мер Стоунгаллов",s="Сенатор Мер Стоунгаллов — політик Айронфорджа й член Ліги Дослідників, що перебуває в Кар'єрі Гол'Болар у Дун Мороґу. Замість сперечатися про політику в столиці, він вирушив на передову, щоб особисто наглядати за стримуванням місцевої навали трогів. Він залучає завзятих шукачів пригод, щоб винищити тварюк, перш ніж ті остаточно захоплять кар'єр.",h="Сенатор Мер Стоунгаллов — політик Айронфорджа й член Ліги Дослідників, що перебуває в Кар'єрі Гол'Болар у Дун...",kw={"сенатор мер стоунгаллов","сенатор","ліга дослідників","кар'єр гол'болар","троги","сенат айронфорджа","дун мороґ"},ang={["faction:Alliance"]="Стоунгаллов дає ранню нагоду побачити, як діє дворфійське керівництво, пропонуючи молодим героям Альянсу прямий громадянський обов'язок: убивати чудовиськ, щоб захистити трудовий люд.",["race:Dwarf"]="Для дворфів бачити обраного сенатора по коліна в багні кар'єру, а не з кухлем елю у Високому Престолі Айронфорджа — приємний доказ справжньої дворфійської твердості."},sec={{t="Політик у ямах",b="Поки більшість членів Сенату Айронфорджа проводять дні в безпечному затишку великих кам'яних зал столиці, Сенатор Мер Стоунгаллов воліє діяти напряму. Як дворф, відданий і врядуванню, і історичним пошукам Ліги Дослідників, він розуміє практичні небезпеки, що загрожують королівству. Коли люті кам'янощелепі троги почали видиратися з глибокої скелі в Кар'єрі Гол'Болар, Стоунгаллов сам вирушив до копальні. Переконаний, що бюрократичне позерство не врятує робітників, він пропонує нагороду вправним мандрівникам, які винищать зухвалих трогів і повернуть кар'єр."}},fp="24,376,24.624.0,32.293.0,47.335.0,53.237.0,64.245.0"}
P.entries["npc:senir-whitebeard"] = {n="Сенір Вайтбірдий",s="Сенір Вайтбірдий — дворфський сановник і польовий агент, що стоїть біля Ґуральні Тандербрю в Хараносі. Як особливий посланець Сенату Айронфорджа, він має стежити за загрозами, що дедалі тісніше оточують Дун Мороґ. Його головне завдання — оцінити наступ тролів Морозогривів і доповідати про їхні пересування безпосередньо дворфському проводу.",h="Сенір Вайтбірдий — дворфський сановник і польовий агент, що стоїть біля Ґуральні Тандербрю в Хараносі.",kw={"сенір вайтбірдий","посланець","сенат айронфорджа","харанос","морозогриви","розвідка"},ang={["faction:Alliance"]="Новобранці Альянсу, що проходять через Дун Мороґ, допомагають Сенірові вберегти серце земель Айронфорджа від того, щоб його відрізали повстання тутешніх тролів.",["race:Dwarf"]="Для дворфів Сенір уособлює бюрократичний, але необхідний зв'язок між захисниками порубіжжя та владою в Айронфорджі."},sec={{t="Посланець Сенату",b="Поки більшість мандрівників приходять до Хараноса заради гамірної корчми й славетного стауту, Сенір Вайтбірдий тут у службових справах. Його, представника, присланого самим Сенатом Айронфорджа, присутність показує, наскільки серйозно у високих залах ставляться до розхитування Дун Мороґу. Він — важлива ланка між місцевими розвідниками, що зустрічають небезпеку на засніженому порубіжжі, і законодавцями, які сперечаються про політику за кам'яною брамою міста."},{t="Око на Морозогривів",b="Найбільше Сеніра турбує дедалі зухваліша агресія тролів Морозогривів. Вигнані й доведені до відчаю серед морозних скель, тролі почали підступати небезпечно близько до дворфських поселень і доріг. Замість самому кидатися в бій, поважний посланець збирає відомості про позиції тролів, особливо навколо їхньої твердині, і складає ретельні звіти, щоб воєначальники Айронфорджа могли завдати рішучого удару."}},fp="16,377,19.432.0,22.434.0,24.191.0,32.239.0,52.235.0,46.205.0,36.221.0,28.179.0"}
P.entries["npc:sentinel-arynia-cloudsbreak"] = {n="Вартова Аринія Клаудзбрейк",s="Вартова Аринія Клаудзбрейк — охоронниця, нічна ельфійка, що перебуває в тихих гаях Галявини Оракула на Тельдрассилі. Їй доручено стежити за священною рівновагою північного віття, і вона насторожено пильнує зачаровані води галявини й лісову звірину.",h="Вартова Аринія Клаудзбрейк — охоронниця, нічна ельфійка, що перебуває в тихих гаях Галявини Оракула на...",kw={"аринія клаудзбрейк","вартова","галявина оракула","тельдрассил","дарнасус","альянс","гарпії"},ang={["faction:Alliance"]="Аринія уособлює пильність калдорейських Вартових, що тримають оборону життєво важливої лісової твердині Альянсу в Калімдорі.",["race:NightElf"]="Для молодих нічних ельфів, що дорослішають на Тельдрассилі, допомога Вартовій Клаудзбрейк дає практичний досвід захисту дикої рівноваги їхньої нової батьківщини."},sec={{t="Сторожа Галявини Оракула",b="Аринія Клаудзбрейк служить у війську Вартових в одному з найвідлюдніших і наймістичніших закутків Тельдрассила — на Галявині Оракула. Серед прадавніх дерев і неземних джерел вона несе варту далеко від гамірних вулиць Дарнасуса, дбаючи, щоб святість дикого краю лишалася непорушеною."},{t="Негаразди на галявині",b="Попри священне народження Тельдрассила, повзуча незлагода почала збурювати його створінь. Аринія покладається на перехожих шукачів пригод і молодих нічних ельфів, щоб дослідити тутешні негаразди — дивну поведінку звірини галявини й містичні явища довкола зачарованих джерел."}},fp="27,268,27.297.0,20.290.0,35.195.0,38.126.0,46.186.0,44.125.0,40.178.0,55.182.0"}
P.entries["npc:shadow-priest-sarvis"] = {n="Жрець Тіні Сарвіс",s="Жрець Тіні Сарвіс стоїть у зруйнованій каплиці Похоронного Подзвону — один із головних провідників щойно пробуджених Відступників. Він знайомить свіжих мерців з їхньою похмурою дійсністю, посилаючи їх винищувати безтямну нежить і збирати відомості про місцеві загрози. Під прапором Леді Сильвани Сарвіс невтомно ліпить із розгублених мерців дисциплінованих слуг Відступників.",h="Жрець Тіні Сарвіс стоїть у зруйнованій каплиці Похоронного Подзвону — один із головних провідників щойно...",kw={"жрець тіні сарвіс","похоронний подзвін","каплиця","відступники","пробудження","погибель","тінь"},ang={["class:Priest"]="Сарвіс утілює те, як Відступники прийняли магію тіні: темний наставник у каплиці, позбавленій Святого Світла.",["race:Undead"]="Сарвіс — один із найперших голосів, які ви чуєте, прокинувшись у могилі; він ставить вас на шлях служіння Темній Леді."},sec={{t="Пастир щойно пробуджених",b="У тінистій каплиці Похоронного Подзвону Жрець Тіні Сарвіс чекає на тих, хто щойно вигрібся з могили. Пробудження душі Відступника — струс і жах: багато хто одразу втрачає розум у безтямному шалі чи відчаї. Сарвіс — опора, що дає мету щойно воскреслим. Він доручає новобранцям добивати шкутильгаючі безтямні трупи, які блукають цвинтарем, і посилає їх убезпечувати межі Похоронного Подзвону від Погибелі, що насувається."},{t="Убезпечення Похоронного Подзвону",b="Окрім того, що Сарвіс призвичаює новобранців, він наглядає за важливою місцевою обороною від невідступних загроз у Галявинах Тірісфалю. Він координує стримування сил Погибелі, що промацують околиці Похоронного Подзвону. Спрямовуючи новачків на здобуття важливих відомостей і бойові випробування, Сарвіс дбає, щоб містечко лишалося укріпленим бастіоном Відступників."}},fp="20,390,30.491.0,19.340.0,28.176.0,38.114.0,51.201.0"}
P.entries["npc:shanda"] = {n="Шанда",s="Шанда — жриця й наставниця, нічна ельфійка, що перебуває в порожнистому стовбурі Алдрассила в Тінедолі. Служачи Сестринству Елуни, вона навчає жерців-новачків із нічних ельфів основних молитов, оберегів та обрядів Місячної Богині. Її провід допомагає молодим послушникам урівноважити світло Елуни з обов'язками захисту Тельдрассила.",h="Шанда — жриця й наставниця, нічна ельфійка, що перебуває в порожнистому стовбурі Алдрассила в Тінедолі.",kw={"шанда","жриця","наставниця","сестринство елуни","елуна","алдрассил","тінедол"},ang={["class:Priest"]="Для жерців — нічних ельфів, що починають шлях у Тінедолі, Шанда — найперша наставниця, яка дарує священні слова, святі сигіли й провід у ласці Елуни.",["race:NightElf"]="Шанда уособлює тривку традицію Сестринства Елуни, дбаючи про духовне здоров'я калдорейської молоді, що робить перші кроки на Тельдрассилі."},sec={{t="Послушниця Місячної Матері",b="Стоячи в тихому святилищі Алдрассила, Шанда — одна з перших духовних провідниць молодих нічних ельфів, відданих Елуні. Поки друїди доглядають коріння й віття Тельдрассила наяву, жриці на кшталт Шанди дбають, щоб духовне серце калдореїв лишалося прив'язаним до Білої Леді. Вона навчає нових посвячених спрямовувати місячну ласку на зцілення й захисні обереги, готуючи їх до зустрічі зі скверною, що повзе у віття Світового Дерева."},{t="Провід для нових посвячених",b="Коли молоді жерці пробуджуються до свого покликання в Тінедолі, їх спрямовують до Шанди довести відданість і вивчити перші молитви. Обрядами на кшталт «В ім'я Елуни» вона випробовує їхню рішучість і дає їм благословенне вбрання та основні замовляння. Під її проводом учні дізнаються, що жриця калдореїв має бути і лагідною рукою для поранених, і непохитним щитом проти тіней."}},fp="6,348,26.491.0,21.422.0,14.218.0,43.197.0,24.150.0,40.176.0"}
P.entries["npc:shari-stilwell"] = {n="Шарі Стілвелл",s="Шарі Стілвелл — наставниця паладинів Відступників, що перебуває в поселенні Брілл на Галявинах Тірісфалю. Носячи прізвище, спільне з помітними постатями Східних Королівств, вона навчає тих Відступників, що беруть на себе мантію святих воїнів. Її присутність знаменує рідкісну й незвичну дисципліну серед нежиті під рукою Королеви Баньші.",h="Шарі Стілвелл — наставниця паладинів Відступників, що перебуває в поселенні Брілл на Галявинах Тірісфалю.",kw={"шарі стілвелл","паладин","наставниця","брілл","джордан стілвелл","світло"},ang={["class:Paladin"]="Для паладинів Відступників, що починають свій шлях на Галявинах Тірісфалю, Шарі Стілвелл — головна наставниця й провідниця у Бріллі.",["race:Undead"]="Шарі Стілвелл віддзеркалює трагічне розколювання родин, спричинене Третьою війною: вона стоїть наставницею-нежиттю, поки її можлива рідня живе далеко на півдні."},sec={{t="Маяк у Бріллі",b="Серед позначених пошестю будівель Брілла Шарі Стілвелл вирізняється як наставниця святих воїнів Відступників. Хоч святе Світло для нежиті нестерпно болісне, Шарі веде молодих Відступників, які витримують цей болісний шлях. Вона допомагає новачкам, що шукають опори на Галявинах Тірісфалю, у перших тренуваннях і звиканні, скеровуючи тих, хто хоче посісти своє місце в королівстві Відступників."},{t="Узи імені Стілвелл",b="Шарі носить те саме прізвище, що й кілька живих постатей, розсіяних по південних королівствах, — зокрема Дафна, Мерісса й уславлений коваль Джордан Стілвелл. Чи відірвало її від цієї рідні падіння Лордерону, чи їх пов'язує лише далеке споріднення — лишається невимовленою трагедією спустошення, яке принесла Погибель."}},fp="14,338,17.419.0,25.324.0,22.197.0,34.111.0,36.213.0,41.267.0"}
P.entries["npc:shelene-rhobart"] = {n="Шелін Робарт",s="Шелін Робарт — наставниця шкіряного ремесла Відступників, що працює при дорозі на Галявинах Тірісфалю. Облаштувавшись на заставі Вартових Смерті, вона постачає вичинені шкури й навчає шкіряного ремесла, підтримуючи військові й господарські зусилля Відступників по всіх уражених землях.",h="Шелін Робарт — наставниця шкіряного ремесла Відступників, що працює при дорозі на Галявинах Тірісфалю.",kw={"шелін робарт","шкіряне ремесло","наставниця","застава","виготовлення","тірісфаль"},ang={["race:Undead"]="Шелін утілює прагматичний підмурок ремесла Відступників: завдяки їй місцеві захисники належно споряджені попри розклад і спустошення Тірісфалю."},sec={{t="Ремесло для Відступників",b="Шелін Робарт провадить своє ремесло на заставі Вартових Смерті — форпості на південний схід від Брілла, при головній дорозі до руїн Лордерону. Навіть у нежитті практичні ремесла лишаються конче потрібними для виживання й війни. Шелін працює зі шкурами звірів, здобутими з хижаків, що никають Тірісфалем, і береться за виготовлення з грубих шкур броні, ременів і похідного спорядження для місцевих патрулів Відступників, які протистоять і Погибелі, і багряним хрестоносцям."}},fp="15,275,25.447.0,33.145.0,37.188.0,30.281.0"}
P.entries["npc:skorn-whitecloud"] = {n="Скорн Вайтклауд",s="Скорн Вайтклауд — літній мисливець-таурен, що мешкає в Селі Бладгуф серед хвилястих рівнин Малгору. Він допомагає молодим мисливцям зрозуміти свій зв'язок із хижаками цієї землі й виручає мандрівників, що натрапляють на небезпеки, які чигають у Малгорі.",h="Скорн Вайтклауд — літній мисливець-таурен, що мешкає в Селі Бладгуф серед хвилястих рівнин Малгору.",kw={"скорн вайтклауд","мисливець","рівнинний бродяга","мелор стоунгуф","село бладгуф","малгор"},ang={["class:Hunter"]="Для молодих мисливців-тауренів Скорн Вайтклауд дає перші настанови у вистежуванні прудких хижаків на кшталт рівнинного бродяги, зміцнюючи духовну гармонію полювання.",["race:Tauren"]="Скорн — приклад відданості родини Вайтклаудів, яка дає прихисток, зброю й практичну мудрість розкиданим поселенням Малгору."},sec={{t="Провідник золотих рівнин",b="Скорн Вайтклауд, що живе в Селі Бладгуф у Малгорі, — старий мисливець, який тепер навчає мисливських звичаїв. Його головна роль — прищеплювати шану до диких створінь рівнин. Він випробовує майбутніх мисливців, посилаючи їх по кігті хитрих рівнинних бродяг Малгору, які потім показують Мелору Стоунгуфу в Тандер Блафі, — так ті, хто бере до рук лук чи спис, усвідомлюють рівновагу між хижаком і здобиччю."},{t="Пильність до неприродного",b="Окрім звичайних мисливських обов'язків, Скорн лишається пильним до дивних порушень у савані. Коли з'являються неприродні загрози — як-от сліди демонічної скверни на звірині рівнин, — Скорн допомагає відтворити, що сталося, і дбає, щоб племена Малгору не втрачали пильності перед злими силами, які прокрадаються в їхню прабатьківську домівку."}},fp="16,259,28.453.0,31.364.1,36.110.0,44.260.0,27.197.0,59.149.0"}
P.entries["npc:solm-hargrin"] = {n="Солм Гарґрін",s="Солм Гарґрін — наставник розбійників, що служить в Анвілмарі в Долині Холодного Хребта. Прагматичний дворф, який цінує честь серед злодіїв, він навчає дворфійських і гномських пройдисвітів-новачків мистецтва підступу. Він твердо вірить, що таємні оперативники стануть життєво важливими, коли геополітична напруга по всьому Азероту розпалиться.",h="Солм Гарґрін — наставник розбійників, що служить в Анвілмарі в Долині Холодного Хребта.",kw={"солм гарґрін","розбійник","наставник","анвілмар","долина холодного хребта","підступ","честь серед злодіїв"},ang={["class:Rogue"]="Для дворфів і гномів, що роблять перші кроки в тіні, Солм Гарґрін дає базовий вишкіл і розшифровує ваші найперші накази гільдії.",["race:Dwarf"]="Солм утілює менш звичний дворфійський шлях, доводячи, що скраданню, хитрості й тихій сталі в Дун Мороґу є не менше місця, ніж важкій броні й сокирам."},sec={{t="Наставник у тінях",b="У дворфійській твердині Анвілмар Солм Гарґрін стежить за засніженими перевалами Долини Холодного Хребта гострим, розважливим оком. Поки Айронфордж здебільшого покладається на грубу силу своїх горян і воїнів, Гарґрін розуміє, що деякі загрози вимагають тихішого, гострішого дотику. Він вітає розбійників-початківців і дворфійського, і гномського роду, розшифровує для них закодовані послання й муштрує їх у ключових прийомах на кшталт Потрошіння. Понад усе Гарґрін обстоює кредо професійної вірності й честі серед злодіїв, готуючи учнів до дедалі хиткішого світу, де долю народів часто вирішують непомітні ножі."}},fp="12,316,23.652.0,20.211.0,48.247.0,49.235.0,49.194.0"}
P.entries["npc:sten-stoutarm"] = {n="Стен Стаутарм",s="Стен Стаутарм — практичний дворфський постачальник і кур'єр, що стоїть біля Анвілмара в Долині Холодного Хребта. Він відповідає за спорядження новобранців і місцеву пошту, дбаючи, щоб молоді горяни лишалися в теплі, ситими й поінформованими попри суворі гірські умови.",h="Стен Стаутарм — практичний дворфський постачальник і кур'єр, що стоїть біля Анвілмара в Долині Холодного...",kw={"стен стаутарм","постачальник","пошта","анвілмар","долина холодного хребта","спорядження"},ang={["faction:Alliance"]="Зв'язок через Перевал Холодного Кряжа вкрай важливий для тренувальних угідь Айронфорджа, і поштова мережа Стена тримає долину сполученою з усім Альянсом.",["race:Dwarf"]="Стен утілює просту й щиру гостинність Дун Мороґу: він дбає, щоб його родичі були вбрані в товсту шкіру й нагодовані, перш ніж вирушать у сніги.",["race:Gnome"]="Оскільки гномські біженці навчаються в Анвілмарі разом із дворфами, Стен ставиться до них із тими самими практичними вимогами: доручає доставити пошту й споряджає проти негоди."},sec={{t="Рука допомоги серед снігів",b="Стен Стаутарм стоїть майже в самому серці Долини Холодного Хребта — одне з перших привітних облич, яке дворфські та гномські новобранці бачать, вийшовши з корчми Анвілмара. Поки долина відрізана зимовими хуртовинами й оточена небезпеками, Стен бере на себе клопіт спорядити зелених учнів міцним одягом, перш ніж вони замерзнуть або непідготовленими заблукають у заметах."},{t="Тримати зв'язок",b="Окрім того, що шиє зимове вбрання з місцевих вовчих шкур, Стен виконує обов'язки неофіційного поштмейстера Долини Холодного Хребта. Він приймає листи, передані через небезпечний Перевал Холодного Кряжа, і розносить службові руни, записки та накази наставникам класів по всій улоговині, щоб воїни, жерці й маги-новачки отримували свої настанови попри ворожих трогів, які перекрили тунелі."}},fp="13,292,26.364.0,22.403.0,21.189.0,43.240.0,34.244.0,52.160.0,30.185.0,63.192.0"}
P.entries["npc:supervisor-raelen"] = {n="Наглядачка Рейлен",s="Наглядачка Рейлен керує заготівлею деревини в Лісозаготівельному Таборі Східної Долини на східному краю Лісу Елвінн. Вона відповідає за тутешніх робітників, дотримання щоденних норм вирубки й за те, щоб заготовлена деревина безпечно потрапляла в ланцюги постачання Стормвінда.",h="Наглядачка Рейлен керує заготівлею деревини в Лісозаготівельному Таборі Східної Долини на східному краю Лісу...",kw={"наглядачка рейлен","лісозаготівля","східна долина","деревина","лісоруби","маршал паттерсон"},ang={["faction:Alliance"]="Підтримання запасів деревини королівства необхідне, щоб живити оборону й будівництво Стормвінда, тож норми Рейлен життєво важливі для військової справи."},sec={{t="Табір за графіком",b="У серці табору, біля Маршала Паттерсона й возів із деревиною, Наглядачка Рейлен керує робітниками, яким доручено заготовляти ліс для королівства. Лісозаготівельний Табір Східної Долини стоїть на кордоні з Горами Редріджу, і керувати ним — чималий клопіт: від узгодження роботи втомлених лісорубів до боротьби зі звіриною й бандитами, що загрожують нормам видобутку. Попри небезпеки довколишніх лісів, Рейлен зосереджена на одному — щоб деревину зібрали, обробили й зв'язали для перевезення."}},fp="17,285,28.547.0,25.201.0,35.147.0,54.200.0,63.194.0"}
P.entries["npc:tallonkai-swiftroot"] = {n="Таллонкай Свіфтрут",s="Таллонкай Свіфтрут — нічний ельф, мешканець Доланаара на Тельдрассилі. Стурбований скверною, що зароджується й отруює велике гілля, він залучає молодих шукачів пригод повертати зачаровані реліквії та стримувати нечисті сили, що мучать ліс.",h="Таллонкай Свіфтрут — нічний ельф, мешканець Доланаара на Тельдрассилі.",kw={"таллонкай свіфтрут","доланаар","тельдрассил","ловці снів","фурболги","фероцитас","скверна"},ang={["class:Druid"]="Турботи Таллонкая зосереджені на реліквіях, що безпечно прив'язують розум до Смарагдового Сну, тож його прохання глибоко стосуються духовних традицій друїдів.",["race:NightElf"]="Таллонкай Свіфтрут утілює пильність, потрібну, щоб захистити Тельдрассил у його вразливі перші роки; він просить молодих калдореїв викорінити скверну, що пускає коріння в їхній новій домівці."},sec={{t="Вартовий Доланаара",b="Живучи в кронах Доланаара, Таллонкай Свіфтрут пильно стежить за довколишніми лісами. Як і багатьох нічних ельфів під гіллям новорослого Світового Дерева, його тривожить неприродне збурення живності та лиховісні тіні, що збираються на околицях поселень."},{t="Загрози в кронах",b="Таллонкай спрямовує шукачів пригод проти нечистих сутностей, що порушують спокій Тельдрассила. Його турбують зіпсуті ловці снів, створені, щоб захищати сплячих друїдів; люті фурболги-Вузлошкіри, що піддаються темній недузі; і зіпсуті містики Вузлошкірів на чолі з Фероцитасом, Пожирачем Снів. Для Таллонкая очищення від цих збурень — ключ до захисту крихкої домівки калдореїв."}},fp="19,238,22.323.0,21.396.0,27.158.0,37.113.0,31.211.0,44.242.0,33.210.0,52.159.0"}
P.entries["npc:tannok-frosthammer"] = {n="Таннок Фростгаммер",s="Таннок Фростгаммер — дворфійський мешканець, якого можна знайти в Ґуральні Тандербрю біля Хараноса в Дун Мороґу. Він тривожно чекає на крам із Долини Холодного Хребта, глибоко стурбований тим, що напади трогів перерізали дороги до Анвілмара.",h="Таннок Фростгаммер — дворфійський мешканець, якого можна знайти в Ґуральні Тандербрю біля Хараноса в Дун...",kw={"таннок фростгаммер","дворф","ґуральня тандербрю","харанос","припаси","троги","гендс спрінґспрокет"},ang={["faction:Alliance"]="Затримані партії Таннока показують, як навіть поселення в серці краю, як-от Харанос, відчувають напругу від дедалі частіших набігів трогів.",["race:Dwarf"]="Для дворфів, що залишають Анвілмар заради широкого світу, доставити припаси Танноку до Ґуральні Тандербрю — один із найперших кроків у серце Дун Мороґу."},sec={{t="Перерізана лінія постачання",b="Перебуваючи при Ґуральні Тандербрю в Хараносі, Таннок Фростгаммер пильно стежить за прибуттям доставок і місцевими новинами. Раптовий наплив трогів, що заполонили Перевал Холодного Кряжа, перервав звичне сполучення з Долиною Холодного Хребта, і Таннок утратив регулярний зв'язок із поселенням в Анвілмарі. Покладаючись на кур'єрів на кшталт гнома-майстра Гендса Спрінґспрокета, щоб ті переправляли життєво важливі припаси й новини небезпечним засніженим перевалом, Таннок утілює тиху тривогу, яку поділяють багато Бронзбірдів, поки підземні загрози підповзають до їхніх порогів."}},fp="18,250,21.582.0,36.138.0,45.209.0,46.180.0"}
P.entries["npc:tarindrella"] = {n="Тариндрелла",s="Тариндрелла — дріада, що пильнує затишні ліси Тінедолу в Тельдрассилі. Як Дочка Кенарія вона тісно працює із захисниками — нічними ельфами, досліджуючи неприродну скверну, що вражає звірину Світового Дерева.",h="Тариндрелла — дріада, що пильнує затишні ліси Тінедолу в Тельдрассилі.",kw={"тариндрелла","дріада","дочка кенарія","тінедол","мох скверни","ґрелли","вузлошкіри","тельдрассил"},ang={["class:Druid"]="Друїди високо шанують дріад як споріднених духів дикого краю, тож провід Тариндрелли щодо недуги Тельдрассила — нагальний заклик берегти рівновагу.",["race:NightElf"]="Для молодих нічних ельфів, що починають у Тінедолі, Тариндрелла — одна з перших дріад, яких вони зустрінуть; вона втілює прадавній союз між калдореями й дітьми Кенарія."},sec={{t="Дочка Кенарія в Тінедолі",b="Дріади — ревні доглядачки природи, народжені від напівбога Кенарія. Поки багато хто з них лишається в глибині прадавніх лісів Калімдору, як-от Ашенваль, Тариндрелла мешкає в захищеній долині Тінедолу на вітті Тельдрассила. Вона — важливий міст між дикими духами й молодими захисниками — нічними ельфами, що роблять перші кроки за межами Алдрассила. Її головна турбота — застаріла скверна, що повзе в ліс, тож вона доручає надійним шукачам пригод відганяти тутешніх шкідників і збирати підказки про корінь недуги."},{t="Дослідження недуги Тельдрассила",b="Попри велич Тельдрассила як нової корони народу нічних ельфів, його незаймані гаї ховають несподівану хворобу. Колись мирні фурболги покинули свої оселі, щоб згуртуватися в плем'я Вузлошкірів, а ґрелли й ґреллята, споганені лихим Мохом Скверни, заполонили пагорби довкола Тінедолу. Тариндрелла підозрює, що за цими змінами стоїть Мох Скверни, і велить посвяченим стати проти ґреллів і принести зразки, щоб спинити скверну, перш ніж та поглине святилище молодого гаю."}},fp="11,240,36.535.0,37.508.0,19.221.0,16.226.0,46.301.0,47.174.0"}
P.entries["npc:telf-joolam"] = {n="Телф Джулам",s="Телф Джулам — троль-шаман із джунглів, із племені Темного Списа, що наглядає за Святинею Приспаного Полум'я. Він проводить посвячуваних Орди крізь випробування, потрібні, щоб спілкуватися з мінливою стихією вогню й керувати нею.",h="Телф Джулам — троль-шаман із джунглів, із племені Темного Списа, що наглядає за Святинею Приспаного Полум'я.",kw={"телф джулам","шаман","троль","святиня приспаного полум'я","вогняний тотем","вогняна сапта","вогонь"},ang={["class:Shaman"]="Телф Джулам — ключова постать на вашому духовному шляху: він проведе вас крізь випробування Вогняної Сапти, щоб ви опанували свій Вогняний Тотем.",["faction:Horde"]="Оберігаючи священні стихійні святині по всьому порубіжжю, старійшини на кшталт Телфа зміцнюють духовний хребет нової Орди.",["race:Troll"]="Старійшина-хранитель із Темного Списа, що веде посвячуваних, показує, як глибоко троляча духовність сплелася з шаманським відродженням Орди."},sec={{t="Хранитель полум'я",b="Серед скель над порубіжжям Телф Джулам доглядає Святиню Приспаного Полум'я. На відміну від спокійної певності землі чи терплячої глибини води, духи вогню вимагають гострої дисципліни й непохитної зосередженості. Телф виступає розпорядником випробувань: він готує молодих шаманів довести свою гідність диким жаринам, перш ніж ті їх поглинуть."},{t="Шлях вогню",b="Під проводом Телфа посвячувані варять і п'ють обрядову Вогняну Сапту, що дарує смертним очам зір у незримі стихійні світи. Він посилає прохачів на скелясті вершини — просто до палаючих духів, — дбаючи, щоб кожен шаман, який здобуде полум'я, ніс у собі повагу до його ненаситного голоду, а не безоглядну гордість."}},fp="11,212,19.360.0,16.337.0,19.152.0,31.114.0,50.198.0,36.166.0,46.198.0,50.154.0"}
P.entries["npc:tenaron-stormgrip"] = {n="Тенарон Стормґріп",s="Тенарон Стормґріп — провідник, нічний ельф, що перебуває високо в Алдрассилі, центральному дереві Тінедолу. Він навчає молодих калдореїв недавньої історії їхнього народу й просить їх набрати води з місячного колодязя.",h="Тенарон Стормґріп — провідник, нічний ельф, що перебуває високо в Алдрассилі, центральному дереві Тінедолу.",kw={"тенарон стормґріп","алдрассил","тінедол","корона землі","місячний колодязь","гора гіджал","дарнасус"},ang={["class:Druid"]="Доручення Тенарона підкреслюють друїдську опіку, потрібну, щоб стежити за небаченим зростанням Тельдрассила й стерегтися прихованої скверни.",["race:NightElf"]="Для молодих нічних ельфів Тенарон Стормґріп — одне з найперших знайомств із громадськими й духовними обов'язками, потрібними, щоб Тельдрассил лишався живим і чистим."},sec={{t="Сторож Алдрассила",b="Умостившись на звивистих дерев'яних помостах Алдрассила, Тенарон Стормґріп — ранній наставник молодих нічних ельфів, що виходять із віття Тінедолу. Зі свого спостережного місця він стежить за здоров'ям тутешніх лісів і життєво важливих місячних колодязів, що їх живлять. Його роль — навчати новачків розуміти їхній глибокий духовний зв'язок зі Світовим Деревом."},{t="Корона Землі",b="Тенарон розпочинає подорож, відому як Корона Землі. Він посилає посвячених набрати фіалу води з місячного колодязя на північ від Алдрассила й розповідає їм, що сталося після Битви за Гору Гіджал. Подорож триває через Тельдрассил і далі, до Дарнасуса."}},fp="17,198,20.379.0,18.255.0,35.137.0,47.123.0,37.171.0,51.237.0,48.208.0,31.124.0"}
P.entries["npc:tharek-blackstone"] = {n="Тарек Блекстоун",s="Тарек Блекстоун — працьовитий майстер інструментів, що мешкає в Хараносі, в засніженому серці Дун Мороґу. Відомий тим, що постачає важке знаряддя місцевим ремісникам, головним своїм замовником він має Белдіна Стілґрілла зі Складу Стілґрила. Хоч він і постійно зайнятий ремеслом, він також надійна людина, до якої звертаються мандрівники, що шукають роботи довкола поселення.",h="Тарек Блекстоун — працьовитий майстер інструментів, що мешкає в Хараносі, в засніженому серці Дун Мороґу.",kw={"тарек блекстоун","майстер інструментів","коваль","харанос","белдін стілґрілл","склад стілґрила","інструменти"},ang={["profession:Blacksmithing"]="Для ковалів, що проходять через Харанос, Тарек — зразок щоденної праці робочого майстра інструментів, який штампує зносостійкі гайкові ключі й залізне кріплення, щоб дворфійська техніка не стояла.",["race:Dwarf"]="Тарек утілює міцний, самодостатній дух робочого люду Дун Мороґу, що тримає місцеву промисловість на ходу суцільною наполегливістю біля ковадла."},sec={{t="Заклопотаний майстер інструментів у Хараносі",b="Серед холодних заметів Хараноса Тарек Блекстоун без упину виготовляє надійне дворфійське знаряддя. Між ремонтом спорядження для місцевих і постачанням більших підприємств йому рідко випадає мить перепочинку. Його найбільший головний біль — і найнадійніший замовник — Белдін Стілґрілл, чий склад механоступів просто за містечком вимагає сталого потоку важких гайкових ключів, шестерень і змінного знаряддя. Щоб кузня працювала й доставки не затримувалися, Тарек часто наймає мандрівників переносити щойно готові ящики з інструментами на склад."},{t="Громадський діяч",b="Окрім ремесла біля ковадла, Тарек тішиться чималою повагою серед люду Дун Мороґу. Хоч він не має офіційного військового звання, його становище в містечку робить його доступним посередником для дрібних доручень, постачання й координації місцевих зусиль."}},fp="17,351,28.576.0,18.251.0,25.221.0,48.273.0,35.132.0,48.150.0"}
P.entries["npc:theocritus"] = {n="Теокрітус",s="Архімаг Теокрітус — дивакуватий чародій з людей, що живе на вершині Вежі Азори на сході Лісу Елвінн. Колись пов'язаний із Кірін-Тором Даларану, нині він живе незалежно, в оточенні слуг і магічних пристроїв для прозирання. Зі свого високого святилища Теокрітус спрямовує свої таємні таланти на нагляд за королівством і боротьбу зі своїм темним суперником — магом-відступником Морґантом.",h="Архімаг Теокрітус — дивакуватий чародій з людей, що живе на вершині Вежі Азори на сході Лісу Елвінн.",kw={"теокрітус","архімаг","вежа азори","морґант","кірін-тор","прозирання","ліс елвінн"},ang={["class:Mage"]="Теокрітус утілює життя чародія поза суворою ієрархією Даларану, показуючи, як самотні майстри облаштовують святилища й провадять прозирання на відстані.",["faction:Alliance"]="Хоч і дивакуватий та відсторонений, Теокрітус використовує своє таємне бачення й ресурси, щоб діяльно боронити східний Елвінн і Редрідж від чаклунів-відступників.",["race:Human"]="Протистояння Теокрітуса й Морґанта віддзеркалює два шляхи людського чаклунства: дисципліновану науку на захисті проти скверніння й темних амбіцій."},sec={{t="Господар вежі",b="Колись член престижного Кірін-Тору Даларану, Архімаг Теокрітус вирішив заснувати незалежну твердиню далеко на півдні, у королівстві Стормвінд. Він оселився у примітній Вежі Азори біля східної дороги на Редрідж. Теокрітус відомий дивацькими звичками та вигідним способом життя: він тримає численну челядь, зокрема багатьох слуг-гномів і власного кравця Морлі Еберлейна. Хоч він і тримається осторонь буденних клопотів місцевих селян, його присутність — важливий магічний щит східного Елвінну."},{t="Війна з Морґантом",b="Найбільший постійний клопіт Теокрітуса — занепалий маг Морґант, небезпечний чорнокнижник, що діє з Вежі Ілґалара в сусідніх Горах Редріджу. Вбачаючи в Морґанті і особистого ворога, і серйозну загрозу Стормвінду, Теокрітус присвятив місяці таємних досліджень, щоб його підірвати. За допомогою артефактів прозирання на кшталт Ока Азори Теокрітус стежить за діями лиходія і проникає в його думки. Він також працює над тим, щоб обернути творіння Морґанта проти нього самого: вивчає магічні підвіски гнолів Тіньової Шкури, сподіваючись передати таємний імпульс, здатний знерухомити всю зграю."}},fp="10,405,19.606.0,24.626.0,18.242.0,33.251.0,35.236.0,25.225.0,51.253.0,35.213.0"}
P.entries["npc:thorgas-grimson"] = {n="Торґас Ґрімсон",s="Торґас Ґрімсон — дворф, наставник мисливців, що служить в Анвілмарі в Долині Холодного Хребта. Загартований слідопит Дун Мороґу, він твердо вірить, що практичне виживання в крижаних пустищах — найкращий учитель для будь-якого стрільця-початківця.",h="Торґас Ґрімсон — дворф, наставник мисливців, що служить в Анвілмарі в Долині Холодного Хребта.",kw={"торґас ґрімсон","мисливець","наставник","анвілмар","долина холодного хребта","вистежування","виживання"},ang={["class:Hunter"]="Для дворфійських стрільців Торґас Ґрімсон часто найперший наставник, якого ви зустрічаєте: він дає ранні настанови з вистежування звірів і виживання в крижаній долині.",["race:Dwarf"]="Ґрімсон утілює витривалий, самодостатній дух горян Айронфорджа, які патрулюють замерзлі вершини Дун Мороґу."},sec={{t="Провідник на холоді",b="У кам'яних залах Анвілмара Торґас Ґрімсон вітає горян і розвідників-новачків, що роблять найперші кроки в суворих заметах Долини Холодного Хребта. Замість обтяжувати молодих мисливців сухими лекціями, Ґрімсон сповідує практичну філософію: справжня майстерність кується на крижаному вітрі, з луком чи рушницею в руці, вистежуючи суворих звірів Дун Мороґу на власні очі."}},fp="15,256,19.390.0,23.226.0,33.214.0,32.213.0,44.195.0"}
P.entries["npc:thorvald-deepforge"] = {n="Торвальд Діпфордж",s="Торвальд Діпфордж — дворфійський торговець зброєю, що стоїть біля прикордонного перевалу в Долині Королів. Він допомагає озброювати мандрівників і захисників, які стережуть важливий шлях між Дун Мороґом і Лох Моданом.",h="Торвальд Діпфордж — дворфійський торговець зброєю, що стоїть біля прикордонного перевалу в Долині Королів.",kw={"торвальд діпфордж","торговець зброєю","долина королів","лох модан","дун мороґ","зброя","перевал"},ang={["profession:Blacksmithing"]="Носячи уславлене родове ім'я Діпфордж, Торвальд торгує практичними, надійними залізними виробами, якими славляться дворфійські ковалі.",["race:Dwarf"]="Стоячи під моноліти предків у Долині Королів, Торвальд утілює незмінне ремесло й лінію постачання, що тримають кордони Каз Модану в безпеці."},sec={{t="Озброюючи східний перевал",b="Серед величних монументів Долини Королів Торвальд Діпфордж служить Альянсу як надійний торговець зброєю. Гірські перевали, що з'єднують серце Каз Модану з околишніми землями, потерпають від набігів трогів і блукаючої звірини, тож добре викувана сталь конче потрібна кожному горянину чи новобранцю в дорозі. Торвальд дбає, щоб ті, хто прибуває з Дун Мороґу чи прямує вглиб Лох Модану, мали клинки й сокири, потрібні для захисту дворфійських земель."}},fp="18,204,23.487.0,26.202.0,47.175.0,52.195.0"}
P.entries["npc:thotar"] = {n="Тотар",s="Тотар — бувалий орк, наставник мисливців у поселенні Гострий Пагорб у Дуротарі. Він навчає майбутніх розвідників і стрільців Орди прадавніх традицій вистежування, стрільби з лука та єднання з дикими звірами. Молодим оркам і тролям, що роблять перші кроки за межами Долини Випробувань, він дає основоположні обряди, потрібні, щоб опанувати сувору звірину Калімдору.",h="Тотар — бувалий орк, наставник мисливців у поселенні Гострий Пагорб у Дуротарі.",kw={"тотар","мисливець","наставник","орк","гострий пагорб","приборкання звірів","дуротар"},ang={["class:Hunter"]="Тотар — важлива віха для молодих мисливців Орди: він навчає життєво важливих обрядів приборкання звірів і володіння дикою природою, щойно новачки виходять зі стартових долин.",["faction:Horde"]="Як передовий наставник на Гострому Пагорбі, Тотар дбає, щоб розвідники й стрільці, які патрулюють кордони Дуротару, були дисциплінованими, пильними й міцно зрідненими з бойовими звірами.",["race:Orc"]="Тотар зберігає й передає традиційні орківські мисливські звичаї, щоб життя на Калімдорі й далі трималося на глибокій прадавній повазі до вистежування та звірів-супутників.",["race:Troll"]="Для мисливців Темного Списа, що вирушають із Села Сен'джин, Тотар дає важливі настанови, поєднуючи прадавні навички виживання Орди з хижими викликами Дуротару."},sec={{t="Наставник на Гострому Пагорбі",b="В укріпленому осередку Гострого Пагорба Тотар служить бувалим наставником для стрільців Орди. Поки новобранці опановують найперші основи в Долині Випробувань, саме Тотарові випадає вести мисливців, коли ті зустрічають суворішу хижу глушину Дуротару. Спираючись на традиції, передані крізь незліченні покоління орків, він навчає не лише влучності, а й глибшої поваги, потрібної, щоб жити поруч із найсмертоноснішими створіннями Калімдору й керувати ними."},{t="Приборкання дикої природи",b="Тотар відіграє вирішальну роль у залученні молодих мисливців до прадавнього мистецтва приборкання звірів. Через низку випробувань він посилає новачків у посушливі каньйони, щоб угамувати тутешніх звірів і порозумітися з ними — отруйних скорпідів, панцирних прибійних повзунів і хитрих вепрів. Проводячи цих молодих розвідників крізь священні обряди приборкання, Тотар дбає, щоб слідопити Орди будували з природою вірний зв'язок, а не просто намагалися підкорити її силою."}},fp="6,374,22.474.0,16.459.0,14.165.0,26.116.0,34.224.0,28.209.0,45.226.0,49.228.0"}
P.entries["npc:thran-khorman"] = {n="Тран Корман",s="Тран Корман — дворфійський наставник воїнів, що служить в Анвілмарі, у засніженій Долині Холодного Хребта. Він наглядає за базовою бойовою муштрою новоспечених воїнів, що виходять у Дун Мороґ.",h="Тран Корман — дворфійський наставник воїнів, що служить в Анвілмарі, у засніженій Долині Холодного Хребта.",kw={"тран корман","воїн","наставник","анвілмар","долина холодного хребта","муштра","вишкіл"},ang={["class:Warrior"]="Для дворфійських і гномських воїнів, що прокидаються біля Перевалу Холодного Кряжа, Тран — найперший майстер, який перевірить вашу витримку, вручить ваші початкові руни чи накази й навчить основ бойового виживання.",["race:Dwarf"]="Тран уособлює вперту, непохитну рішучість захисників Айронфорджа, що зберігають готовність навіть у мирний час, щоб королівство ніколи не було захоплене зненацька."},sec={{t="Муштрувальник Долини Холодного Хребта",b="Біля навчального майданчика Анвілмара Тран Корман має завдання перетворювати сирих дворфійських новобранців і гномів-гостей на дисциплінованих бійців. До кожного, кому бракує твердості для бою на передовій, він ставиться грубо й безкомпромісно. У його очах, хоч Третя війна й скінчилася, мир — лише ілюзія: троги наступають на Перевал Холодного Кряжа, а гори повні небезпек. Він вимагає невпинної практики з сокирою, булавою й щитом, щоб захисники Айронфорджа ніколи не притупилися."}},fp="13,213,31.528.0,21.197.0,28.221.0,51.239.0"}
P.entries["npc:tommy-joe-stonefield"] = {n="Томмі Джо Стоунфілд",s="Томмі Джо Стоунфілд — молодий фермер, затиснутий у гіркій родинній ворожнечі в серці Лісу Елвінн. Глибоко закоханий у Мейбелл Маклур, він мусить покладатися на тихі береги річки й таємні послання, щоб приховати їхній роман від ворожої рідні.",h="Томмі Джо Стоунфілд — молодий фермер, затиснутий у гіркій родинній ворожнечі в серці Лісу Елвінн.",kw={"томмі джо стоунфілд","мейбелл маклур","кохання","ферма стоунфілдів","ворожнеча","річка"},ang={["faction:Alliance"]="Для шукачів пригод Альянсу, що досліджують південний Елвінн, таємний роман Томмі Джо — скромне нагадування про тихе особисте життя, яке триває в тіні бандитства й політичних заворушень у краї."},sec={{t="Нещасливе кохання й ворожнеча",b="Стоячи на березі річки одразу на захід від Ферми Стоунфілдів, Томмі Джо Стоунфілд цілими днями дивиться через воду на садибу Маклурів. Стоунфілди й Маклури роками плекають ворожнечу, сварячись за землю, гордість і дрібні фермерські чвари. Та попри неприязнь, яку проповідують старші, Томмі Джо по вуха закохався в Мейбелл Маклур. Не маючи змоги зустрічатися відкрито, не викликавши обурення обох домів, він покладається на довірених посередників і співчутливу бабусю — Бабусю Стоунфілд, — щоб обмінюватися таємними записками й знаками прихильності."}},fp="20,246,19.588.0,28.156.0,38.139.0,46.160.0,37.172.0"}
P.entries["npc:tormus-deepforge"] = {n="Тормус Діпфордж",s="Тормус Діпфордж — дворфійський коваль, що працює в центрі Великої Кузні в Айронфорджі. Надійний ремісник, він координує постачання заліза й забезпечує озброєнням оборонні зусилля Альянсу по всьому Каз Модану й за його межами.",h="Тормус Діпфордж — дворфійський коваль, що працює в центрі Великої Кузні в Айронфорджі.",kw={"тормус діпфордж","коваль","велика кузня","айронфордж","залізо","лейкшир","поселення айронбенда"},ang={["profession:Blacksmithing"]="Для ковалів, що працюють біля Великої Кузні, Тормус — ключова ланка між сирими зливками й спорядженням війська на передовій.",["race:Dwarf"]="Гордий ремісник гірського королівства, Тормус показує готовність Айронфорджа плавити й доправляти зброю щоразу, коли союзники у Великому Альянсі кличуть на допомогу."},sec={{t="Майстер Великої Кузні",b="Просто біля ревучого вогню Великої Кузні Тормус Діпфордж наглядає за значними ковальськими роботами від імені клану Бронзбірдів. Окрім того, що сам кує сталь, Тормус — важливий контакт з постачання для ковалів і застав, яким потрібне сире залізо: він організовує припаси для обложених поселень на кшталт Лейкшира в Редріджі й координує дії з дворфійськими розкопками, як-от Поселенням Айронбенда в Лох Модані."}},fp="16,227,25.434.0,34.112.0,54.219.0,29.197.0"}
P.entries["npc:ukor"] = {n="Укор",s="Укор — орк-пеон, що відпочиває біля східної стежки за межами Долини Випробувань у Дуроторі. Прагнучи допомогти своєму народові, він ніс припаси аж із Гострого Пагорба — і виявив, що на тренувальних землях провізії й так удосталь.",h="Укор — орк-пеон, що відпочиває біля східної стежки за межами Долини Випробувань у Дуроторі.",kw={"укор","пеон","робітник","припаси","долина випробувань","гострий пагорб","ґроск"},ang={["faction:Horde"]="Для нових новобранців, що виходять зі своїх випробувань, допомога Укору — одна з перших нагод підтримати повсякденну логістику Орди між поселеннями.",["race:Orc"]="Орки-пеони несуть важку фізичну працю, на якій будується нова Орда, і Укор показує, що навіть скромні робітники щиро прагнуть підтримати воїнів Дуротару."},sec={{t="Доручення пеона",b="Поки більшість орків-пеонів проводять життя під пильним оком суворих наглядачів, рубаючи ліс чи тягаючи каміння, Укор, простий робітник, спробував прислужитися з власної волі. Чи то з наказу, чи то з натхнення віднести харчі з Гострого Пагорба новобранцям у Долині Випробувань, він здійснив небезпечний перехід червоними рівнинами Дуротару повз скорпідів і вепрів, що нишпорять довкола. Прибувши, він з'ясував, що Долина вже добре забезпечена і його пакунок нікому не потрібен. Виснажений і трохи зневірений, він сидить при дорозі й покладається на молодих шукачів пригод, щоб ті повернули невикористані припаси на північ, Корчмарю Ґроску."}},fp="4,233,15.612.0,12.114.0,53.223.0,43.176.0"}
P.entries["npc:undertaker-mordo"] = {n="Гробар Мордо",s="Гробар Мордо — доглядач склепу Похоронного Подзвону, найперше обличчя, яке бачать щойно пробуджені Відступники, розплющивши очі. Тим, хто прокидається, він каже, що Король-Ліч більше не має над ними влади, і відсилає їх на службу справі Відступників; тіла, які так і не ворухнулися, йдуть у вогонь.",h="Гробар Мордо — доглядач склепу Похоронного Подзвону, найперше обличчя, яке бачать щойно пробуджені...",kw={"гробар мордо","склеп","похоронний подзвін","пробудження","жрець тіні сарвіс","відступники"},ang={["race:Undead"]="Гробар Мордо — найперший, з ким ви розмовляєте, розплющивши очі у смерті; він спрямовує ваші перші непевні кроки на службі королеві Сильвані."},sec={{t="Пробудження в Похоронному Подзвоні",b="Доглядаючи склеп Похоронного Подзвону на Галявинах Тірісфалю, Гробар Мордо наглядає за мертвими, поки трупи вириваються з розтрощених лабет Погибелі. Кожному щойно звільненому з Відступників, що прокидається в холоді склепу, Мордо дає перший орієнтир у невпізнанному другому житті. Він оцінює їхній здоровий глузд, знайомить із дійсністю їхнього стану й одразу скеровує до служби під рукою королеви Сильвани Віндраннер."},{t="Ті, хто не прокидається",b="Не кожне тіло, принесене до склепу, прокидається. Мордо довго не чекає: трупи, що лишаються нерухомими, летять у вогонь, а тих, хто ворухнувся, зустрічають із сухим нетерпінням і без жодних церемоній. Кожного, хто підводиться при здоровому глузді, відсилають сходами вгору й дорогою далі — до каплиці, де на них чекає Жрець Тіні Сарвіс, який пояснює їхнє нове існування. Безтямні зомбі, що заполонили північ села, — клопіт Сарвіса, а не Мордо: саме жрець тіні посилає щойно піднятих нищити їх."}},fp="16,304,27.440.0,21.504.0,24.164.0,34.182.0,60.238.0,43.227.0"}
P.entries["npc:veron-amberstill"] = {n="Верон Амберстілл",s="Верон Амберстілл — дворфійський заводчик баранів, що мешкає на Ранчо Амберстілл на сході Дун Мороґу. Він доглядає витривалих гірських баранів, традиційних їздових тварин Айронфорджа, і пропонує їх умілим вершникам, які заслужили його довіру.",h="Верон Амберстілл — дворфійський заводчик баранів, що мешкає на Ранчо Амберстілл на сході Дун Мороґу.",kw={"верон амберстілл","барани","заводчик","ранчо амберстілл","їздові тварини","дун мороґ","айронфордж"},ang={["faction:Alliance"]="Союзники Айронфорджа, які хочуть опанувати їзду на гірському барані, мусять спершу довести відданість дворфійському королівству, щоб заслужити повагу Верона.",["race:Dwarf"]="Верон утілює глибоку спадщину вашого народу з гірськими звірами, надаючи звичайних і прудких баранів, на яких покладається кожен дворфійський шукач пригод, щоб долати Каз Модан."},sec={{t="Володар їздових тварин",b="Серед припорошених снігом пагорбів східного Дун Мороґу Верон Амберстілл наглядає за уславленим поголів'ям Ранчо Амберстілл. Гірські барани ідеально пасують до підступних схилів Каз Модану: твердо стоять на ногах і мають густу шерсть проти укусів гірських заметілей. Верон розводить і навчає цих звірів носити дворфійських розвідників, горян і мандрівних шукачів пригод. Поки своїм дворфам він охоче дає звичайних і прудких їздових тварин, чужинці мусять довести непохитну вірність престолу Айронфорджа, перш ніж він розлучиться з кимось зі свого дорогоцінного стада."}},fp="16,241,20.563.0,24.193.0,41.228.0,34.143.0,43.213.0"}
P.entries["npc:vesprystus"] = {n="Веспристус",s="Веспристус — майстер польотів, нічний ельф, що перебуває на пристані Селища Рут'теран біля підніжжя Тельдрассила. Він наглядає за сідалом вишколених гіпогрифів, що переносять мандрівників між великим Світовим Деревом і материковим Калімдором.",h="Веспристус — майстер польотів, нічний ельф, що перебуває на пристані Селища Рут'теран біля підніжжя...",kw={"веспристус","майстер польотів","гіпогрифи","селище рут'теран","тельдрассил","темне узбережжя","обердайн"},ang={["faction:Alliance"]="Веспристус — життєво важлива ланка для будь-якого мандрівника Альянсу, що прибуває на пристань Тельдрассила й потребує швидкої переправи до прибережного Темного Узбережжя.",["race:NightElf"]="Для молодих нічних ельфів — шукачів пригод, що вперше покидають Тельдрассил, Веспристус часто той, хто відправляє їх у політ назустріч першому погляду на материковий Калімдор."},sec={{t="Доглядач сідала Рут'терана",b="Умостившись біля південного підніжжя Тельдрассила в Селищі Рут'теран, Веспристус доглядає гіпогрифів, що з'єднують відокремлене ельфійське віття з рештою світу. Хоч магічний портал веде з Рут'терана просто до міста Дарнасус у кронах угорі, польоти на гіпогрифах дають швидку переправу до Темного Узбережжя й материка. Веспристус працює в злагоді з майстром польотів в Обердайні по той бік протоки, забезпечуючи безпечний шлях вартовим, посланцям і шукачам пригод, що вирушають у Калімдор."}},fp="10,231,30.511.0,36.250.0,36.220.0,56.205.0"}
P.entries["npc:vol-jin"] = {n="Вол'джин",s="Вол'джин — вождь тролів Темного Списа і майстерний мисливець тіней. Мешкаючи у Фортеці Ґроммаш поруч із Вождем Траллом, він є довіреним радником Орди й водночас працює над тим, щоб забезпечити своєму вигнаному народові постійний дім у Дуротарі.",h="Вол'джин — вождь тролів Темного Списа і майстерний мисливець тіней.",kw={"вол'джин","вождь","темний спис","тролі","мисливець тіней","фортеця ґроммаш","оргріммар"},ang={["faction:Horde"]="Поруч із Траллом Вол'джин — опора Нової Орди: він дає їй хитромудрі поради та люту відданість тролів із джунглів.",["race:Troll"]="Вол'джин — ваш вождь, що веде Темний Спис крізь вигнання й злигодні з духовною мудрістю та тактичною рішучістю."},sec={{t="Вождь Темного Списа",b="Вол'джин очолив плем'я Темного Списа після трагічної смерті свого батька Сен'джина на прадавньому острівному домі племені. Коли мурлоки, що поклонялися морській відьмі, та людські війська ледь не знищили відлюдне плем'я, втрутилися орки Тралла, і між двома народами зав'язався міцний зв'язок. Залишивши руїни своїх островів, Вол'джин присягнув своїми тролями Новій Орді й повів їх через Велике Море на Калімдор."},{t="Рада в Долині Мудрості",b="Хоч Темний Спис і заснував поселення в Дуротарі, внутрішні зради — насамперед віроломство Залазана на Островах Відлуння — змусили багатьох біженців перебратися на материк, у Село Сен'джин. Більшість часу Вол'джин проводить у Фортеці Ґроммаш в Оргріммарі, безпосередньо надаючи Траллу свою гостру стратегічну пораду та майстерність мисливця тіней. Із серця орківської столиці він наглядає за молодою Ордою, водночас прагнучи повернути своєму народові його законні землі."}},fp="7,245,26.432.0,31.465.0,15.219.0,24.117.0,37.296.0,53.269.0"}
P.entries["npc:vorn-skyseer"] = {n="Ворн Скайсір",s="Ворн Скайсір — мирний таурен, мешканець Табору Нарачі на Плато Червоної Хмари в Малгорі. Відпочиваючи серед наметів табору, він вітає молодих шукачів пригод, що починають свій шлях, і знайомить їх із місцевим життям.",h="Ворн Скайсір — мирний таурен, мешканець Табору Нарачі на Плато Червоної Хмари в Малгорі.",kw={"ворн скайсір","табір нарачі","гостинність","плато червоної хмари","таурени","малгор"},ang={["faction:Horde"]="Ворн — приклад спокійної та сталої вдачі рівнинних племен, що зібралися під проводом Кайрна Бладгуфа, аби збудувати постійний дім.",["race:Tauren"]="Для молодих тауренів на Плато Червоної Хмари Ворн Скайсір часто стає одним із перших знайомих, заспокійливих облич, що вітають їх перед кроком у ширше життя Малгору."},sec={{t="Привітне обличчя в Таборі Нарачі",b="Табір Нарачі на Плато Червоної Хмари має у Ворні Скайсірі неформального привітного господаря для молодих тауренів. Поки ті проходять обряди посвяти, перш ніж вирушити в ширші долини Малгору, Ворн дарує добре слово й гостинність і допомагає новоприбулим освоїтися в таборі."},{t="Відсторонений спостерігач",b="Ворн не воїн. Оборону табору він лишає його сміливцям, а сам веде тихе, неквапливе життя, задоволений тим, що пильнує мирні рівнини своєї батьківщини."}},fp="12,210,31.291.0,19.159.0,20.166.0,30.110.0,28.154.0"}
P.entries["npc:willem"] = {n="Віллем",s="Помічник Віллем — людський солдат війська Стормвінда, що стоїть просто перед Абатством Нортшира. Служачи під проводом Маршала Макбрайда, він — головний польовий зв'язковий, що скеровує новобранців на боротьбу з місцевими загрозами в Долині Нортширу. Його нагальна турбота — придушити дедалі більше вторгнення Братства Дефіас.",h="Помічник Віллем — людський солдат війська Стормвінда, що стоїть просто перед Абатством Нортшира.",kw={"помічник віллем","нортшир","абатство нортшира","дефіас","маршал макбрайд","новобранці"},ang={["class:Warrior"]="Новобранці-воїни знаходять у Помічникові Віллемі практичного польового зв'язкового, що спрямовує їхню воїнську силу на очищення від бандитів і відновлення ладу в королівстві.",["faction:Alliance"]="Віллем — перша точка дотику з внутрішньою безпекою Альянсу: він показує, як глибоко заворушення Дефіас загрожують навіть мирному серцю Елвінну.",["race:Human"]="Для людей, що виходять з Абатства Нортшира у світ, Помічник Віллем — часто найперший військовий офіцер, що вітає їх на службі королівству Стормвінд."},sec={{t="Вартовий біля абатства",b="Стоячи за кілька кроків від воріт Абатства Нортшира, Помічник Віллем утілює передову присутність війська Стормвінда в долині. Військо королівства розтягнуте по багатьох землях, тож місцева безпека тяжко лягає на маленькі загони на кшталт гарнізону Макбрайда. Віллем оцінює добровольців, що прибувають, і одразу дає їм завдання: допомагати тутешнім мешканцям і берегти околиці долини."},{t="Протистояння Дефіас",b="Найнагальніша турбота Віллема — зухвала діяльність Братства Дефіас. Бандити в червоних банданах вдерлися просто в Нортшир: крадуть припаси, залякують тутешніх фермерів на кшталт Міллі Осворт і закріплюються на довколишніх виноградниках і пагорбах. Віллем призначає винагороди за відомих горлорізів, як-от Ґаррик Педфут, щоб зламати їхнє керівництво, перш ніж вони захоплять землі абатства."}},fp="6,323,23.420.0,22.420.0,21.200.0,33.138.0,45.225.0,33.155.0,41.185.0,62.222.0"}
P.entries["npc:william-pestle"] = {n="Вільям Пестл",s="Вільям Пестл — алхімік з людей, що зупинився в корчмі «Лев'яча Гордість» у Ґолдширі. Разом із братом Морґаном він тримає аптеку в Торговому Кварталі Стормвінда. Він часто наймає мандрівних шукачів пригод збирати дивні реагенти — свічки кобольдів, водорості мурлоків і трави.",h="Вільям Пестл — алхімік з людей, що зупинився в корчмі «Лев'яча Гордість» у Ґолдширі.",kw={"вільям пестл","алхімік","аптека","ґолдшир","реагенти","лікер невидимості","ліс елвінн"},ang={["faction:Alliance"]="Вільям допомагає постачати Торговий Квартал Стормвінда життєво важливими ліками й дрібницями, покладаючись на новобранців Альянсу, що проходять через Ґолдшир, аби добути матеріали з навколишнього лісу.",["profession:Herbalism"]="Для травників, що мандрують через Ґолдшир, Вільям Пестл утілює практичний, торговий бік збирання рослин: він невпинно перетворює дике зілля й дивні водорості на корисні суміші."},sec={{t="Аптекар на виїзді",b="Поки його брат Морґан Пестл стоїть за прилавком аптеки Пестлів у Торговому Кварталі Стормвінда, Вільям працює з корчми «Лев'яча Гордість» у Ґолдширі. Перебування в Лісі Елвінн дозволяє йому тісно співпрацювати з місцевими збирачами й добувати сировину, якої повсякчас потребують міські крамниці. Він регулярно відправляє вантажі до столиці, щоб мешканці Стормвінда мали сталий доступ до цілющих мазей, настоянок і порошків."},{t="Дивовижні реагенти",b="Ремесло Вільяма часто вимагає незвичних складників, що виходять далеко за межі простих городніх трав. Він часто доручає новачкам збирати воскові свічки, які носять кобольди, що заполонили Елвінн, а також кришталеві водорості, відібрані в мурлоків Кришталевого Озера, просто на схід від Ґолдшира. Хоч такі суміші здаються непосвяченим химерними, Вільям наполягає, що ці дивні інгредієнти мають потужні алхімічні властивості."},{t="Зілля для юного кохання",b="Окрім звичного ремесла, Вільям — давній друг Мілдред Стоунфілд. Коли юні закохані Мейбелл Маклур і Томмі Джо Стоунфілд опиняються між своїми запекло ворогуючими фермерськими родинами, Вільям погоджується зварити Лікер Невидимості. Його напій на водоростях із місцевих вод дозволяє Мейбелл непомітно вислизнути й зустрітися з Томмі Джо."}},fp="14,300,17.463.0,16.405.0,27.380.1,22.199.0,34.82.0,41.174.0,35.175.1,54.180.0,58.173.1"}
P.entries["npc:yaw-sharpmane"] = {n="Яв Шарпмейн",s="Яв Шарпмейн — досвідчений тауренський наставник мисливців у Селі Бладгуф у Малгорі. Він веде молодих мисливців, що виходять із Табору Нарачі, й допомагає їм опанувати диких звірів прабатьківських рівнин.",h="Яв Шарпмейн — досвідчений тауренський наставник мисливців у Селі Бладгуф у Малгорі.",kw={"яв шарпмейн","мисливець","наставник","приборкання","звір","село бладгуф","малгор"},ang={["class:Hunter"]="Для тауренських мисливців, що залишають безпечне Плато Червоної Хмари, Яв Шарпмейн — незамінний наставник, який допоможе вам заприязнитися з вашим найпершим диким супутником.",["race:Tauren"]="Яв утілює шановану традицію Шу'хало — жити в злагоді з природою й шанувати духів диких звірів Малгору."},sec={{t="Провідник на рівнинах",b="Серед наметів і вогнищ Села Бладгуф Яв Шарпмейн служить Шу'хало як наставник у влучній стрільбі, вистежуванні та виживанні. Молодих мисливців, які довели свою вправність на Плато Червоної Хмари, посилають до Ява відточувати ремесло, щойно вони ступають на широкі рівнини Малгору."},{t="Опанування зв'язку",b="Найважливіша роль Ява — провести мисливців-новачків через прадавній обряд приборкання диких звірів. Він доручає посвячуваним заприязнитися з тутешньою живністю Малгору, перевіряючи їхнє терпіння й повагу до природної рівноваги, і лише тоді навчає, як доглядати й виховувати постійного супутника."}},fp="13,216,21.311.0,18.309.0,21.179.0,31.100.0,38.159.0,27.165.0,52.178.0,45.148.0"}
P.entries["npc:yvette-farthing"] = {n="Іветт Фартінґ",s="Іветт Фартінґ — мешканка Брілла з Відступників на Галявинах Тірісфалю, що живе в Таверні «Шибеничний Кінець» разом зі своїм батьком Коулменом. Хоч вона здається такою ж загартованою й відстороненою, як будь-хто з підданих Сильвани, у ній досі жевріє привид смертного кохання, яке обірвала Погибель.",h="Іветт Фартінґ — мешканка Брілла з Відступників на Галявинах Тірісфалю, що живе в Таверні «Шибеничний Кінець»...",kw={"іветт фартінґ","турман аґаманд","кохання","лист","таверна шибеничний кінець","млини аґаманда"},ang={["race:Undead"]="Іветт утілює глибокий душевний конфлікт, який переживають багато Відступників: боротьбу між невідступними людськими спогадами про кохання й гіркою, загартованою дійсністю нежиття."},sec={{t="Відлуння млинів",b="До того як Третя війна обернула Лордерон на руїну, Іветт кохала Турмана Аґаманда, одного зі спадкоємців квітучих Млинів Аґаманда. Коли чума Погибелі підступила, Іветт і її батько Коулмен благали Турмана покинути маєток і тікати разом із ними. Турман відмовився з відданості спадщині своєї родини. Зрештою обоє загинули й повстали в нежитті, та якщо Іветт знайшла місце серед вільних Відступників у Бріллі, то трагічна остаточна доля Турмана лишалася їй невідомою."},{t="Останнє прощання",b="Перш ніж млини захопили, Турман написав Іветт поспішного любовного листа, у якому розповів про зраду свого брата Девліна й оплакав свій вибір лишитися. Погибель перехопила послання, і воно загубилося серед руїн Млинів Аґаманда, доки його не знайшли шукачі пригод. Прочитавши передсмертне зізнання Турмана, Іветт на мить виявляє справжній смертний розпач, а тоді змушує себе повернутися до холодної відстороненості — з гіркотою, що таким давнім прив'язаностям немає місця в похмурій дійсності Відступників."}},fp="15,285,19.496.0,16.499.1,23.213.0,45.201.0,54.262.1,23.230.0"}
P.entries["npc:zaldimar-wefhellt"] = {n="Залдімар Вефгеллт",s="Залдімар Вефгеллт — людський наставник магів на верхньому поверсі корчми «Лев'яча Гордість» у Ґолдширі. Він навчає чарівників-початківців, що проходять Лісом Елвінн, перш ніж відправити їх до вищих практиків у Стормвінді.",h="Залдімар Вефгеллт — людський наставник магів на верхньому поверсі корчми «Лев'яча Гордість» у Ґолдширі.",kw={"залдімар вефгеллт","маг","наставник","ґолдшир","лев'яча гордість","таємна магія"},ang={["class:Mage"]="Для молодих людей-магів, що покидають Абатство Нортшира, Залдімар — перший наставник, якого ви зустрічаєте в ширшому світі: він навчає перших заклинань, перш ніж скерувати вас до Святилища Чародія в Стормвінді.",["faction:Alliance"]="Розташувавшись у гамірній корчмі «Лев'яча Гордість», Залдімар дбає, щоб чарівники Альянсу, які патрулюють Ліс Елвінн, мали доступ до магічного навчання без потреби одразу вирушати до Стормвінда."},sec={{t="Маг у Ґолдширі",b="Хоч корчма «Лев'яча Гордість» у Ґолдширі найбільше відома втомленими подорожніми, галасливими шукачами пригод і місцевими плітками, у її верхніх кімнатах живуть наставники різних ремесел. В одній із кімнат другого поверху Залдімар Вефгеллт навчає магів-новачків основ таємної магії, вогню й морозу. Щойно учень переростає його ранню науку, він посилає його на північ до Кварталу магів у Стормвінді — вчитися в Дженнеї Кеннон."}},fp="17,261,21.436.0,25.207.0,35.122.0,38.167.0,39.80.0"}
P.entries["npc:zarlman-two-moons"] = {n="Зарлман Ту-Мунс",s="Зарлман Ту-Мунс — шанований містик тауренів, що мешкає в Селі Бладгуф у центрі Малгору. Поки Бейн Бладгуф наглядає за щоденними земними справами селища, Зарлман веде його духовне життя й спілкування з духами. Він відіграє ключову роль у посвяті молодих тауренів у доросле життя через священний Обряд Видіння.",h="Зарлман Ту-Мунс — шанований містик тауренів, що мешкає в Селі Бладгуф у центрі Малгору.",kw={"зарлман ту-мунс","містик","обряд видіння","духи","село бладгуф","бейн бладгуф","малгор"},ang={["class:Shaman"]="Зарлман — зразок класичної шаманської традиції тауренів, що врівноважує єднання з духами й практичний провід племенем.",["faction:Horde"]="Перебуваючи в центральному осередку Малгору, Зарлман знайомить новоприбулих союзників Орди з глибокими духовними звичаями, що формують культуру тауренів.",["race:Tauren"]="Для шукачів пригод із тауренів Зарлман — неодмінний провідник, який допомагає вам завершити священні обряди юності й пробудити духовний зір."},sec={{t="Хранитель Незримого",b="У Селі Бладгуф провід поділений між тілесним і містичним. Бейн Бладгуф керує обороною та земними потребами поселення, але саме Зарлман Ту-Мунс підтримує гармонію світу духів. У культурі, глибоко вкоріненій у шані до Матері-Землі й мудрості предків, Зарлман слугує провідником між щоденними клопотами рівнин і позачасовими голосами минулого."},{t="Обряд Видіння",b="Найважливіший обов'язок Зарлмана перед народом — проводити Обряд Видіння, традиційне випробування, яке має пройти кожен таурен, що дорослішає. Навчаючи посвячених готувати священні напої й уважно слухати знамення предків, він допомагає молодим мисливцям, шаманам і воїнам відкрити свій призначений шлях і духів-провідників. Під його проводом посвячені засвоюють: тілесна сила на рівнинах мало важить без духовної ясності."}},fp="17,328,20.424.0,18.436.0,25.285.0,44.250.0,27.256.0,37.120.0,43.211.0,52.230.0"}
P.entries["npc:zarrin"] = {n="Заррін",s="Заррін — кулінарний наставник, нічний ельф, що перебуває в Доланаарі на вітті Тельдрассила. Доглядаючи відкрите вогнище за сільською корчмою, він навчає молодих нічних ельфів і гостей традиційних калдорейських способів куховарства.",h="Заррін — кулінарний наставник, нічний ельф, що перебуває в Доланаарі на вітті Тельдрассила.",kw={"заррін","кулінарія","наставник","вогнище","доланаар","корчма","тельдрассил"},ang={["profession:Cooking"]="Для шукачів пригод, що починають подорож у Тельдрассилі, Заррін — головний наставник, який учить обертати м'ясо диких звірів і зібрані дари лісу на поживні страви.",["race:NightElf"]="Заррін береже повсякденні калдорейські харчові звичаї, дбаючи, щоб традиційні смаки й способи жили далі під шатром Світового Дерева."},sec={{t="Хранитель вогнища Доланаара",b="Облаштувавшись за корчмою Доланаара, осторонь головної вулиці, Заррін доглядає відкритий вогонь, біля якого ділиться кулінарним мистецтвом калдореїв. Виживання в Тельдрассилі вимагає користуватися корінною рослинністю й звіриною велетенського дерева, і Заррін навчає тих, хто хоче прогодувати себе збиральництвом і домашніми стравами."}},fp="6,221,24.345.0,24.119.0,23.116.0,29.150.0"}
P.entries["npc:zenn-foulhoof"] = {n="Зенн Фаулгуф",s="Зенн Фаулгуф — сатир, що тиняється одразу на схід від Доланаара в Тельдрассилі. Він підходить до перехожих із проханнями про лісові складники, а тутешні нічні ельфи пильно за ним стежать.",h="Зенн Фаулгуф — сатир, що тиняється одразу на схід від Доланаара в Тельдрассилі.",kw={"зенн фаулгуф","сатир","доланаар","складники","жаба","тельдрассил","шахрай"},ang={["class:Druid"]="Втручання Зенна в дикі складники й свідоме поширення споганення прямо суперечить науці Кола Кенарія, яка прагне зберегти Тельдрассил незайманим.",["race:NightElf"]="Сатири — найбільша зрада калдорейського спадку. Бачити, як один із них розсівся на священному вітті Тельдрассила, — образа Елуні й духам дикого краю."},sec={{t="Інтриган у лісі",b="На відміну від більшості сатирів — відвертих ворогів на службі демонічних володарів, — Зенн Фаулгуф якось добився хисткого терпіння до себе одразу за Доланааром. Він підтримує дружню личину, запевняючи, що змінився або хоче торгувати нешкідливими лісовими складниками — іклами нічних шаблезубів, перами стригідних сов і павутинним шовком Вебвуда. Насправді ж він маніпулює довірливою молоддю, щоб добути складники для огидних обрядів. Рада Доланаара не дозволяє йому діяти безкарно: замість стратити його негайно, вона велить шукачам пригод принизити його, нагодувавши споганеним лісовим плодом, що на якийсь час обертає підступного сатира на нешкідливу жабу."}},fp="13,183,22.640.1,64.230.0,64.140.1,16.224.0"}
P.entries["npc:zjolnir"] = {n="Зйолнір",s="Зйолнір — троль Темного Списа, заводчик їздових тварин у Селі Сен'джин на південному узбережжі Дуротару. Він постачає навчених їздових рапторів Темному Спису та надійним чемпіонам Орди. Для тролів-вершників його стайня лютих, відданих звірів — предмет глибокої культурної гордості.",h="Зйолнір — троль Темного Списа, заводчик їздових тварин у Селі Сен'джин на південному узбережжі Дуротару.",kw={"зйолнір","раптори","їздові тварини","сен'джин","темний спис","заводчик","дуротар"},ang={["faction:Horde"]="Кожен воїн Орди, що доведе непохитну відданість племені Темного Списа, може заслужити привілей їхати в бій на одному з рапторів Зйолніра.",["race:Troll"]="Для тролів Темного Списа Зйолнір постачає прудких кігтистих звірів, що є осердям їхньої спадщини та бойових традицій."},sec={{t="Заводчик рапторів Темного Списа",b="Зйолнір, що порається біля загонів Села Сен'джин, доглядає лютих рапторів, яких тролі Темного Списа полюбляють як їздових тварин. Раптори норовливі й хижі від природи, тож вирощувати їх і сідлати для війни може лише досвідчена рука. Зйолнір охоче дає цих цінних звірів, слухняних свистку, тролям-побратимам, які опанували потрібне мистецтво верхової їзди. Чужинці з ширшої Орди спершу мають заслужити найвищу довіру племені Темного Списа, перш ніж Зйолнір подумає довірити їм когось зі своєї зграї."}},fp="7,289,32.501.0,25.154.0,23.200.0,36.192.0"}
P.entries["npc:zureetha-fargaze"] = {n="Зуріта Фарґейз",s="Зуріта Фарґейз — орчиня-наставниця в Долині Випробувань у Дуроторі, що стоїть поряд із Наглядачем Тазз'рілом. Пильна до скверни, вона спрямовує молодих новобранців Орди розслідувати й викорінювати темний вплив культу Палаючого Клинка, що ховається в долині.",h="Зуріта Фарґейз — орчиня-наставниця в Долині Випробувань у Дуроторі, що стоїть поряд із Наглядачем Тазз'рілом.",kw={"зуріта фарґейз","палаючий клинок","культ","долина випробувань","медальйон","скверна","дуротар"},ang={["class:Warlock"]="Чорнокнижники в Долині Випробувань рано стикаються з дорученнями Зуріти, маючи справу з дикими, оскверненими мерзенними фамільярами, пов'язаними з темними прикликаннями Палаючого Клинка.",["race:Orc"]="Для молодих орків, що роблять перші кроки у світ, Зуріта втілює невсипущу пильність, потрібну, щоб демонічна скверна минулого не отруїла їхню нову батьківщину."},sec={{t="Очі в долині",b="Поки Наглядач Тазз'ріл наглядає за працею й дисципліною молодих орків і тролів Темного Списа, Зуріта Фарґейз пильнує тонші, підступніші загрози. Культ Палаючого Клинка таємно проник у Долину Випробувань: він спотворює менших демонів і набирає сили в сусідній печері — Ковені Палаючого Клинка. Зуріта доручає неперевіреним шукачам пригод відібрати в культистів медальйони, щоб підтвердити їхню присутність і зруйнувати їхні перші задуми, перш ніж відправити загартованих новобранців далі, у Дуротар."}},fp="16,268,18.523.0,24.185.0,45.247.0,56.175.0"}
P.entries["quest:11"] = {n="Винагорода за гнолів Річколапів",s="Винагорода за гнолів Річколапів — офіційна угода від Помічника Рейнера з Гарнізону Вестбрук: винищити гнолів, що насуваються на західні кордони Лісу Елвінн. Військо Стормвінда пропонує винагороду за розмальовані нараменні пов'язки, зняті зі зграй Річколапів, що заполонили ліси й водойми.",h="Винагорода за гнолів Річколапів — офіційна угода від Помічника Рейнера з Гарнізону Вестбрук: винищити гнолів...",kw={"винагорода","гноли","річколапи","помічник рейнер","гарнізон вестбрук","нараменні пов'язки"},ang={["faction:Alliance"]="Прикордонні винагороди підносять вашу репутацію у війську Стормвінда й водночас убезпечують життєво важливі торгові шляхи через серце королівства.",["race:Human"]="Для людей королівства полювання на Річколапів — прямий внесок у захист рубежів Елвінну й підтримку перевантаженої варти корони."},sec={{t="Загроза на кордоні",b="Гарнізон Вестбрук охороняє важливе прикордоння між Лісом Елвінн і Вестфолом. Та виснажені сили гарнізону ледве стримують агресивний наплив гнолів Річколапів. Ці дикі створіння влаштували табори одразу на південь від сторожової вежі й далі на схід, довкола берегів Озера Кам'яного Кургану, підступивши так близько, що загрожують мирним подорожнім і тутешнім садибам."},{t="Ціна порядку",b="Не маючи змоги виділити регулярну піхоту, щоб прочесати ліси, Помічник Рейнер призначає винагороду за нападників. Щоб підтвердити вбивства, Рейнер вимагає доказу бойової перемоги — розмальованих нараменних пов'язок гнолів, знятих із убитих тварюк. Наймаючи мандрівних шукачів пригод і новобранців проріджувати зграю, гарнізон сподівається притупити наступ Річколапів, перш ніж ті затоплять західні марки."}},fp="21,288,22.425.0,18.382.0,52.192.0,60.236.0,38.117.0,28.216.0,55.214.0,37.177.0"}
P.entries["quest:111"] = {n="Поговори з бабусею",s="Це доручення посилає шукача пригод до Бабусі Стоунфілд від імені її онука Томмі Джо. Затиснутий у гіркій ворожнечі між родинами Стоунфілдів і Маклурів, Томмі Джо сподівається, що літня матріарх знає спосіб, як йому побачити Мейбелл Маклур.",h="Це доручення посилає шукача пригод до Бабусі Стоунфілд від імені її онука Томмі Джо.",kw={"бабуся стоунфілд","томмі джо","мейбелл маклур","ворожнеча","кохання","ферма"},ang={["faction:Alliance"]="Поки Стормвінд протистоїть заворушенням Дефіас і нападам звірів, мандрівники Альянсу часто опиняються в ролі посередників у дрібних домашніх сварках між сусідами-фермерами.",["race:Human"]="Для людей, що мандрують Елвінном, конфлікт Стоунфілдів і Маклурів — нагадування про те, як глибоко сягають місцеві образи в серці Стормвінда навіть у тіні ширших криз королівства."},sec={{t="Ворожнеча й заборонене кохання",b="Стоунфілди й Маклури роками живуть у гіркому фермерському суперництві, перетворивши сусідні садиби на ворожу територію. Між двома вогнями опинилися молодий Томмі Джо Стоунфілд і Мейбелл Маклур, чий роман доводиться тримати в цілковитій таємниці. Відчайдушно шукаючи способу зустрітися з коханою, не розпаливши насильства між рідними, Томмі Джо звертається по пораду до бабусі."},{t="Бабусина хитрість",b="Хоч вік тримає Бабусю Стоунфілд у чотирьох стінах, вона розуміє природу ворожнечі краще за будь-кого. Вона визнає, що справжній союз двох родин неможливий, доки живе стара неприязнь, та аж ніяк не збирається дозволити сусідським образам цілком розчавити молоде кохання. Замість закликати до обережності, вона починає вигадувати дрібні нагоди звести двох закоханих разом."}},fp="17,236,25.402.0,16.391.0,52.231.0,37.134.0,58.259.0,55.178.0,38.173.1,23.149.0"}
P.entries["quest:112"] = {n="Збір водоростей",s="«Збір водоростей» — доручення аптекаря Вільяма Пестла з Ґолдшира, що має допомогти двом юним закоханим, яким не судилося бути разом. Щоб зварити зілля невидимості для Мейбелл Маклур, Пестл посилає шукачів пригод відбирати рідкісні морські водорості в мурлоків, що гніздяться довкола Кришталевого Озера.",h="«Збір водоростей» — доручення аптекаря Вільяма Пестла з Ґолдшира, що має допомогти двом юним закоханим, яким...",kw={"водорості","мурлоки","кришталеве озеро","ґолдшир","пестл","зілля невидимості","закохані"},ang={["faction:Alliance"]="Зачищаючи табори мурлоків довкола Кришталевого Озера за дивним дорученням Пестла, ви заразом угамовуєте агресивну загрозу, що причаїлася надто близько до східного шляху з Ґолдшира.",["profession:Herbalism"]="Для збирачів трав кришталеві водорості — рідкісна дивовижа: океанська рослина, яку добувають не з ґрунту чи морського дна, а просто з торбин прісноводних мурлоків-збирачів."},sec={{t="Ліки від забороненого кохання",b="Запекла ворожнеча між фермерськими родинами Стоунфілдів і Маклурів не дає юним Томмі Джо Стоунфілду та Мейбелл Маклур зустрічатися відкрито. У відчаї, прагнучи навідати коханого й не спричинити збройної бійки між ріднею, Мейбелл шукає незвичного виходу: прослизнути через долину непоміченою. Вільям Пестл, химерний травник і аптекар, що влаштувався в Корчмі «Лев'яча Гордість» у Ґолдширі, береться зварити лікер невидимості. Та для такого рідкісного напою потрібні інгредієнти, яких у шафах «Лев'ячої Гордості» не знайти."},{t="Збирачі з Кришталевого Озера",b="Головна складова для варива Пестла — кришталеві водорості. Зазвичай вони ростуть далеко в солоних океанських водах, але прісні береги Кришталевого Озера, що лежить одразу на схід від Ґолдшира, захопили племена мурлоків. Із причин, відомих лише їхнім дивним інстинктам, ці прибережні збирачі натягали оберемки морських кришталевих водоростей у свої грубі табори на суходолі. Щоб назбирати досить стебел, доведеться прорубати собі шлях крізь кубла лютих земноводних, вирвати рослини з їхніх лап і повернутися до Ґолдшира, де Пестл перегонить лікер."}},fp="15,282,27.576.0,30.581.0,42.211.0,53.225.0,49.224.0,30.150.0,39.206.0,22.182.0"}
P.entries["quest:114"] = {n="Втеча",s="«Втеча» — розв'язка забороненого роману Мейбелл Маклур і Томмі Джо Стоунфілда в Лісі Елвінн. Зібравши інгредієнти по всьому краю, ви приносите Мейбелл зварений Вільямом Пестлом Лікер Невидимості, щоб вона непомітно прослизнула повз рідню. Це коротка таємна перемога юного кохання над закоренілою сільською ворожнечею.",h="«Втеча» — розв'язка забороненого роману Мейбелл Маклур і Томмі Джо Стоунфілда в Лісі Елвінн.",kw={"втеча","мейбелл маклур","томмі джо","лікер невидимості","пестл","ліс елвінн","кохання"},ang={["faction:Alliance"]="Для юних шукачів пригод, що починають шлях у Лісі Елвінн, допомога Томмі Джо й Мейбелл — легкий перепочинок між боями з бандитами Дефіас і гнолами. Вона показує, що буденні сільські чвари живуть навіть на порозі Стормвінда.",["race:Human"]="Місцеві люди-поселенці Елвінну добре знають, якими глибокими бувають уперті родинні образи, тож дрібна таємна сусідська допомога тут — запорука миру."},sec={{t="Вариво для справжнього кохання",b="Ворожнеча Маклурів і Стоунфілдів тягнеться поколіннями й не лишає місця для злагоди, а тим паче для залицянь. Обидві родини пильно бережуть своїх і люто ненавидять сусідів, тож Бабуся Стоунфілд звернулася до Вільяма Пестла, алхіміка з Корчми «Лев'яча Гордість» у Ґолдширі. З кришталевих водоростей, зібраних на ближніх озерах, Пестл склав Лікер Невидимості — достатньо сильний, щоб приховати втечу Мейбелл із садиби Маклурів."},{t="Зникнути в лісі",b="Отримавши пляшку, Мейбелл Маклур може вислизнути поміж дерев до Томмі Джо. Її мучить провина за обман рідних, та відданість коханому сильніша за страх викриття. Випивши лікер, вона зникає просто у вас на очах — і закохані здобувають кілька дорогоцінних хвилин наодинці, подалі від пильних поглядів ворогуючих старших."}},fp="10,366,26.442.0,24.354.1,31.186.0,41.182.0,61.208.0,52.172.1,42.177.0,54.175.1"}
P.entries["quest:119"] = {n="Повернення до Вернера",s="«Повернення до Вернера» — доручення Альянсу: доправити громіздкий вантаж із п'ятдесяти свіжовикуваних підків назад до Лейкшира. Коваль Арґус із Ґолдшира доручає вам знову перетнути кордон із Редріджем і передати скриню нетерплячому Вернеру Осґуду.",h="«Повернення до Вернера» — доручення Альянсу: доправити громіздкий вантаж із п'ятдесяти свіжовикуваних підків...",kw={"підкови","вернер осґуд","коваль арґус","лейкшир","редрідж","доставка"},ang={["faction:Alliance"]="Налагоджені лінії постачання між Лісом Елвінн і Редріджем — запорука того, що обложені віддалені поселення на кшталт Лейкшира залишаться зв'язаними з серцем королівства.",["profession:Blacksmithing"]="Перевезення п'ятдесяти підків показує, якою виснажливою є логістика прикордоння: коней треба підковувати навіть тоді, коли місцеві ковадла перевантажені війною."},sec={{t="Кур'єр через кордон",b="Ви вже подолали шлях із Лейкшира до Лісу Елвінн, щоб роздобути необхідне «взуття» для місцевих коней, і тепер завдання завершується перевезенням готової скрині з п'ятдесятьма підковами назад на схід. Гори Редріджу й далі потерпають від нестачі припасів і нападів гнолів, тож кожен шмат заліза важливий, щоб коні й тяглова худоба могли ходити суворими гірськими дорогами."},{t="Записка на скрині",b="Вернер Осґуд щиро радіє, що підкови нарешті прибули, однак Коваль Арґус кував їх не з братньої доброти. До вантажу додано рахунок із вимогою сплати. Вернера помітно дратує, що ґолдширський коваль справді чекає на винагороду, та небезпеки, що нависли над Редріджем, не лишають часу сперечатися про борг — попереду значно грізніші клопоти."}},fp="16,266,27.389.0,21.401.0,40.129.0,40.143.0,47.177.0,51.188.0,57.205.0,48.123.0"}
P.entries["quest:123"] = {n="Колекціонер",s="Цей перехоплений лист, відібраний у гнолів-грабіжників, що никають лісом, містить точний розклад відправлень золота з покинутих шахт Лісу Елвінн. Адресований невловимій постаті, відомій лише як «Колекціонер», графік натякає на злагоджену операцію, яка процвітає просто під носом у гарнізону Стормвінда.",h="Цей перехоплений лист, відібраний у гнолів-грабіжників, що никають лісом, містить точний розклад відправлень...",kw={"колекціонер","графік збору золота","гноли","шахти","дефіас","ліс елвінн","маршал дуґан"},ang={["class:Rogue"]="Перехоплювати розклади й відстежувати організовану контрабанду — класичне ремесло розбійника, і воно показує, як глибоко злочинні синдикати вкоренилися в нетрях Елвінну.",["faction:Alliance"]="Кожна унція золота, вивезена з Елвінну потай, позбавляє Корону життєво важливих податків і сировини в час, коли королівство ледве захищає власні кордони.",["profession:Mining"]="У закритих шахтах Елвінну досі залягають багаті жили міді й дорогоцінних металів — і хтось незаконно їх розробляє, поки чесні рудокопи сидять удома зі страху."},sec={{t="Паперовий слід у лапах гнолів",b="Зачищаючи зграї гнолів, що причаїлися на сході Лісу Елвінн, шукачі пригод натрапляють серед грубих шкур і примітивної зброї на дивний клапоть пергаменту — Графік Збору Золота. Це аж ніяк не звірині кривулі: у записці детально розписано дати й час передачі дорогоцінного металу, видобутого просто з місцевих шахт. Одержувачі явно мають дисципліну й уміння планувати, адже спрямовують вантажі до наглядача, названого лише «Колекціонером»."},{t="Тривожна звістка для Ґолдшира",b="Коли знахідку приносять Маршалу Дуґану в Корчму «Лев'яча Гордість», вона стає тривожним потрясінням. Офіційний видобуток по всьому Елвінну зупинено вже кілька місяців через напади гнолів, засилля кобольдів і мандрівних бандитів. Усвідомлення, що руду й далі систематично добувають і вивозять, а гноли носять при собі вантажні відомості, підтверджує: організована злочинна мережа з тіні розкрадає природні багатства королівства."},{t="Око на ділянку Брекуеллів",b="Графік указує на ймовірне місце перебування Колекціонера — поблизу Гарбузової Ділянки Брекуеллів на сході Лісу Елвінн. Дуґан уже чув це прізвисько в чутках, та не мав чітких доказів, хто керує цією зграєю й куди зрештою пливе крадене золото. Переданий графік дає гарнізону перший надійний слід у полюванні на організатора цих перевезень."}},fp="13,325,35.465.0,29.465.0,27.381.1,33.190.0,23.175.0,46.225.0,29.165.0,40.162.0,45.142.0"}
P.entries["quest:1462"] = {n="Земляна Сапта",s="«Земляна Сапта» — обряд поповнення, який пропонує Віщун Рейвенфезер у Таборі Нарачі. Молодим шаманам, що проходять посвяту для єднання з духами каменю, потрібен цей напій, щоб відкрити внутрішній зір. Якщо новачок загубить чи проллє приготоване вариво, не завершивши обряду, віщунка готує нове, щоб випробування могло тривати.",h="«Земляна Сапта» — обряд поповнення, який пропонує Віщун Рейвенфезер у Таборі Нарачі.",kw={"земляна сапта","сапта","шаман","рейвенфезер","табір нарачі","малгор","таурени"},ang={["class:Shaman"]="Сапта — основне знаряддя вашого раннього вишколу, духовний каталізатор, що вперше відкриває вам очі на сили стихій, які ведуть світ.",["faction:Horde"]="Опору Орди на шаманські традиції плекають у таких місцях, як Малгор, де племінні віщуни терпляче ростять нове покоління духовних провідників.",["race:Tauren"]="Шанування Матері-Землі починається з уміння чути землю, і старійшини Табору Нарачі ретельно дбають, щоб жодного юнака не відвернули від священного шляху."},sec={{t="Напій видінь",b="Шлях шамана починається з налаштування смертних чуттів на сили поза фізичним зором. Щоб побачити духів стихій землі, посвячуваний має випити сильнодійне обрядове вариво, відоме як сапта. Насичена природними есенціями, пов'язаними зі стихією каменю й ґрунту, Земляна Сапта піднімає завісу між фізичним світом і духовним планом і дає новачкові єднатися просто з елементалями землі Малгору."},{t="Другий шанс на зір",b="Духовні мистецтва вимагають дисципліни, та досвідчені віщуни знають, що молоді посвячувані часто помиляються чи гублять священні реагенти, блукаючи нетрями. Табір Нарачі ніколи не відмовляє в другому шансі: Віщун Рейвенфезер пильно вартує тут, щоб кожен учень, який загубить вариво до єднання біля кам'яного монумента, міг відновити приготування. З тихим терпінням вона дає нову посудину, щоб новачок міг постати перед духами незламним."}},fp="11,355,19.433.0,24.422.0,23.266.0,47.265.0,25.214.0,48.248.0,51.181.0,25.255.0"}
P.entries["quest:1463"] = {n="Земляна Сапта",s="Це доручення — перевірка відповідальності для посвячуваного шамана в Долині Випробувань. Якщо послушник загубить освячену Земляну Сапту до єднання з духами землі, Канаґа Ерткаллер дає заміну разом із суворим нагадуванням поводитися зі священними напоями обережно.",h="Це доручення — перевірка відповідальності для посвячуваного шамана в Долині Випробувань.",kw={"земляна сапта","сапта","шаман","ерткаллер","долина випробувань","дуротар"},ang={["class:Shaman"]="Для посвячуваного втрата сапти — ранній урок дисципліни: єднання зі стихіями потребує твердої зосередженості, а не недбалих рук.",["race:Orc"]="У посушливих скелях Дуротару молоді орки, що опановують давні шляхи шаманізму, мають довести свою відданість предкам і землі під ногами.",["race:Troll"]="Тролі Темного Списа, що йдуть шляхом стихій у Долині Випробувань, учаться поєднувати традиційне шанування лоа з прямою шаною до духів стихій."},sec={{t="Другий шанс зі стихіями",b="Шлях шамана вимагає цілковитої уважності й поваги до духів світу. Приготована особливими обрядами, Земляна Сапта — стихійне вариво, що має стоншити завісу між фізичним світом і духами каменю та ґрунту. Коли посвячуваний ненароком губить чи проливає цей напій, мандруючи Дуротаром, Канаґа Ерткаллер готовий щиро приготувати ще один — та не без застереження новачкові бути значно пильнішим зі священними дарами."},{t="Настанова Канаґи",b="Канаґа Ерткаллер наглядає за шаманами-початківцями, що виходять із Лігва в Долині Випробувань. Розуміючи, що молоді орки й тролі схильні до безладу перших випробувань, він наголошує: духи стихій не терплять недбалості. Прийняти другу сапту — маленький урок смирення, що нагадує молодому шаману: силу, дану землею, треба берегти й шанувати."}},fp="11,293,33.494.0,17.415.0,23.229.0,45.248.0,34.167.0,47.197.0,33.161.0,48.189.0"}
P.entries["quest:147"] = {n="Полювання на людину",s="«Полювання на людину» — завдання Альянсу від Маршала Дуґана з Ґолдшира: знищити посильного Дефіас, відомого як «Колекціонер». Діючи із захопленої Гарбузової Ділянки Брекуеллів, цей посередник спрямовує крадене золото з шахт Лісу Елвінн просто до скарбниці Братства.",h="«Полювання на людину» — завдання Альянсу від Маршала Дуґана з Ґолдшира: знищити посильного Дефіас, відомого...",kw={"полювання","колекціонер","дефіас","гарбузова ділянка","каменярі","маршал дуґан","перстень"},ang={["class:Rogue"]="Потаємна оборудка Колекціонера на гарбузовій ділянці викриває дедалі ширшу мережу розбійників і кишенькових злодіїв, що пускає коріння по всьому Лісі Елвінн.",["faction:Alliance"]="Захист місцевих ресурсів Стормвінда — справа першорядна: знищення Колекціонера перекриває потік королівського золота, яким мали оплатити повстання просто біля столиці.",["race:Human"]="Знайдений перстень каменяра зачіпає болючу струну в недавній історії Стормвінда — нагадує про гіркі суперечки з робітниками, що розкололи королівство після відбудови столиці."},sec={{t="Правосуддя на гарбузовій ділянці",b="Після того як у гнолів Елвінну знайшли графік збору золота, Маршал Дуґан посилає шукачів пригод на Гарбузову Ділянку Брекуеллів. Колись тиху садибу захопили бандити Дефіас і гноли. Серед зарослого гарбузиння переховується Колекціонер — посередник, який краде королівську руду й організовує відправлення для повстання, що набирає сили."},{t="Печатка ремісника",b="Убивши Колекціонера, шукачі пригод забирають його перстень і приносять Маршалу Дуґану. На подив маршала, на персні — не звичайний злодійський герб, а знак старої Гільдії каменярів Стормвінда. Знахідка натякає на неприємну правду: розбійники, що душать Ліс Елвінн, — не просто пройдисвіти, а колишні майстри, які стали запеклими злочинцями після відбудови Стормвінда."}},fp="7,280,28.376.0,17.413.1,31.158.0,55.176.0,49.268.1,61.217.1,30.149.0,38.183.0"}
P.entries["quest:1470"] = {n="Крізь завісу",s="«Крізь завісу» — вступне випробування для чорнокнижників від Вені Мартанд у Похоронному Подзвоні. Воно перевіряє рішучість щойно піднятого чорнокнижника, посилаючи його збирати черепи сусідніх безтямних скелетів. Виконавши завдання, новачок здобуває знання, потрібне, щоб прикликати й прив'язати до себе біса-прислужника.",h="«Крізь завісу» — вступне випробування для чорнокнижників від Вені Мартанд у Похоронному Подзвоні.",kw={"крізь завісу","чорнокнижник","веня мартанд","біс","скелети","похоронний подзвін"},ang={["class:Warlock"]="Цей обряд переходу — ваш перший справжній крок у демонологію, що показує основний урок: хаотичну магію треба гнути залізною волею.",["race:Undead"]="Чорнокнижники Відступників спираються на свою моторошну відстороненість від смертності, щоб безстрашно вивчати хаотичну й темну магію в тінях Похоронного Подзвону."},sec={{t="Перший крок новачка",b="Щойно пробуджені чорнокнижники Відступників починають свій шлях у Похоронному Подзвоні під настановами Вені Мартанд. Вона навчає, що справжня сила — не в грубій силі, а в знанні й точному володінні хаотичними силами. Щоб довести, що мають зосередженість і хист пройти крізь завісу між світами й підкорити істот Нижнього Світу, новачків посилають збирати черепи неспокійних скелетів Гримучих Кісток, що блукають біля покинутої кузні Похоронного Подзвону."},{t="Підкорення Нижнього Світу",b="Коли скелетні рештки зібрано, Веня вважає посвяченого готовим ступити далі простих темних заклять. Здобуті матеріали слугують обрядом переходу й доводять, що новачок здатен здолати безтямну нежить і витримати похмуру дійсність свого ремесла. Натомість Веня передає ритуали, потрібні, щоб зігнути біса під волю прикликача, застерігаючи: попри дрібний зріст демона, його хитрість і вогонь зроблять його небезпечним союзником."}},fp="17,294,21.468.0,22.460.0,38.117.0,45.148.0,45.165.0,44.131.0,43.144.0,40.126.0"}
P.entries["quest:1485"] = {n="Мерзенні прислужники",s="У посушливій Долині Випробувань наставник чорнокнижників Рузан доручає майбутнім практикам темних мистецтв довести свою вправність у бою з мерзенними фамільярами. Щоб здобути знання прикликання демонів, посвячувані мають зустріти цих бісівських створінь у бою й забрати їхні відрубані голови. Це скромний, небезпечний перший крок до влади над силою Скверни під пильним оком Орди.",h="У посушливій Долині Випробувань наставник чорнокнижників Рузан доручає майбутнім практикам темних мистецтв...",kw={"мерзенні прислужники","фамільяри","чорнокнижник","рузан","біс","долина випробувань","скверна"},ang={["class:Warlock"]="Це випробування — ваш перший обряд переходу як чорнокнижника: ви доводите, що здатні підкорити демонічний вогонь, перш ніж здійснити обряд прикликання власного біса.",["faction:Horde"]="Хоч Орда дозволяє чорнокнижникам навчатися в Дуроторі, їхні темні мистецтва тримають під щільним замком у відокремлених місцях на кшталт Лігва.",["race:Orc"]="Орчі чорнокнижники щодня стикаються з темною історією свого народу, доводячи самовладання й вірність у суспільстві, яке пам'ятає жахи скверни."},sec={{t="Хистке місце в Орді",b="Чорнокнижники посідають непевне місце в щойно викуваній Орді Тралла. Спадщина демонічної скверни та кривавих угод, що колись принесли орчому роду руїну, лишила глибокі шрами й невигаслу недовіру. Хоч практиків магії Скверни в Дуроторі терплять, їх не люблять і не вітають. Багато хто обирає відлюдне життя в тінистих закутках на кшталт Лігва, практикуючи своє мистецтво подалі від цікавих очей і навчаючи тих рідкісних посвячуваних, що наважуються ступити на цей шлях."},{t="Випробування влади",b="Перш ніж дати учневі небезпечні обряди, потрібні, щоб підкорити біса своїй волі, Рузан вимагає доказу переваги. Біля печери на північний схід від Лігва мерзенні фамільяри скрадаються й жбурляють вогняними кулями в кожного, хто наблизиться. Убиваючи цих менших демонів і забираючи їхні голови, посвячуваний доводить, що здатен здолати вогняних супротивників, якими прагне керувати, — і що його не поглине та сама магія, якою він має намір повелівати."}},fp="14,398,31.472.0,20.441.0,53.326.0,35.202.0,44.315.0,45.197.0,33.174.0,13.190.0"}
P.entries["quest:1499"] = {n="Мерзенні прислужники",s="Це завдання завершує першу виправу молодого чорнокнижника проти демонічних прислужників, що ховаються в Долині Випробувань. Убивши мерзенних фамільярів під проводом Рузана, неофіт доповідає про свій учинок Зуріті Фарґейз, яка керує винищенням Палаючого Клинка, що насувається.",h="Це завдання завершує першу виправу молодого чорнокнижника проти демонічних прислужників, що ховаються в...",kw={"мерзенні прислужники","фамільяри","чорнокнижник","зуріта фарґейз","рузан","палаючий клинок","долина випробувань"},ang={["class:Warlock"]="Для посвячуваного в темні мистецтва зустріч із мерзенними фамільярами — необхідне випробування: ви доводите, що можете підкорювати й знищувати дикі сутності Скверни, а не ставати їхньою здобиччю.",["race:Orc"]="Присутність демонічних фамільярів — гидке нагадування про темні угоди, що колись поневолили орчий рід, тож їхнє вигнання з землі Дуротару — справа виживання культури.",["race:Troll"]="Тролі Темного Списа, що ділять Долину Випробувань, дивляться на демонічну магію з глибокою підозрою, тож молодим практикам важливо довести свою вірність у боротьбі з культистами-відступниками."},sec={{t="Питання дисципліни",b="Поки інших молодих воїнів і розвідників у Долині Випробувань Зуріта Фарґейз посилає просто стримувати навалу в Ковені Палаючого Клинка, посвячувані чорнокнижники спершу відповідають перед своїми тіньовими наставниками. Рузан вимагає доказу сили й влади над меншими демонами, перш ніж повернути учнів у лоно загальної оборони Орди, щоб їхні зусилля служили і колу чорнокнижників, і безпеці Лігва."},{t="Загроза Ковену",b="Зуріта Фарґейз пильно стежить за північною печерою над Долиною Випробувань. Мерзенні фамільяри, що скрадаються всередині, — лише найслабші улюбленці культистів Палаючого Клинка, та їхня відкрита присутність на священних тренувальних землях — зухвала образа і дедалі більша небезпека. Доповідь про ваш успіх проти них підтверджує: навіть ті, хто йде шляхом мистецтв Скверни, лишаються відданими захисту Дуротару від справжньої скверни."}},fp="14,288,22.439.0,23.442.0,75.298.0,27.216.0,34.169.0,52.245.0,56.294.0,47.225.0"}
P.entries["quest:15"] = {n="Розвідати Ехо-Рідж",s="«Розвідати Ехо-Рідж» — одне з перших військових доручень Маршала Макбрайда в Долині Нортширу. Новобранців посилають на північ, до Шахти Ехо-Рідж, аби винищити кобольдів-робітників, що лізуть із-під землі, і з'ясувати справжній розмах зарази, що загрожує мінеральним багатствам абатства.",h="«Розвідати Ехо-Рідж» — одне з перших військових доручень Маршала Макбрайда в Долині Нортширу.",kw={"ехо-рідж","кобольди","шахта","нортшир","маршал макбрайд","розвідка"},ang={["faction:Alliance"]="Кобольди, що підповзають так близько до духовного серця Стормвінда в Нортширі, показують, яким уразливим стало королівство, коли його регулярні сили розтягнуто до краю.",["profession:Mining"]="Шахта Ехо-Рідж — головне джерело міді для ковалів Нортширу, тож зачистка цих підземних тунелів для рудокопів — питання прямого економічного виживання.",["race:Human"]="Для молодих людей, що починають службу в Долині Нортширу, захист Ехо-Ріджу від підземних шкідників — одне з перших випробувань, у якому вони доводять свою цінність королівству."},sec={{t="Зараза, що глибшає",b="Перші сутички довкола Нортширу зводилися до розрізнених шкідників, що никали лісовим узліссям, та невдовзі розвідники донесли про значно організованішу загрозу. Кобольди не просто нишпорили лісами — вони великими силами зібралися біля Шахти Ехо-Рідж. Маршал Макбрайд наказує новобранцям рушати на північ, стати до бою з кобольдами-робітниками біля входу в шахту й оцінити, наскільки глибоко вкоренилися ці паразити."},{t="Загроза багатству абатства",b="Шахта Ехо-Рідж — важливе джерело руди й сировини для братства Нортширу та стормвіндської варти, розквартированої тут. Щуроподібні збирачі, захопивши тунелі, паралізують видобуток і оголюють, як тонко розтягнута місцева оборона. Знищення десяти робітників виявляється лише першим кроком: побоювання Макбрайда справджуються — зараза сягає значно глибше в штольні, ніж може зарадити звичайний патруль на поверхні."}},fp="22,301,23.435.0,28.426.0,29.183.0,37.146.0,40.227.0,48.204.1,57.228.0,56.163.0"}
P.entries["quest:1516"] = {n="Поклик Землі",s="«Поклик Землі» — перше випробування для шаманів-новачків Орди, що навчаються в Долині Випробувань. Дане Канаґою Ерткаллером, воно перевіряє витривалість і терпіння шамана: щоб приготувати обрядову сапту, треба вполювати демонічних переслідувачів Скверни.",h="«Поклик Землі» — перше випробування для шаманів-новачків Орди, що навчаються в Долині Випробувань.",kw={"поклик землі","шаман","ерткаллер","переслідувачі скверни","земляна сапта","долина випробувань","палаючий клинок"},ang={["class:Shaman"]="Цей обряд — ваше перше офіційне єднання зі стихіями, що закладає підвалини вашого Тотема Землі.",["race:Orc"]="В Орді Тралла повернення на шаманський шлях ушановує давні кланові традиції, що існували задовго до демонічної скверни.",["race:Troll"]="Відьмаки й духовидці Темного Списа приймають духів землі, щоб підтримати свій новознайдений дім поряд з орками."},sec={{t="Перший зв'язок",b="Перш ніж шаман зможе кликати стихії, він має встановити тривкий зв'язок із кожною з них по черзі. В орчій і тролячій культурі цей духовний шлях починається із землі — основи життя, витривалості й терпіння. Канаґа Ерткаллер — провідник початківців у Долині Випробувань; він учить, що земля вимагає найвищої поваги й стійкості, перш ніж дарує свій захист."},{t="Очисне полювання",b="Щоб довести готовність єднатися з упертими духами землі, посвячуваних посилають у північні яри, де гніздиться культ Палаючого Клинка. Полюючи на переслідувачів Скверни — осквернених потойбічних гончаків, прикликаних темною магією, — шаман доводить здатність боронити землю від неприродного тління. Здобуті копита Канаґа використовує як складники для Земляної Сапти — священного напою, що відкриває смертним очам план стихій."}},fp="13,260,14.398.0,16.449.0,34.202.0,26.202.0,39.178.0,34.160.0,58.189.0,50.188.0"}
P.entries["quest:1517"] = {n="Поклик Землі",s="Цей священний обряд — перше духовне єднання посвячуваного зі стихіями в Дуроторі. Під проводом Канаґи Ерткаллера молоді шамани випивають сильнодійну Земляну Сапту на Камені Духів, щоб пронизати завісу й стати просто перед Малим Проявом Землі.",h="Цей священний обряд — перше духовне єднання посвячуваного зі стихіями в Дуроторі.",kw={"поклик землі","шаман","земляна сапта","камінь духів","прояв землі","прихована стежка","дуротар"},ang={["class:Shaman"]="Цей обряд — ваш найперший крок на шляху налаштування на стихії; він учить, що справжня майстерність починається з тихого терпіння землі.",["race:Orc"]="Для орків, що повертаються до шляхів предків після поколінь скверни, єднання через Земляну Сапту — священне віднайдення традиційного зв'язку їхнього народу з духами.",["race:Troll"]="Відьмаки й духовидці Темного Списа приймають ці земляні обряди, щоб пристосувати свої глибокі зв'язки з предками до суворого, випаленого сонцем краєвиду Дуротару."},sec={{t="Сила сапти",b="Сапта — містичне вариво, відоме лише небагатьом майстрам-шаманам. Зварений зі стихійною магією, напій служить мостом між смертним сприйняттям і духовним планом, даруючи сильним духом «зір сапти». Оскільки його сила прив'язує дух того, хто п'є, просто до стихії, традиція вимагає ніколи не пити його поза освяченою святою землею."},{t="Паломництво до Каменя Духів",b="Щоб єднатися із землею, посвячувані покидають Долину Випробувань і сходять Прихованою Стежкою в південні скелі Дуротару. Наприкінці стежки стоїть Камінь Духів — піднесене святилище над суворою пусткою. Випита тут сапта дає посвячуваному побачити те, чого не бачать буденні очі: присутність стихії, що тихо чекає серед каміння."},{t="Терпіння землі",b="Малий Прояв Землі не вимагає ні крові, ні підкорення — лише щоб прохач смиренно став перед світом. Поки інші сили стихій — вогонь, вода й повітря — мають бурхливих, мінливих і часто хаотичних духів, земля дарує сталість. Вона вітає прохача, нагадуючи, що гори дають витривалість, а рівнини — безмежне терпіння."}},fp="13,260,22.371.0,25.352.0,21.400.0,23.225.0,29.179.0,46.196.0,40.238.0,42.217.0,48.212.0"}
P.entries["quest:1518"] = {n="Поклик Землі",s="«Поклик Землі» — завершальний обряд випробування землі для молодих шаманів у Дуроторі. Поєднавшись із проявом духу землі, посвячуваний повертається до Канаґи Ерткаллера з грубим кварцом, щоб отримати свій перший стихійний тотем.",h="«Поклик Землі» — завершальний обряд випробування землі для молодих шаманів у Дуроторі.",kw={"поклик землі","шаман","грубий кварц","тотем землі","ерткаллер","прояв землі","долина випробувань"},ang={["class:Shaman"]="Цей обряд дає вам перший тотем і відкриває вміння закорінюватися в стихіях і кликати землю на допомогу.",["faction:Horde"]="Стихії Калімдору дикі й неприборкані, тож зв'язок, який кують шамани Орди, конче потрібен для виживання їхніх нових поселень.",["race:Orc"]="Випробування втілює тривале відродження орчого шаманізму в Дуроторі — повернення до рівноваги стихій після десятиліть демонічної скверни.",["race:Troll"]="Відьмаки й духовидці Темного Списа навчаються поряд з орками в Долині Випробувань, доповнюючи своє традиційне єднання чотирма стихійними шляхами."},sec={{t="Серце каменю",b="Щоб єднатися із землею, шаман-новачок має дивитися далі за грубу силу. Виявивши терпіння й смирення перед Малим Проявом Землі, посвячуваний отримує скромний знак — шматок грубого кварцу. Хоч на вигляд він непримітний, цей крихітний камінь — тривке зерно сили й доказ, що дух прийняв обітницю прохача."},{t="Перший із чотирьох шляхів",b="Повернення кварцу Канаґі Ерткаллеру в Долину Випробувань завершує випробування. Канаґа вправляє камінь у Тотем Землі — фізичне осердя, через яке шаман спрямовує непохитний захист і силу землі. Цей обряд знаменує офіційний вступ посвячуваного в першу з чотирьох стихійних дисциплін і закладає підвалини для цілого життя єднання з природним світом."}},fp="13,246,18.371.0,23.408.0,34.245.0,26.235.0,25.210.0,44.216.0,49.228.0,41.184.0"}
P.entries["quest:1520"] = {n="Поклик Землі",s="Цей священний обряд знаменує духовне налаштування шамана-таурена на стихію землі. Випивши Земляну Сапту біля святого каменя на схід від Табору Нарачі, посвячені зазирають за межі тілесних чуттів, щоб безпосередньо поєднатися з Малим Проявом Землі.",h="Цей священний обряд знаменує духовне налаштування шамана-таурена на стихію землі.",kw={"поклик землі","земляна сапта","малий прояв землі","камінь кодо","шаман","табір нарачі"},ang={["class:Shaman"]="Цей обряд — духовне осердя зв'язку шамана-таурена із землею, обов'язковий міст до єднання з землею й отримання Тотема Землі.",["race:Tauren"]="Глибока шана до Матері-Землі робить ритуал сапти одним із найшанованіших у культурі випробувань дорослішання для духовних учнів тауренів на Плато Червоної Хмари."},sec={{t="Призначення сапти",b="Сапта — ретельно приготоване церемоніальне зілля, яке шаманські старійшини варять, щоб прив'язати смертний дух посвяченого безпосередньо до первісної стихії. Її готують магією предків, і таємниці варіння зберігає лише дехто з тауренів. Випитий у призначеному священному місці, напій розширює розум і прориває завісу між тілесним світом і духовним планом, щоб стихії можна було побачити в їхній первісній подобі."},{t="Єднання біля Каменя Кодо",b="Табір Нарачі лишається позаду: на схід від нього височіє Камінь Кодо — грізний кам'яний стовп, що слугує святим прихистком. Випита тут сапта відкриває Малий Прояв Землі, що чекає на прочанина. На відміну від мінливих, вогняних чи шалених ликів природи, які шаман зустріне далі на своєму шляху, дух землі просить лише, щоб посвячений підійшов у тихому смиренні, і дарує незламну силу гір і спокійне терпіння рівнин усім, хто шанує землю."}},fp="13,245,24.449.0,22.456.0,23.205.0,27.115.0,42.151.0,46.204.0,52.165.0,54.210.0"}
P.entries["quest:1521"] = {n="Поклик Землі",s="Цей обряд завершує перше єднання молодого шамана-таурена з духами землі в Малгорі. Випивши Земляну Сапту й поговоривши безпосередньо з проявом духа, посвячений отримує уламок сирого каменю, щоб принести його додому. Повернення туди, де на нього чекає Табір Нарачі, знаменує офіційний зв'язок містика-початківця з першою з чотирьох стихій.",h="Цей обряд завершує перше єднання молодого шамана-таурена з духами землі в Малгорі.",kw={"поклик землі","грубий кварц","тотем землі","малий прояв землі","віщун рейвенфезер","шаман","табір нарачі"},ang={["class:Shaman"]="Цей обряд знаменує здобуття вашого найпершого тотема. Він заземлює вашу духовну сутність і відкриває вам змогу творити основні обереги землі.",["faction:Horde"]="Шамани — життєво важливі духовні опори й радники нової Орди, що поєднують смертні раси з мінливими силами стихій Калімдору.",["race:Tauren"]="Культура тауренів ставиться до Матері-Землі з глибокою шаною. Це випробування прив'язує посвяченого безпосередньо до живого каменю й ґрунту його прабатьківської землі."},sec={{t="Дар від гори",b="Коли посвячений єднається з Малим Проявом Землі на скелях біля Плато Червоної Хмари, дух дарує простий Грубий Кварц. Хоч камінь непоказний на вигляд, він уособлює угоду зі стихією й витривалість самого каменю. Дух нагадує молодому шаману, що терпіння й сила — головні чесноти, яких вимагає земля, і обіцяє, що взаємна повага подарує гармонію з землею."},{t="Перший тотем",b="Коли посвячений повертається до Табору Нарачі, Віщун Рейвенфезер із подарованого кварцу виготовляє найперший Тотем Землі шамана. Це значно більше, ніж оздобний знак становища: тотем — постійний тілесний і духовний якір. Через це різьблене осердя посвячений спрямовує заземлювальну, захисну магію самої землі й робить перший справжній крок на чотирьох стихійних шляхах."}},fp="13,352,24.402.0,15.387.0,40.178.0,47.203.0,25.241.0,51.205.0,37.157.0,48.198.0"}
P.entries["quest:1525"] = {n="Поклик вогню",s="Це випробування — вирішальна підготовка до єднання шамана з вогнем: посвячуваний має зібрати леткі складники для Вогняної Сапти. Телфу Джуламу потрібні компоненти, насичені жаром і магічною силою: смола геомантів Гостроманів і мішечок темних реагентів від культистів Палаючого Клинка, що ховаються в Дуроторі.",h="Це випробування — вирішальна підготовка до єднання шамана з вогнем: посвячуваний має зібрати леткі складники...",kw={"поклик вогню","шаман","вогняна сапта","телф джулам","вогняна смола","гострогриви","палаючий клинок"},ang={["class:Shaman"]="Цей обряд перевіряє здатність молодого шамана врівноважувати протилежні сили й показує, що полум'я — не просто пальне для гніву, а знаряддя життя і світла, коли його веде мудрість.",["faction:Horde"]="Випробування посилає захисників Орди вдарити по двох нагальних загрозах просто на їхніх кордонах: шипогривах Гостроманів, що насуваються в Пустках, і підступних культистах Палаючого Клинка, що зарилися в Дуроторі.",["race:Orc"]="Для орків мати справу з Палаючим Клинком — гірке нагадування про темну магію чорнокнижників, що колись осквернила їхній народ, тож повернути вогонь як чисту природну стихію — важливий акт відновлення культури."},sec={{t="Приготування Вогняної Сапти",b="Щоб бачити духів вогню й говорити з ними, шаман не може покладатися лише на смертний зір. Як земля вимагала власного напою, так і відкрити чуття Вічному Полум'ю можна лише особливою Вогняною Саптою. Для зілля потрібні реагенти, від природи пов'язані з жаром і полум'ям. Відлюдник Телф Джулам посилає посвячуваних через Дуротар і у східні Пустки здобути ці складники в тих, хто володіє первісним жаром і згубним чаклунством."},{t="Вороги і стихії",b="Потрібні складники показують, як по-різному сторони черпають вогонь. Чаклуни-шипогриви Гостроманів зі східних Пусток носять вогняну смолу — в'язкий горючий побічний продукт їхніх земляних обрядів. Натомість мішечок реагентів треба відібрати в культистів Палаючого Клинка, що причаїлися в Печері Пилового Вітру серед ярів на північний схід від Гострого Пагорба. Хоч культисти-чорнокнижники вживають вогонь як знаряддя руйнування й демонічного хаосу, сирі реагенти в їхніх мішечках і далі природно відгукуються на саму стихію."},{t="Природа полум'я",b="Коли сапту зварено, Телф Джулам відкриває важливу істину про стихії: вогонь — щось значно більше, ніж руйнування й загибель. Він палить і пожирає, та водночас він — серце тепла, світла і творення. Справжня рівновага вимагає розуміти, що протилежні сили надають одна одній сенсу, і мудрий шаман уживає протилежні сили стихій разом, а не має вогонь лише за зброю."}},fp="12,343,22.442.0,20.527.0,19.406.1,21.302.0,29.275.0,33.219.0,42.311.0,19.245.0,30.223.1"}
P.entries["quest:1526"] = {n="Поклик вогню",s="Це випробування — вирішальна мить налаштування шамана на вогонь на вершинах Дуротару. Під проводом відлюдника Телфа Джулама посвячуваний має випити сильнодійну вогняну сапту, щоб побачити Малий Прояв Вогню й стати з ним на герць. Перемога над духом дає сяйливий жар, яким розпалюють жаровню в Святилищі Вічного Полум'я й запалюють обрядовий смолоскип.",h="Це випробування — вирішальна мить налаштування шамана на вогонь на вершинах Дуротару.",kw={"поклик вогню","шаман","вогняна сапта","прояв вогню","телф джулам","сяйливий жар","святилище вічного полум'я"},ang={["class:Shaman"]="На відміну від твердої, непіддатливої землі, вогонь мінливий і руйнівний. Це випробування вчить, що вогонь поглине нерішучого закликача й вимагає непохитної зосередженості та влади, щоб його опанувати.",["faction:Horde"]="Орки й тролі-шамани здійснюють паломництво на червоні скелі Дуротару, щоб довести своє єднання з вогняними духами землі."},sec={{t="Очі полум'я",b="Духи вогню рідко лишаються на видноті для невтаємничених. Щоб єднатися з ними, шаман має змінити своє сприйняття вогняною саптою — стихійним напоєм, настояним на реагентах, зібраних у пустищах і на узбережжі. Випитий напій відкриває чуття незримому, являючи менших духів і прояви, що танцюють на скелях вершини."},{t="Герць із проявом",b="Вогонь не кориться пасивній відданості; він вимагає сили, рішучості й поваги. На вершині гори чекає Малий Прояв Вогню. Відчувши пронизливий погляд шамана, щойно сапта подіє, дух чекає на початок виклику. Посвячуваних учать бити швидко й без вагань, бо стихійний вогонь живиться затяжним боєм і що довше триває герць, то лютішим і гарячішим стає."},{t="Жаровня Сплячого Полум'я",b="Коли прояв підкорено, шаман забирає його останній жар у вигляді сяйливого жару. Повернувшись до святилища на вершині, він кладе жар у Жаровню Сплячого Полум'я. Хоч її відкрито суворому сонцю й вітрам Дуротару, карбований метал лишається чистим і холодним, доки жар не торкнеться чаші, — а тоді вона вибухає ритмічним білим полум'ям, що запалює обрядовий смолоскип."}},fp="12,363,17.359.0,29.427.0,32.403.1,34.232.0,38.217.0,47.140.0,19.189.0,58.193.0,38.158.0"}
P.entries["quest:1578"] = {n="Постачання фронту",s="Постачання фронту — раннє завдання для дворфійських ковалів-початківців, яке дає Тормус Діпфордж в Айронфорджі. Воно доручає ковалям кувати зброю й броню на підтримку горян, що стоять у Лох Модані проти невпинних набігів трогів.",h="Постачання фронту — раннє завдання для дворфійських ковалів-початківців, яке дає Тормус Діпфордж в...",kw={"постачання фронту","ковальство","тормус діпфордж","торвальд діпфордж","лох модан","горяни","мідна зброя"},ang={["faction:Alliance"]="Безпека кордонів Каз Модану береже гірські дороги, що з'єднують Айронфордж зі Стормвіндом і операціями Альянсу на півдні.",["profession:Blacksmithing"]="Це завдання — ранній обряд посвяти для майбутніх ковалів, що перевіряє їхнє вміння виготовляти надійну, однакову мідну зброю й броню для справжнього військового вжитку.",["race:Dwarf"]="Оборона Лох Модану напряму залежить від дворфійської майстерності, доводячи, що ремісник біля міхів не менш важливий для виживання королівства, ніж горянин із рушницею."},sec={{t="Озброюючи горян",b="У великих кузнях Айронфорджа майстер-коваль Тормус Діпфордж пильно стежить за кордонами королівства Каз Модан. Горянам, що боронять долини Лох Модану, доводиться сутужно через раптові напади трогів, які вириваються з розкопаних руїн і печер. Щоб їхні оборонні лінії мали все потрібне, необхідна безперервна зміна свіжих клинків, поясів і кріплень, тож до справи долучаються й місцеві ремісники."},{t="Рід Діпфорджів",b="Щоб постачати оборону, не відриваючи досвідчених майстрів від міських кузень, Тормус посилає учнів на схід до Лох Модану. Там його колега Торвальд Діпфордж тримає польовий арсенал у південній сторожовій вежі. Доправивши міцні мідні сокири й мідні ланцюгові пояси просто Торвальдові, ковалі доводять свою надійність і здобувають досконаліші ковальські прийоми."}},fp="19,259,23.405.0,21.389.0,43.205.0,36.215.0,53.221.0,36.194.0,40.146.0,57.219.0"}
P.entries["quest:1581"] = {n="Еліксири для Блейдліфів",s="У вітті Доланаара Сірал Блейдліф шукає алхіміка, щоб поповнити запаси родинної справи, яка стрімко росте. Її чоловік просиджує безкінечні години над казанами, і Сірал сподівається, що партія свіжих еліксирів полегшить його працю, а помічник дістане в'язку рідкісних трав.",h="У вітті Доланаара Сірал Блейдліф шукає алхіміка, щоб поповнити запаси родинної справи, яка стрімко росте.",kw={"еліксири","блейдліфи","сірал блейдліф","алхімія","доланаар","трави","тельдрассил"},ang={["faction:Alliance"]="Коли Доланаар добре забезпечений відновлювальними й захисними напоями, його захисники й мандрівні союзники готові до лісових загроз.",["profession:Herbalism"]="Багатий ґрунт Тельдрассила рясніє Срібнолистом і Земнокоренем, тож назбирати сировини для замовлення Сірал неважко.",["race:NightElf"]="Підтримка тутешніх ремісників на кшталт Блейдліфів допомагає молодому поселенню Доланаар рости під шатром Тельдрассила."},sec={{t="Тягар добробуту",b="Поселення Доланаар — важливе перехрестя для мандрівників, вартових і друїдів, що прокладають шлях шатром Тельдрассила. Із такою кількістю подорожніх торгівля травами й алхімією, яку ведуть Сірал Блейдліф із чоловіком, розквітла. Та великий попит має свою ціну. Її чоловік проводить майже весь час, схилившись над пляшечками й казанами, щоб полиці не порожніли, і подружжю майже не лишається часу одне для одного."},{t="Обмін торговки",b="Замість дозволити своєму партнерові згоріти під лавиною замовлень, Сірал звертається до перехожих травників і зіллєварів. Замовляючи готові напої — Еліксири Левової Сили й Малого Захисту, — вона поповнює запаси крамниці, а навзаєм пропонує свіжозібрані нечасті трави. Для алхіміка-початківця, що вправляється в ремеслі під Великим Деревом, це чудова нагода обернути звичайну лісову рослинність на жадані місцеві трави."}},fp="26,276,22.435.0,19.467.0,44.238.0,39.175.0,51.165.0,31.185.0,50.161.0,33.119.0"}
P.entries["quest:1598"] = {n="Викрадений фоліант",s="«Викрадений фоліант» — випробування-посвята для чорнокнижників-початківців із людей, що навчаються в Долині Нортширу. За дорученням наставниці Друзілли Ла Салль адепт має пробратися в сусідній табір Дефіас і повернути заборонену книгу «Сили Порожнечі». Так чорнокнижник-новачок доводить свою вправність і здобуває знання, потрібні, щоб зв'язати першого демонічного слугу.",h="«Викрадений фоліант» — випробування-посвята для чорнокнижників-початківців із людей, що навчаються в Долині...",kw={"чорнокнижник","фоліант","сили порожнечі","друзілла ла салль","дефіас","біс","нортшир"},ang={["class:Warlock"]="Цей обряд посвяти перевіряє, чи зможе чорнокнижник-новачок пройти небезпечною територією, не здригнувшись. Повернувши фоліант, ви отримуєте таємні обряди, потрібні, щоб прикликати свого першого біса.",["faction:Alliance"]="Працюючи просто під носом у паладинів і кліриків Нортширу, чорнокнижники Альянсу мусять ступати тихо й користатися з промахів злочинців, щоб здобути заборонені окультні знання.",["race:Human"]="Завдання показує, як глибоко Братство Дефіас проникло в Нортшир: воно спокушає навіть відлюдних учнів абатства красти священні тексти й приставати до заколоту."},sec={{t="Заборонена нагода",b="У володіннях Стормвінда чорнокнижники ступають обережно: вправляються у своєму небезпечному ремеслі по затишних кутках і ховають дослідження від сторонніх очей. Абатство Нортшира зберігає в архівах стародавні знання, зокрема заборонені гримуари під замком. Друзілла Ла Салль, наставниця чорнокнижників, що причаїлася на землях абатства, давно жадала одного з таких томів — «Сил Порожнечі», — та не наважувалася накликати підозру кліриків і паладинів абатства, вламуючись до охоронюваного крила бібліотеки власноруч."},{t="Нагода для Дефіас",b="Нагода для Ла Салль випала, коли один із послушників абатства пристав до Братства Дефіас. Тікаючи у Виноградники Нортшира до бандитів, книжник-відступник дорогою поцупив кілька цінних текстів. Злодії отаборилися в таборі Дефіас серед виноградників і сховали здобич у польовому наметі, навіть не здогадуючись про справжню небезпеку темних мистецтв, захованих у книзі."},{t="Перше зв'язування",b="Для майбутнього чорнокнижника повернення фоліанта — водночас випробування на витримку й короткий шлях до темніших таємниць. Той, хто наважиться пройти через табір бандитів і принести книгу, задовольняє честолюбство Друзілли й доводить свою готовність. Отримавши гримуар до рук, вона винагороджує учня темними обрядами, потрібними, щоб прикликати й зв'язати біса — найпершого демона, якого вчиться підкорювати підмайстер."}},fp="15,377,23.518.0,18.420.0,17.410.0,31.286.0,52.312.0,32.181.0,56.276.0,55.237.0,39.246.0"}
P.entries["quest:1599"] = {n="Початок",s="Початок — обряд посвяти для чорнокнижників-початківців Альянсу, що розпочинають шлях у Дун Мороґу. Під неохочим наставництвом Аламара Грімма новачків посилають зібрати магічні талісмани з пера в сусідніх новачків тролів Морозогривів, щоб довести свою вправність, перш ніж опанувати мистецтво призову біса.",h="Початок — обряд посвяти для чорнокнижників-початківців Альянсу, що розпочинають шлях у Дун Мороґу.",kw={"початок","чорнокнижник","аламар грімм","біс","талісман з пера","морозогриви","анвілмар"},ang={["class:Warlock"]="Це завдання — визначальний перший крок у подорожі чорнокнижника Альянсу в Дун Мороґу, що відкриває вам змогу прикликати першого демонічного слугу.",["race:Gnome"]="Гноми-чорнокнижники, що вчаться ремесла в Долині Холодного Хребта, мусять довести свій розум і магічну перевагу, перехитривши місцевих тролів Морозогривів."},sec={{t="Неохочий наставник",b="У безпечному притулку Анвілмара темну магію відкрито не вітають, але терплять із необхідності. Аламар Грімм, досвідчений чорнокнижник, веде свої окультні дослідження відносно непомітно. Коли нові практики виявляють сирий хист, невідомі покровителі з темніших кіл Айронфорджа переконують Грімма відірватися від студій і особисто оцінити новобранців."},{t="Іскра темної магії",b="Перш ніж відкрити новачкові таємниці поневолення менших демонів, Грімм вимагає практичного доказу і фізичної витривалості, і магічної спорідненості. Сусідні новачки тролів Морозогривів, що збираються в печері на південний захід від Анвілмара, носять примітивні талісмани з пера, насичені ледь відчутною первісною магією. Зібрати ці талісмани — довести, що майбутній чорнокнижник здатен подолати магічного супротивника, а заразом дати Гріммові цікаві зразки для подальших досліджень."},{t="Призов біса",b="Повернення з талісманами переконує Грімма, що новачок має достатньо волі, щоб вижити. Випробування завершується навчанням призову біса — найосновнішого поплічника чорнокнижника. Разом із ритуалом Грімм дає суворе застереження: попри крихітний зріст, біси володіють хаотичною вогняною магією, яка легко може взяти гору над недисциплінованим господарем."}},fp="10,299,18.378.0,23.446.0,17.354.0,31.110.0,37.212.0,40.127.0,58.138.0,42.170.0,42.178.0"}
P.entries["quest:16"] = {n="Напоїти Джерарда",s="«Напоїти Джерарда» — проста послуга для Джерарда Тіллера, фермера, що гарує на Виноградниках Маклюрів у Лісі Елвінн. Спраглий під пекучим сонцем, він міняє звичайний урожай на пляшки свіжої джерельної води. Для юних шукачів пригод це ранній урок обміну й підтримки місцевих трударів.",h="«Напоїти Джерарда» — проста послуга для Джерарда Тіллера, фермера, що гарує на Виноградниках Маклюрів у Лісі...",kw={"джерард тіллер","джерельна вода","яблука","виноградники","обмін","ліс елвінн"},ang={["faction:Alliance"]="Підтримка фермерів Нортширу дає певність, що гарнізон і жерці абатства не голодуватимуть у неспокійний час оборони королівства.",["race:Human"]="Для людей, що починають свій шлях у Нортширі, допомога сусідам на кшталт Джерарда Тіллера — ранній приклад духу спільноти, який тримає Елвінн укупі."},sec={{t="Спрагла праця на виноградниках",b="Ферми Лісу Елвінн дають більшу частину зерна, фруктів та овочів, які споживають містяни й гарнізони Стормвінда. Доглядати ряди посівів просто неба — важка й спекотна праця. Джерард Тіллер цілими днями порається в землі на Виноградниках Маклюрів, відганяє шкідників і дбає про врожай. Бігати туди-сюди до міських колодязів йому ніколи, тож він покладається на новобранців, що проходять повз, аби ті принесли чистої джерельної води."},{t="Господарство на обмін",b="Замість монет Джерард воліє чесний і простий обмін харчами. Мандрівники, що мають при собі зайві пляшки Освіжаючої Джерельної Води, можуть виміняти їх на свіжі яблука, щойно зірвані в саду. У королівстві, що з останніх сил підтримує лад і годує армію, прямий обмін між дрібними господарями й новобранцями лишається практичним способом зводити кінці з кінцями в сільському Елвінні."}},fp="19,325,35.446.0,21.394.0,21.183.0,27.192.0,43.155.0,25.160.0,47.61.0,24.84.0"}
P.entries["quest:1654"] = {n="Випробування праведності",s="Випробування праведності — визначальне випробування для паладинів, що зростають у силі й прагнуть освяченої зброї Світла. Майстер-зброяр Джордан Стілвелл пропонує викувати надзвичайне святе озброєння, доручаючи захисникові обшукати далекі землі в пошуках рідкісних ковальських складників, зокрема його загубленого родинного молота.",h="Випробування праведності — визначальне випробування для паладинів, що зростають у силі й прагнуть освяченої...",kw={"випробування праведності","паладин","джордан стілвелл","свята зброя","ковальський молот","самоцвіт кор","фортеця шадовфенг"},ang={["class:Paladin"]="Це завдання — традиційний полігон, що винагороджує відданість і жертовність зброєю, викуваною, щоб спрямовувати святу силу Світла.",["faction:Alliance"]="Спільне зусилля поєднує людську майстерність і володіння Альянсу по всьому Каз Модану й за його межами, щоб озброїти захисників проти дедалі більших темних загроз.",["profession:Blacksmithing"]="Джордан Стілвелл — зразок вершин смертного ковальства: він поєднує повернуте спадкове знаряддя з очищеними таємними й мінеральними складниками, щоб кувати святі реліквії."},sec={{t="Священне замовлення",b="Біля величних воріт Айронфорджа Джордан Стілвелл шукає гідного супутника Світла. Визнаючи діяння паладина, що зростає в силі, коваль пропонує священну угоду: він викує легендарну зброю, що стане тривким символом відданості, якщо паладин візьме на себе небезпечну біганину, потрібну, щоб здобути матеріали найвищого ґатунку."},{t="Складники освячення",b="Щоб викувати зброю, здатну спрямовувати Світло, потрібні інгредієнти з усіх Східних Королівств і з-за їхніх меж. Задум Стілвелла вимагає чотирьох окремих предметів: міцної дубової деревини Вайтстоуну, очищеної руди від майстрів-старателів, очищеного Самоцвіту Кор, що пульсує сирою силою, і повернення власного ковальського молота Джордана, покинутого, коли він із дружиною тікав із Фортеці Шадовфенг. Пошуки змушують паладина випробувати свою витримку проти далеких загроз."},{t="Спадщина коваля",b="Для Джордана Стілвелла ця справа — значно більше за просту торгівлю. Серед потрібних предметів — молот його батька, реліквія, глибоко пов'язана з його ремеслом і родоводом. Поєднавши це повернуте знаряддя з рідкісним очищеним Самоцвітом Кор, Джордан нарешті отримує нагоду втілити задуми, які плекав роками, обертаючи родинну відданість на священне знаряддя справедливості."}},fp="25,315,19.349.0,26.459.0,20.376.1,34.167.0,23.224.0,46.145.0,43.178.0,18.163.0,45.104.0"}
P.entries["quest:1667"] = {n="Мертвозубий Джек",s="Маршала Гаґґарда, відставного офіцера, що живе на сході Лісу Елвінн, обманом змусили віддати свій службовий знак розбійникові Дефіас на ім'я Мертвозубий Джек. У темряві Джек накинув стормвіндську накидку й видав себе за Маршала Дуґана, аби вкрасти значок. Гаґґард просить повернути його, поки Братство Дефіас не скористалося ним, щоб видавати себе за урядовців Стормвінда.",h="Маршала Гаґґарда, відставного офіцера, що живе на сході Лісу Елвінн, обманом змусили віддати свій службовий...",kw={"мертвозубий джек","маршал гаґґард","знак","дефіас","самозванець","ліс елвінн"},ang={["class:Rogue"]="Витівка Мертвозубого Джека доводить, що Братство Дефіас спирається на маскування, хитрість і зухвалість не менше, ніж на грубий розбій на дорогах.",["class:Warrior"]="Маршал Гаґґард колись був загартованим бійцем передової, і тим, хто повертає йому честь, він віддячує запасною зброєю, збереженою з років дійсної служби.",["race:Human"]="Для людей Стормвінда ця крадіжка показує, наскільки вразливі сільські околиці королівства перед шпигунами Дефіас, які без вагань надягають кольори корони, щоб обдурити відставних ветеранів."},sec={{t="Шахрайство в темряві",b="Навіть загартованих вояків на схилі літ можна заскочити зненацька. Маршал Гаґґард, що живе в самотній хатині на східних пагорбах Елвінну, був певен, що розмовляє з Маршалом Дуґаном, коли одного вечора до нього підійшов чоловік у стормвіндській накидці. Пославшись на службову справу, незнайомець попросив старий маршальський знак Гаґґарда. Гадаючи, що передає його товаришу по службі, Гаґґард послухався — а самозванець, злодій Дефіас на прізвисько Мертвозубий Джек, тільки й зміг, що засміятися йому в обличчя й зникнути в лісі."},{t="Загроза фальшивої влади",b="Хоч Гаґґард у відставці, його старий знак і досі має законну вагу й владу Королівства Стормвінд. Поки бандити Дефіас розповзаються Елвінном, Вестфолом і Редріджем, справжній офіцерський знак у руках злочинців — безпосередня небезпека. З ним шпигуни можуть проходити повз пости варти, переспрямовувати патрулі чи забирати припаси. Джек відходить до табору на півдні, щоб сховати крадену здобич у замкненій скрині, а Гаґґард відчайдушно сподівається повернути знак, перш ніж станеться непоправне."}},fp="15,375,17.532.0,29.519.0,23.253.0,45.200.0,44.199.0,38.156.0,51.204.0,40.207.1"}
P.entries["quest:1681"] = {n="Поселення Айронбенда",s="Коваль Айронфорджа Тормус Діпфордж прагне помсти за свого наставника, Стерджі Айронбенда, чия віддалена навчальна застава на сході Дун Мороґу впала під раптовим і кривавим нападом. Різанина сталася після прибуття рідкісної партії тіньової руди, яка одразу привернула люту увагу дворфів Темного Заліза.",h="Коваль Айронфорджа Тормус Діпфордж прагне помсти за свого наставника, Стерджі Айронбенда, чия віддалена...",kw={"поселення айронбенда","стерджі айронбенд","тормус діпфордж","темне залізо","тіньова руда","помста","озеро ложа гелма"},ang={["profession:Blacksmithing"]="Трагічна доля Стерджі Айронбенда — пересторога про те, як гонитва за екзотичними, невипробуваними рудами може накликати смертельні небезпеки на кузню.",["race:Dwarf"]="Набіг на заставу Айронбенда підкреслює гірку й незгасну ненависть між дворфами Бронзбірдами з Айронфорджа та їхніми родичами з Темного Заліза."},sec={{t="Падіння майстра",b="Стерджі Айронбенда шанували по всьому Айронфорджу як неперевершеного вчителя ковальського ремесла. У своєму відлюдному поселенні на південь від Озера Ложа Гелма він навчав перспективних учнів далеко від людних ковадел Великої Кузні. Та мирна справа раптово скінчилася, коли один з учнів здобув незнайомий мінерал, названий тіньовою рудою. Зацікавлений її властивостями, Айронбенд вирішив поекспериментувати зі зразком, геть не підозрюючи, що саме володіння ним прирекло його школу на загибель."},{t="Набіг Темного Заліза",b="Невдовзі після того, як тіньова руда потрапила до поселення, ворожі дворфи Темного Заліза здійснили безжальний раптовий напад на заставу. Нападники не знали милосердя: вони вирізали Стерджі Айронбенда й кожного учня під його опікою, а тоді зайняли угіддя. Тормус Діпфордж, один з уцілілих вихованців Айронбенда, що живе в столиці, відмовляється лишити різанину безкарною й посилає мандрівників Альянсу помститися за вчителя та повернути прокляту руду, що принесла загибель поселенню."}},fp="19,307,15.487.0,18.496.0,37.101.0,24.208.0,50.230.0,19.169.0,24.205.0,50.149.0"}
P.entries["quest:1688"] = {n="Сурена Каледон",s="«Сурена Каледон» — навчальне завдання для чорнокнижників від Ґакіна Зв'язувача Темряви з потаємного підвалу під «Зарізаним Ягням» у Стормвінді. Ґакін доручає чорнокнижнику-початківцю вистежити його колишню ученицю, що зрадила його й утекла до Братства Дефіас, і повернути коштовне намисто з кровавика.",h="«Сурена Каледон» — навчальне завдання для чорнокнижників від Ґакіна Зв'язувача Темряви з потаємного підвалу...",kw={"сурена каледон","ґакін","чорнокнижник","кровавик","дефіас","зарізане ягня","стормвінд"},ang={["class:Warlock"]="Полювання на Сурену Каледон — випробування для чорнокнижника Альянсу, яке доводить: зрада коштує життя, а сентиментам у темних мистецтвах не місце.",["race:Human"]="Дезертирство Сурени показує, якою принадною лишається спокуса Братства Дефіас для невдоволених підданих королівства Стормвінд."},sec={{t="Озлоблений учитель",b="Під таверною «Зарізане Ягня» у Кварталі магів Ґакін Зв'язувач Темряви навчає новачків забороненого мистецтва прикликання скверни. Та й у Ґакіна в минулому були помилки. Перш ніж узяти нових учнів, він навчав молоду жінку на ім'я Сурена Каледон, захоплений і її прихованим магічним хистом, і її вродою. Однак Сурена покинула навчання й прихильність Ґакіна та втекла з міста, щоб приєднатися до Братства Дефіас разом зі своїм коханцем Ерланом Драджмуром."},{t="Украдений кровавик",b="Життя дівчини після втечі Ґакіна мало обходить, але він не бажає розлучатися з коштовним намистом із кровавика, яке подарував їй за часів навчання. Він посилає свого новітнього підмайстра на південний схід, до Гарбузової Ділянки Брекуеллів у Лісі Елвінн — садиби, захопленої бандитами Дефіас, — із чітким наказом зняти коштовність із Сурени будь-якою ціною. Повернений кровавик стане магічним каталізатором для наступного випробування учня: прикликати й зв'язати Блукача порожнечі."}},fp="14,305,15.455.0,21.499.1,22.227.0,36.250.0,34.148.0,41.205.1,24.189.0,47.190.0"}
P.entries["quest:1689"] = {n="Зв'язування",s="«Зв'язування» — останнє випробування на ранньому етапі навчання чорнокнижника Альянсу, мета якого — зв'язати блукача порожнечі в Стормвінді. Під проводом Ґакіна Зв'язувача Темряви майбутній прикликач за допомогою повернутого Намиста Кровавика витягає прислужника з безодні в потаємне підземне коло й силою змушує його скоритися.",h="«Зв'язування» — останнє випробування на ранньому етапі навчання чорнокнижника Альянсу, мета якого — зв'язати...",kw={"зв'язування","блукач порожнечі","чорнокнижник","ґакін","намисто кровавика","стормвінд","квартал магів"},ang={["class:Warlock"]="Цей обряд посвяти дає чорнокнижнику основного захисного прислужника й знаменує перехід від необачного аматора до повелителя сил з інших вимірів.",["faction:Alliance"]="Хоч Альянс відстоює Святе Світло й лад чародійства, прагматичні лідери заплющують очі на темних практиків під Кварталом магів, визнаючи, що в лихі часи без їхніх похмурих мистецтв не обійтися.",["race:Gnome"]="Гноми-чорнокнижники підходять до темного прикликання з науковою цікавістю: під проводом Ґакіна підкорення істот Порожнечі для них — точний метафізичний експеримент.",["race:Human"]="Люди-чорнокнижники мусять зважати на прискіпливу увагу стормвіндського духівництва: вони приборкують небезпечних істот у тіні, ховаючи свою силу від міста нагорі."},sec={{t="Підкорення у криптах",b="Під «Зарізаним Ягням» у стормвіндському Кварталі магів в'ється лабіринт забутих катакомб — далеко від пильних очей Срібної Длані та магістрів Кірін-Тору. Тут Ґакін Зв'язувач Темряви навчає новачків, що опанувати темні мистецтва означає не просто спрямовувати потоки магії, а утверджувати цілковиту владу над потойбічними істотами. Повернувши вкрадене Намисто Кровавика від Сурени Каледон, чорнокнижник має витягти блукача порожнечі просто в коло прикликання під таверною."},{t="Утвердити волю над Порожнечею",b="З блукачем порожнечі не домовляються — його ламають. Скориставшись прихованою силою Намиста Кровавика, прикликач розриває завісу й витягає істоту з тіні у світ смертних. Щоб завершити угоду, чорнокнижник мусить і фізично, і магічно бити створіння, доки його воля не розсиплеться, — так доводять свою владу. Коли блукача здолано, його сутність прив'язується до заклинача, і той здобуває витривалого тіньового захисника, здатного витримувати жорстокі удари в майбутніх битвах."}},fp="11,290,25.543.0,28.501.0,38.288.0,28.301.0,39.261.0,56.262.0,41.203.0,56.266.0"}
P.entries["quest:170"] = {n="Нова загроза",s="Нова загроза — раннє бойове доручення, яке дає Балір Фростгаммер у Долині Холодного Хребта. Дворфійських горян застав зненацька раптовий сплеск трогів, що вириваються по всьому Дун Мороґу, загрожуючи місцевим поселенням і таборам.",h="Нова загроза — раннє бойове доручення, яке дає Балір Фростгаммер у Долині Холодного Хребта.",kw={"нова загроза","балір фростгаммер","троги","скелещелепи","долина холодного хребта","анвілмар","табір"},ang={["faction:Alliance"]="Стримати підземну загрозу в Долині Холодного Хребта — означає зберегти навчальні угіддя Айронфорджа придатними й гарантувати, що південна гірська брама лишиться безпечною для новобранців Альянсу.",["race:Dwarf"]="Для молодих дворфів Бронзбірдів, що виходять з Анвілмара, відбити набіги трогів — особистий обов'язок захистити священні землі й тунелі Дун Мороґу."},sec={{t="Прорив у Долину Холодного Хребта",b="Долину Холодного Хребта довго вважали захищеним притулком для молодих дворфійських воїнів і горян, що навчаються в Дун Мороґу. Той спокій розбився, коли підземні кам'янощелепі троги почали в приголомшливій кількості видиратися на поверхню. До Анвілмара швидко дійшли звістки, що троги заполонили замерзле озеро й довколишні передгір'я, зриваючи щоденні патрулі й перерізаючи життєво важливі шляхи постачання через перевал долини."},{t="Захоплений табір",b="Криза сягнула піку, коли тварюки здійснили узгоджений напад на дворфійський табір на заході, змусивши горян відступити й покинути пости. Не маючи людей і не в змозі відірвати повноцінні полки від Айронфорджа, Балір Фростгаммер звернувся до щойно набраних шукачів пригод, щоб ті прорубалися крізь лави Кам'янощелепів і убезпечили пагорби, перш ніж тварюки підступлять просто до порога Анвілмара."}},fp="12,240,26.426.0,14.404.0,25.209.0,44.222.0,36.179.0,47.196.0,41.203.0,40.220.0"}
P.entries["quest:1739"] = {n="Зв'язування",s="«Зв'язування» — завершальний обряд посвяти для чорнокнижників Альянсу, що прагнуть підкорити сукуба в Стормвінді. Із зачарованим осердям, здобутим із Серцедерева, адепт входить до кола прикликання під «Зарізаним Ягням», щоб витягти демона й здолати його в бою. Коли демона переможено, його волю сковують, прирікаючи його служити прикликачу.",h="«Зв'язування» — завершальний обряд посвяти для чорнокнижників Альянсу, що прагнуть підкорити сукуба в...",kw={"зв'язування","сукуб","чорнокнижник","осердя серцедерева","ґакін","зарізане ягня","склеп"},ang={["class:Warlock"]="Цей обряд — ключова віха для чорнокнижників із людей і гномів: вони переходять від безмозких бісів і блукачів порожнечі до влади над розумними, розважливими демонами.",["faction:Alliance"]="Саме існування цього ритуалу глибоко під Стормвіндом показує, як Альянс тихо терпить магію тіні в потаємних закутках, попри доктрини Церкви."},sec={{t="Спуск до Склепу",b="Під мостинами «Зарізаного Ягняти» в стормвіндському Кварталі магів лежить просторий склеп, присвячений забороненим мистецтвам. Подалі від пильних очей міської варти й Собору Світла таємна громада міських чорнокнижників проводить тут свої найнебезпечніші ритуали. Кола прикликання, викарбувані в камені, спрямовують первісні сили Нижнього Світу й дають честолюбним посвяченим змогу прорвати завісу між світами."},{t="Приборкання спокусниці",b="Прикликати сукуба — це значно більше, ніж бурмотіти заклинання. Чорнокнижник має принести фокус — у цьому разі підготовлене Осердя Серцедерева — і здійснити біля кола обряд прориву. Сукуби вміють розбещувати, спокушати й підкорювати навіть найстійкіший розум. Щоб утвердити цілковиту владу, прикликач мусить зітнути тварюку в двобої, відіславши її тілесну оболонку назад у Викривлений Нижній Світ й водночас закріпивши справжню прив'язь."},{t="Таємниці Ґакіна",b="Убивши прикликане створіння, переможний посвячений повертає виснажене осердя Ґакіну Зв'язувачу Темряви. Довівши і силу духу, і бойову вправність, підмайстер отримує основні знання, потрібні, щоб кликати сукуба через порожнечу, коли завгодно. Цей ритуал знаменує змужніння чорнокнижника Альянсу — відтепер він адепт, здатний давати раду мінливим, розумним демонам."}},fp="11,370,22.421.0,26.440.0,15.398.1,36.258.0,43.307.0,39.356.0,28.297.0,34.235.0,50.298.0"}
P.entries["quest:176"] = {n="РОЗШУКУЄТЬСЯ: «Гоґґер»",s="«РОЗШУКУЄТЬСЯ: „Гоґґер“» — оголошення Альянсу про винагороду, вивішене біля Ґолдшира, за голову велетенського лютого ватажка гнолів. Гоґґер никає південно-західними хащами Лісу Елвінн і жорстоко зривав усі спроби місцевої влади його здолати.",h="«РОЗШУКУЄТЬСЯ: „Гоґґер“» — оголошення Альянсу про винагороду, вивішене біля Ґолдшира, за голову велетенського...",kw={"гоґґер","гноли","розшукується","винагорода","ґолдшир","ліс елвінн","узлісся"},ang={["faction:Alliance"]="Перемога над Гоґґером вважається обрядом посвяти для молодих героїв Альянсу, що гартують характер, обороняючи серце земель Стормвінда.",["race:Human"]="Для людей Елвінну смерть Гоґґера означає безпеку садиб і торгових шляхів, які місяцями тероризували засідки гнолів."},sec={{t="Загроза в лісі",b="Поки Ліс Елвінн потерпає від розбою й навали кобольдів, племена гнолів на півдні стали зухвалішими й згуртованішими під грубим проводом Гоґґера. Гоґґер, що височіє над звичайними гнолами Річколапів, отаборився біля Узлісся, нападає на подорожніх і бере гору над патрулями місцевого ополчення, яких посилають його вгамувати."},{t="Відчай Ґолдшира",b="Армія Стормвінда розтягнута до межі й не може виділити регулярних сил, щоб пильнувати околиці столиці, тож Маршал Дуґан пішов на незвичний крок — призначив відкриту винагороду за звіра. Щоб здолати Гоґґера, треба заглибитися у вкрай ворожі землі гнолів, а його лютість зробила його найсмертоноснішою загрозою для шукачів пригод-початківців в Елвінні."}},fp="16,253,21.347.0,23.369.0,14.234.0,26.184.0,32.274.0,41.151.0,52.226.0,56.251.0"}
P.entries["quest:179"] = {n="Дворфійські постачальники",s="Дворфійські постачальники — вступне завдання на виживання в Долині Холодного Хребта, яке пропонує Стен Стаутарм. За винищення місцевих вовків і збирання їхнього жилавого м'яса на зимові харчі новобранців винагороджують міцними рукавицями, що бережуть від обмороження в лютому холоді Дун Мороґу.",h="Дворфійські постачальники — вступне завдання на виживання в Долині Холодного Хребта, яке пропонує Стен...",kw={"дворфійські постачальники","стен стаутарм","вовки","рукавиці","долина холодного хребта","анвілмар","виживання"},ang={["race:Dwarf"]="Для молодих дворфів Бронзбірдів, що виходять у Долину Холодного Хребта, це завдання — ранній урок прикордонної самодостатності: заробіть своє утримання, забезпечте табір і шануйте гірський холод.",["race:Gnome"]="Знайшовши притулок у дворфійських родичів у Дун Мороґу, гноми швидко переконуються, що для виживання в Анвілмарі практичний гірський одяг потрібен не менше за гострий розум."},sec={{t="Чесна угода в Холодному Хребті",b="Високогірний перевал Долини Холодного Хребта люто холодний, і непідготовлені мандрівники швидко переконуються, що звичайне спорядження стихії не рівня. Стоячи біля Анвілмара, Стен Стаутарм пропонує новобранцям просту прикордонну угоду: вирушити в засніжені замети, вполювати вовків, що там никають, і принести шматки жилавого м'яса, щоб поповнити припаси застави. Натомість він дає справжні теплі рукавиці, щоб молоді шукачі пригод зберегли всі десять пальців."},{t="Жити з того, що дає долина",b="Хоч вовки — постійна небезпека для дворфійських розвідників і гномів-новачків, що навчаються в долині, вони також життєво важливий ресурс. Їхнє м'ясо годує гарнізон, що стоїть в Анвілмарі, а винищення їхнього поголів'я робить стежки між місцевими таборами дещо безпечнішими. Угода Стаутарма має подвійну мету: перевірити вміння новобранця давати раду місцевій звірині й заразом запасти харчі на люті ночі попереду."}},fp="18,283,25.471.0,21.438.0,21.262.0,29.195.0,43.175.0,30.166.0,48.221.0,29.145.0"}
P.entries["quest:18"] = {n="Братство злодіїв",s="«Братство злодіїв» — одне з перших завдань, яке дає Помічник Віллем біля Абатства Нортшира. Він посилає молодих новобранців Альянсу за східну річку, щоб відтіснити зграю розбійників, відому як Братство Дефіас. Зібрані червоні бандани з мішковини — відмітний знак злодіїв — стають для влади Стормвінда першим речовим доказом організованої присутності цієї групи в долині.",h="«Братство злодіїв» — одне з перших завдань, яке дає Помічник Віллем біля Абатства Нортшира.",kw={"братство дефіас","бандани","помічник віллем","нортшир","розбійники","новобранці"},ang={["class:Rogue"]="Зустріч із Дефіас дає розбійникам-новачкам уявлення про те, як організовані злочинні мережі діють у тіні людських земель.",["faction:Alliance"]="Влада Стормвінда покладається на щойно прибулих новобранців Альянсу, щоб підтримувати мир у Нортширі, поки регулярне військо королівства розтягнуте до краю.",["race:Human"]="Для людей, що починають вишкіл у Нортширі, сутичка з Дефіас — перше суворе нагадування про те, що безпека Королівства Стормвінд руйнується зсередини."},sec={{t="Бандити в долині",b="Долину Нортширу довго вважали безпечним прихистком у Лісі Елвінн: її охороняла варта Стормвінда, а саму долину присвятили вишколу новобранців і кліриків Святого Світла. Останнім часом, однак, порядок на околицях похитнувся. Волоцюги й злодії перейшли східну річку, никають біля лісу й ставлять невеликі табори просто під носом в абатства. Помічник Віллем, що відповідає за лад у долині, розуміє: місцева варта не має людей, щоб пильнувати кожен закуток без допомоги добровольців."},{t="Багряний знак",b="Від звичайних розбійників цих злочинців відрізняють злагодженість і однакове вбрання. Вони звуть себе Братством Дефіас і засвідчують свою належність до нього червоними банданами з мішковини, якими закривають обличчя. Наказавши новобранцям полювати на розбійників і забирати їхні маски, Помічник Віллем прагне стримати їхній зухвалий наступ і водночас зважити, як глибоко Дефіас проникли в серце королівства."}},fp="22,393,21.543.0,17.440.0,31.267.0,82.264.0,36.162.0,44.197.0,41.217.0,45.203.0"}
P.entries["quest:1806"] = {n="Випробування праведності",s="Випробування праведності завершується біля кузні Джордана Стілвелла поза Айронфорджем у Дун Мороґу. Зібравши небезпечні складники по всіх Східних Королівствах і Калімдорі, паладин чекає, поки коваль створює могутній бойовий молот. Це знаменує перехід учня в визнаного захисника Світла.",h="Випробування праведності завершується біля кузні Джордана Стілвелла поза Айронфорджем у Дун Мороґу.",kw={"випробування праведності","кулак верігана","бош веріган","джордан стілвелл","паладин","бойовий молот","айронфордж"},ang={["class:Paladin"]="Цей обряд посвяти винагороджує ваші небезпечні мандри далекими землями Кулаком Верігана — знаковою зброєю, присвяченою обстоюванню праведності.",["profession:Blacksmithing"]="Спостерігати за Джорданом Стілвеллом біля ковадла — бачити, як майстерність може вкласти святе призначення в сиру сталь і здобуті матеріали.",["race:Dwarf"]="Викуваний тут молот увічнює пам'ять Боша Верігана, шанованого дворфійського паладина, який утілював стійкість Каз Модану."},sec={{t="Данина коваля",b="Майстер-коваль Джордан Стілвелл працює біля воріт Айронфорджа. Хоч він і зізнається в дрібці заздрості до мандрівних паладинів, він глибоко пишається тим, що підтримує справу своїм молотом і ковадлом. Коли йому приносять рідкісні матеріали, зібрані в тіньових криптах, затонулих руїнах і небезпечних копальнях, Стілвелл виконує обіцянку й кує зброю, гідну справжнього захисника."},{t="Спадщина Боша Верігана",b="Готовий бойовий молот охрещено Кулаком Верігана на честь Боша Верігана, шанованого дворфійського паладина й близького особистого друга Джордана Стілвелла. Передаючи цю священну зброю в руки молодого захисника від себе й від дружини, Стілвелл дбає, щоб пам'ять і доблесть його полеглого друга жили далі проти темряви, що загрожує Азероту."}},fp="25,320,17.391.0,27.358.0,43.211.0,21.190.0,35.152.0,59.243.0,50.225.0,54.228.0"}
P.entries["quest:1819"] = {n="Улаг Різник",s="Улаг Різник — обряд посвяти для молодих воїнів Відступників у Галявинах Тірісфалю. Вартовий Смерті Діллінджер доручає вам звільнити й стратити поневоленого воїна Погибелі, ув'язненого в північному мавзолеї, — випробування вашої бойової рішучості, що здобуде вам повагу Вартових Смерті.",h="Улаг Різник — обряд посвяти для молодих воїнів Відступників у Галявинах Тірісфалю.",kw={"улаг різник","діллінджер","брілл","мавзолей","погибель","воїн","випробування"},ang={["class:Warrior"]="Це випробування — ранній полігон для воїнів Відступників: воно перевіряє вашу відвагу в сутичці з могутнім, підкореним чужій волі поборником Погибелі.",["race:Undead"]="Доля Улага показує жахливу правду про владу Погибелі — трагічну межу між Відступниками, які вирвалися на волю, і тими, чий розум досі в рабстві Короля-Ліча."},sec={{t="Скутий раб Погибелі",b="Коли Погибель прокотилася Лордероном, Відступникам вдалося захопити незвичайного воїна-нежить, який назвався Улагом Різником. Розум Улага лишався ясним і притомним, та дух його нерозривно скоряла психічна воля Короля-Ліча. Прагнучи зрозуміти, як саме Погибель сковує вільну волю, Відступники тримали його під магічною печаттю в мавзолеї на північ від Брілла, сподіваючись розірвати духовні ланцюги цієї сутності."},{t="Випробування ката",b="Усі спроби вирвати Улага з ментальних лещат Короля-Ліча зазнали невдачі. Збагнувши, що справжню свободу йому може дати лише знищення, Вартовий Смерті Діллінджер перетворив бранця на бойове випробування для молодих воїнів Відступників. Зрушивши камінь-череп біля входу до склепу, воїн ламає захисні печаті, випускає Улага з ув'язнення — і дарує йому звільнення лезом сокири."}},fp="16,280,22.455.0,23.417.0,24.233.0,44.246.0,44.236.0,21.178.0,33.174.0,36.156.0"}
P.entries["quest:182"] = {n="Тролляча печера",s="Доручене горянином Ґреліном Вайтбірдом, це завдання посилає шукачів пригод винищити молодих тролів Морозогривів, що збираються в південних печерах Долини Холодного Хребта. Поки Сенат Айронфорджа заклопотаний дедалі гострішою кризою з трогами, самотні розвідники й охочі новобранці мусять давати раду прикордонним сутичкам, перш ніж тролі закріпляться назавжди.",h="Доручене горянином Ґреліном Вайтбірдом, це завдання посилає шукачів пригод винищити молодих тролів...",kw={"тролляча печера","ґрелін вайтбірд","морозогриви","тролі","долина холодного хребта","розвідка","печера"},ang={["class:Hunter"]="Скелі довкола південної печери — суворий полігон для молодих слідопитів, що вчаться виганяти ворожу здобич із гірських висот.",["race:Dwarf"]="Для молодих дворфів Бронзбірдів, що виходять у сніги, винищення загонів Морозогривів — і справа прикордонної безпеки, і давня гірська ворожнеча.",["race:Gnome"]="Знайшовши притулок у Дун Мороґу після падіння Гномреґану, гноми охоче дають свій розум і зброю, щоб позбавити дворфів-господарів довколишніх загроз."},sec={{t="Очі на холоді",b="Поки регулярні сили Айронфорджа поглинуті відбиттям набігів трогів Кам'янощелепів по снігових полях, південні підступи не можна лишати без нагляду. Ґреліна Вайтбірда та його брата Сеніра гірська влада відрядила оцінити, чи становлять тутешні крижані тролі безпосередню небезпеку для серця краю. З кручі над замерзлою долиною Ґрелін сам-один стежить за їхніми пересуваннями."},{t="Випереджувальний удар",b="Розвідка Ґреліна показала, що місцевий клан Морозогривів почав оселятися в глибокій печері вздовж південного хребта Долини Холодного Хребта. Вважаючи повну військову мобілізацію марною тратою дворфійських сил, розвідник волів найняти вправних місцевих добровольців, щоб винищити зухвалих молодиків. Прорідити їхніх молодих бійців — означає зірвати їхній табір, перш ніж Морозогриви зможуть здійснити узгоджені набіги на сусідні дворфійські обійстя."}},fp="14,348,16.431.0,19.464.0,70.270.0,29.237.0,32.120.0,25.216.0,53.218.0,36.197.1"}
P.entries["quest:1820"] = {n="Поговори з Колманом",s="«Поговори з Колманом» — перехідне завдання в Галявинах Тірісфалю для тих, хто вже довів свою вартість у боротьбі з Погибеллю. Вартовий Смерті Діллінджер відсилає здібних воїнів із міської площі до місцевої таверни — допомогти Коулмену Фартінґу з його особистими та фракційними порахунками.",h="«Поговори з Колманом» — перехідне завдання в Галявинах Тірісфалю для тих, хто вже довів свою вартість у...",kw={"коулмен фартінґ","брілл","таверна","діллінджер","вендета","тірісфаль"},ang={["faction:Horde"]="Для мандрівників, що допомагають убезпечити Лордерон, знайомство з місцевими жителями Брілла — надійна опора для дій по всіх Галявинах Тірісфалю.",["race:Undead"]="Багато Відступників поряд із вірністю Темній Леді плекають особисті образи; прохання Коулмена Фартінґа показують, як тісно у Тірісфалі переплітаються особиста втрата й захист нації."},sec={{t="Слово від варти",b="Допомігши приборкати серйозні місцеві загрози — скажімо, упокоївши небезпечні рештки Погибелі на кшталт Улага Різника, — шукачі пригод здобувають особисту довіру Вартового Смерті Діллінджера. Як один із вартових, що пильнують дороги до Брілла, Діллінджер сам судить, хто здатен на більше, ніж звичайні обходи периметра, і скеровує вмілих бійців до городян, яким потрібна особлива послуга."},{t="Приватна вендета",b="Не кожен конфлікт у Галявинах Тірісфалю ведеться за наказом верховного командування з Андерсіті. По всьому зруйнованому королівству Лордерон уцілілі мерці носять у собі глибокі образи, пов'язані з землями, родинами й статками, що лишилися в минулому. Коулмен Фартінґ вичікує в Таверні «Шибеничний Кінець», шукаючи знаряддя помсти, щоб ударити по загрозах, які й досі тиняються біля колишніх поселень на кшталт Млинів Аґаманда."}},fp="18,283,21.406.0,18.413.0,34.123.0,33.132.0,45.174.0,57.145.0,53.164.0,32.162.0"}
P.entries["quest:1821"] = {n="Реліквії роду Аґамандів",s="Коулмен Фартінґ доручає шукачам пригод сплюндрувати Родинний Склеп Аґамандів на північному краю Млинів Аґаманда. Гнаний гіркою образою за власну смертну загибель, він прагне відібрати в колишніх господарів їхню родову зброю і стерти останні рештки їхньої гідності.",h="Коулмен Фартінґ доручає шукачам пригод сплюндрувати Родинний Склеп Аґамандів на північному краю Млинів...",kw={"аґаманди","склеп","реліквії","коулмен фартінґ","млини аґаманда","родова зброя"},ang={["class:Rogue"]="Прослизнути повз гулів, що чигають у темряві, і поцупити стародавню зброю з охоронюваних поховальних склепінь — для майстрів тіні справа звична.",["faction:Horde"]="Зачистка склепу підриває укорінену владу Погибелі над північчю Галявин Тірісфалю, роблячи край безпечнішим для мандрівників Орди.",["race:Undead"]="Гірке завдання Коулмена Фартінґа втілює давні образи й незагоєні рани, які чимало Відступників несуть зі смертного життя в нежиття."},sec={{t="Гірка образа слуги",b="Перш ніж Третя війна спустошила Лордерон, Коулмен Фартінґ служив заможній і впливовій родині Аґамандів на їхніх розлогих млинах у Галявинах Тірісфалю. Хай що сталося під час падіння маєтку, у своїй смерті Фартінґ цілковито звинувачує колишніх панів. Тепер, піднятий у нежитті серед Відступників, він дивиться на падіння Аґамандів зі злісним задоволенням, радіючи, що колись горда династія обернулася на безтямних прислужників Короля-Ліча."},{t="Осквернення склепу",b="Щоб остаточно загасити рештки родинної слави, Фартінґ посилає шукачів пригод до Родинного Склепу Аґамандів, схованого під північними кручами млинів. У його населених привидами кам'яних залах неспокійні мерці блукають пліч-о-пліч із недобитками Погибелі. Фартінґ вимагає добути чотири славетні реліквії — родовий меч, сокиру, кинджал і булаву Аґамандів, — щоб спадок їхнього роду позбувся останньої крихти честі."}},fp="17,272,25.468.0,21.443.0,33.266.0,45.219.0,36.230.0,42.144.0,39.181.0,63.180.0"}
P.entries["quest:183"] = {n="Мисливець на вепрів",s="Мисливець на вепрів — раннє доручення від дворфа-мисливця Таліна Кіная в Долині Холодного Хребта. Сплеск місцевої популяції скельних вепрів зробив ліси надто небезпечними, і молодим новобранцям доручають винищити зухвалих звірів, щоб досвідчені мисливці могли спокійно йти по сліду.",h="Мисливець на вепрів — раннє доручення від дворфа-мисливця Таліна Кіная в Долині Холодного Хребта.",kw={"мисливець на вепрів","талін кінай","скельні вепри","вепр","долина холодного хребта","анвілмар","полювання"},ang={["class:Hunter"]="Талін Кінай утілює пряме дворфійське ставлення до вистежування: тримайте приціл твердо, шануйте звірів і розчищайте хащі, коли дичина стає надто ворожою.",["race:Dwarf"]="Жити в горах — означає ділити землю з лютою звіриною. Винищити войовничих скельних вепрів довкола Анвілмара — обряд посвяти для кожного молодого дворфа, що робить перші кроки за межі кузні.",["race:Gnome"]="Для гномів-біженців, що щойно прибули з Гномреґану, зустріч із лютими дикими вепрами Дун Мороґу — суворе, практичне знайомство з життям у суворому дворфійському краї."},sec={{t="Переповнена долина",b="Долина Холодного Хребта зазвичай тихий, захищений навчальний майданчик для молодих горян і вчених Айронфорджа. Та в суворому зимовому кліматі звірина часто стає неспокійною й надто численною. Талін Кінай, досвідчений мисливець, що стоїть біля Анвілмара, помічає, що зухвалі малі скельні вепри розплодилися так швидко, що становлять справжню загрозу для кожного, хто блукає засніженими стежками."},{t="Доглядаючи сніги",b="Полювання — наріжний камінь дворфійського життя: воно дає м'ясо, шкуру й необхідну практику польового ремесла. Та коли дичина стає напастю, що нападає, щойно побачить, треба винищити зайве, щоб відновити рівновагу. Прорідивши скельних вепрів на схилах долини, молоді шукачі пригод доводять свою бойову готовність і дають місцевим мисливцям простір для їхнього ремесла, щоб ті не були задавлені кількістю."}},fp="15,279,16.412.0,17.384.0,21.214.0,38.203.0,34.120.0,57.168.0,43.215.0,49.224.0"}
P.entries["quest:1842"] = {n="Копита сатирів",s="«Копита сатирів» — завдання від троля-ремісника Ула'елека з Села Сен'джин. Щоб викувати пару наділених силою жорстоких латних рукавиць, воїни мають вирушити на північ, в Ашенваль, полювати на сатирів і здобути їхні магічно набряклі, нерозколоті копита.",h="«Копита сатирів» — завдання від троля-ремісника Ула'елека з Села Сен'джин.",kw={"копита сатирів","сатири","ашенваль","ула'елек","сен'джин","рукавиці","воїн"},ang={["class:Warrior"]="Це завдання — частина обряду поступу воїна, що випробовує його бойову стійкість проти хитрих демонічних засідників заради особистих обладунків.",["faction:Horde"]="Це полювання виводить воїнів Орди з посушливих рівнин Дуротару вглиб спірних земель нічних ельфів в Ашенвалі.",["race:Troll"]="Методи Ула'елека показують прагматичну вдачу ремесла Темного Списа: висмоктувати сиру сутність із полеглих магічних ворогів замість покладатися лише на звичайне ковальство."},sec={{t="Приборкання оскверненої сутності",b="Щоб викувати обладунки, здатні змагатися з найжорстокішими силами Калімдору, ремісник Темного Списа Ула'елек дивиться далі за буденне залізо та шкіру. Він посилає майбутніх воїнів на північ, у давні ліси Ашенвалю, де в тутешніх ковенах сатирів гніздиться невигасла демонічна скверна."},{t="Набряк магії Ашенвалю",b="За словами Ула'елека, сатири північно-східного Ашенвалю живляться, висмоктуючи приховану чистоту лісу й обертаючи її на мерзенну силу. Ті демони, що найглибше нажерлися цього позиченого життя, мають неприродно набряклі копита, які втратили природну розколину. Ула'елек має намір витягти цю зосереджену магічну енергію і вплести її просто в рукавиці, які кує."}},fp="12,253,28.286.0,30.413.0,36.195.0,27.145.0,36.161.0,16.157.0,31.140.0,44.180.0"}
P.entries["quest:1843"] = {n="Жорстокі Латні Рукавиці",s="«Жорстокі Латні Рукавиці» — вінець ремесла майстра для загартованих воїнів Орди. Коли рідкісні складники зібрано в далеких землях, ремісник Ула'елек виготовляє грізну пару рукавиць, покликаних принести честь і майстру, і носієві.",h="«Жорстокі Латні Рукавиці» — вінець ремесла майстра для загартованих воїнів Орди.",kw={"жорстокі латні рукавиці","рукавиці","ула'елек","воїн","обладунки","ремесло","дуротар"},ang={["class:Warrior"]="Ці рукавиці знаменують перехід воїна до дисциплінованого бойового лідерства і слугують надійною частиною захисного спорядження, викуваного саме для важкого ближнього бою.",["faction:Horde"]="Ремесло Орди тримається на тривкій традиції та бойовій гордості, щоб чемпіони несли в бій духовну вагу й честь своїх майстрів."},sec={{t="Шедевр ремісника",b="Викувати обладунок, гідний загартованого воїна передової, — для ремісників Орди більше ніж просте металоробство: це духовна справа. Ула'елек, ремісник із Дуротару, вкладає свій рід і вміння в ці жорстокі латні рукавиці. Використовуючи загартовані трофеї, здобуті з небезпечних супротивників, він створює обладунок, що витримує люті удари й водночас посилює наступальну міць носія."},{t="Честь предків",b="В орчих і тролячих традиціях добра зброя й обладунки несуть у бій престиж кузні та дух майстра. Вручаючи воїну готові рукавиці, Ула'елек довіряє йому спадщину своїх предків. Від чемпіона, який носить їх у бою, чекають відваги, бойової дисципліни та сили, гідних цієї майстерності."}},fp="16,262,25.416.0,15.367.0,16.212.0,49.203.0,52.214.0,32.168.0,43.180.0,41.182.0"}
P.entries["quest:1861"] = {n="Дзеркальне Озеро",s="«Дзеркальне Озеро» — вступне дослідницьке завдання для магів-початківців Альянсу, які навчаються в Кварталі магів Стормвінда. За дорученням Дженнеї Кеннон підмайстри вирушають на південний захід від міської брами, щоб узяти пробу води з водоспаду Дзеркального Озера на залишкове магічне забруднення.",h="«Дзеркальне Озеро» — вступне дослідницьке завдання для магів-початківців Альянсу, які навчаються в Кварталі...",kw={"дзеркальне озеро","маг","дженнея кеннон","святилище чародія","проба води","стормвінд"},ang={["class:Mage"]="Це завдання знаменує перехід підмайстра від запилюжених фоліантів у Святилищі Чародія до дослідження справжніх магічних явищ, і винагородою стає перший справжній посох мага або куля для другої руки.",["faction:Alliance"]="Дбати про безпеку природних багатств Елвінну — один із непомітних способів, якими маги Святилища Чародія оберігають серце королівства.",["race:Human"]="Дзеркальне Озеро живить довколишні поля й річки Елвінну, тож його чистота життєво важлива для щоденного здоров'я мешканців Стормвінда."},sec={{t="Лей-лінії та зміщені потоки",b="За останні десятиліття Азерот пережив катастрофічні магічні потрясіння — від відкриття Темного Порталу до Третьої війни й битви біля Гори Гіджал. Ці жорстокі удари зірвали прадавні чародійські потоки з їхніх колись стійких русел. У Святилищі Чародія в Стормвінді маги на кшталт Дженнеї Кеннон пильно стежать за цими зсувами, побоюючись, що зміщені потоки магічної сили просочаться в довколишні нетрі й отруять місцеву природу."},{t="Проба води",b="Дзеркальне Озеро притулилося під скелями на південний захід від брами Стормвінда й слугує головним природним водосховищем, яке живлять гірські водоспади. Від цих вод залежить уся округа, тож Дженнея посилає магів-новачків зі скляною пляшкою просто до підніжжя водоспаду. Зібрані свіжі бризки дають Святилищу змогу провести тонкі ворожіння й реагентні проби, щоб з'ясувати, чи не почала дика магія просочуватися в питну воду."}},fp="11,279,31.453.0,18.464.0,60.237.0,29.215.0,37.141.0,31.177.0,47.214.0,67.127.0"}
P.entries["quest:1879"] = {n="Поговори з Бінк",s="«Поговори з Бінк» — виклик Альянсу, що скеровує магів-новачків із Дун Мороґу до столиці, Айронфорджа. Надісланий Маґісом Спаркмантлом, він посилає перспективних заклиначів на допомогу Бінк, дослідниці таємних мистецтв, що працює в Залі Таїнств.",h="«Поговори з Бінк» — виклик Альянсу, що скеровує магів-новачків із Дун Мороґу до столиці, Айронфорджа.",kw={"поговори з бінк","бінк","маґіс спаркмантл","маг","зала таїнств","містичний квартал","айронфордж"},ang={["class:Mage"]="Цей виклик знаменує ваш відхід від вступного вишколу в долині до ширших справ учених чародіїв Айронфорджа.",["faction:Alliance"]="Спільні студії в Залі Таїнств показують тісне поєднання гномського розуму й дворфійської гостинності під прапором Альянсу.",["race:Gnome"]="Бінк і Маґіс Спаркмантл утілюють продовження гномської традиції таємних мистецтв у гостинних залах Айронфорджа після втрати Гномреґану."},sec={{t="Виклик від колеги",b="Маги-новачки, що навчаються серед холодних скель Дун Мороґу, зрештою потрапляють на око Маґісу Спаркмантлу. Помітивши, що учень переріс елементарні вправи довкола Хараноса, Спаркмантл передає слово від своєї колеги, Бінк. Прохання точне й безкомпромісне: Бінк потрібен фахівець із таємних мистецтв, і вона відмовляється довіряти справу будь-кому, хто не володіє магією."},{t="Зала Таїнств",b="Завдання веде молодих магів до Містичного Кварталу Айронфорджа, де вчені, жерці й чародії збираються під високими кам'яними склепіннями Зали Таїнств. Тут Бінк веде свої студії, оцінюючи прибулих учнів гострим поглядом. На її думку, сирий потенціал — лише початок: недисциплінований заклинач у таємних справах швидко стає небезпекою, а не помічником."}},fp="15,259,21.388.0,21.404.0,21.113.0,22.108.0,31.192.0,32.141.0,52.134.0,30.172.0"}
P.entries["quest:21"] = {n="Сутичка на Ехо-Рідж",s="«Сутичка на Ехо-Рідж» — пряма військова операція за наказом Маршала Макбрайда: очистити Шахту Ехо-Рідж від кобольдів-робітників. Після першої розвідки цей удар має не дати підземній заразі закріпитися в Долині Нортширу назавжди.",h="«Сутичка на Ехо-Рідж» — пряма військова операція за наказом Маршала Макбрайда: очистити Шахту Ехо-Рідж від...",kw={"ехо-рідж","кобольди","шахта","сутичка","маршал макбрайд","нортшир"},ang={["class:Warrior"]="Підземні бійки проти роїв робітників дають молодим воїнам перший смак ближнього бою проти багатьох укріплених ворогів.",["faction:Alliance"]="Кожна відбита в чудовиськ шахта дає камінь і руду, без яких не відбудувати й не зміцнити людські поселення після війни.",["profession:Mining"]="Зачистка шахти від зарази повертає надію, що цінні рудні жили Долини Нортширу знову можна буде безпечно розробляти й виплавляти.",["race:Human"]="Зачистка Ехо-Ріджу — перше справжнє бойове випробування новобранця на захист рідного королівства, у якому він доводить свою доблесть просто перед військовим командуванням Стормвінда."},sec={{t="Зачистка шахти",b="Щойно розвідка підтвердила, що кобольди заполонили Шахту Ехо-Рідж, Маршал Макбрайд не гаючись організував рішучу контратаку. Якщо підземних шкідників не чіпати, вони швидко укріплюють тунелі, накопичують крадені запаси й плодяться без упину. Щоб захистити Долину Нортширу — важливий землеробський і духовний осередок, — місцевий гарнізон покладається на новобранців: ті мають стати до бою з кобольдами-робітниками й проріджувати їхні лави, поки ті не вкоренилися ще глибше."},{t="Тонка оборона",b="Те, що для прямого лобового штурму доводиться залучати щойно зарахованих новобранців, свідчить про виснажений стан армії Стормвінда. Передові гарнізони розтягнуті вздовж південних кордонів, по всьому Елвінну ширяться чутки про заворушення, тож місцевим офіцерам на кшталт Макбрайда доводиться збирати будь-які охочі руки. Успішна сутичка на Ехо-Рідж доводить надійність новобранця, здобуває йому справжню повагу й готує до важливіших місій деінде в королівстві."}},fp="22,283,16.486.0,14.500.0,46.266.0,24.223.0,52.263.0,34.203.0,57.260.0,66.252.0"}
P.entries["quest:2159"] = {n="Посилка для Доланаара",s="«Посилка для Доланаара» — доручення для молодих нічних ельфів, що покидають затишне віття Тінедолу заради ширших просторів Тельдрассила. Портанніус, затриманий справами з тутешніми друїдами, доручає мандрівникам віднести пакунок трав на південь, Корчмареві Келдаміру. Проста подорож позначає перехід посвяченого в гамірний осередок Доланаара.",h="«Посилка для Доланаара» — доручення для молодих нічних ельфів, що покидають затишне віття Тінедолу заради...",kw={"посилка для доланаара","портанніус","корчмар келдамір","трави","тінедол","доланаар","тельдрассил"},ang={["class:Druid"]="Заклопотаність Портанніуса друїдами Тінедолу натякає на глибші духовні обов'язки й порушення природної рівноваги, якими переймається Коло Кенарія у вітті.",["profession:Herbalism"]="Доставка показує, які важливі сирі трави з родючих ґрунтів Тінедолу для цілителів, кухарів і доглядачів Доланаара.",["race:NightElf"]="Узятися за це завдання означає для нічного ельфа покинути захищену колиску Алдрассила заради ширшої відповідальності за захист Тельдрассила."},sec={{t="Гінець для Тінедолу",b="Перш ніж нові шукачі пригод покинуть навчальні угіддя Тінедолу, Портанніус шукає когось, хто прямує дорогою до решти Тельдрассила. Заклопотаний нагальними справами з друїдами, що доглядають долину, він не може відірватися, щоб самому бігати з буденними дорученнями. Натомість він вкладає в руки майбутнього героя в'язку свіжозібраних трав, щоб важливі припаси дісталися на південь лісовою стежкою."},{t="Дорога до Доланаара",b="Південна дорога з відлюдної долини веде мандрівників до Доланаара — одного з найважливіших поселень нічних ельфів на великому вітті Тельдрассила. Там Корчмар Келдамір порядкує гостинністю, відпочинком і припасами для подорожніх, вартових і друїдів. Приймаючи трави від імені Портанніуса, Келдамір користається нагодою закликати молодих шукачів пригод дати спочинок розуму й духові, перш ніж стати проти скверни, що шириться світовим деревом."}},fp="17,359,26.414.0,20.466.0,19.211.0,48.201.0,27.111.0,26.216.0,26.140.0,53.187.0"}
P.entries["quest:2160"] = {n="Припаси для Таннока",s="Припаси для Таннока — доручення для шукачів пригод-початківців, що залишають Долину Холодного Хребта небезпечним гірським перевалом у великий Дун Мороґ. Гном-майстер Гендс Спрінґспрокет посилає ящик потрібних харчів Танноку Фростгаммеру до корчми при Ґуральні Тандербрю в Хараносі в обхід кишачих трогами стежок, що перерізали звичну торгівлю.",h="Припаси для Таннока — доручення для шукачів пригод-початківців, що залишають Долину Холодного Хребта...",kw={"припаси для таннока","гендс спрінґспрокет","таннок фростгаммер","ящик","перевал холодного кряжа","ґуральня тандербрю","харанос"},ang={["faction:Alliance"]="Відновлення торгівлі між відрізаними заставами тримає внутрішні лінії постачання Айронфорджа в русі попри дикі набіги трогів.",["race:Dwarf"]="Пронести припаси з Анвілмара до Хараноса — ваш обряд посвяти: вихід із захищеної долини на службу ширшому королівству Айронфорджа.",["race:Gnome"]="Допомога Гендсу Спрінґспрокету показує надійну співпрацю між вигнанцями Гномреґану та їхніми дворфійськими господарями в Дун Мороґу."},sec={{t="Заблокована долина",b="Долина Холодного Хребта традиційно полігон і прихисток для молодих дворфів Айронфорджа й уцілілих вигнанців Гномреґану, але недавні події підірвали її зв'язок із рештою Дун Мороґу. Набіги трогів заполонили Перевал Холодного Кряжа, і гірську тіснину стало небезпечно переходити. Горяни розтягнуті тонко, стережучи поселення й оборонні периметри, тож заплановані супроводи припасів затримуються на багато днів."},{t="Гендс і помічник корчмаря",b="Гендс Спрінґспрокет, гном, що зупинився в Анвілмарі, опинився з ящиком життєво важливих корчемних припасів для Хараноса й без жодного безпечного способу доправити його особисто. Знаючи, що витривалі шукачі пригод уже готуються кинути виклик небезпечному перевалу, він залучає мандрівників, що вирушають у дорогу, пронести вантаж Танноку Фростгаммеру, помічникові в людній корчмі Тандербрю."},{t="Гостинне вогнище в Хараносі",b="Дістатися Хараноса — для шукача пригод вхід у ширший світ Дун Мороґу. Таннок Фростгаммер радо приймає доставку, зауважуючи, що звісток з Анвілмара бракувало, відколи троги зірвали рух через перевал. Доправлений крам відновлює крихку лінію зв'язку й торгівлі між двома відрізаними дворфійськими громадами."}},fp="18,367,18.421.0,35.383.0,30.353.0,28.205.0,26.196.0,45.192.0,37.174.0,41.140.0,59.201.0"}
P.entries["quest:2161"] = {n="Тягар пеона",s="«Тягар пеона» — вступне завдання з доставки від Укора, стривоженого орка-робітника, що застряг на стежці за межами Долини Випробувань. Спробувавши доставити харчі новобранцям, яким вони виявилися непотрібні, Укор доручає мандрівникам безпечно повернути важкий вантаж до Гострого Пагорба.",h="«Тягар пеона» — вступне завдання з доставки від Укора, стривоженого орка-робітника, що застряг на стежці за...",kw={"тягар пеона","укор","пеон","робітник","припаси","гострий пагорб","долина випробувань"},ang={["faction:Horde"]="Цей перехід — вихід із тренувальних земель, що знайомить мандрівників із Гострим Пагорбом, головним осередком оборони й постачання Орди в південному Дуроторі.",["race:Orc"]="Орча культура цінує фізичну міць і відвагу, тож пеони на кшталт Укора опиняються на самому дні суспільної ієрархії; виконати його доручення — означає побачити, як навіть скромна праця тримає молоду націю Дуротару на плаву."},sec={{t="Доставка не за адресою",b="Укор — щирий пеон, що вирушив із Гострого Пагорба з добрими намірами, тягнучи важкий пакунок харчів до Долини Випробувань. Вірячи, що новобранцям у червоному каньйоні конче потрібні харчі, він подолав дорогу лише для того, щоб його відіслали геть. Наглядачі випробувань навмисне тримають припаси мізерними: як згодом зауважує Корчмар Ґроск, виживання на пісному харчі вважають способом гартувати дисципліну й витривалість молодих воїнів Орди."},{t="Небезпеки червоної пустки",b="Хоч Укор дістався перевалу, повертатися випаленою сонцем землею Дуротару йому страшно. Скелі вздовж стежки кишать агресивними скорпідами, отруйними павуками й вепрами, що нишпорять довкола. Без зброї, броні й бойового духу, якого чекають від орчих бійців, наляканий робітник чекає при дорозі й благає кожного шукача пригод, що покидає тренувальні землі, узяти на себе його тягар і повернути його до корчми."}},fp="15,305,20.477.0,23.460.0,12.254.0,62.278.0,36.156.0,44.229.0,39.269.0,23.222.0"}
P.entries["quest:218"] = {n="Вкрадений щоденник",s="Вкрадений щоденник — раннє завдання Альянсу в Дун Мороґу, у якому Ґрелін Вайтбірд доручає шукачам пригод увійти до тролячої печери в Долині Холодного Хребта й повернути його вкрадений записник. Щоб забрати його, ви мусите здолати грізного тролячого ватажка Ґрік'ніра Холодного. Повернення щоденника дає Ґреліну змогу завершити оцінку тролячої загрози в Долині Холодного Хребта.",h="Вкрадений щоденник — раннє завдання Альянсу в Дун Мороґу, у якому Ґрелін Вайтбірд доручає шукачам пригод...",kw={"вкрадений щоденник","ґрелін вайтбірд","ґрік'нір холодний","троляча печера","морозогриви","тролі","долина холодного хребта"},ang={["faction:Alliance"]="Придушення зухвалого племені Морозогривів гарантує, що початкові долини Дун Мороґу лишаться захищеними від внутрішніх заворушень.",["race:Dwarf"]="Знищення ватажків Морозогривів у Долині Холодного Хребта захищає молодих дворфійських новобранців, що роблять перші кроки за межі Анвілмара.",["race:Gnome"]="Гномські біженці, що знайшли прихисток в Анвілмарі, покладаються на безпеку перевалів Долини Холодного Хребта, поки перегруповуються на дворфійській землі."},sec={{t="Загублені нотатки вченого",b="Ґрелін Вайтбірд спостерігає за тролями Морозогривами, що наступають на Долину Холодного Хребта, й веде докладні нотатки про їхні звички й раптову зухвалість. Під час заворушень незвично кремезний троль утік з його особистим щоденником і сховався в глибині їхнього лігва. Для Ґреліна втрата не лише сентиментальна: у записнику — основна частина його розвідки, і офіційна оцінка стоїть на місці, доки його не повернуть із печери."},{t="Сутичка з Ґрік'ніром Холодним",b="Здоровань, що забрав щоденник, — Ґрік'нір Холодний, могутній троль Морозогрив із прикметним розписом на тілі й обличчі, який править у серці тролячої печери долини. Убити Ґрік'ніра — означає зламати місцеве керівництво тролів печери й повернути щоденник Ґреліна. Коли ватажка знищено, Ґрелін почувається досить упевнено, щоб доповісти, що становище з тролями в долині під контролем, і надсилає завершені висновки своєму братові Сеніру."}},fp="18,368,22.459.0,29.474.0,37.160.0,37.95.0,39.176.0,42.193.1,67.198.0,24.160.0"}
P.entries["quest:233"] = {n="Доставка пошти в Долині Холодного Хребта",s="Доставка пошти в Долині Холодного Хребта — просте кур'єрське доручення, яке Стен Стаутарм в Анвілмарі довіряє новобранцям. Гірські перевали часто забиті снігом, а троги тиснуть поруч, тож рознесення свіжої кореспонденції до таборів уздовж замерзлого озера тримає відрізаних захисників долини на зв'язку.",h="Доставка пошти в Долині Холодного Хребта — просте кур'єрське доручення, яке Стен Стаутарм в Анвілмарі довіряє...",kw={"доставка пошти","стен стаутарм","талін кінай","листи","долина холодного хребта","анвілмар","кур'єр"},ang={["faction:Alliance"]="Кожна застава в Долині Холодного Хребта відіграє роль у безпеці Дун Мороґу, тож надійне листування необхідне для ранньої військової координації.",["race:Dwarf"]="Носити звістки між заставами підкреслює спільну твердість дворфів Айронфорджа, яка тримає навіть найдальших розвідників долини пов'язаними зі своїми кланами.",["race:Gnome"]="Як гостям і союзникам у Дун Мороґу після падіння Гномреґану, допомога з лініями зв'язку зміцнює довіру місцевих дворфійських захисників."},sec={{t="Кур'єр у снігу",b="Життя в Долині Холодного Хребта відлюдне навіть у найспокійнішу пору. Коли зимові кур'єри щасливо долають гірський перевал із поштою з решти Дун Мороґу, листи швидко громадяться в Анвілмарі. Стен Стаутарм, заклопотаний місцевим постачанням і безпекою, покладається на мандрівних новобранців, щоб ті несли ці згортки західною дорогою, а не лишали важливі звістки припадати пилом у залі."},{t="Прикордонні застави",b="Адресат, Талін Кінай, стоїть на варті біля замерзлого озера на заході, стежачи за пересуваннями трогів і небезпечною звіриною. Навіть на холоді слово з Айронфорджа й довколишніх застав лишається дорогим. Однак сортування пошти в суворих гірських умовах рідко буває бездоганним, і листи для різних розвідників часто мандрують разом в одному згортку."}},fp="30,297,21.405.0,17.372.0,29.210.0,31.118.0,52.151.1,49.265.0,36.148.1,43.146.0"}
P.entries["quest:234"] = {n="Доставка пошти в Долині Холодного Хребта",s="Це доручення завершує кур'єрський рейс засніженими заметами Долини Холодного Хребта. Передати послання від горянина Таліна Кіная далі південно-східною дорогою — означає, що Ґрелін Вайтбірд лишається на зв'язку з дворфійською столицею.",h="Це доручення завершує кур'єрський рейс засніженими заметами Долини Холодного Хребта.",kw={"доставка пошти","талін кінай","ґрелін вайтбірд","послання","долина холодного хребта","кур'єр","айронфордж"},ang={["faction:Alliance"]="Надійні кур'єрські маршрути підступними засніженими перевалами постачають віддаленим розвідникам Альянсу накази й життєво важливі відомості.",["race:Dwarf"]="Кожна застава в Дун Мороґу розраховує на депеші з престолу Короля Маґні в Айронфорджі, щоб оборона королівства лишалася узгодженою."},sec={{t="Ланка до гори",b="Навіть у такій відрізаній улоговині, як Долина Холодного Хребта, новини й офіційне листування мусять мандрувати. Поки Анвілмар — адміністративне серце долини, польові розвідники й вартові вздовж стежок покладаються на піших кур'єрів, щоб передавати послання між високими перевалами й Айронфорджем."},{t="Слово для Вайтбірда",b="Ґрелін Вайтбірд тримає невеликий табір дорогою на південний схід від поста Таліна Кіная. Зносячи крижані замети й постійні наскоки трогів, досвідчені горяни на цих віддалених спостережних пунктах залежать від регулярних послань, щоб знати про ширші справи в Дун Мороґу й королівстві за його межами."}},fp="30,230,22.291.0,19.316.0,25.214.0,32.205.0,35.246.0,42.146.0,47.173.0,44.197.0"}
P.entries["quest:239"] = {n="Гарнізону Вестбрука потрібна допомога!",s="Маршал Дуґан відряджає вільних шукачів пригод на захід, до Гарнізону Вестбрук — застави, що стереже кордон Лісу Елвінн із Вестфолом. Армія Стормвінда розкидана по всьому королівству, тож Помічник Рейнер і його вартові без регулярних підкріплень опиняються під дедалі більшим тиском агресивних гнолів Річколапів і бродячих злодіїв.",h="Маршал Дуґан відряджає вільних шукачів пригод на захід, до Гарнізону Вестбрук — застави, що стереже кордон...",kw={"гарнізон вестбрук","помічник рейнер","гноли","річколапи","вестфол","ліс елвінн","маршал дуґан"},ang={["faction:Alliance"]="Добровольці Альянсу беруть тут на себе роль регулярних солдатів — виконують чорну роботу, щоб ключові землі не скотилися в цілковитий хаос.",["race:Human"]="Для людей Стормвінда цей наказ — тривожна ознака занедбаності королівства: він на власні очі показує, якою тонкою стала оборона корони після зникнення Короля."},sec={{t="Розтягнуте прикордоння",b="Гарнізон Вестбрук позначає західний край Лісу Елвінн — саме там, де обжиті ліси поступаються неспокійним рівнинам Вестфолу. Що зухвалішими стають загони гнолів і бандити вздовж річок і західних доріг, то наполегливіше невеликий гарнізон застави благає про підкріплення. Однак ані Маршал Дуґан, ані урядники Ґолдшира не мають вільних професійних солдатів Стормвінда, тож місцевим командирам лишається тільки наймати мандрівних найманців і шукачів пригод."},{t="Загроза з-за струмка",b="Головна небезпека для Помічника Рейнера та його людей — зграя гнолів Річколапів, чиї загони нападають на подорожніх і сусідні садиби. Діючи на прикордонні між Елвінном і Вестфолом, ці гноли скористалися з того, що Стормвінд відволікли політичні й військові клопоти, і просунулися вглиб обжитих земель. Гарнізон Вестбрук — остання лінія оборони, яка не дає їм безкарно гуляти серцем лісу."}},fp="30,345,25.500.0,27.446.0,64.313.0,36.200.0,40.188.0,21.244.0,46.162.0,46.249.0"}
P.entries["quest:2399"] = {n="Пророслі віяла",s="Після ботанічних дослідів Деналана біля Озера Ал'Амет посаджене насіння листя вкорінюється й розквітає. Ця тиха мить — успішний урожай у розумінні дивної й життєво важливої рослинності Тельдрассила. Мандрівники, що оглядають грядки, можуть на власні очі побачити стрімкий ріст.",h="Після ботанічних дослідів Деналана біля Озера Ал'Амет посаджене насіння листя вкорінюється й розквітає.",kw={"пророслі віяла","мерехтливе листя","деналан","озеро ал'амет","грядка","ботаніка","тельдрассил"},ang={["class:Druid"]="Друїди, що спостерігають за грядкою Деналана, можуть оцінити тиху рівновагу природи, бачачи, як життя квітне під уважним доглядом навіть посеред дедалі більших небезпек Тельдрассила.",["profession:Herbalism"]="Дослідження Деналана відбивають практичне мистецтво збирання й вивчення неповторної рослинності Тельдрассила і показують, як швидко тутешнє насіння пристосовується до доглянутого ґрунту.",["race:NightElf"]="Догляд за щойно пророслою рослинністю відбиває обов'язок калдореїв стежити за життям, що вкорінюється на їхньому молодому Світовому Дереві, і плекати його."},sec={{t="Сад біля Озера Ал'Амет",b="Сховавшись біля Озера Ал'Амет, ботанік Деналан присвятив себе опису незвичайної рослинності Тельдрассила. Коли він посіяв насіння, здобуте з таємничого мерехтливого листя, ґрунт швидко дав результат. У його доглянутій грядці з багатого суглинку вистрілюють дивні, тремтливі віяла листя, що просяться, аби їх зібрали й дослідили."},{t="Дивна рослинність Світового Дерева",b="Тельдрассил молодий, неосяжний і повниться стрімким природним розвитком, який і захоплює, і тривожить травників — нічних ельфів. Мерехтливе листя та його пророслі пагони — приклад того, як швидко життя хапається за віття великого дерева, натякаючи на могутню, але непередбачувану життєву силу, вплетену в ґрунт острова."}},fp="19,281,25.337.0,35.336.0,29.224.0,34.120.0,36.220.0,34.166.0,29.166.0,26.96.0"}
P.entries["quest:2438"] = {n="Смарагдовий Ловець Снів",s="Таллонкай Свіфтрут у Доланаарі просить шукачів пригод повернути дорогу родинну реліквію з його покинутої оселі в Селі Зоряного Вітерця. Смарагдовий Ловець Снів, подарований йому друїдським сторожем Ґероласом Талветреном, лишився там, коли споганені фурболги Вузлошкірів заполонили тихе поселення. Повернення цього амулета не дасть його лагідній магії природи потрапити в огидні руки.",h="Таллонкай Свіфтрут у Доланаарі просить шукачів пригод повернути дорогу родинну реліквію з його покинутої...",kw={"смарагдовий ловець снів","таллонкай свіфтрут","ґеролас талветрен","село зоряного вітерця","вузлошкіри","фурболги","доланаар"},ang={["class:Druid"]="Амулет — безпосередній витвір Ґероласа Талветрена, сторожа, що доглядає ваших сплячих родичів у Курганному Лігві Бан'етіл, тож його повернення — справа друїдської честі.",["faction:Alliance"]="Допомога вигнаним калдореям Доланаара зміцнює місцеву стабільність, поки Тельдрассил бореться зі скверною, що шириться серед племен фурболгів.",["race:NightElf"]="Зоряний Вітерець колись був тихим прихистком для вашого народу. Допомогти Таллонкаю повернути його спадок — маленький удар по безумству, що охоплює звірину Тельдрассила."},sec={{t="Друїдський талісман",b="Смарагдовий ловець снів — значно більше ніж оздобна дрібничка. Створений Ґероласом Талветреном, шанованим сторожем сплячих друїдів у Курганному Лігві Бан'етіл, амулет мав спрямовувати безтурботні течії Смарагдового Сну. Черпаючи цю чисту духовну силу, ловець снів дарує носієві спокій і удачу. Такі знаки надзвичайно рідкісні, і дістають їх лише небагато довірених, чиє життя сплетене з опікою над лісом."},{t="Втеча із Села Зоряного Вітерця",b="Донедавна Село Зоряного Вітерця було мирним поселенням серед віття Тельдрассила. Тихе життя скінчилося, коли тутешні фурболги Вузлошкірів піддалися несамовитому безумству й вигнали нічних ельфів з їхніх споконвічних осель. У жаху й сум'ятті евакуації Таллонкай був змушений лишити свій найдорожчий скарб у шухляді комода в південно-східній частині села, безсилий повернути його самотужки."},{t="Загроза скверни",b="Залишити осередок магії Смарагдового Сну в серці захопленого села — великий ризик. Вузлошкіри вже довели свою податливість до темних впливів, і артефакт, що пульсує силами Сну, легко можна споганити чи обернути на зброю. Безпечне повернення ловця снів віддає Таллонкаю частку спадку Зоряного Вітерця, перш ніж фурболги чи інші огидні мешканці встигнуть осквернити його незгаслу магію."}},fp="24,377,18.471.0,26.451.0,24.410.1,33.219.0,59.242.0,27.237.0,26.128.0,56.172.0,48.185.1"}
P.entries["quest:2459"] = {n="Фероцитас, Пожирач Снів",s="«Фероцитас, Пожирач Снів» — завдання Альянсу, яке дає Таллонкай Свіфтрут у Доланаарі. Повернувши собі пошкоджений родинний ловець снів, Таллонкай виявляє, що його могутнє смарагдове осердя видерли фурболґи Вузлошкіри, що живуть на північ від Села Зоряного Вітерця. Шукачів пригод посилають знищити зіпсутих містиків і відібрати вкрадений самоцвіт у їхнього ватажка — Фероцитаса.",h="«Фероцитас, Пожирач Снів» — завдання Альянсу, яке дає Таллонкай Свіфтрут у Доланаарі.",kw={"фероцитас","ловець снів","вузлошкіри","фурболґи","тельдрассил","доланаар","таллонкай"},ang={["class:Druid"]="Ловці снів — могутні знаряддя, пов'язані зі Смарагдовим Сном; бачити, як один із них осквернив зіпсутий фурболґ, — означає вимагати швидкої відплати від імені природи.",["race:NightElf"]="Вузлошкіри колись були союзниками калдорей, тож зіпсуття їхніх містиків і крадіжка священних талісманів — гірка трагедія для кожного нічного ельфа, що боронить Тельдрассил."},sec={{t="Осквернена реліквія",b="Коли Таллонкай Свіфтрут оглянув ловець снів, повернутий зі зіпсутих хащ, полегшення швидко змінилося розпачем. Священну реліквію спаплюжили: яскравий смарагд, її серцевину, вирвали з плетеної рами. Серед нічних ельфів ходили чутки, що ватага містиків Вузлошкірів на північ від Села Зоряного Вітерця підпала під вплив фурболґа-ватажка на ім'я Фероцитас, Пожирач Снів, який зухвало носив на шиї сяйливий зелений камінь. Знаючи, що в лапах цього створіння священний самоцвіт і марний, і спотворений, Таллонкай послав захисників відібрати його."},{t="Очищення від містиків",b="Фурболґи Вузлошкіри, що населяють північні околиці Тельдрассила, колись були мирними сусідами, та зіпсуття, яке дедалі глибше просякає Світове Дерево, ввергло їх у шал і безумство. Їхні містики, що колись творили лагідні обряди природи, почали черпати з викривлених магічних потоків. Вистеживши Фероцитаса й прорубавшись крізь почет містиків, які стережуть його лісовий сховок, мандрівники повертають лісові рівновагу й добувають самоцвіт Таллонкая, щоб ловець снів нарешті став цілим."}},fp="25,360,18.578.0,19.503.0,42.163.0,17.219.0,49.174.0,51.191.0,30.184.0,38.218.0"}
P.entries["quest:248"] = {n="Шукати далі",s="«Шукати далі» — шпигунська місія Альянсу, якою керує чарівник Теокрітус через зачарований канал зв'язку. Щоб розібратися в напруженні між магом-відступником Морґантом і орками Блекрок, ви маєте пробратися до сторожової вежі біля Фортеці Кам'яної Варти й сховати зачарований гліф у непримітній посудині.",h="«Шукати далі» — шпигунська місія Альянсу, якою керує чарівник Теокрітус через зачарований канал зв'язку.",kw={"теокрітус","морґант","гліф азори","кам'яна варта","чорна скеля","редрідж","шпигунство"},ang={["class:Mage"]="Теокрітус покладається на витончену магію далекого ворожіння через Гліф Азори — так Кірін-Тор і маги Азори налагоджують магічне стеження на ворожих територіях.",["faction:Alliance"]="Фортеця Кам'яної Варти лишається головною твердинею клану Блекрок в Редріджі. Відомості про їхні чвари з Морґантом конче потрібні для оборони Лейкшира."},sec={{t="Розкол у Редріджі",b="Зі свого святилища в Лісі Елвінн чарівник Теокрітус за допомогою ворожильної магії пильно стежить за східним Редріджем. Спостерігаючи за Вежею Ілґалара, він помічає раптовий розбрат між Морґантом, чорнокнижником-відступником із людського роду, та орками Блекрок, що закріпилися у Фортеці Кам'яної Варти. Замість діяти спільно проти Королівства Стормвінд ці ворожі сили зчепилися за якусь невідому здобич, і Теокрітус вирішує втрутитися, перш ніж шальки терезів хитнуться."},{t="Око на Кам'яній Варті",b="Щоб пробити оборону Фортеці Кам'яної Варти, Теокрітусу потрібна друга магічна точка опори. Він наказує шукачам пригод піднятися на вцілілу сторожову вежу, що стоїть поруч зі зруйнованою твердинею. Там, серед гарнізонного мотлоху, порожній глек, викинутий орківськими вартовими, стає ідеальною непримітною схованкою. Щойно Гліф Азори закріплено всередині посудини, Теокрітус зможе подумки перебирати думки тих, хто перебуває в Кам'яній Варті, і дізнатися, що посварило Морґанта з орками Блекрок."}},fp="15,307,18.487.0,21.494.1,29.154.0,44.210.0,31.155.0,32.177.0,38.158.1,21.179.0"}
P.entries["quest:2499"] = {n="Похмуродуб",s="Деналан просить шукачів пригод покласти край Похмуродубові — могутньому деревлянику, якого зіпсував величезний наріст. Знавіснілий звір, що оселився в печері на південному березі Озера Ал'Амет, тепер розносить пошесть серед місцевої живності.",h="Деналан просить шукачів пригод покласти край Похмуродубові — могутньому деревлянику, якого зіпсував...",kw={"похмуродуб","деревляник","деналан","озеро ал'амет","тельдрассил","пухлина"},ang={["class:Druid"]="Бачити деревляника-охоронця, спотвореного дивними пухлинами, — для друїдів моторошне нагадування, що юна екосистема Тельдрассила глибоко хвора.",["profession:Herbalism"]="Травники, що допомагають Деналанові, на власні очі бачать, як рослинне життя під впливом незримої гнилі перетворюється на злоякісну мохову пошесть.",["race:NightElf"]="Трагічне падіння Похмуродуба б'є в саме серце громади нічних ельфів, загрожуючи озеру, що лежить просто в тіні Алдрассила."},sec={{t="Полеглий охоронець",b="Похмуродуб колись був великим проводирем деревляників — лісових духів, що доглядають буйне гілля Тельдрассила. На жаль, зіпсуття, яке повзе Світовим Деревом, не розрізняє простої живності й давніх захисників. Доведений до шалу велетенською пухлиною, що набрякла на його корі, Похмуродуб став посудиною пошесті, а не опікуном росту."},{t="Очищення Озера Ал'Амет",b="Причаївшись у печері на південному березі Озера Ал'Амет, Похмуродуб своєю отруйною присутністю труїть довколишні води й лісових звірів. Деналан, не здатний стати проти чудовиська сам, прагне його знищення не зі злості — а щоб милосердно відтяти джерело зіпсуття й дослідити химерну розрослу пухлину, що мучить духів озера."}},fp="10,235,17.379.0,21.354.0,19.184.0,33.228.0,29.113.0,48.228.0,36.144.0,28.179.0"}
P.entries["quest:2541"] = {n="Сплячий друїд",s="Глибоко в Курганному Лігві Бан'етіл сплячий нічний ельф Обен Рейджклов опинився у страшній магічній пастці. Ворожі шамани фурболґів Вузлошкірів відтяли його сновидний дух від тіла й мерзенними чарами оживили його плоть, зробивши з неї навіженого вартового.",h="Глибоко в Курганному Лігві Бан'етіл сплячий нічний ельф Обен Рейджклов опинився у страшній магічній пастці.",kw={"обен рейджклов","курганне лігво бан'етіл","вузлошкіри","шамани","вуду","смарагдовий сон","тельдрассил"},ang={["class:Druid"]="Для друїдів доля Обена — жах наяву: коли тіло викрадають, поки ви єднаєтеся зі Смарагдовим Сном, це руйнує саму основу друїдського сну.",["race:NightElf"]="Осквернення Курганного Лігва Бан'етіл показує, як низько впали фурболґи Вузлошкіри від своєї давньої спорідненості з калдореями."},sec={{t="Порушений сон",b="Друїди нічних ельфів сходять у курганні лігва по всьому Калімдору, щоб століттями спілкуватися з природою уві сні: їхні духи блукають Смарагдовим Сном, поки смертні тіла спочивають у кам'яних нішах. Але зіпсуття, що вразило Тельдрассил, штовхнуло місцеве плем'я фурболґів Вузлошкірів до відчайдушної дикості. У Курганному Лігві Бан'етіл шамани Вузлошкірів знайшли спосіб прорвати освячений спокій Обена Рейджклова й вирвати його живий дух зі сплячої оболонки."},{t="Вуду й зіпсуття",b="Замість убити Обена, шамани Вузлошкірів скористалися зловісним талісманом — Шаманським Вудуйським Оберегом — і силоміць оживили його порожню оболонку. Безпорадно ув'язнений у Смарагдовому Сні, вигнаний дух Обена може лише дивитися, як його тіло блукає коридорами й наосліп нападає на кожного, хто ступить до лігва. Щоб розплутати чари й знайти шлях до повернення тіла, його примарна проєкція доручає шукачам пригод здобути один з оберегів Вузлошкірів для вивчення."}},fp="18,273,19.481.0,21.466.1,21.217.0,36.213.0,32.199.0,45.188.0,53.210.0,44.202.0"}
P.entries["quest:2561"] = {n="Друїд Пазура",s="Глибоко в курганах Тельдрассила примарна подоба Обена Рейджклова просить про трагічне звільнення. Зіпсуті фурболґи наклали темні чари на його тілесну оболонку, тож вам доведеться знищити бездушну шкаралупу й розірвати пута, щоб його дух повернувся до Смарагдового Сну.",h="Глибоко в курганах Тельдрассила примарна подоба Обена Рейджклова просить про трагічне звільнення.",kw={"друїд пазура","обен рейджклов","вузлошкіри","вуду","смарагдовий сон","курган","тельдрассил"},ang={["class:Druid"]="Бачити сплячого Друїда Пазура, оскверненого зіпсутими фурболґами, — моторошне нагадування про те, як небезпечно залишати тіло без нагляду, єднаючись зі Смарагдовим Сном.",["race:NightElf"]="Тельдрассил мав стати прихистком для нічних ельфів, та стрімке зіпсуття корінних фурболґів, таких як Вузлошкіри, несе безпосередню загрозу навіть у їхніх священних курганах."},sec={{t="Відтятий дух",b="Спочиваючи в курганах під Тельдрассилом, Обен Рейджклов зазнав жахливої долі. Зіпсуті фурболґи Вузлошкіри наклали на його сонне тіло мерзенні чари вуду й відтяли дух від смертної плоті. Ув'язнений у Смарагдовому Сні, дух Обена блукає поблизу, не маючи ні спокою, ні змоги повернути собі тіло."},{t="Милосердя до плоті",b="Вивчення вудуйського оберега Вузлошкірів відкрило гірку правду: тілесна оболонка Обена цілком у владі фурболґів. Щоб зруйнувати чари, шукач пригод має зайти до сусідньої зали, здолати безтямну, ворожу подобу Обена Рейджклова й застосувати над його рештками оберіг фурболґів — лише так можна остаточно розбити магію, що тримає його душу."}},fp="17,284,16.324.0,19.345.1,36.287.0,34.201.0,36.194.1,41.219.0,22.210.0,61.197.0"}
P.entries["quest:282"] = {n="Спостереження Сеніра",s="Зібравши важливі відомості про місцеві загрози в Долині Холодного Хребта, Ґрелін Вайтбірд довіряє вам донести його висновки братові, Сеніру Вайтбірдому, в Харанос. Проте, щоб залишити захищену долину, треба пройти тунелем, який недавно захопили ворожі троги й який стереже Горянин Талос.",h="Зібравши важливі відомості про місцеві загрози в Долині Холодного Хребта, Ґрелін Вайтбірд довіряє вам донести...",kw={"спостереження сеніра","ґрелін вайтбірд","сенір вайтбірдий","горянин талос","звіт","тунель","троги","харанос"},ang={["faction:Alliance"]="Безпечний прохід між дворфійськими долинами критично важливий для оборони Айронфорджа й безпеки кур'єрів Альянсу.",["race:Dwarf"]="Для дворфійських горян і новобранців прохід східним тунелем — ваше перше офіційне відрядження за межі навчальних угідь Долини Холодного Хребта.",["race:Gnome"]="Для гномських біженців, що живуть серед Бронзбірдів, ця депеша — шлях із першого прихистку до ширших проблем, що охопили Дун Мороґ."},sec={{t="Кур'єр для Вайтбірдів",b="Ґрелін Вайтбірд доклав чимало зусиль, документуючи тролячу діяльність довкола Долини Холодного Хребта. Коли його щоденник поцупили, а потім повернули, стало ясно, що зібрані відомості надто важливі, щоб довіряти їх недосвідченому учневі. Бажаючи обминути проміжні руки, Ґрелін обирає загартованого шукача пригод, щоб той передав звіт просто його братові, Сеніру Вайтбірдому, який веде справи за межами долини, в Хараносі."},{t="Заблокований перевал до Хараноса",b="Залишити Долину Холодного Хребта більше не проста прогулянка головною дорогою. Східний тунель, що з'єднує долину з ширшим засніженим плато Дун Мороґу, брутально захопили троги-копачі. Щоб необережні цивільні не забрели в смертельну пастку, варта Айронфорджа поставила Горянина Талоса просто перед проходом. Лише мандрівникам із нагальною офіційною справою дозволено минути сторожовий пост і кинути виклик підземній пастці."}},fp="20,320,29.471.0,28.475.0,37.141.0,49.197.0,50.201.0,36.142.0,58.184.0,52.143.0"}
P.entries["quest:287"] = {n="Твердиня Морозогривів",s="Твердиня Морозогривів — розвідувальне завдання Альянсу, яке дає Сенір Вайтбірдий у Хараносі. Вистеживши ворожих тролів Морозогривів до їхньої добре охоронюваної печерної твердині біля Озера Крижаного Потоку, Сенір залучає відважних розвідників, щоб ті наважилися зайти всередину, знищили їхніх мисливців за головами й здобули життєво важливі відомості для його розвідувальних звітів.",h="Твердиня Морозогривів — розвідувальне завдання Альянсу, яке дає Сенір Вайтбірдий у Хараносі.",kw={"твердиня морозогривів","морозогриви","тролі","сенір вайтбірдий","озеро крижаного потоку","розвідка","мисливці за головами","харанос"},ang={["faction:Alliance"]="Безпека Дун Мороґу гарантує, що гірські дороги, які з'єднують Айронфордж із сусідніми королівствами, лишаться вільними від ворожих племінних засідок.",["race:Dwarf"]="Тролі Морозогриви оскаржують панування Айронфорджа на засніжених вершинах Дун Мороґу; розвідати їхню головну печерну твердиню критично важливо для оборони королівства.",["race:Gnome"]="Поки гноми оселилися по всьому Дун Мороґу й Хараносі після падіння Гномреґану, стримання наступу тролів Морозогривів береже крихкі коридори постачання біженців."},sec={{t="Розвідник, що відстає від графіка",b="Горянин і розвідник Сенір Вайтбірдий, що стоїть у Хараносі, мав стежити за загрозою тролів Морозогривів, яка насувається по всьому Дун Мороґу. Хоч він і успішно простежив зухвалі племена до їхнього головного печерного житла на південний захід від Села Брюнолл, сама кількість озброєних тролів змусила його завагатися. Не наважуючись ступити всередину сам і серйозно відстаючи з офіційними звітами, Сенір наймає подорожніх шукачів пригод вирушити в крижані закапелки замість нього."},{t="Прорив до печери",b="Твердиня вирізана в західних вершинах над Озером Крижаного Потоку — крижаний редут, набитий ворожими крижаними тролями. Щоб виконати завдання Сеніра, розвідники мусять пробитися глибоко підземними тунелями, винищити лютих Мисливців за головами Морозогривів, що стоять на виступах, і скласти карту внутрішнього розташування. Пережити цей спуск — здобути критично важливі відомості, потрібні Сеніру, щоб завершити висновки для військових командирів Айронфорджа."}},fp="14,325,23.484.0,20.448.0,32.264.0,24.222.0,42.295.0,29.249.0,52.210.1,41.215.0"}
P.entries["quest:3065"] = {n="Проста Табличка",s="«Проста Табличка» — вступний обряд переходу для воїнів-початківців, що входять у Долину Випробувань. Вручена вам після того, як ви довели свою вправність проти тутешніх звірів, вона спрямовує вас до Франґа — місцевого ветерана, якому доручено обертати сиру силу на бойову дисципліну.",h="«Проста Табличка» — вступний обряд переходу для воїнів-початківців, що входять у Долину Випробувань.",kw={"проста табличка","воїн","франґ","ґорнек","долина випробувань","плямисті вепри"},ang={["class:Warrior"]="Цей виклик — ваш найперший крок на шлях воїна в Дуроторі; він веде вас просто до Франґа вчитися основних стійок і ударів.",["faction:Horde"]="Орда покладається на постійний потік загартованих бійців передової, щоб убезпечити хиткі кордони Дуротару від кентаврів, шипогривів і людських зайд.",["race:Troll"]="Тролі Темного Списа, що навчаються в долині, можуть почути грубуваті зауваги Франґа щодо їхньої любові до списів замість орчих сокир, хоч він поважає все, що вбиває."},sec={{t="Поклик до зброї",b="Коли ви доведете, що здатні дати раду Плямистим Вепрам долини, Ґорнек вручає вам пергамент, позначений саме для вас. У суворому середовищі Дуротару Орда не лишає своїх бійців надовго без настанов. Табличка — запрошення розшукати Франґа, наставника воїнів, що стоїть біля Лігва."},{t="У затінку Лігва",b="Франґ ховається в затінку одразу біля Лігва, спостерігаючи, як новобранці стікаються з червоних чагарників. Він оцінює новачків досвідченим оком, готовий передати основи — чи то махати важкою сокирою, чи то орудувати списом, — щоб кожен новий солдат міг боронити крихкі поселення молодої Орди."}},fp="13,277,17.338.0,26.318.0,26.170.0,21.131.0,23.121.0,39.213.0,32.159.0,31.164.0"}
P.entries["quest:308"] = {n="Відвернути увагу Джарвена",s="У льоху Ґуральні Тандербрю вартовий Джарвен Тандербрю опиняється серед барил, яких йому заборонено торкатися. Жадаючи скуштувати родинного ремесла, він просить подорожнього шукача пригод принести кухоль Громового Елю, щоб загострити розум на чергуванні.",h="У льоху Ґуральні Тандербрю вартовий Джарвен Тандербрю опиняється серед барил, яких йому заборонено торкатися.",kw={"відвернути увагу джарвена","джарвен тандербрю","вартовий","громовий ель","льох","ґуральня тандербрю","харанос"},ang={["class:Rogue"]="Відволікти вартового міцним трунком — давній трюк ремесла, навіть якщо Джарвен сам радо просить його відволікти.",["race:Dwarf"]="Кожен дворф розуміє муку стояти на варті біля діжок легендарного елю, не маючи права на жоден ковток."},sec={{t="Спраглий вартовий на чергуванні",b="Джарвену Тандербрю доручено стерегти глибокі запаси Ґуральні Тандербрю в Хараносі. Хоч він і оточений найкращим стаутом у Дун Мороґу, він працює під суворим родинним наказом не прикладатися до запасів на варті. Спокуса виявляється надто сильною, і він залучає подорожніх, щоб ті принесли йому пінту міцного Громового Елю з кранів нагорі."},{t="Сумнівний гострильний камінь",b="Джарвен наполягає, що добрий трунок лише загострить його чуття й зміцнить його варту. Чи мудро потурати вартовому на чергуванні — питання відкрите, та серед витривалих дворфів Дун Мороґу мало хто дорікне комусь із Тандербрю за бажання скуштувати всесвітньо відоме вариво власної рідні."}},fp="18,257,23.385.0,19.276.0,26.163.0,46.215.0,27.133.0,44.142.0,33.151.0,44.149.0"}
P.entries["quest:3082"] = {n="Гравірована Табличка",s="«Гравірована Табличка» — вступне завдання мисливця, яке дають у Долині Випробувань після перших випробувань. Воно спрямовує майбутніх тролів-мисливців з'явитися до наставниці мисливців Джен'шан, щоб почати офіційний вишкіл у нетрях.",h="«Гравірована Табличка» — вступне завдання мисливця, яке дають у Долині Випробувань після перших випробувань.",kw={"гравірована табличка","мисливець","джен'шан","ґорнек","долина випробувань","темний спис"},ang={["class:Hunter"]="Це завдання знаменує ваш офіційний вступ до лав мисливців Орди і встановлює ваш зв'язок із дикою природою та місцевою наставницею.",["faction:Horde"]="Обмін між Джен'шан і молодими новобранцями показує, як Орда поєднує відмінні культурні сили орків і тролів задля спільного виживання.",["race:Orc"]="Для молодих орків отримати табличку означає вчитися витонченого скрадання й вистежування в нетрях у союзників із Темного Списа, доповнюючи традиційну воїнську міць.",["race:Troll"]="Джен'шан пишається тим, як мисливські знання Темного Списа допомогли Орді вкоренитися на Калімдорі, і підтверджує життєво важливу роль тролячих традицій у виживанні їхніх союзників."},sec={{t="Поклик на полювання",b="Коли мисливці-новачки доведуть свою першу вправність проти тутешніх вепрів Лігва, їх перестріває Ґорнек із вирізьбленим посланням. Кам'яна табличка несе знак Джен'шан — умілої тролиці-мисливиці, що стоїть неподалік. Ґорнек передає її як знак, що молодий мисливець виявив достатньо завзяття, аби привернути увагу досвідчених майстрів виживання, і це позначає перехід від простого грубого виживання до дисциплінованого вишколу в нетрях."},{t="Поділитися виживанням",b="Коли ви з'являєтеся до Джен'шан, тролиця-наставниця розповідає про глибоку історію між орками й тролями в Орді. Орки мали славетні традиції воїнів і шаманів, а тролі Темного Списа принесли давні вміння скрадання, вистежування й виживання, що допомогли оркам вистояти на Азероті. Джен'шан бачить у вишколі нових мисливців тривалий обмін знаннями про виживання, що зближує союзні народи через спільну повагу до полювання."}},fp="13,237,21.438.0,23.469.0,28.147.0,28.135.0,45.195.0,42.172.0,62.121.0,34.168.0"}
P.entries["quest:3083"] = {n="Зашифрована Табличка",s="Зашифрована Табличка — виклик, який Ґорнек вручає майбутнім розбійникам, що навчаються в Долині Випробувань. Написане шифром послання спрямовує злодюжок-новачків до Рваґа — таємного агента в Лігві, який керує вишколом розбійників і зв'язками з Розтрощеною Рукою.",h="Зашифрована Табличка — виклик, який Ґорнек вручає майбутнім розбійникам, що навчаються в Долині Випробувань.",kw={"зашифрована табличка","розбійник","рваґ","ґорнек","розтрощена рука","лігво","долина випробувань"},ang={["class:Rogue"]="Ця табличка — ваше офіційне посвячення в таємні операції Дуротару: вона зводить вас із першим наставником, Рваґом, і знайомить із непомітним впливом Розтрощеної Руки.",["race:Orc"]="Хоч традиційна орча культура шанує відкритий бій на полі битви, орчі розбійники відіграють незамінну роль розвідників і лазутчиків у сучасній Орді.",["race:Troll"]="Розбійники Темного Списа поєднують чуття слідопитів джунглів із мистецтвом клинка, якого навчають наставники в Лігві, і так утверджують свою тиху користь серед союзників-орків."},sec={{t="Шифрований виклик",b="Щойно посвячуваний доведе свою вправність проти тутешньої звірини, Ґорнек вручає йому Зашифровану Табличку, доставлену саме для нього. Замість простої мови послання замкнене в шифрі — випробування й пересторога, що личать тим, хто практикує мистецтво скрадання, отрут і хитрощів. Воно запрошує новобранця спуститися в Лігво й зустріти Рваґа — наставника, відповідального за вишкіл розбійників, крадіїв і злодюжок для Орди."},{t="Тінь Руки",b="Розгадавши вказівки й увійшовши в Лігво, посвячувані знаходять Рваґа — агента, пов'язаного з Розтрощеною Рукою. Хоч він запевняє новоприйнятих розбійників, що гільдія не диктуватиме їм кожен подих, він застерігає: Рука спитає з нього, якщо учень не впорається. У молодій нації, оточеній ворогами, Орда значною мірою покладається на мовчазних розвідників і спритних злодюжок, щоб збирати відомості й усувати загрози з тіні."}},fp="16,270,15.438.0,22.457.0,44.149.0,38.142.0,24.122.0,37.134.0,49.177.0,35.115.0"}
P.entries["quest:3084"] = {n="Табличка з Рунними Письменами",s="Табличка з Рунними Письменами — послання-виклик, яке отримують майбутні шамани, що навчаються в Долині Випробувань. Надіслана Шікріком, вона запрошує здібних посвячуваних почати офіційне навчання єднання з духами й володіння стихійними силами землі, вогню, води й повітря.",h="Табличка з Рунними Письменами — послання-виклик, яке отримують майбутні шамани, що навчаються в Долині...",kw={"табличка з рунами","шаман","шікрік","ґорнек","стихії","долина випробувань","тралл"},ang={["class:Shaman"]="Ця табличка — ваше офіційне посвячення на шаманський шлях; вона доручає вам урівноважувати сили стихій і бути маяком провідництва предків.",["faction:Horde"]="Шаманізм — моральний і духовний хребет нової Орди, компас честі й рівноваги на суворому прикордонні.",["race:Orc"]="Табличка відображає сучасне повернення орків до шаманізму предків, яке обстоює Тралл, і відхід від темної чорнокнижницької спадщини демонічного минулого.",["race:Troll"]="Тролі Темного Списа, що практикують шаманізм, знаходять спільну мову з орками-наставниками на кшталт Шікріка, поєднуючи єднання з предками зі спільними стихійними традиціями Орди."},sec={{t="Поклик до духів",b="Коли шамани-початківці доведуть свою першу дисципліну на запорошених тренувальних землях Долини Випробувань, Ґорнек вручає їм вирізьблену кам'яну табличку. Руни на ній — запрошення від Шікріка, тутешнього наставника шаманів, знак, що посвячуваний готовий дивитися далі за простий фізичний бій і дослухатися до глибших течій природного світу."},{t="Духовне провідництво в новій Орді",b="Шаманізм посідає священне місце у відродженій Орді. Як учить Шікрік, шамани черпають свою міць із чотирьох стихійних сил, а силу — від духів предків. За прикладом Вождя Тралла від шаманів чекають, що вони будуть духовними провідниками й опорою мудрості для своїх громад і даруватимуть захист поселенням, які вкорінюються по всьому Дуротару."}},fp="21,286,21.360.0,37.362.0,34.234.0,15.221.0,60.244.0,25.150.0,25.154.0,40.242.0"}
P.entries["quest:3085"] = {n="Освячена Табличка",s="Простий виклик, який отримують жерці-початківці в Долині Випробувань після першої перевірки сили. Табличка з написом посилає молодих служителів духів до Кен'джая — тутешнього наставника жерців-тролів, який відкриває їм глибше єднання з духами.",h="Простий виклик, який отримують жерці-початківці в Долині Випробувань після першої перевірки сили.",kw={"жрець","кен'джай","долина випробувань","табличка","духи","тролі"},ang={["class:Priest"]="Це завдання знаменує перехід від буденних випробувань долини до справжнього духовного навчання під проводом Кен'джая біля Лігва.",["faction:Horde"]="Поки Орда облаштовується в Дуротарі, містики дбають, щоб духовні обряди й воля духів лишалися осердям зростання молодої держави.",["race:Troll"]="Табличка підкреслює духовні традиції Темного Списа: звернення до духів предків і лоа замість догматичних учень чужоземних жрецтв."},sec={{t="Послання від Кен'джая",b="Довівши свою стійкість у сутичках із місцевими вепрами під наглядом Ґорнека, молоді жерці, що навчаються в Долині Випробувань, отримують різьблений камінь, відомий як Освячена Табличка. Послання, передане через Ґорнека, несе знак Кен'джая — містика з племені Темного Списа, що стоїть біля входу до Лігва й наглядає за новачками, покликаними на шлях віри та духовної магії."},{t="Єднання з духами",b="На відміну від Святого Світла, якому служать люди й дворфи за морем, жрецтво серед тролів Темного Списа в Орді зосереджене на єднанні з духами та лоа. Кен'джай вітає новоприбулих послушників у Дуротарі нагадуванням, що їхня сила народжується з духовної дисципліни, і обіцяє навчити їх вищих обрядів лише тоді, коли їхній зв'язок із духами зміцніє."}},fp="15,268,22.369.0,26.376.0,28.205.0,15.231.0,51.194.0,57.198.0,17.169.0,43.190.0"}
P.entries["quest:3086"] = {n="Гліфічна Табличка",s="Гліфічна Табличка — вступне класове завдання в Долині Випробувань для магів-новачків Орди. Її передає Ґорнек після того, як новобранець доведе свою силу, і вона скеровує юних чарівників до Май'ї, наставниці магів-тролів біля входу до Лігва.",h="Гліфічна Табличка — вступне класове завдання в Долині Випробувань для магів-новачків Орди.",kw={"маг","май'а","гліфічна табличка","долина випробувань","таємна магія"},ang={["class:Mage"]="Це завдання — ваше офіційне вітання в лавах магів Орди: воно знайомить вас із наставницею долини й наголошує на дисципліні розуму, потрібній, щоб тримати в шорах сиру магію.",["race:Orc"]="У традиційній культурі орків магів немає зовсім, тож це навчання — радше нагода для інших рас Орди, як-от тролів Темного Списа, відточити своє ремесло на тренувальних землях Дуротару.",["race:Troll"]="Для тролів Темного Списа, що стають на шлях таємної магії, навчання в Май'ї відображає те, як плем'я дедалі більше опановує впорядковане чаклунство поряд зі своїми традиційними духовними обрядами."},sec={{t="Послання в різьбленому камені",b="Довівши свою стійкість у сутичках із тутешньою звіриною в Долині Випробувань, маги-початківці отримують різьблену табличку, яку передає Ґорнек. Послання походить від Май'ї, наставниці магів у долині: вона кличе учня знайти її біля входу до Лігва, щойно той буде готовий узятися за справжнє вивчення таємної магії."},{t="Небезпеки незримого",b="Зустрівши учня, Май'а не гає часу на церемонії й одразу переходить до суворої правди про таємну силу. Визнаючи, що маги здатні змінювати світ, вона попереджає: найбільша загроза для них — не ворожі воїни й не чужі раси, а незрима, розбещувальна спокуса самої магії. Вона радить смирення й терпіння, застерігаючи, що неприборкане чаклунство легко обманює чародія, змушуючи переоцінювати власну майстерність."}},fp="14,242,28.358.0,25.438.0,46.162.0,14.230.0,24.134.0,42.256.0,44.192.0,53.144.0"}
P.entries["quest:3087"] = {n="Гравірований Пергамент",s="Гравірований Пергамент — вступне завдання, що скеровує молодих мисливців-орків у Долині Випробувань до їхньої наставниці Джен'шан. Записку передає Ґорнек після першого бойового хрещення новачка, і вона відкриває двері до особливого вишколу в дикій природі та мистецтва виживання в Дуротарі.",h="Гравірований Пергамент — вступне завдання, що скеровує молодих мисливців-орків у Долині Випробувань до їхньої...",kw={"мисливець","джен'шан","гравірований пергамент","долина випробувань","дуротар"},ang={["class:Hunter"]="Ця записка — перше офіційне визнання вас мисливцем Орди: вона скеровує вас до Джен'шан, щоб відточити влучність і зрозуміти дику природу.",["faction:Horde"]="Мисливці розвідують кордони й годують табори; рання наука ремесла дбає про те, щоб молода держава Дуротар була нагодована й захищена.",["race:Orc"]="Мисливці-орки покладаються на таких наставників, як Джен'шан, щоб пристосувати традиційні кланові способи полювання до посушливих скель і смертоносних звірів Дуротару.",["race:Troll"]="Для новобранців Темного Списа навчання в Джен'шан зберігає живими давні традиції вистежування здобичі в джунглях, принесені з Островів Відлуння."},sec={{t="Поклик дикої землі",b="Довівши свою стійкість у сутичках із тутешніми плямистими вепрами, мисливці, що починають шлях у Долині Випробувань, отримують гравірований пергамент із рук Ґорнека. Послання походить від Джен'шан, досвідченої мисливиці Темного Списа, яка спостерігає за новоприбулими з околиць табору. Записка — це офіційне запрошення розпочати справжнє навчання: визнання того, що новачок має чуття, потрібне, аби впокорити неприборканих звірів і суворі землі Дуротару."},{t="Шлях мисливця",b="Явившись до Джен'шан, новобранець перестає бути простим рекрутом і стає справжнім слідопитом. Джен'шан одразу розвіює хибну думку, ніби ремесло мисливця простіше за таємні мистецтва чи шаманізм предків. Опанувати хижаків Дуротару, доглядати зброю для стрільби й виживати на безжальній землі — усе це вимагає невпинної дисципліни. Вона скеровує своїх учнів допомагати іншим мешканцям долини, щоб випробувати свої вміння, а тоді повернутися до неї по складніші навички виживання."}},fp="16,283,23.472.0,16.490.0,29.206.0,40.119.0,16.195.0,55.216.0,41.182.0,27.96.0"}
P.entries["quest:3088"] = {n="Зашифрований Пергамент",s="Зашифрований Пергамент — виклик, який отримують розбійники-орки, що довели в Долині Випробувань свої основні навички виживання. Написаний шифром, він скеровує перспективних новобранців у затінені глибини Лігва на зустріч із Рваґом — агентом, що служить інтересам Розтрощеної Руки.",h="Зашифрований Пергамент — виклик, який отримують розбійники-орки, що довели в Долині Випробувань свої основні...",kw={"розбійник","рваґ","зашифрований пергамент","розбита рука","лігво","долина випробувань"},ang={["class:Rogue"]="Цей пергамент — ваше офіційне посвячення в таємну службу Орди: він знайомить вас із Рваґом і відкриває ваш перший фаховий вишкіл.",["faction:Horde"]="Навіть такий шляхетний вождь, як Тралл, визнає, що шпигуни й розвідники потрібні, аби захистити молоді землі Дуротару від прихованих загроз.",["race:Orc"]="На відміну від типових воїнів-орків, які шукають відкритої кривавої слави, розбійники-орки поєднують дисципліну предків із тихою хитрістю, якої вимагає Розтрощена Рука."},sec={{t="Шифрований виклик",b="Довівши свою стійкість у сутичках із тутешньою звіриною, новачки-орки отримують зашифрований пергамент, який передає Ґорнек. Поки інші наставники відкрито набирають учнів на галявині, учитель розбійників Рваґ воліє надійну непомітність шифру й каменю. Пергамент веде новобранця повз залитий сонцем табір углиб печери, відомої як Лігво."},{t="Очі в тінях",b="Розгадавши записку й зайшовши всередину, новачок знаходить Рваґа, що причаївся серед скель. Насторожений чорнокнижниками, які ховаються ще глибше в печері, Рваґ не гаючись пояснює свою справжню відданість: він наглядає за новобранцями від імені Розтрощеної Руки. Поки орківське суспільство славить відкриту честь і славу на полі бою, Розтрощена Рука діє як мовчазна мережа шпигунів, горлорізів і збирачів відомостей Орди."}},fp="19,293,15.355.0,19.441.0,34.182.0,34.192.0,22.198.0,31.214.0,27.225.0,30.209.0"}
P.entries["quest:3089"] = {n="Пергамент з Рунними Письменами",s="Пергамент з Рунними Письменами — послання, яке отримують шамани-початківці Орди, що розпочинають свій шлях у Долині Випробувань. Його написала наставниця Шікрік, і він кличе перспективних новачків до справжнього навчання єднанню з духами та стихіями.",h="Пергамент з Рунними Письменами — послання, яке отримують шамани-початківці Орди, що розпочинають свій шлях у...",kw={"шаман","шікрік","пергамент","рунні письмена","духи","стихії","долина випробувань"},ang={["class:Shaman"]="Цей пергамент — ваш перший крок на духовному шляху, що скріплює священний союз із духами та первісними стихіями Дуротару.",["race:Orc"]="Для орків повернення до шаманізму вшановує традиції предків із Дренору, які ледь не згасли під час демонічного розбещення Старої Орди.",["race:Troll"]="Тролі Темного Списа, що відгукуються на цей поклик, вплітають своє вроджене єднання з духами й шану до предків у спільні шаманські традиції нової Орди."},sec={{t="Поклик духів",b="Довівши свої основні навички виживання в сутичках із тутешньою звіриною, нові шамани-орки отримують пергамент із рунними письменами від Ґорнека, наглядача Долини Випробувань. На пергаменті — містичні знаки Шікрік, наставниці шаманів у долині, яка просить новоприбулого новачка з'явитися до неї."},{t="Шлях шамана",b="Прихід до Шікрік — це початок священного обов'язку шамана перед Ордою. Шікрік нагадує молодому новачкові, що його покликання — не лише воєнне: він обраний бути провідником духів предків і володарем гніву стихій. Через Шікрік нові шамани вчаться спрямовувати духовні сили, зцілювати рани й кликати на поміч природні сили Калімдору."}},fp="24,270,26.317.0,22.385.0,37.168.0,24.165.0,30.142.0,42.161.0,44.145.0,34.159.0"}
P.entries["quest:3092"] = {n="Гравірована Записка",s="Гравірована Записка — офіційний виклик, адресований перспективним молодим мисливцям-тауренам, яких зібрав Табір Нарачі. Передане від імені наставника Ланки Фаршота послання кличе новачка почати опановувати практичні й духовні мистецтва дикої природи.",h="Гравірована Записка — офіційний виклик, адресований перспективним молодим мисливцям-тауренам, яких зібрав...",kw={"гравірована записка","мисливець","ланка фаршот","ґрулл гоквінд","табір нарачі","шу'гало"},ang={["class:Hunter"]="Цей виклик знаменує ваше офіційне посвячення в традицію мисливців і готує вас опанувати мистецтво влучної стрільби, виживання в дикій природі й дружби зі звірами.",["race:Tauren"]="Для шу'гало полювання — священний обов'язок, що шанує Матір-Землю через повагу до звірів, які годують плем'я на рівнинах Малгору."},sec={{t="Поклик до полювання",b="Молодим тауренам, що навчаються серед круч Плато Червоної Хмари й виявляють хист до влучної стрільби та слідопитства, передають гравіроване послання. Записка, що переходить із рук Ґрулла Гоквінда, несе звістку: Ланка Фаршот помітив родовід і природну здібність юнака й закликає його взятися за науку під його пильним оком."},{t="Традиція рівнин",b="Для шу'гало мисливець — значно більше, ніж простий розвідник чи воїн. Мисливці годують племена своєю здобиччю, захищають кочові стійбища й живуть у тісній рівновазі зі звірами Калімдору. Кличучи новачка на навчання, Ланка закладає підвалини для опанування зброї, розуміння створінь Малгору і, зрештою, стародавнього мистецтва приборкувати диких супутників."}},fp="11,247,21.346.0,23.398.0,39.152.0,22.132.0,31.134.0,44.152.0,41.189.0,45.148.0"}
P.entries["quest:3094"] = {n="Зелена Записка",s="Зелена Записка — офіційний виклик, який вручають перспективним молодим тауренам на Плато Червоної Хмари. Довірене Ґруллу Гоквінду послання велить майбутнім захисникам дикої природи розшукати наставника друїдів Ґарта Містраннера там, де стоїть Табір Нарачі.",h="Зелена Записка — офіційний виклик, який вручають перспективним молодим тауренам на Плато Червоної Хмари.",kw={"зелена записка","друїд","ґарт містраннер","ґрулл гоквінд","табір нарачі","мати-земля","плато червоної хмари"},ang={["class:Druid"]="Цей виклик — найперше посвячення друїда в спрямування диких енергій і неспокійних духів Азерота.",["faction:Horde"]="Друїди-таурени — головний міст між сучасною Ордою й природними таємницями Калімдору, що дає духовну рівновагу первісній бойовій силі фракції.",["race:Tauren"]="Для тауренів друїдизм — не просто школа магії, а священний заповіт, успадкований від їхньої міфічної відданості Матері-Землі."},sec={{t="Поклик на шлях",b="Молодих тауренів, що беруться за свої обов'язки на Плато Червоної Хмари, швидко вирізняють за природними дарами. Ґрулл Гоквінд передає це послання від імені гінця, якого надіслав Ґарт Містраннер. Записка — запрошення в стародавнє коло друїдизму тауренів: вона кличе посвяченого від простих сільських доручень до того, щоб дослухатися до шепітливої рівноваги рівнин."},{t="Голоси Матері-Землі",b="Коли посвячений відгукується на виклик, Ґарт Містраннер застерігає друїда-початківця: духи предків і природи стали неспокійними по всьому Малгору. Друїди-таурени мають бути живими втіленнями природи й зберігати злагоду з волею Матері-Землі, хоч би які далекі суперечки точилися. Нічні ельфи теж практикують друїдичні мистецтва, та Ґарт застерігає: їхня гордість засліплює їх і не дає побачити власний глибокий зв'язок тауренів зі світом природи."}},fp="12,237,21.383.0,25.433.0,25.201.0,36.134.0,35.150.0,54.278.0,40.202.0,62.137.0"}
P.entries["quest:3096"] = {n="Зашифрований Сувій",s="Зашифрований Сувій — непримітний виклик, який отримують щойно пробуджені розбійники Відступників у Похоронному Подзвоні. Передана через Жерця Тіні Сарвіса, шифровка скеровує новобранця до Девіда Тріаса — наставника розбійників, що тихо працює з місцевого заїзду.",h="Зашифрований Сувій — непримітний виклик, який отримують щойно пробуджені розбійники Відступників у...",kw={"зашифрований сувій","девід тріас","сарвіс","похоронний подзвін","розбійник","тінеслідці"},ang={["class:Rogue"]="Це послання — ваше офіційне посвячення в таємну мережу Відступників, місток між щойно піднятим трупом і майбутнім таємним агентом.",["race:Undead"]="Поки новостворені Відступники обороняють Галявини Тірісфалю від Погибелі та недобитків живих, розвідники й таємні агенти життєво важливі для стратегії виживання Темної Леді."},sec={{t="Тихий виклик",b="Поки щойно піднята нежить б'ється з безтямними зомбі на цвинтарі, очільники поселення придивляються до тих, хто має хист до скрадання й хитрощів. Жрець Тіні Сарвіс вручає цей запечатаний пергамент перспективним розвідникам, щойно ті доведуть свою первинну готовність. Позначений непримітною печаткою Девіда Тріаса, він слугує першим знайомством із тіньовою мережею, що діє в глибині ієрархії Відступників."},{t="Очі в тінях",b="Девід Тріас спостерігає за перехрестям і заїздом Похоронного Подзвону, вишукуючи кандидатів для майбутніх таємних операцій. Відступникам потрібні не прості злодії чи безрозсудні кишенькові крадії, а дисципліновані таємні агенти на службі молодого королівства. Тріас натякає, що здібні розбійники з часом можуть привернути увагу Тіньових Переслідувачів — відданого загону Відступників, де цінують хитрість, точність і беззастережну вірність Темній Леді."}},fp="16,243,15.433.0,19.443.0,44.200.0,19.169.0,46.205.0,29.217.0,39.142.0,29.108.0"}
P.entries["quest:3097"] = {n="Освячений Сувій",s="Освячений Сувій — вступний виклик для щойно пробуджених жерців Відступників у Похоронному Подзвоні. Передане Жерцем Тіні Сарвісом, послання кличе новака до Темного Клірика Дюстена в зруйновану сільську каплицю — дізнатися, як нежить тримається віри після смерті.",h="Освячений Сувій — вступний виклик для щойно пробуджених жерців Відступників у Похоронному Подзвоні.",kw={"освячений сувій","дюстен","сарвіс","жрець","похоронний подзвін","тінь","віра"},ang={["class:Priest"]="Це завдання — ваше філософське хрещення в жрецтві Відступників: відмова від традиційного благочестя заради опори на себе, страждання і магії Тіні.",["race:Undead"]="Сувій утілює світогляд Відступників: відірвані від колишньої людської віри, вони виживають лише залізною волею і взаємною необхідністю."},sec={{t="Виклик у Похоронному Подзвоні",b="Коли щойно пробуджена нежить вибирається з могил Похоронного Подзвону, її розум часто ще хитається від пережитого: чуми, смерті й раптового звільнення з лещат Короля-Ліча. Для тих, хто за життя був ревним послідовником Святого Світла, сум'яття особливо глибоке. Поки молода нежить б'ється з безтямною Погибеллю на околицях поселення, Жрець Тіні Сарвіс перехоплює вхідні послання. Освячений сувій, позначений знаком Темного Клірика Дюстена, велить новопіднятим жерцям облишити блукання і з'явитися до оскверненої міської каплиці."},{t="Віра, переосмислена наново",b="Доставивши сувій, новак стикається з суворим богослов'ям жрецтва Відступників. Темний Клірик Дюстен не добирає м'яких слів: Святе Світло покинуло їх у смерті, духи предків — порожні казки, а демони з інших світів байдужі до їхньої біди. Натомість духівництво Відступників навчає: єдине справжнє джерело порятунку — чиста сила волі та безоглядна опора на себе. Під наставництвом Дюстена новопідняті жерці вчаться спрямовувати і божественну дисципліну, і Тінь, черпаючи силу не з відданості далеким богам, а з непохитної переконаності у власному виживанні."}},fp="15,277,23.577.0,15.584.0,28.210.0,35.179.0,40.201.0,37.133.0,46.244.0,38.197.0"}
P.entries["quest:3098"] = {n="Гліфічний Сувій",s="Гліфічний Сувій — офіційний виклик, який отримують щойно пробуджені маги Відступників у Похоронному Подзвоні. Пергамент із печаткою наставниці магів Ізабелли скеровує перспективних адептів таємної магії до неї, в осквернену сільську церкву, — приборкати свою нестримну силу.",h="Гліфічний Сувій — офіційний виклик, який отримують щойно пробуджені маги Відступників у Похоронному Подзвоні.",kw={"гліфічний сувій","ізабелла","маг","похоронний подзвін","таємна магія","даларан"},ang={["class:Mage"]="Цей сувій — ваше офіційне посвячення в лави магів Відступників; він напряму пов'язує ваше ремесло з виживанням і відродженням вашого щойно звільненого народу.",["race:Undead"]="Маги Відступників володіють таємною магією з темною метою: для них це не вчена гра Даларана, а незамінна зброя, щоб повернути вкрадену батьківщину."},sec={{t="Виклик до таємної магії",b="Коли щойно піднятий Відступник, винищуючи безтямну Погибель довкола Похоронного Подзвону, виявляє хист до таємної магії, старші одразу беруть його на замітку. Гліфічний Сувій, переданий із рук у руки, позначено магічною печаттю Ізабелли, місцевої наставниці магів. Він велить новопіднятому адепту з'явитися до її посту в зруйнованій церкві, адже неконтрольований магічний хист небезпечний для Відступників не менше, ніж для їхніх ворогів."},{t="Магія в нежитті",b="У зруйнованій каплиці Похоронного Подзвону Ізабелла втовкмачує новачкам: смерть не звільнила їх від небезпек таємної магії. Нехай смертність забрала тілесну слабкість, та нестримний потяг магії та її згубна природа нікуди не поділися. Для Відступників опанування таємної магії — не просто інтелектуальна вправа, а знаряддя виживання і помсти: спосіб повернути собі долю і стерти кожного, хто зазіхне на їхнє крихке відвоювання Лордерону."}},fp="14,286,23.482.0,25.502.0,27.226.0,36.169.0,26.165.0,52.239.0,60.174.0,43.134.0"}
P.entries["quest:310"] = {n="Запеклі суперники",s="Запеклі суперники — раннє завдання Альянсу в Дун Мороґу, народжене з лютого змагання між двома гордими дворфійськими броварськими родинами. Марлет Барліб'ю посилає шукача пригод проникнути до Ґуральні Тандербрю в Хараносі й попорпатися в запасах суперників.",h="Запеклі суперники — раннє завдання Альянсу в Дун Мороґу, народжене з лютого змагання між двома гордими...",kw={"запеклі суперники","марлет барліб'ю","тандербрю","барліброю","громовий ель","окріп барліброю","льох","харанос"},ang={["class:Rogue"]="Проникнути до охоронюваного льоху, відволікти вартового й непомітно підмінити контрабанду — звична робота для будь-якого розбійника, навіть якщо нагорода — пиво, а не золото.",["faction:Alliance"]="Харанос — культурний і логістичний осередок Дун Мороґу для мандрівників Альянсу, тож місцеві корчемні суперечки — часта розвага для новобранців, що проходять повз.",["race:Dwarf"]="Для дворфів броварство — серйозна справа, що за престижем не поступається ковальству. Устрягнути в льохову ворожнечу через суперницькі елі — цілком звична річ серед снігів Дун Мороґу."},sec={{t="Смак змагання",b="Мало що в Каз Модані розпалює пристрасті так швидко, як пінта елю. Барліброю давно нидіють у тіні уславленої Ґуральні Тандербрю в Хараносі. Хоч Марлет Барліб'ю неохоче визнає, що ремесло Тандербрю гідне поваги, вона не може стерпіти думки, що це єдиний уславлений трунок у Дун Мороґу. Щоб струснути місцевий смак, вона задумує підмінити діжку Громового Елю своїм вогняним варивом — Окропом Барліброю."},{t="Підступ у льоху",b="Щоб здійснити задум, треба прослизнути просто під носом у відвідувачів Хараноса. Під кухнею ґуральні лежить підвальна комора, де витримані діжки чекають, щоб їх відкоркували. Оскільки Тандербрю тримають вартового біля свого найціннішого запасу, майбутній диверсант мусить знайти спосіб відманити сторожа, перш ніж потай підмінити барила."}},fp="13,260,22.464.0,17.369.0,34.153.0,40.144.0,27.194.0,49.179.0,49.197.0,33.120.0"}
P.entries["quest:3103"] = {n="Освячений Лист",s="Освячений Лист — офіційний виклик, який Маршал Макбрайд вручає перспективним молодим жерцям від імені наставниці Абатства Нортшира, Жриці Анетти. Він знаменує початок формального навчання жерця-початківця засадам Святого Світла посеред неспокійного й уразливого світу.",h="Освячений Лист — офіційний виклик, який Маршал Макбрайд вручає перспективним молодим жерцям від імені...",kw={"освячений лист","жрець","жриця анетта","святе світло","нортшир","маршал макбрайд"},ang={["class:Priest"]="Це завдання означає ваше офіційне посвячення в учні Святого Світла під проводом Жриці Анетти й подає вашу божественну магію як життєво важливий обов'язок зцілювати розколотий світ.",["race:Human"]="Абатство Нортшира здавна було прихистком віри й одужання для Королівства Стормвінд і зберігає свої традиції, попри лихо, що підступає до Елвінну."},sec={{t="Поклик до сану",b="Довівши свою доблесть у боротьбі зі шкідниками, що лізуть на виноградники Нортширу, жерці-новачки отримують послання зі священною печаткою Жриці Анетти. Лист, переданий через Маршала Макбрайда, слугує запрошенням розпочати серйозне вивчення Святого Світла в тихих залах абатства."},{t="Світ, що потребує допомоги",b="Отримавши лист, Жриця Анетта доносить до нового учня, у якому похмурому стані перебуває світ. Загроза Палаючого Легіону й досі кидає довгі тіні на Азерот, а континенти потерпають від свіжих ран і заворушень. У її очах узяти на себе служіння жерця — не просто вчена відданість, а нагальний моральний обов'язок нести зцілення й розраду стражденному світу."}},fp="15,292,22.311.0,15.409.0,28.217.0,30.202.0,45.233.0,36.130.0,61.180.0,50.205.0"}
P.entries["quest:3104"] = {n="Гліфічний Лист",s="Гліфічний Лист — офіційний виклик, який Маршал Макбрайд вручає магам-початківцям із людей у Долині Нортширу. Записка, скріплена чародійською печаткою Келдена Бремена, кличе перспективних заклиначів до Абатства Нортшира, щоб розпочати формальне навчання таємних мистецтв.",h="Гліфічний Лист — офіційний виклик, який Маршал Макбрайд вручає магам-початківцям із людей у Долині Нортширу.",kw={"гліфічний лист","маг","келден бремен","чародійство","нортшир","маршал макбрайд"},ang={["class:Mage"]="Це завдання знаменує ваш офіційний перехід від сирого, невишколеного таланту до визнаного підмайстра чародійських мистецтв Стормвінда під проводом Келдена Бремена.",["race:Human"]="Люди-маги Нортширу успадковують традицію, що сягає перших людських чародіїв Даларану й Кірін-Тору, і несуть чародійську міць у Королівство Стормвінд."},sec={{t="Поклик до чародійства",b="Коли майбутній підмайстер доводить свої здібності, допомагаючи Маршалу Макбрайду проти місцевих шкідників, командир гарнізону вручає йому послання, позначене чародійськими рунами. Лист надіслав сам Келден Бремен, наставник магів Нортширу, який придивляється до новобранців, що прибувають до абатства, шукаючи ознак магічної дисципліни й таланту."},{t="Тягар чародійства",b="Абатство Нортшира історично було прихистком Святого Світла, однак небезпеки, що нависли над Стормвіндом, вимагають практиків усіх дисциплін. Відгукнувшись на лист, новачок піднімається сходами до Келдена Бремена. Замість легкої похвали наставник дає суворе попередження: щоб опанувати чародійську силу, треба кидати виклик природним межам, а це викликає у простолюду і глибоку повагу, і глибинний страх."}},fp="14,275,23.348.0,22.425.0,32.137.0,29.135.0,31.157.0,44.207.0,41.155.0,48.178.0"}
P.entries["quest:3105"] = {n="Опоганений Лист",s="Опоганений Лист — таємний виклик для чорнокнижників-початківців із людей, що навчаються в Долині Нортширу. Послання, яке потайна наставниця Друзілла Ла Салль довірила Маршалу Макбрайду, кличе посвячених подалі від допитливих очей варти абатства — розпочати формальне навчання мистецтва скверни.",h="Опоганений Лист — таємний виклик для чорнокнижників-початківців із людей, що навчаються в Долині Нортширу.",kw={"опоганений лист","чорнокнижник","друзілла ла салль","скверна","нортшир","маршал макбрайд"},ang={["class:Warlock"]="Це завдання — формальний набір людей-чорнокнижників у Нортширі, що встановлює тонку рівновагу між переховуванням від осудливої варти й опануванням небезпечної магії Нижнього Світу.",["race:Human"]="Людська культура здебільшого шанує Святе Світло та дисципліноване чародійство Кірін-Тору, тож людям-чорнокнижникам доводиться вправлятися в прикликанні на тихих околицях таких поселень, як Нортшир."},sec={{t="Таємний виклик",b="Поки жерці та паладини відкрито навчаються в освячених залах Абатства Нортшира, адепти темнішої магії мусять ступати обережно. Довівши свою вправність у боротьбі з місцевими кобольдами, чорнокнижники-новачки отримують листа, переданого через Маршала Макбрайда. Послання з печаткою Друзілли Ла Салль наказує заклиначу-початківцю негайно з'явитися на її відлюдний пост за головними мурами абатства, перш ніж братися за будь-які інші справи."},{t="Спокуса й честолюбство",b="Зустріч із Друзіллою відкриває, яким хистким є шлях чорнокнижника під пильним оком стормвіндської варти, яку вона зневажливо зве «жалюгідними простаками». Друзілла відверто застерігає учня: черпати силу з Викривленого Нижнього Світу й спілкуватися з демонами означає жити під постійною загрозою розбещення. Вона радить терпіння, обачність і непохитне самовладання, щоб не стати жертвою темних енергій, якими вони орудують, — але дає зрозуміти, що така обережність ніколи не має гасити палке честолюбство."}},fp="14,304,18.465.0,23.538.0,29.223.0,50.315.0,35.143.0,45.296.0,58.248.0,47.161.0"}
P.entries["quest:3106"] = {n="Проста Руна",s="Проста Руна — вступне завдання для дворфів-воїнів-новачків у Долині Холодного Хребта. Передана Стеном Стаутармом від імені наставника воїнів Трана Кормана, вона скеровує свіжих новобранців до Анвілмара, щоб розпочати бойовий вишкіл.",h="Проста Руна — вступне завдання для дворфів-воїнів-новачків у Долині Холодного Хребта.",kw={"проста руна","воїн","тран корман","стен стаутарм","анвілмар","долина холодного хребта","вишкіл"},ang={["class:Warrior"]="Ця руна знаменує офіційний вступ воїна до бойової дисципліни, скеровуючи нові клинки й довбні просто до Трана Кормана в Анвілмарі.",["faction:Alliance"]="Долина Холодного Хребта — початковий навчальний майданчик для гірських сил, що боронять південні підступи Альянсу до Каз Модану.",["race:Dwarf"]="Тран Корман надзвичайно пишається тим, що вчить дворфійських новобранців битися з традиційною твердістю, закорінюючи їхню культуру в сталі й залізі посеред світу, що стрімко змінюється.",["race:Gnome"]="Утративши Гномреґан через трогів і радіацію, гномські бійці, що починають шлях у Долині Холодного Хребта, мусять учитися війни на передовій пліч-о-пліч із дворфійськими наставниками, щоб вижити у вигнанні."},sec={{t="Виклик до ковадла",b="Поки молоді новобранці винищують шкідників і доводять свою твердість довкола Долини Холодного Хребта, досвідчені розвідники пильно виглядають перспективних бійців. Стен Стаутарм передає камінь із написом — просту руну, — яку йому вручив Тран Корман. Цей виклик кличе бойових хлопців і дівчат із засніжених стежок долини до теплої ковальської зали Анвілмара, щоб офіційно присягнути воїнському ремеслу."},{t="Дун Мороґ, що змінюється",b="З'явившись до Трана, одразу бачиш суворі реалії сучасного Дун Мороґу. Досвідчений наставник говорить відверто про мінливий краєвид королівства: переселені гноми, що шукають прихистку після катастрофічних вибухів, які знищили Гномреґан, дворфи, що опановують чужоземні таємні мистецтва чи переймають людську відданість Святому Світлу, і повсякчасна загроза підземних трогів, що дряпаються в гірські кордони. В очах Трана тверда бойова дисципліна лишається підмурівком, потрібним, щоб усе це витримати."}},fp="11,242,22.389.0,21.522.0,24.215.0,21.231.0,50.294.0,30.278.0,62.277.0,32.159.0"}
P.entries["quest:3107"] = {n="Освячена Руна",s="Освячена Руна — вступний виклик, який вручають дворфійським паладинам-початківцям у Долині Холодного Хребта. Передана Стеном Стаутармом від імені Бромоса Ґруммнера, вона знаменує офіційне прийняття послушника до Лицарів Срібної Длані.",h="Освячена Руна — вступний виклик, який вручають дворфійським паладинам-початківцям у Долині Холодного Хребта.",kw={"освячена руна","паладин","бромос ґруммнер","стен стаутарм","срібна длань","святе світло","анвілмар"},ang={["class:Paladin"]="Ця руна — ваш перший офіційний крок до Лицарів Срібної Длані, що встановлює ваш обов'язок спрямовувати Світло на захист Айронфорджа.",["race:Dwarf"]="Дворфійські паладини поєднують традиційну дворфійську стійкість із богослов'ям, якого навчили люди, вносячи непохитну рішучість у вчення Святого Світла."},sec={{t="Виклик до Анвілмара",b="Поки шукачі пригод-новачки винищують трогів і вовків довкола Долини Холодного Хребта, місцеві очільники пильно стежать за тими, хто виявляє хист до божественної бойової вправності. Стен Стаутарм вручає цю руну з написом молодим паладинам, наказуючи знайти Бромоса Ґруммнера в теплі Анвілмара. Це водночас і запрошення, і офіційне повідомлення, що сирий потенціал тепер треба загартувати дисципліною."},{t="Дворфи й Святе Світло",b="Хоч Лицарі Срібної Длані постали серед людей Лордерону, дворфи Айронфорджа прийняли філософію Святого Світла з палкою відданістю. Бромос Ґруммнер вітає послушників у братстві, нагадуючи, що дворфійські паладини тепер поділяють урочистий обов'язок захищати Азерот. Закорінений у жертовності, традиції й бойовій чесноті, орден вимагає, щоб новобранці взяли молот і віру рівною мірою."}},fp="16,245,21.418.0,26.433.0,29.165.0,23.194.0,55.247.0,35.150.0,33.123.0,49.155.0"}
P.entries["quest:3108"] = {n="Гравірована Руна",s="Гравірована Руна — письмовий виклик, який вручають дворфійським мисливцям-новачкам, що допомагають варті в Долині Холодного Хребта. Переданий Стеном Стаутармом, камінь із написом скеровує слідопитів-початківців до Торґаса Ґрімсона в Анвілмарі, щоб офіційно розпочати бойовий і лісовий вишкіл.",h="Гравірована Руна — письмовий виклик, який вручають дворфійським мисливцям-новачкам, що допомагають варті в...",kw={"гравірована руна","мисливець","торґас ґрімсон","стен стаутарм","анвілмар","долина холодного хребта","вистежування"},ang={["class:Hunter"]="Ця руна розпочинає вашу подорож мисливця в Дун Мороґу, знайомлячи вас із Торґасом Ґрімсоном і засадничими дворфійськими традиціями вистежування, догляду за зброєю й виживання в дикій природі.",["race:Dwarf"]="Вирізьблювати послання в суцільному камені — вияв давньої дворфійської шани до тривкого ремесла, навіть для буденних викликів і польових вказівок."},sec={{t="Виклик у камені",b="Допомагаючи Стену Стаутарму з довколишніми загрозами в Долині Холодного Хребта, перспективні дворфійські мисливці отримують кам'яну табличку з написом, відому як Гравірована Руна. Замість передавати усні накази чи простий пергамент, дворфійські наставники воліють різьблені руни для офіційних послань. Руна велить одержувачу підбити підсумок своєї ранньої праці й з'явитися до Анвілмара по глибші настанови в мистецтві полювання."},{t="Традиції мисливця Дун Мороґу",b="Показати руну Торґасу Ґрімсону — означає для мисливця вступити до офіційної дисципліни. Торґас наголошує, що гірське ремесло й виживання в Каз Модані вимагають глибокої поваги до суворого довкілля: читати сліди в лютих заметах, доглядати зброю й набої, розуміти диких звірів, що никають скелями. Гравірований камінь — перший крок мисливця від самотнього блукальця з рушницею до учня досвідчених слідопитів Анвілмара."}},fp="11,289,18.443.0,35.466.0,24.175.0,26.172.0,32.104.0,44.243.0,58.235.0,38.218.0"}
P.entries["quest:3109"] = {n="Зашифрована Руна",s="Зашифрована Руна — закодоване послання, яке вручають майбутнім розбійникам, що роблять перші кроки в Долині Холодного Хребта. Передане Стеном Стаутармом, вигравіруване послання скеровує перспективні тіні до Анвілмара, щоб з'явитися до наставника розбійників Солма Гарґріна.",h="Зашифрована Руна — закодоване послання, яке вручають майбутнім розбійникам, що роблять перші кроки в Долині...",kw={"зашифрована руна","розбійник","солм гарґрін","стен стаутарм","анвілмар","шифр","долина холодного хребта"},ang={["class:Rogue"]="Ця руна — ваш перший офіційний контакт із мережею розбійників Дун Мороґу, що веде вас до Солма Гарґріна, щоб почати відточувати скрадання, бойові хитрощі й ремесло виживання.",["race:Dwarf"]="Солм вітає дворфів клану Айронфорджа в тінях, зауважуючи, що ніщо так не тримає оперативника живим у Дун Мороґу, як холодний клинок і темрява.",["race:Gnome"]="Солм закликає учнів виявляти побратимство до гномів, що знайшли прихисток у Долині Холодного Хребта після трагічної втрати їхнього дому в Гномреґані."},sec={{t="Послання в коді",b="Допомагаючи Стену Стаутарму на засніжених перевалах Долини Холодного Хребта, гострозорі розбійники отримують дивний гравірований камінь. Стен зізнається, що річ йому підкинули, щоб він її передав, і підозрює, що вона просто від Солма Гарґріна. Замість гукати через подвір'я, шукаючи потенційних розвідників і пройдисвітів, Солм використовує зашифровану руну, щоб перевірити обачність новачка й покликати його під дах."},{t="Під кроквами Анвілмара",b="В Анвілмарі Солм Гарґрін вітає новоприбулих оперативників у ремеслі. Він пропонує навчити маневрів, ударів і тонких мистецтв, що тримають оперативника живим і наповнюють його кишені монетою. Окрім гостріння кинджалів, Солм нагадує дворфійським розбійникам дбати про своїх переселених гномських союзників, які досі оговтуються після катастрофічного падіння Гномреґану."}},fp="14,248,17.392.0,24.381.0,29.185.0,29.124.0,33.196.0,33.232.0,33.146.0,36.106.0"}
P.entries["quest:311"] = {n="Повернення до Марлет",s="Повернення до Марлет — пустотливе завершення запеклої броварської ворожнечі в Дун Мороґу. Проникнувши до льоху Хараноса й підмінивши діжку вогняним Окропом Марлет, шукач пригод повертається до Села Брюнолл із трофейним барилом Громового Елю як незаперечним доказом.",h="Повернення до Марлет — пустотливе завершення запеклої броварської ворожнечі в Дун Мороґу.",kw={"повернення до марлет","марлет барліб'ю","село брюнолл","громовий ель","окріп барліброю","барило","харанос"},ang={["class:Rogue"]="Проникнути до охоронюваного льоху, щоб підмінити заборонені діжки, — кумедна перевірка скрадання й спритності рук серед засніжених пагорбів.",["race:Dwarf"]="Дворфійська культура має броварство за мистецтво й змагання честі, тож дрібне льохове шпигунство — справа великої місцевої гордості."},sec={{t="Здобич диверсії",b="Дворфійські суперництва рідко вирішуються дипломатією, коли на кону ель. Марлет Барліб'ю із Села Брюнолл плекає люту змагальну образу на ґуральників Хараноса, творців уславленого Громового Елю. Коли її міцний «Окріп» непомітно підкинуто до льоху Тандербрю, Марлет вимагає доказу подвигу. Винести справжнє барило Громового Елю з-під їхнього носа — і трофей, і козир."},{t="Гірке вариво залагоджено",b="Притягти важку діжку назад через засніжені хребти до Села Брюнолл — завершити витівку. Марлет у захваті від того, що задум удався, і зловтішно смакує тим, як перехитрила варту й льохових майстрів Хараноса. Хоч на поверхні витівка й нешкідлива, вона скріплює люту, безкомпромісну гордість, яку різні дворфійські родини вкладають у свої фірмові рецепти по всьому Дун Мороґу."}},fp="17,278,22.453.0,21.378.0,34.166.0,26.181.0,33.153.0,26.110.0,36.198.0,37.174.0"}
P.entries["quest:3110"] = {n="Освячена Руна",s="Освячена Руна — вступне завдання для дворфійських жерців-початківців у Долині Холодного Хребта. Стен Стаутарм передає руну з написом від наставника жерців Бранстока Калдера, яка кличе новачка до Анвілмара, щоб поглибити зв'язок зі Святим Світлом.",h="Освячена Руна — вступне завдання для дворфійських жерців-початківців у Долині Холодного Хребта.",kw={"освячена руна","жрець","брансток калдер","стен стаутарм","святе світло","анвілмар","долина холодного хребта"},ang={["class:Priest"]="Цей пергамент знаменує ваше офіційне визнання як служителя Святого Світла в Дун Мороґу й скеровує вас до Бранстока Калдера по найперші закляття.",["race:Dwarf"]="Дворфійські жерці поєднують глибоку відданість Світлу зі звичною гірською твердістю, і без них не втримати Долину Холодного Хребта проти трогів-загарбників."},sec={{t="Поклик до ряси",b="Поки новоприбулий жрець допомагає Стену Стаутарму розчищати найближчі загрози біля Анвілмара, він потрапляє на око духовному провідникові поселення. Брансток Калдер довіряє Стену освячену руну з молитвами й настановами, яка скеровує молодого шукача пригод до міцних зал Анвілмара, щоб офіційно розпочати священні студії."},{t="Захисники Холодного Хребта",b="Хоч дворфійська культура часто наголошує на бойовій стійкості й важкій броні, Святе Світло лишається наріжним каменем суспільства Айронфорджа. У Долині Холодного Хребта святі заклиначі відіграють життєво важливу роль поруч із воїнами й мисливцями, захищаючи анклав від зухвалих набігів трогів і небезпечної звірини, що підкрадається заметами."}},fp="13,258,22.364.0,22.331.0,26.202.0,25.229.0,34.123.0,48.168.0,30.116.0,36.148.0"}
P.entries["quest:3112"] = {n="Проста Службова Записка",s="Проста Службова Записка — послання, яке вручають майбутнім гномам-воїнам, що починають шлях у Долині Холодного Хребта. Передана Стеном Стаутармом надворі, вона скеровує новонавчених бійців до Анвілмара на зустріч із Траном Корманом, який пообіцяв підготувати їх до повернення Гномреґану.",h="Проста Службова Записка — послання, яке вручають майбутнім гномам-воїнам, що починають шлях у Долині...",kw={"проста службова записка","воїн","гном","тран корман","стен стаутарм","анвілмар","гномреґан"},ang={["class:Warrior"]="Це послання офіційно розпочинає бойову освіту гнома-воїна, установлюючи зв'язок із досвідченими майстрами зброї Айронфорджа.",["race:Dwarf"]="Дворфійські наставники на кшталт Трана Кормана ставлять біду гномів нарівні з власними давніми чварами, виявляючи глибоку солідарність із переселеними союзниками.",["race:Gnome"]="Записка підкреслює вигнання гномів із Гномреґану та їхню тиху рішучість вишколити воїнів, здатних повернути їхнє радіоактивне місто."},sec={{t="Виклик до Анвілмара",b="Поки молодий гном-воїн винищує трогів і вепрів, що дошкуляють Долині Холодного Хребта, для горянина Стена Стаутарма, він отримує коротке послання, підкинуте дворфові до рук. Розгледівши потенціал у новобранці-біженці, досвідчений наставник Тран Корман за допомогою записки кличе новачка до центральної зали Анвілмара, щоб розпочати справжній бойовий вишкіл."},{t="Обітниця солідарності",b="Хоч дворфійські наставники часом і підсміюються з гномів-воїнів через їхній крихітний зріст, Тран Корман ставиться до їхньої боротьби серйозно. Співчуваючи втраті Гномреґану, Тран порівнює біду гномів із тим, що відчули б дворфи, якби Айронфордж упав перед Темним Залізом. Дотримуючи слова, він присягається навчати бійців-вигнанців мистецтва війни, доки ті не будуть готові відвоювати свій дім."}},fp="17,274,21.363.0,22.406.0,30.211.0,25.181.0,44.231.0,30.124.0,21.166.0,44.208.0"}
P.entries["quest:3113"] = {n="Зашифрована Записка",s="Зашифрована Записка — вступний виклик для гномів-розбійників-початківців, що прибувають до Долини Холодного Хребта. Передана через Стена Стаутарма, замаскована записка тихо скеровує нових оперативників до Солма Гарґріна в Анвілмарі.",h="Зашифрована Записка — вступний виклик для гномів-розбійників-початківців, що прибувають до Долини Холодного...",kw={"зашифрована записка","розбійник","гном","солм гарґрін","стен стаутарм","анвілмар","гномреґан"},ang={["class:Rogue"]="Це завдання — перший поклик для гномів-розбійників, що знайомить їх із Солмом Гарґріном і філософією взаємного захисту, потрібною, щоб провадити таємне ремесло на дворфійських землях.",["race:Dwarf"]="Дворфійські горяни на кшталт Стена Стаутарма сприяють цьому зв'язку, показуючи практичну співпрацю між Айронфорджем і переселеними гномами в Долині Холодного Хребта.",["race:Gnome"]="Записка підкреслює біду гномських біженців після катастрофи в Гномреґані, показуючи, як уцілілі гуртуються, живучи гостями серед дворфів."},sec={{t="Непомітне знайомство",b="Поки новоприбулі гноми допомагають горянам Долини Холодного Хребта з місцевими загрозами від трогів, Стен Стаутарм передає згорнутий аркуш пергаменту, довірений йому потай. Зовні записка вдає офіційну службову записку, та насправді це запрошення зустрітися з Солмом Гарґріном, наставником розбійників, що служить в Анвілмарі."},{t="Спільні злигодні в снігу",b="Послання відображає неспокійну реальність, що постала перед гномами після раптового падіння Гномреґану. Витіснені з підземного дому, уцілілі гноми мусять тіснитися зі своїми дворфійськими господарями в Дун Мороґу. Солм Гарґрін розуміє, що розбійники привертають підозру, коли речі зникають, і обстоює мовчазну солідарність серед майстрів ремесла задля їхнього спільного виживання."}},fp="20,238,23.321.0,28.393.0,35.194.0,32.242.0,61.274.0,42.133.0,34.160.0,44.188.0"}
P.entries["quest:3114"] = {n="Гліфічний Меморандум",s="Гліфічний Меморандум — вступне завдання, що скеровує магів-новачків у Долині Холодного Хребта до їхнього місцевого наставника в Анвілмарі. Довірене горянину Стену Стаутарму, послання кличе початківців таємних мистецтв знайти ексцентричного гнома Марріка Нуррібіта, щоб розпочати офіційні студії заклять.",h="Гліфічний Меморандум — вступне завдання, що скеровує магів-новачків у Долині Холодного Хребта до їхнього...",kw={"гліфічний меморандум","маг","маррік нуррібіт","стен стаутарм","анвілмар","долина холодного хребта","навчання"},ang={["class:Mage"]="Це послання — ваше офіційне знайомство з навчанням таємних мистецтв у Дун Мороґу, що зводить вас напряму з вашим першим наставником.",["faction:Alliance"]="Злагоджена співпраця Стена Стаутарма й Марріка Нуррібіта ілюструє тісне партнерство дворфів і гномів, що ділять Долину Холодного Хребта.",["race:Gnome"]="Маррік Нуррібіт — один із кількох гномських фахівців, які після падіння Гномреґану знайшли прихисток на дворфійських землях, щоб навчати свого традиційного ремесла."},sec={{t="Послання для магів-новачків",b="Допомагаючи горянину Стену Стаутарму з ранніми обов'язками по Долині Холодного Хребта, новоприбулі маги отримують виклик від місцевого авторитету в таємних мистецтвах. Стен одержує письмовий меморандум, адресований заклиначеві-початківцю, і передає його, радячи знайти хвилинку, прочитати зміст і зайти в тепло Анвілмара, щоб зустрітися з автором."},{t="Навчання в Марріка Нуррібіта",b="Автор меморандуму — Маррік Нуррібіт, гном, наставник магів, що служить в Анвілмарі. Замість топити учня в густих теоретичних лекціях, Маррік дає прості, приземлені поради: не встрягайте в серйозні халепи, відкладайте монети на навчання й корчемні напої і суворо уникайте радіоактивної катастрофи, якою став полеглий Гномреґан. Коли основні очікування окреслено, Маррік готовий навчати новачків таємних мистецтв."}},fp="18,304,26.362.0,29.436.0,29.139.0,23.157.0,33.134.0,49.171.0,31.138.0,42.176.0"}
P.entries["quest:3115"] = {n="Осквернений меморандум",s="Осквернений Меморандум — вступне завдання для гномів-чорнокнижників-початківців, що роблять перші кроки в Долині Холодного Хребта. Тихо передане через Стена Стаутарма, послання кличе неофіта в тіні Анвілмара на зустріч з Аламаром Гріммом, який проповідує самодостатність через темну силу, а не довіру до дворфів-господарів.",h="Осквернений Меморандум — вступне завдання для гномів-чорнокнижників-початківців, що роблять перші кроки в...",kw={"осквернений меморандум","чорнокнижник","гном","аламар грімм","стен стаутарм","анвілмар","гномреґан"},ang={["class:Warlock"]="Це послання знаменує ваш офіційний вступ до ремесла чорнокнижника, подаючи демонічні угоди не як божевілля, а як прагматизм, народжений виживанням.",["race:Dwarf"]="Дворфи-господарі терплять цих темних практиків під своїм дахом із відвертою відразою й гострою настороженістю.",["race:Gnome"]="Меморандум відображає глибоке приховане обурення, яке дехто з гномів-вигнанців відчуває через своє переселене становище й залежність від Айронфорджа."},sec={{t="Непомітний виклик",b="Навіть у замерзлій заставі Долини Холодного Хребта практику темних мистецтв зустрічають із глибокою підозрою. Допомагаючи Стену Стаутарму з місцевими загрозами, молоді гноми-чорнокнижники отримують підкинуту записку. Стен передає її неохоче, озвучуючи хистке перемир'я, яке дозволяє чорнокнижникам бути на землях Альянсу: «пильнуй себе… твоєму брату тут не надто довіряють»."},{t="Гномська гіркота у вигнанні",b="Відгукнувшись на записку, чорнокнижник зустрічає Аламара Грімма, що зачаївся в залах Анвілмара. Грімм не добирає слів щодо біди гномів. У його очах звичайне винахідництво й буденна магія геть підвели Гномреґан, довівши їхній народ майже до вимирання й лишивши його біженцями другого сорту, залежними від дворфійської доброї волі. Замість молитися Святому Світлу чи покладатися на дворфійську політику, Грімм закликає учня прикликати й підкорити бісів, що пропонують беззастережну покору."}},fp="18,326,18.373.0,27.513.0,31.174.0,48.248.0,20.232.0,53.235.0,38.131.0,33.156.0"}
P.entries["quest:3116"] = {n="Простий Сигіл",s="«Простий Сигіл» — вступний виклик для юних воїнів нічних ельфів у Тінедолі. Його передає Консерватор Ілталайн від імені наставниці Алііссії, і він офіційно знаменує перехід новобранця до бойового вишколу, щоб захищати молоде гілля Тельдрассила.",h="«Простий Сигіл» — вступний виклик для юних воїнів нічних ельфів у Тінедолі.",kw={"простий сигіл","воїн","алііссія","консерватор ілталайн","тінедол","алдрассил","тельдрассил"},ang={["class:Warrior"]="Це завдання знаменує ваш офіційний початок як воїна калдорей і знайомить вас із Алііссією — вашою першою наставницею в ратній справі.",["faction:Alliance"]="Порада Алііссії відображає перші спроби нічних ельфів прийняти на своєму гіллі інші раси Альянсу попри століття відособленості.",["race:NightElf"]="Сигіл говорить просто про стрімкі зміни довкола калдорей — від висадження Тельдрассила до відкриття усамітненої домівки для чужоземних союзників."},sec={{t="Заклик до зброї в Тінедолі",b="Довівши свої перші навички виживання в сутичках із неспокійною живністю Тінедола, юні воїни нічних ельфів одержують через Консерватора Ілталайна сигіл із написом. Цей знак — офіційне запрошення від Алііссії, місцевої наставниці воїнів, що стоїть на варті в Алдрассилі: вона кличе новачка виступити вперед і присвятити свою ратну силу захистові свого народу."},{t="Буремна нова доба",b="Коли ви приходите до Алііссії, вона вписує вишкіл воїна в тло стрімких і тривожних змін. Усього за кілька років нічні ельфи виростили Світове Дерево Тельдрассил, побачили, як підступна скверна ширилася серед лісових звірів і поблизу, і далеко, та знову з'єдналися з давніми землями предків, які вважали втраченими, — такими як Фералас. Перед лицем цих небезпек здібні захисники потрібні невідкладно."},{t="Відкрите гілля",b="Окрім ратної дисципліни, Алііссія готує юних калдорей до світу за межами їхньої затишної галявини. Вона радить новобранцям не судити упереджено чужинців інших рас, що прибувають на Тельдрассил. Застерігаючи, що не кожен мандрівник діє з чистих спонук, вона наголошує: союзники життєво важливі для захисту калдорей, — і закликає учнів виявляти розумну довіру, беручи на себе роль захисників."}},fp="12,280,28.370.0,20.422.0,18.430.0,25.162.0,31.146.0,28.145.0,52.261.0,61.259.0,47.233.0"}
P.entries["quest:3117"] = {n="Гравірований Сигіл",s="«Гравірований Сигіл» — письмовий виклик, що його через Консерватора Ілталайна одержують юні мисливці нічних ельфів у Тінедолі. Він кличе їх угору, на могутнє гілля Алдрассила, до наставниці Аянни Еверстрайд, щоб офіційно ступити на шлях лучництва й звірознавства.",h="«Гравірований Сигіл» — письмовий виклик, що його через Консерватора Ілталайна одержують юні мисливці нічних...",kw={"гравірований сигіл","мисливець","аянна еверстрайд","консерватор ілталайн","тінедол","алдрассил"},ang={["class:Hunter"]="Це завдання знаменує ваше офіційне знайомство з мисливським наставництвом на Тельдрассилі й відчиняє двері до науки лука, вистежування та володарювання над звірами.",["race:NightElf"]="Для калдорей полювання — священна дисципліна, сплетена з гармонією природи й шануванням Елуни, а не проста розвага."},sec={{t="Виклик на гілля",b="Довівши свою ранню пильність у захисті Тінедола, юні мисливці калдорей одержують від Консерватора Ілталайна знак із написом. Гравірований сигіл, що його спершу приніс посланець від наставниці мисливців Аянни Еверстрайд, велить новачкові піднятися високо, до верхніх ярусів Алдрассила, звідки наставники пильнують крони."},{t="Шлях мисливця",b="Зустріч з Аянною — офіційний початок мисливського вишколу на Тельдрассилі. Вона навчає новачків двоєдиного мистецтва: влучної стрільби й розуміння диких створінь Калімдору. Аянна наголошує, що справжній мисливець має ставитися до своїх звірів-супутників із повагою, зберігаючи пильність і смирення у світі, повному незримих небезпек."}},fp="12,266,23.350.0,22.334.0,25.137.0,35.109.0,31.120.0,34.157.0,49.207.0,41.102.0"}
P.entries["quest:3118"] = {n="Зашифрований Сигіл",s="«Зашифрований Сигіл» — вступний виклик для новоявлених розбійників нічних ельфів, що прибувають до Тінедола. Його передає Консерватор Ілталайн від імені Фрагуна Шейдвіспера: він скеровує таємних оперативників розпочати вишкіл і пам'ятати, яким крихким є мир у Калімдорі.",h="«Зашифрований Сигіл» — вступний виклик для новоявлених розбійників нічних ельфів, що прибувають до Тінедола.",kw={"зашифрований сигіл","розбійник","фрагун шейдвіспер","консерватор ілталайн","тінедол","алдрассил","калімдор"},ang={["class:Rogue"]="Це завдання знаменує ваш вступ до мережі калдорей — розвідників, убивць і збирачів відомостей, яким доручено берегти Тельдрассил від незримих ворогів.",["faction:Alliance"]="Наставники Тінедола нагадують новобранцям, що угоди між фракціями крихкі, а розвідка — запорука того, щоб не допустити вторгнень Орди.",["race:NightElf"]="Навіть у затишному прихистку Алдрассила калдореї пильно стежать за мінливими кордонами Калімдору, щоб захистити своє щойно висаджене гілля."},sec={{t="Послання з тіні",b="Поки молодші нічні ельфи вивчають рівновагу природи під наглядом Консерватора Ілталайна, ті, хто схильний до скритності й хитрощів, одержують тихіший виклик. Зашифрований Сигіл приносить гонець від Фрагуна Шейдвіспера, наставника розбійників у Тінедолі. Списаний шифрами, зрозумілими лише посвяченим у ремесло, він велить власникові розгадати зміст і розшукати Фрагуна біля коріння Алдрассила, щоб офіційно розпочати навчання."},{t="Пильнуючи обрій",b="Послання Фрагуна — не просто запрошення на вишкіл; це тверезе застереження про розстановку сил у Калімдорі. Третя війна скінчилася, та мир між Альянсом і новопосталою Ордою тонкий, як папір. У Тінедолі розвідників і донощиків-розбійників закликають змалку розвивати очі й вуха, стежачи за можливими загрозами й таємними провокаціями, що здатні знову розпалити війну на кордонах."}},fp="15,280,24.439.0,20.437.0,28.164.0,41.169.0,39.144.0,45.228.0,50.181.0,53.192.0"}
P.entries["quest:3119"] = {n="Освячений Сигіл",s="«Освячений Сигіл» — вступний виклик для юних жерців нічних ельфів, що починають вишкіл у Тінедолі. Консерватор Ілталайн передає послання від наставниці жерців Шанди, яка скеровує новачків шукати настанов в Алдрассилі, де вони вчаться володіти благодаттю Елуни.",h="«Освячений Сигіл» — вступний виклик для юних жерців нічних ельфів, що починають вишкіл у Тінедолі.",kw={"освячений сигіл","жрець","шанда","елуна","консерватор ілталайн","тінедол","алдрассил"},ang={["class:Priest"]="Цей обряд переходу зводить молодого жерця калдорей із Шандою й започатковує його офіційне навчання світлу та мудрості Елуни.",["faction:Alliance"]="Слова Шанди підкреслюють, як щойно укладені союзи в Альянсі приводять незнайомі раси й мандрівників просто на гілля Тельдрассила.",["race:NightElf"]="Жрецтво — осердя культури калдорей, керованої давніми традиціями місячної відданості, що вели цей народ тисячоліттями."},sec={{t="Покликання до служіння",b="Жерці в культурі нічних ельфів посідають священне місце як служниці й слуги богині місяця Елуни. Коли юний калдорей у Тінедолі виявляє хист до божественного світла й відданості, Консерватор Ілталайн довіряє йому освячений сигіл. Надісланий гінцем від наставниці жерців Шанди, цей знак — офіційне запрошення з'явитися до дерева Алдрассил і розпочати духовне навчання."},{t="Мінливий світ",b="Зустрівши Шанду, молодий послушник дізнається, що затишне святилище Тельдрассила переживає незвичні потрясіння. Шанда зауважує, що гілля Світового Дерева повниться мандрівниками, зокрема й представниками ширшого Альянсу, яким дозволено зустрітися з калдореями. Хоч великий світ і кличе, Шанда радить новачкам спершу дати раду бідам, що безпосередньо спіткали Тінедол, перш ніж вирушати до ширших конфліктів за його межами."}},fp="14,305,20.428.0,16.449.0,27.161.0,14.184.0,24.118.0,45.236.0,51.159.0,36.218.0"}
P.entries["quest:312"] = {n="Вкрадені припаси Тундри МакҐранна",s="Тундра МакГранн, поранений дворфійський мисливець, що живе серед холодних скель Дун Мороґу, втратив зимові припаси через сумнозвісного місцевого звіра. Велетенський єті, відомий як Старий Айсбірд, затягнув посилену торієм м'ясну скриню МакГранна до свого лігва. Не в змозі наздогнати звіра на хворій нозі, мисливець покладається на подорожніх шукачів пригод, які прослизнуть усередину й повернуть його харчі.",h="Тундра МакГранн, поранений дворфійський мисливець, що живе серед холодних скель Дун Мороґу, втратив зимові...",kw={"вкрадені припаси","тундра макгранн","старий айсбірд","єті","м'ясна скриня","торій","дун мороґ"},ang={["class:Hunter"]="Побратими-слідопити поспівчувають біді МакГранна: місяці старанного оброблення й зберігання дичини зведені нанівець звіром-опортуністом, поки він вистежував оленів.",["class:Rogue"]="МакГранн навмисне шукає скрадливих мандрівників, тож ця крадіжка — хрестоматійна робота для розвідників, здатних прослизнути за спиною Старого Айсбірда, так і не оголивши клинка.",["race:Dwarf"]="Кожен дворф у Дун Мороґу знає безжальну жорстокість гірської зими: без збереженого м'яса чи прихистку навіть загартований горянин не витримає морозу."},sec={{t="Зимові запаси й украдені скрині",b="Пережити суворі зими Дун Мороґу можна лише з підготовкою, особливо горянам, що живуть поза теплом Хараноса й Айронфорджа. Тундра МакГранн старанно засолив цілий місячний запас в'яленого м'яса, щоб перебути хуртовини холодної пори. Остерігаючись голодних диких ведмедів, він запечатав харчі в посиленій торієвій м'ясній скрині. На жаль, він не врахував суцільної сили гірських єті, які понесли всю скриню замість ламати її на місці."},{t="Лігво Старого Айсбірда",b="Винуватець крадіжки — Старий Айсбірд, грізний і лютий єті, що зачаївся серед зубчастих пагорбів. Поки МакГранн полював на оленів, Айсбірд ухопив скриню й затягнув її до своєї гірської печери. Хоч МакГранн і певен, що навіть єті не розтрощить суцільне торієве обшиття, через поранену ногу похід по неї для нього був би самогубством. Кожен сміливець, що зважиться зайти до печери, мусить або зітнутися зі звіром напряму, або ретельно вибрати мить, поки чудовисько никає заметами."}},fp="30,373,32.541.0,18.519.0,23.186.0,33.155.0,46.194.0,26.184.0,57.189.0,34.127.0"}
P.entries["quest:3120"] = {n="Зелений Сигіл",s="«Зелений Сигіл» — письмовий виклик для щойно пробуджених друїдів нічних ельфів у Тінедолі. Консерватор Ілталайн передає його, щоб скерувати новоявлених майстрів перевтілення до Марданта Стронґоука в гіллі Алдрассила. Він знаменує офіційний початок навчання друїда таємницям природи й Смарагдового Сну.",h="«Зелений Сигіл» — письмовий виклик для щойно пробуджених друїдів нічних ельфів у Тінедолі.",kw={"зелений сигіл","друїд","мардант стронґоук","консерватор ілталайн","тінедол","алдрассил","смарагдовий сон"},ang={["class:Druid"]="Це завдання — ваше офіційне посвячення у вчення Кола Кенарія під проводом Марданта Стронґоука, що виводить вас на довгий шлях пізнання Смарагдового Сну.",["race:NightElf"]="Друїдизм глибоко вплетений у культуру нічних ельфів; показати цей сигіл в Алдрассилі — перший крок посвяченого в давню традицію."},sec={{t="Поклик гілля",b="Щойно юний нічний ельф виявляє хист до підтримання рівноваги в Тінедолі, його належить офіційно представити ордену. Консерватор Ілталайн одержує Зелений Сигіл від гінця й довіряє його посвяченому. Цей маленький знак означає, що коло в Алдрассилі звернуло на нього увагу й запрошує молодого друїда офіційно розпочати навчання."},{t="Єднання і Сон",b="Коли посвячений показує сигіл Мардантові Стронґоуку всередині Алдрассила, його приймають до кола. Глибше єднання зі Смарагдовим Сном і опанування звіриних подоб ще попереду, та Мардант стає його першим провідником, якому доручено навчити тлумачити духів природи й спрямовувати первісну силу лісу."}},fp="13,326,20.364.0,23.330.0,26.170.0,34.128.0,43.235.0,34.157.0,40.156.0,34.178.0"}
P.entries["quest:313"] = {n="Сиве Лігво",s="Пілот Стоунґір із Хараноса шукає когось зі справжньою дворфійською твердістю, щоб облаштувати свою улюблену облогову машину Троллплоу. Щоб перевірити витримку майбутнього шукача пригод, він посилає його на захід, у небезпечну печеру, відому як Сиве Лігво, полювати на диких вендиґо заради їхніх густих шкур.",h="Пілот Стоунґір із Хараноса шукає когось зі справжньою дворфійською твердістю, щоб облаштувати свою улюблену...",kw={"сиве лігво","пілот стоунґір","вендиґо","троллплоу","шкури","склад стілґрила","харанос"},ang={["profession:Engineering"]="Кожен, хто цінує ремесло дворфійських облогових машин, знає: утримувати важку техніку на морозі вимагає творчих рішень для тепла в кабіні.",["race:Dwarf"]="Для молодих горян і шукачів пригод Айронфорджа вийти проти вендиґо Сивого Лігва — квінтесенція місцевого обряду посвяти.",["race:Gnome"]="Жити пліч-о-пліч із дворфами довкола Хараноса — означає долучатися до спорядження важких броньованих машин Айронфорджа."},sec={{t="Перевірка твердості",b="Керувати велетенським дворфійським облоговим танком — потрібні залізні нерви й міцна будова тіла, щоб витримувати механізми, від яких цокотять зуби, на крижаному гірському повітрі. Пілот Стоунґір, що служить на Складі Стілґрила біля Хараноса, заявляє, що має і те, й те з лишком. Замість роздавати роботу чи повагу за так, він кидає новачкам виклик: довести, що в них така сама непохитна вдача, вирушивши в замерзлі пагорби назустріч тутешнім звірам."},{t="Затишок у Троллплоу",b="Облогова машина Стоунґіра носить горде й анітрохи не скромне ім'я Троллплоу, але її тісна, обшита залізом кабіна люто холодна в суворому кліматі Дун Мороґу. Стоунґір знаходить практичне, хоч і дике розв'язання: шкура вендиґо. Густі гриви, зняті з лютих вендиґо, що никають Сивим Лігвом, дають матеріал для міцного теплого килима на палубу Троллплоу, а заразом тримають поголів'я місцевих звірів у межах."}},fp="16,281,14.425.0,30.426.0,23.224.0,34.163.0,38.185.0,18.206.0,48.167.0,39.204.0"}
P.entries["quest:314"] = {n="Захист отари",s="Захист отари — завдання, яке дає Рудра Амберстілл на Ранчо Амберстілл у Дун Мороґу. Лютий хижий звір на ім'я Ваґаш ночами нападає на цінних гірських баранів ранчо, а оскільки військовий гарнізон Айронфорджа розтягнутий по всьому королівству, місцеві заводчики мусять покладатися на захист подорожніх шукачів пригод.",h="Захист отари — завдання, яке дає Рудра Амберстілл на Ранчо Амберстілл у Дун Мороґу.",kw={"захист отари","рудра амберстілл","ранчо амберстілл","ваґаш","барани","хижак","дун мороґ"},ang={["class:Hunter"]="Вистежити такого сумнозвісного верховного хижака, як Ваґаш, у його гірському лігві — класичний полігон для будь-якого слідопита, що відточує навички в заметах Дун Мороґу.",["faction:Alliance"]="Поки полки Високого Престолу відтягнуто на підтримку зобов'язань Альянсу по всіх Східних Королівствах, допомога скрутним сільським обійстям стабілізує домашній фронт.",["race:Dwarf"]="Для дворфійських мандрівників захистити Ранчо Амберстілл — означає захистити тих самих гірських баранів, що несуть ваших родичів у бій по всьому Каз Модану."},sec={{t="Загроза для ранчо",b="Ранчо Амберстілл постачає гірських баранів, що слугують знаковими їздовими й робочими тваринами дворфів Бронзбірдів. Утримувати ці отари життєво важливо для сільського господарства Дун Мороґу. Коли впала ніч і над загонами розляглися відчайдушні крики, родина Амберстілл виявила, що двоє їхніх цінних баранів зникли. Винуватець — Ваґаш, сумнозвісний і дикий звір, що зачаївся в сусідніх скелях над ранчо й відомий тим, що люто полює на місцеву худобу."},{t="Виснажена оборона",b="Зазвичай місцевими загрозами такого масштабу займалися б дворфійські горяни чи королівські сили Короля Маґні Бронзбірда. Проте регулярне військо Айронфорджа нині розтягнуте по далеких кордонах на підтримку ширшого Альянсу. Лишившись без офіційного військового загону, щоб патрулювати хребти, Рудра Амберстілл змушений просити незалежних бійців вистежити Ваґаша й принести одне з його смертоносних ікол як доказ."}},fp="19,335,21.456.0,17.452.0,14.250.0,26.210.0,47.246.0,32.240.0,34.185.0,47.216.0"}
P.entries["quest:315"] = {n="Ідеальне темне пиво",s="Реджолд Барліброю із Села Брюнолл твердо вирішив зварити довершений дворфійський стаут, поєднавши родинну броварську традицію з екзотичними місцевими інгредієнтами. Щоб довершити експериментальний рецепт, він шукає мерехтраву — різку рослину, яку вирощують лише ворожі тролі Морозогриви на Мерехтливому Хребті. Відважних мандрівників посилають до тролячого табору, щоб поцупити зілля просто з племінних кошиків.",h="Реджолд Барліброю із Села Брюнолл твердо вирішив зварити довершений дворфійський стаут, поєднавши родинну...",kw={"ідеальне темне пиво","реджолд барліброю","мерехтрава","стаут","село брюнолл","мерехтливий хребет","морозогриви"},ang={["profession:Herbalism"]="Хоч мерехтрава й не стандартне ремісниче зілля, унікальні ботанічні риси цієї морозостійкої рослини роблять її цікавою дивовижею серед замерзлих скель Дун Мороґу.",["race:Dwarf"]="Броварство для клану Бронзбірдів майже священне, і знайти екзотичне дике зілля, щоб перевершити суперницькі корчми, вважається шляхетною справою."},sec={{t="Амбіції бровара",b="У Селі Брюнолл броварство — більше ніж ремесло, це спосіб життя, особливо для родини Барліброю. Реджолд Барліброю вірить, що броварська велич у нього в крові, та щоб досягти легендарного «ідеального стауту», потрібне нестандартне новаторство. Замість покладатися лише на звичайний хміль, солод і гірську джерельну воду, Реджолд звертає погляд на дику флору Дун Мороґу, щоб надати своєму елю неповторної гостроти."},{t="Троляче зілля Мерехтливого Хребта",b="Таємний інгредієнт, якого жадає Реджолд, — мерехтрава, морозостійка рослина, яку тролі Морозогриви вирощують на Мерехтливому Хребті на північному заході. Поки Морозогриви збирають її для своїх племінних і містичних ритуалів, дворфи не мали з неї практичної користі, хіба що зауважили її різкий, прикметний смак. Поцуплене просто зі сховкових кошиків у тролячому селищі, зілля стає осердям найновішого й найсміливішого бродильного експерименту Реджолда."}},fp="17,402,19.424.0,31.459.0,20.281.0,31.242.0,56.313.0,25.248.0,42.182.0,47.191.0"}
P.entries["quest:317"] = {n="Запаси для Джетстіма",s="Запаси для Джетстіма — завдання Альянсу, яке пропонує Пілот Беловфіз на Складі Стілґрила в Дун Мороґу. Готуючи свою облогову машину до тривалого розгортання з Обложною Бригадою Айронфорджа, пілот залучає місцевих мисливців, щоб ті зібрали м'ясо вепрів і ведмежі шкури на харчі для екіпажу.",h="Запаси для Джетстіма — завдання Альянсу, яке пропонує Пілот Беловфіз на Складі Стілґрила в Дун Мороґу.",kw={"запаси для джетстіма","пілот беловфіз","джетстім","облогова бригада","вепряче м'ясо","ведмежі шкури","склад стілґрила"},ang={["faction:Alliance"]="Співпраця дворфійських ремонтних дворів і броньованих екіпажів Облогової Бригади тримає передову облогову техніку Альянсу в робочому стані.",["profession:Cooking"]="Збір товстих шматків вепрячого м'яса в заметах Дун Мороґу підкреслює головну дичину, що годує місцеві гірські гарнізони.",["race:Dwarf"]="Дичина зі скель Дун Мороґу тримає дворфійські екіпажі Облогової Бригади ситими й відпочилими, поки вони працюють у машинних дворах Каз Модану.",["race:Gnome"]="Допомога Беловфізу тримає дворфійську Облогову Бригаду — механізованого союзника Айронфорджа для гномів-вигнанців — повністю спорядженою для довгих походів попереду."},sec={{t="Спорядження машини",b="Пілот Беловфіз, що служить просто біля Хараноса на Складі Стілґрила, наглядає за підготовкою до майбутньої далекої операції Облогової Бригади. Його облоговий танк на ім'я Джетстім потребує і механічного налаштування від майстра-інженера Белдіна Стілґрілла, і місячного запасу польових харчів, щоб екіпаж лишався дієздатним у суворих морозах Дун Мороґу."},{t="Полювання на снігових полях",b="Оскільки Белдін Стілґрілл порпається під капотом Джетстіма, Беловфіз не може покинути машину, щоб зібрати харчі й утеплення. Він скеровує мандрівників полювати на засніжених рівнинах на південь від Сивого Лігва, де тутешні вепри дають поживне м'ясо на їжу, а місцеві ведмеді — густі шкури, що годяться на теплу постіль у танку."}},fp="17,280,23.382.0,23.325.0,17.210.0,23.228.0,44.185.0,26.183.0,34.220.1,44.223.0"}
P.entries["quest:318"] = {n="Евершайн",s="Евершайн — завдання Альянсу на доставку, що починається з Пілота Беловфіза біля Хараноса. Дворфійський пілот облогової машини посилає мандрівників на захід до Села Брюнолл по міцне дворфійське вариво, яке приготував Реджолд Барліброю. Трунок слугує і зігрівальним напоєм, і аварійним високооктановим пальним для облогової машини Беловфіза.",h="Евершайн — завдання Альянсу на доставку, що починається з Пілота Беловфіза біля Хараноса.",kw={"евершайн","пілот беловфіз","реджолд барліброю","село брюнолл","пальне","джетстім","вариво"},ang={["profession:Engineering"]="Використання леткого дистильованого спирту як допоміжного підсилювача пального показує, як пілоти на кшталт Беловфіза тримають облогові машини на ходу в суворих умовах.",["race:Dwarf"]="Міцний трунок Реджолда Барліброю втілює вогняні крайнощі дворфійської броварської традиції на холодних вершинах Дун Мороґу.",["race:Gnome"]="Звичка Пілота Беловфіза перетворювати буденні речі — навіть дворфійську горілку — на імпровізоване пальне вразила б будь-якого гномського майстра."},sec={{t="Міцне вариво",b="Дворфійське броварство уславлене на весь Каз Модан, але рецепти Реджолда Барліброю в Селі Брюнолл розсувають межі звичайного бродіння. Його експериментальний напій, Евершайн, сумнозвісний тим, що валить з ніг усіх, крім найміцніших дворфів. Попри люту міцність, його цінують у лютому холоді Дун Мороґу за суцільну зігрівальну силу."},{t="Пальне для Пілота Беловфіза",b="Пілоти облогових машин часто знаходять нетрадиційне застосування буденним речам, і Пілот Беловфіз не виняток. Працюючи зі Складу Стілґрила біля Хараноса, Беловфіз покладається на Евершайн не лише як на ковток проти крижаних вітрів, а й як на додаткове пальне. Залитий просто в топку його облогової машини Джетстім, леткий спирт дає вибуховий сплеск аварійної потужності, який не раз витягав його з халепи."}},fp="9,327,19.362.0,24.448.0,18.221.0,40.231.0,26.182.0,25.209.0,49.222.1,33.236.0"}
P.entries["quest:319"] = {n="Послуга для Евершайна",s="Щоб здобути діжку Евершайну для Пілота Беловфіза на Складі Стілґрила, шукач пригод мусить спершу допомогти Селу Брюнолл. Бровар Реджолд Барліброю відмовляється розлучатися зі своїм трунком, доки небезпечних хижаків, що никають довколишніми заметами, не прорідять.",h="Щоб здобути діжку Евершайну для Пілота Беловфіза на Складі Стілґрила, шукач пригод мусить спершу допомогти...",kw={"послуга для евершайна","реджолд барліброю","село брюнолл","хижаки","ведмеді","вепри","снігові леопарди","евершайн"},ang={["class:Hunter"]="Проріджування зухвалих хижаків західного Дун Мороґу — перевірка влучності проти найвитриваліших зимових звірів скель.",["race:Dwarf"]="Кожен дворф розуміє, як важливо тримати диких хижаків подалі від чесного перегінного куба, щоб легендарні діжки Брюнолла лишалися неторканими.",["race:Gnome"]="Пілоти облогових машин і майстри на Складі Стілґрила нетерпляче чекають на цю діжку й покладаються на шукачів пригод, які задобрять упертого бровара, щоб підготовка Джетстіма тривала."},sec={{t="Угода бровара",b="У Реджолда Барліброю є діжка Евершайну, потрібна Пілотові Беловфізу, та він не квапиться віддавати своє дорогоцінне вариво задарма. Замість просити монет, Реджолд просить захисту. Дикі звірі західного Дун Мороґу — ненажерливі Крижанокігті Ведмеді, товстошкірі Старі Скельні Вепри й Снігові Леопарди, що никають довкола, — підходять небезпечно близько до Села Брюнолл, постійно відволікаючи місцевих і наражаючи їх на небезпеку."},{t="Спокій для ремісників",b="Хоч Реджолд одразу наполягає, що жоден поважний дворф не тремтить перед дикими тваринами, боротьба з хижаками цілодобово з'їдає цінні години. Винищення місцевої звірини дає селянам спокій, потрібний, щоб зосередитися на дистиляції й ковальстві, не тримаючи одне око повсякчас на узліссі."}},fp="21,264,18.420.0,23.313.0,42.205.0,18.221.0,39.181.0,31.120.0,40.145.0,54.184.0"}
P.entries["quest:33"] = {n="Вовки перетинають кордон",s="«Вовки перетинають кордон» — одне з перших завдань, яке дає Іґан Пелтскіннер біля Абатства Нортшира. Він наймає нових шукачів пригод полювати на вовків, що никають долиною, і збирати їхнє м'ясо для власної кухні.",h="«Вовки перетинають кордон» — одне з перших завдань, яке дає Іґан Пелтскіннер біля Абатства Нортшира.",kw={"вовки","іґан пелтскіннер","вовче м'ясо","нортшир","полювання","кулінарія"},ang={["profession:Cooking"]="Апетит Іґана до вовчого стейка знайомить нових шукачів пригод із суворою правдою прикордоння Азерота: що вполював, те часто можна зготувати й з'їсти.",["race:Human"]="Для людей-новобранців, що починають шлях у Нортширі, це одне з перших практичних завдань на захист найближчих кордонів Стормвінда."},sec={{t="Практичне прохання",b="Поки Маршал Макбрайд і варта Стормвінда зосереджують свої нечисленні сили на захисті Абатства Нортшира від бандитів Дефіас, звичайні ремісники мають щоденні потреби. Іґан Пелтскіннер стоїть під мурами абатства й плекає глибоку неприязнь до місцевих лісових вовків. Замість просто нарікати на звірів, що блукають прикордонними лісами, він наймає новобранців, що проходять повз, проріджувати їхні зграї й приносити жорстке вовче м'ясо йому на сковорідку."},{t="Дика природа Нортширу",b="Долина Нортширу колись була мирним прихистком, захищеним пологими пагорбами й густими лісами. Та відколи Королівство Стормвінд потерпає від безвладдя й нестачі війська, дикі хижаки — молоді вовки й лісові вовки — посміливішали й підходять дедалі ближче до стежок і садів абатства. Зачистка від них не лише наповнює комору Іґана, а й робить ближні стежки безпечнішими для послушників, робітників і щойно прибулих захисників."}},fp="24,218,19.440.0,19.442.0,25.206.0,30.143.0,29.152.0,39.185.0,53.185.0,44.157.0"}
P.entries["quest:3361"] = {n="Біда біженця",s="Після катастрофічного падіння Гномреґану під натиском трогів і радіації переселені гноми втекли в засніжені пустища Дун Мороґу. Біля Анвілмара інженер на ім'я Фелікс Віндлболт під час панічної евакуації втратив своє життєво важливе майно й інструменти через мародерів із тролів Морозогривів.",h="Після катастрофічного падіння Гномреґану під натиском трогів і радіації переселені гноми втекли в засніжені...",kw={"біда біженця","фелікс віндлболт","гномреґан","біженці","морозогриви","тролі","анвілмар","інструменти"},ang={["profession:Engineering"]="Жоден поважний ремісник не стоятиме осторонь, поки мародери тягнуть точні болти, штангенциркулі й ящики з інструментами, які збирали все життя.",["race:Dwarf"]="Гори Холодного Хребта століттями давали прихисток вашим родичам; допомогти гномським біженцям закріпитися в Анвілмарі — ушанувати давній союз між Айронфорджем і Гномреґаном.",["race:Gnome"]="Це завдання втілює гірку трагедію вашого народу: утративши чудесний дім через отруту й зраду, звичайні майстри тепер мусять благати чужинців вирвати базові інструменти в грубих тролів."},sec={{t="Утеча з Гномреґану",b="Коли підземні троги захопили високотехнологічне місто Гномреґан, Великий Тінкер Ґелбін Меккаторк і його радники дозволили випустити радіоактивний газ у відчайдушній спробі винищити загарбників. Ризикований крок обернувся катастрофою: він убив тисячі невинних, перетворив уцілілих на безтямних прокажених гномів і змусив решту населення до панічного виходу через Дун Мороґ."},{t="Мародери в снігу",b="Інженери й майстри-втікачі несли, які могли, цінні інструменти й креслення. Однак крижаними гірськими перевалами між Гномреґаном і Долиною Холодного Хребта никають тутешні тролі Морозогриви. Поки Фелікс Віндлболт пробивався до прихистку Анвілмара, нальотчики Морозогривів вихопили його скриню з інструментами, скриньку й відро болтів і відвезли їх до своїх таборів на південний захід від містечка."}},fp="20,283,26.396.0,22.399.0,25.243.0,29.266.0,29.221.0,43.182.0,42.237.0,61.221.0"}
P.entries["quest:3364"] = {n="Доставка Пекучого Ранкового Варива",s="Доставка Пекучого Ранкового Варива — поспішне доручення через Долину Холодного Хребта: доправити свіжий гарячий напій, перш ніж він вистигне на гірському морозі. Норі Прайддріфт довіряє доставку шукачеві пригод, щоб Дурнан Фуркаттер отримав свій ранковий узвар обпікаюче гарячим.",h="Доставка Пекучого Ранкового Варива — поспішне доручення через Долину Холодного Хребта: доправити свіжий...",kw={"доставка пекучого ранкового варива","ранковий узвар","норі прайддріфт","дурнан фуркаттер","анвілмар","долина холодного хребта","гарячий напій"},ang={["profession:Cooking"]="Подавати напої належної температури — ознака справжньої кулінарної поваги, особливо в безжальних морозах Дун Мороґу.",["race:Dwarf"]="Кожен дворф розуміє трагедію холодного напою на крижаному гірському повітрі, тож цей забіг через долину — справа чистого принципу."},sec={{t="Наввипередки з морозом",b="Пронизливий холод Дун Мороґу зіпсував не одну гарячу страву, і ранковий узвар не виняток. Доставивши порцію Ґреліну Вайтбірду, Норі Прайддріфт розуміє, що не встигне принести ще один свіжий кухоль до Анвілмара, перш ніж той замерзне в неїстівну кашу. Замість підвести клієнта, він залучає будь-якого прудкого мандрівника, готового кинути виклик снігу."},{t="Ціна теплого кухля",b="Дурнан Фуркаттер, що перебуває в теплі гірської зали Анвілмара, відомий своєю вибагливістю щодо напоїв. Прохолодний ранковий узвар просто не годиться. Доправлений гарячим напій дарує втомленому дворфові таку потрібну перерву від обов'язків, хоч Норі все одно чекає, що його улюблений кухоль повернуть цілим."}},fp="26,254,24.351.0,23.318.0,24.171.0,41.190.0,23.202.0,17.156.0,26.169.0,28.133.0"}
P.entries["quest:3365"] = {n="Поверни кухоль",s="Після доставки обпікаюче гарячого ранкового узвару через замети Дун Мороґу лишається останнє доручення: повернути порожній кухоль. Дурнан Фуркаттер відсилає гінця назад через Долину Холодного Хребта, щоб повернути дорогоцінний кухоль Норі Прайддріфта. Проста люб'язність, але продавець напою глибоко її цінує.",h="Після доставки обпікаюче гарячого ранкового узвару через замети Дун Мороґу лишається останнє доручення...",kw={"поверни кухоль","кухоль","норі прайддріфт","дурнан фуркаттер","ранковий узвар","долина холодного хребта","етикет"},ang={["profession:Cooking"]="Кожен порядний кухар чи бровар знає: якісне обслуговування не закінчується, доки посуд не пораховано й не повернуто на кухню.",["race:Dwarf"]="Кожен дворф знає, що привласнити кухоль шинкаря — швидкий шлях до бійки; повернути кухоль Норі — елементарна дворфійська ввічливість."},sec={{t="Справа корчемного етикету",b="Подавати обпікаюче гарячий ранковий узвар на лютому морозі Дун Мороґу — делікатна справа. Коли Дурнан Фуркаттер відігріє кістки гарячим варивом, порожній кухоль не можна просто кинути в сніг. Дворфійська гостинність тримається на взаємній повазі, і загубити добрий посуд — певний спосіб лишитися без наступних порцій."},{t="Кухлі на деревах не ростуть",b="Повернення до Долини Холодного Хребта завершує доставку для Норі Прайддріфта. Як Норі любить нагадувати забудькуватим кур'єрам, міцний посуд на деревах не росте — особливо в крижаних скелях дворфійської батьківщини. Повернути порожній кухоль цілим — закріпити репутацію шукача пригод як надійної людини в місцевій громаді."}},fp="18,313,28.361.0,24.354.0,23.120.0,27.109.0,40.158.0,46.176.0,40.133.0,36.135.0"}
P.entries["quest:3376"] = {n="Зломи Шарптаска!",s="«Зломи Шарптаска!» — вирішальний обряд посвяти, який дає Сміливець Віндфезер на Плато Червоної Хмари. Щоб убезпечити батьківщину тауренів від безперервних наскоків, молодих звитяжців посилають на схід, у Яр Тернистого Клинка, вбити Вождя Шарптаска Торнмантла. Загибель ватажка Щетиноспинів завдає тяжкого удару шипогривам, що зазіхають на Малгор.",h="«Зломи Шарптаска!» — вирішальний обряд посвяти, який дає Сміливець Віндфезер на Плато Червоної Хмари.",kw={"шарптаск","торнмантл","шипогриви","щетиноспини","малгор","яр тернистого клинка","віндфезер"},ang={["class:Hunter"]="Для мисливців це завдання — головне раннє випробування: вистежити здобич, яка має власну хитрість, зброю та намір уполювати вас у відповідь.",["faction:Horde"]="Стративши Вождя Шарптаска, союзники Орди засвідчують свою відданість справі замирення Малгору та здобуття мирних земель для нових братів-тауренів.",["race:Tauren"]="Убивство Шарптаска Торнмантла — одне з останніх випробувань, які молодий таурен проходить перед тим, як покинути Табір Нарачі, доводячи, що має рішучість захищати племена від ворожих сусідів."},sec={{t="Дім, здобутий кров'ю",b="Трав'янисті висоти Плато Червоної Хмари віддавна були мирним прихистком, де молоді таурени осягають традиції полювання та єднання із Земною Матір'ю. Та цей спокій раз у раз під загрозою. На сході лежить Яр Тернистого Клинка — зарослий колючками виярок, який присвоїло собі вороже плем'я шипогривів-Щетиноспинів. Шипогриви мають тауренів за загарбників, що крадуть священну землю, і без упину нападають на племена, які намагаються налагодити осіле життя в Малгорі."},{t="Загроза Торнмантла",b="Постійні напади на плато — не сліпа лють: ними керує жорстокий Вождь Шарптаск Торнмантл. Засівши в укріпленому саморобному селищі в глибині яру, Шарптаск спрямовує своїх воїнів і геомантів проти шу'хало. Розуміючи, що Щетиноспини не припинять наскоків, доки їхній вождь дихає, Сміливець Віндфезер наказує майбутньому герою прорватися в яр, здолати Торнмантла й повернутися з його відтятою головою як доказом."},{t="Уроки полювання",b="Для молодих тауренів та їхніх союзників полювання на Шарптаска — більше ніж проста страта: це посвята в сувору правду виживання. Як навчає Сміливець Віндфезер, лови на звіра вчать терпіння, а полювання на ворога, досить хитрого, щоб полювати у відповідь, випробовує мужність, пильність і бойову дисципліну. Загибель Шарптаска — це справедливість за полеглих родичів і знак, що мисливець готовий вийти на широкі рівнини Малгору."}},fp="16,345,19.488.0,25.507.0,23.453.0,35.229.0,47.190.0,37.204.0,48.259.0,41.200.0,64.277.0"}
P.entries["quest:35"] = {n="Подальші тривоги",s="«Подальші тривоги» — кур'єрське завдання Альянсу від Маршала Дуґана з Ґолдшира: перевірити чутки про загрозу з води. Маршал посилає вас на схід через Ліс Елвінн порадитися з Вартовим Томасом біля річкової переправи. Так ваша увага зміщується від буденної служби в центральному гарнізоні до дедалі гострішої кризи безпеки на східному прикордонні.",h="«Подальші тривоги» — кур'єрське завдання Альянсу від Маршала Дуґана з Ґолдшира: перевірити чутки про загрозу...",kw={"мурлоки","вартовий томас","маршал дуґан","міст","ліс елвінн","редрідж","тривоги"},ang={["faction:Alliance"]="Завдання підкреслює дедалі більші тріщини в Королівстві Стормвінд і показує, якою тонкою стала людська оборона навіть за кілька кроків від столиці.",["race:Human"]="Для людей Елвінну поширення агресивних мурлоків загрожує житниці краю — фермам і торговим артеріям, що з'єднують Ґолдшир із Лейкширом."},sec={{t="Очі на східній переправі",b="Поки центральний Ліс Елвінн знемагає під тягарем розбою й шкідників, почали ширитися тривожні чутки про водяних істот, що повзуть уздовж берегів річки. Маршал Дуґан, командир гарнізону в Ґолдширі, не бажає відмахнутися від паніки. Замість знімати вартових із міста він посилає мандрівників на схід — порадитися з Вартовим Томасом, який несе варту на мосту через східну річку, що веде до Редріджу."},{t="Розтягнуте прикордоння",b="Вартовий Томас тримає заставу біля мосту вже понад тиждень і на власні очі бачить те, про що в Ґолдширі могли лише здогадуватися. Напіврозумні ворожі мурлоки влаштували табори вздовж усіх водних шляхів східного Елвінну. Армія Стормвінда відсутня, місцеві гарнізони прикуті до захисту міських мурів і ліній постачання, тож такі сільські застави, як пост Томаса, лишаються у критичній ізоляції перед цією навалою."}},fp="16,348,28.437.0,25.425.0,48.234.0,32.152.0,38.193.0,30.126.0,58.226.0,45.167.0"}
P.entries["quest:3519"] = {n="Друг у біді",s="«Друг у біді» — відчайдушне прохання про допомогу від Іверрона, юного нічного ельфа, якого в Тінедолі знайшли отруєним укусами павуків. Збитий з ніг смертоносною Ґітіісс Мерзенною, Іверрон посилає мандрівників до Діранії Сілвершайн, поки отрута не забрала його життя.",h="«Друг у біді» — відчайдушне прохання про допомогу від Іверрона, юного нічного ельфа, якого в Тінедолі знайшли...",kw={"іверрон","діранія сілвершайн","ґітіісс мерзенна","павук","отрута","тінедол","алдрассил"},ang={["class:Druid"]="Друїди рано засвоюють, що порушена рівновага серед місцевої живності може звалити необережного, — тож нагально треба розуміти отрути природи й протидіяти їм.",["race:NightElf"]="Для юних калдорей, що починають вишкіл під Алдрассилом, біда Іверрона — суворе нагадування: навіть затишне гілля Тінедола більше не вільне від зіпсуття й смертельної небезпеки."},sec={{t="Необачна вилазка",b="Розлогі крони Тінедола дають прихисток усілякій живності, та сусідні заплетені павутинням западини ховають значно темніші загрози. Знехтувавши давніми застереженнями, Іверрон підійшов надто близько до павучих печер і натрапив на Ґітіісс Мерзенну — лютого павука, чия отрута швидко здолала юного ельфа. Його паморочить, сили тануть, і сам він дістатися безпечного місця не здатен."},{t="Поклик до Алдрассила",b="Відчайдушно чіпляючись за життя, Іверрон просить кожного перехожого мерщій бігти назад до центрального дерева Алдрассил і сповістити Діранію Сілвершайн. Діранія, яка звикла наглядати за ним і добре знає небезпеки долини, — його єдина надія на рятівну протиотруту, приготовану перш ніж отрута стане смертельною."}},fp="16,264,18.394.0,19.311.0,15.216.0,22.130.0,27.166.0,33.137.0,60.187.1,47.217.0"}
P.entries["quest:3521"] = {n="Протиотрута Іверрона",s="«Протиотрута Іверрона» — нагальне завдання в Тінедолі: врятувати отруєного розвідника нічних ельфів. Зібравши дикі гриби, лілії та павучий іхор, шукачі пригод допомагають Діранії Сілвершайн зварити ліки, перш ніж отрута візьме своє.",h="«Протиотрута Іверрона» — нагальне завдання в Тінедолі: врятувати отруєного розвідника нічних ельфів.",kw={"протиотрута","іверрон","діранія сілвершайн","гриби","лілії","павуки вебвуда","тінедол"},ang={["class:Druid"]="Виготовлення ліків із місцевої флори й знешкодження природних отрут відображає ту основоположну рівновагу, яку друїди прагнуть зберігати в дикій природі.",["profession:Herbalism"]="Збирання лілій Місячної Пелюстки й гіацинтових грибів показує, якими сильними цілющими властивостями наділені дикі рослини Тельдрассила, якщо поводитися з ними обережно.",["race:NightElf"]="Доглядати полеглих родичів — священний обов'язок у Тінедолі, де кожен захисник потрібен, щоб уберегти молоде Світове Дерево, яке щойно пустило бруньки."},sec={{t="Наввипередки з отрутою",b="Розвідуючи гілля Тінедола, юний Іверрон став жертвою отруйних ікол місцевих павуків Вебвуда. Він упав і помирає, і його життя цілком залежить від знання трав Діранії Сілвершайн в Алдрассилі. Юнак швидко згасає, тож їй треба негайно приготувати особливий відвар, що знешкодить лють отрути, яка біжить його жилами."},{t="Реагенти Тінедола",b="Рецепт Діранії спирається на цілющу флору Тельдрассила, врівноважену самою отрутою. Гіацинтові гриби, що їх полюбляють злодійкуваті ґрелли на півдні, дають землисту основу, а ніжні лілії Місячної Пелюстки з тихих лісових озерець — очисну силу. Щоб завершити відвар, треба добути зразок іхору Вебвуда просто з павуків, які нишпорять біля Печери Тіньової Нитки, — так ліки підлаштують під їхню отруту."}},fp="18,226,20.372.0,22.448.0,15.139.0,39.140.0,40.160.0,35.151.0,31.121.0,38.116.0"}
P.entries["quest:3522"] = {n="Протиотрута Іверрона",s="Це доручення змушує шукача пригод мчати наввипередки з часом, щоб доставити щойно зварені ліки отруєному розвідникові нічних ельфів. Іверрон, що застряг біля кишенної павуками печери в Тінедолі, цілком залежить від трав'яного відвару Діранії Сілвершайн — поки сильнодійна суміш не втратила сили.",h="Це доручення змушує шукача пригод мчати наввипередки з часом, щоб доставити щойно зварені ліки отруєному...",kw={"протиотрута","іверрон","діранія сілвершайн","ліки","павуки вебвуда","тінедол","тельдрассил"},ang={["profession:Herbalism"]="Нестійкість відвару показує, як непросто працювати з сирою лісовою флорою: без належного зберігання рослинні суміші майже миттєво втрачають свої життєдайні властивості.",["race:NightElf"]="Для юних нічних ельфів, які проходять вишкіл у Тінедолі, порятунок Іверрона — тверезе нагадування про дедалі більше зіпсуття й агресію серед корінної живності Тельдрассила."},sec={{t="Наввипередки з годинником",b="Діранія Сілвершайн готує цілющий відвар зі свіжозібраних отруйних залоз, коренів лілій і гіацинтових грибів, але його нестійка алхімічна природа — серйозна небезпека. Ліки зберігають силу всього п'ять хвилин після перегонки. Той, хто несе флакон, має без вагань мчати з галявини просто на північні узвишшя."},{t="Звичка потрапляти в халепу",b="Іверрон став жертвою павуків Вебвуда, що чаяться біля курганів і печер Тінедола. За власним зізнанням, він має прикрий хист устрявати в небезпеку й раз у раз покладається на знання трав Діранії, аби виплутатися з халепи. Навіть випивши протиотруту, він одужує повільно й з осторогою поглядає на ворожих павуків, що досі стережуть його дорогу додому."}},fp="18,291,24.353.0,18.413.0,53.242.0,25.128.0,25.178.0,47.205.1,46.248.0,57.174.0"}
P.entries["quest:354"] = {n="Смерті в родині",s="Коулмен Фартінґ, колишній робітник млина, що нині мешкає в Бріллі, прагне особистої помсти аристократичній родині Аґамандів. Умовлені лишитися й боронити маєтки від Погибелі під час Третьої війни, Фартінґ і його товариші загинули разом зі своїми впертими господарями — а потім Аґаманди повстали безтямними рабами Короля-Ліча.",h="Коулмен Фартінґ, колишній робітник млина, що нині мешкає в Бріллі, прагне особистої помсти аристократичній...",kw={"аґаманди","коулмен фартінґ","помста","млини аґаманда","турман","ґреґор","нісса"},ang={["faction:Horde"]="Знищення очільників Аґамандів усуває небезпечних командирів Погибелі, що чигають надто близько до Брілла й північних підступів до Андерсіті.",["race:Undead"]="Це завдання відображає глибокі особисті образи, які чимало Відступників досі несуть зі смертного життя, — незагоєну травму падіння Лордерону і гіркоту до тих, хто привів їх до загибелі."},sec={{t="Спадок гордині",b="Перш ніж Третя війна спустошила Лордерон, Аґаманди були найбагатшою і найвпливовішою землеробською династією Галявин Тірісфалю. Їхні розлогі млини й родючі пасовища давали щедре зерно, а на них працювали десятки орендарів і мірошників. Коли королівством поповзла Чума Нежиті, Аґаманди відмовилися тікати чи кидати родові володіння, переконані, що кам'яні мури і віддані робітники стримають жахіття, що насувалися зі сходу."},{t="Ціна вірності",b="Повіривши запевненням панів, віддані робітники на кшталт Коулмена Фартінґа лишилися боронити маєток. Оборона виявилася марною проти невпинного натиску Погибелі. Аґамандів та їхніх робітників вирізали, тіла гнили там, де впали, а потім їх підняли в нежитті. Фартінґ зрештою вирвався на волю завдяки визволенню Сильвани Віндраннер, а от патріархи та спадкоємці Аґамандів лишилися в ментальних лещатах Короля-Ліча й блукають зруйнованими млинами безтямними вартовими Погибелі."},{t="Гірка відплата",b="Нині Коулмен Фартінґ мешкає в Бріллі й плекає люту ненависть до колишніх господарів, чия пиха коштувала йому смертного життя. Шукаючи розв'язки й відплати, він посилає поборників Відступників до Млинів Аґаманда — знищити Ґреґора, Ніссу й Турмана Аґамандів. Фартінґ відверто сподівається, що за гнилими личинами його колишні пани зберегли рівно стільки свідомості, щоб відчути жах, коли їхнє нежиття обірветься насильно."}},fp="20,357,17.490.0,20.524.0,18.434.0,27.213.0,41.261.0,35.194.0,47.167.0,32.181.0,49.205.0"}
P.entries["quest:355"] = {n="Поговори зі Севреном",s="Після того як особисті порахунки Коулмена Фартінґа на Млинах Аґаманда зведено, Магістрат Севрен кличе шукача пригод до Брілла. Млини приховують значно більше, ніж злопам'ятних родинних привидів: це жива загроза Погибелі на північному кордоні поселення.",h="Після того як особисті порахунки Коулмена Фартінґа на Млинах Аґаманда зведено, Магістрат Севрен кличе шукача...",kw={"севрен","магістрат","брілл","коулмен фартінґ","млини аґаманда","погибель"},ang={["faction:Horde"]="Брілл — перша лінія оборони Андерсіті; очищення довколишніх полів від Погибелі життєво важливе для влади Орди над північчю Лордерону.",["race:Undead"]="Довівши свою вправність проти безтямної Погибелі, ви швидко здобуваєте визнання у Бріллі: від випадкових доручень — до прямого захисту міста під началом Магістрата Севрена."},sec={{t="Від помсти до громадського обов'язку",b="Коулмен Фартінґ шукав особистої відплати колишнім сусідам — Аґамандам, — посилаючи мандрівників на північ розправитися з нежиттю, що тиняється біля борошняних млинів. Щойно останки було доставлено, Коулмен збагнув: його приватна образа перетинається з ширшою тактичною проблемою. Увесь маєток Аґамандів досі кишить безтямно агресивними прислужниками Погибелі — просто біля порога Брілла."},{t="Поклик магістрата",b="Магістрат Севрен відповідає перед Темною Леді за цивільну та військову безпеку Брілла. Вражений звістками про шукача пригод, здатного вижити в глибоких рейдах населеними привидами полями, Севрен бере справу у свої руки і скеровує ці вмілі руки до самого кореня зарази — стародавнього родинного склепу Аґамандів."}},fp="17,256,28.404.0,21.309.0,55.228.0,37.144.0,38.191.0,51.142.0,59.149.0,45.185.0"}
P.entries["quest:356"] = {n="Тиловий патруль",s="Тиловий патруль — розвідувальна місія від Вартової Смерті Ліннеї для захисту оборони Відступників на східному кордоні Тірісфалю. Вона велить бійцям винищити заблукалі жахіття Погибелі та неспокійних духів, що оселилися на Хуторі Балнірів, перш ніж вони перетнуть лінії постачання Заслону.",h="Тиловий патруль — розвідувальна місія від Вартової Смерті Ліннеї для захисту оборони Відступників на східному...",kw={"тиловий патруль","ліннея","заслон","хутір балнірів","жахіття","духи"},ang={["faction:Horde"]="Утримання східного периметра Тірісфалю гарантує Орді її хистку опору на півночі Східних Королівств проти легіонів нежиті.",["race:Undead"]="Для Відступників захист тилу Заслону — питання виживання; знищення осередку Погибелі на Хуторі Балнірів береже рідні землі від нового захоплення Королем-Лічем."},sec={{t="Прикрити фланг Заслону",b="Заслон — головна перепона, що не дає пошесті й військам Західних Чумних Земель ринути в Галявини Тірісфалю. Вартова Смерті Ліннея відповідає за безпеку тилу на цьому рубежі. Оскільки лінія не може дозволити собі розпорошувати сили на засідки з тилу, будь-яку нежить, що прослизнула повз вузький прохід, слід знищити, перш ніж вона переріже лінії постачання фронту."},{t="Руїни Хутора Балнірів",b="Колись Хутір Балнірів славився на весь Лордерон розведенням добірних королівських скакунів, та під час Третьої війни запався в руїну. Нині геть спустошені зарослі поля й напівзруйновані стайні дають прихисток зайдам — Кровоточивим Жахіттям і неспокійним Мандрівним Духам. Зачистка цього місця позбавляє Короля-Ліча плацдарму в самому Тірісфалі й убезпечує шлях для підкріплень Орди."}},fp="17,315,28.410.0,29.392.0,45.261.0,24.159.0,42.198.0,48.176.0,23.111.0,55.164.0"}
P.entries["quest:358"] = {n="Гробокопи",s="Магістрат Севрен із Брілла доручає шукачам пригод винищити гнилошкірих гнолів в братській могилі на південний захід від Лігва Гаррена. Цих немертвих звірів послала Погибель — викопувати трупи перших жертв чуми, щоб поповнити свої лави. Їхня загибель і здобутий бальзамувальний іхор захищають полеглих і допомагають дослідженням Королівського Аптекарського Товариства.",h="Магістрат Севрен із Брілла доручає шукачам пригод винищити гнилошкірих гнолів в братській могилі на південний...",kw={"гробокопи","гноли","гнила шкура","братська могила","севрен","іхор","лігво гаррена"},ang={["faction:Horde"]="Зрив постачання Погибелі убезпечує північ Лордерону й зміцнює опору Орди проти решток сил Короля-Ліча.",["race:Undead"]="Для Відступників не дати Погибелі підняти колишніх мешканців Тірісфалю означає вберегти полеглих земляків від жахливої долі безтямного рабства."},sec={{t="Осквернення братських могил",b="Коли Чума Нежиті вперше прокотилася Галявинами Тірісфалю, мерці накопичувалися швидше, ніж їх устигали ховати як належить. По всій півночі викопали величезні братські могили, щоб умістити приголомшливі втрати. Донедавна поховані там останки уникали воскресіння. Та тепер Погибель напустила на рови на південний захід від Лігва Гаррена гнилошкірих гнолів, щоб ті ексгумували зотлілі рештки на поповнення армій Короля-Ліча."},{t="Алхімія Погибелі — проти неї самої",b="Гнилошкірих підтримує бальзамувальний іхор — алхімічна суміш, що зберігає й оживлює їхні гниючі тіла. Наказуючи розвідникам убивати гробокопів і добувати цю рідину, Магістрат Севрен завдає двох ударів разом: зупиняє жнива Погибелі на свіжі тіла й доставляє цінні біологічні зразки просто до аптекарів Брілла, які прагнуть обернути ремесло Короля-Ліча проти нього самого."}},fp="12,355,30.448.0,30.421.0,45.211.0,29.196.0,32.111.0,51.197.0,41.146.0,59.167.0"}
P.entries["quest:360"] = {n="Повернення до магістрата",s="«Повернення до магістрата» завершує термінову розвідувальну естафету між східним кордоном Галявин Тірісфалю і містечком Брілл. Доповівши Вартовій Смерті Ліннеї на її заставі на схід від Брілла, шукачі пригод вирушають назад — доставити тривожні вісті просто Магістратові Севрену. Послання підтверджує: безтямні прислужники Короля-Ліча й далі промацують кордони молодої нації Відступників.",h="«Повернення до магістрата» завершує термінову розвідувальну естафету між східним кордоном Галявин Тірісфалю і...",kw={"магістрат","севрен","ліннея","заслон","брілл","донесення","погибель"},ang={["faction:Horde"]="Опора Орди у Східних Королівствах тримається на стабільності Галявин Тірісфалю, тож оборона Заслону критично важлива проти жахіть нежиті з Чумних Земель.",["race:Undead"]="Везучи відомості від Заслону, ви на власні очі бачите, якою хисткою є свобода Відступників: господар, від якого ви втекли, досі шкребеться в поріг вашого нового дому."},sec={{t="Вісті з рубежу",b="Східна дорога з Галявин Тірісфалю веде просто у Західні Чумні Землі — спустошені руїни, де безроздільно панує Погибель. Щоб орди нежиті не ринули на щойно відвойовану батьківщину, Відступники звели Заслон — укріплений пропускний пункт, за яким із тилової застави пильнують похмурі вартові на кшталт Вартової Смерті Ліннеї. Зібравши відомості про те, що тисне на східні ворота, Ліннея відсилає гінців щодуху на захід Королівським трактом до Брілла, перш ніж ворожі лазутчики скористаються будь-якою прогалиною."},{t="Обітниця Севрена",b="Коли Магістрат Севрен отримує донесення у Бріллі, воно підтверджує його найгірші побоювання: розвідники Погибелі знаходять шляхи в обхід чи крізь передовий периметр. Для Відступників кожен повзучий гуль і безтямний скелет — не просто військова прикрість, а нагадування про рабство, з якого вони вирвалися під час падіння Лордерону. Севрен непохитний: хай яким невпинним стане натиск Короля-Ліча, вільна нежить ніколи не зречеться своєї новоздобутої волі."}},fp="24,413,16.569.0,12.492.0,33.229.0,51.255.0,25.217.0,20.211.0,45.238.0,35.160.0"}
P.entries["quest:361"] = {n="Недоставлений лист",s="Вицвіле, заплямоване кров'ю послання, знайдене серед кістяних руїн Млинів Аґаманда, адресоване Іветт Фартінґ. Воно відкриває трагічне прощання двох закоханих у дні, коли Погибель котилася Лордероном, і дає зазирнути в те, що Відступники лишили позаду, обмінявши життя на нежиття.",h="Вицвіле, заплямоване кров'ю послання, знайдене серед кістяних руїн Млинів Аґаманда, адресоване Іветт Фартінґ.",kw={"лист","іветт фартінґ","турман аґаманд","кохання","млини аґаманда","таверна","брілл"},ang={["faction:Horde"]="Для мандрівників, що відвідують Брілл, цей віднайдений пергамент — наочний приклад емоційної відстороненості, яка визначає народ Відступників.",["race:Undead"]="Лист утілює гострий, болючий розрив між смертними спогадами Відступників та їхнім холодним, підпорядкованим меті існуванням під рукою Королеви Баньші."},sec={{t="Послання, загублене в падінні",b="Цей невідправлений пергамент написав Турман Аґаманд, старший син патріарха Ґреґора Аґаманда, і він так і не дійшов до адресатки, перш ніж родинний маєток обернувся на руїну. Коли Чума Нежиті поглинула Галявини Тірісфалю, Турман відмовився покинути рідну домівку й рідню. Серед жахіть навали він узявся за перо, щоб написати останнє послання Іветт Фартінґ, яку кохав, доки королівство не обернулося на попіл."},{t="Розірваний зв'язок",b="Коли лист нарешті потрапляє до рук Іветт Фартінґ у Таверні «Шибеничний Кінець» у Бріллі, він викликає короткий, болісний спалах пам'яті. Вона згадує, як благала Турмана тікати з Млинів Аґаманда разом із нею та її батьком, і нарікає, що брат Турмана, Бренд, тримав на нього зло. Та тепло швидко згасає. Як і багато хто з Відступників, Іветт гартує серце, відкидає смертний жаль і оголошує, що коханню немає місця в її новому існуванні."}},fp="20,283,26.434.0,16.473.1,22.185.0,23.194.0,31.138.0,41.188.0,46.218.1,21.153.0"}
P.entries["quest:362"] = {n="Прокляті млини",s="Коулмен Фартінґ із Брілла прагне помститися колишнім землевласникам, Аґамандам, зібравши й знищивши їхні неспокійні немертві рештки. Це завдання веде вас на північ, до Млинів Аґаманда, — упокоїти Девліна Аґаманда, гострого на язик молодшого сина маєтку. Так починається гірка вендета проти родини, що не вберегла простий люд Тірісфалю від Чуми.",h="Коулмен Фартінґ із Брілла прагне помститися колишнім землевласникам, Аґамандам, зібравши й знищивши їхні...",kw={"прокляті млини","девлін аґаманд","коулмен фартінґ","млини аґаманда","вендета","брілл"},ang={["faction:Horde"]="Допомагати Відступникам у Тірісфалі означає допомагати їм викорінювати небезпечні осередки Погибелі з околиць Брілла й Андерсіті.",["race:Undead"]="Це завдання відображає глибокі станові образи, що пережили падіння Лордерону: Відступники зберігають смертні порахунки зі шляхетними землевласниками, які не вберегли їх від Чуми."},sec={{t="Гіркі жнива",b="До Третьої війни Млини Аґаманда були житницею північного Тірісфалю і належали заможній поміщицькій родині. Коли Погибель прокотилася Лордероном, прості люди шукали в шляхетних землевласників захисту — і не знайшли ні прихистку, ні порятунку. Коулмен Фартінґ вижив у нежитті, та серце його досі з'їдає ненависть до родини, якій він служив. Замість лишити їх блукати у вічних муках, Фартінґ прагне моторошної втіхи: зібрати їхні кістки й осквернити їх під власним каблуком."},{t="Молодший брат",b="Девлін Аґаманд був молодшим братом Турмана Аґаманда. За життя Девліна пам'ятали як кволого, злостивого та в'їдливого юнака — повну протилежність лагідному старшому братові. Коли Чума Нежиті підповзла до маєтку, Девлін одним із перших став жертвою скверни. Тепер, позбавлений і того крихкого розуму, що мав за життя, його безтямний труп невгамовно белькоче на північній дорозі, яка веде до родинних млинів."}},fp="17,376,16.522.0,19.471.0,48.283.0,34.162.0,39.191.0,42.174.0,46.184.0,47.147.1"}
P.entries["quest:363"] = {n="Грубе пробудження",s="Грубе пробудження — перше завдання для щойно пробуджених Відступників у склепах Похоронного Подзвону. Повставши зі смерті вільними від залізної хватки Короля-Ліча, ви отримуєте наказ відійти від печей для спалення і спуститися з пагорба, щоб дізнатися правду про своє нове існування від Жерця Тіні Сарвіса.",h="Грубе пробудження — перше завдання для щойно пробуджених Відступників у склепах Похоронного Подзвону.",kw={"грубе пробудження","похоронний подзвін","мордо","сарвіс","склеп","нежиття"},ang={["class:Priest"]="Жрець Тіні Сарвіс, до якого ви з'являєтеся, одразу знайомить вас із Культом Забутої Тіні, який переосмислює духовну відданість після нежиття.",["faction:Horde"]="Це пробудження вводить вас у хистку орбіту Орди — союзу, народженого з чистої необхідності перед лицем спільного винищення.",["race:Undead"]="Ця мить визначає ваше відродження: скинути кайдани Погибелі й вибороти собі злостиве, вільне існування серед Відступників."},sec={{t="Могильний початок",b="Розплющити очі в сирому підземному холоді склепу Похоронного Подзвону — тривожне знайомство з нежиттям. Гробар Мордо пильнує над щойно похованими, сортуючи воскреслих на тих, хто повернув собі вільну волю, і тих, кому судилася вогняна яма. Для багатьох повстати з могили означає прокинутися до гнилі, холодного каменю й цілковитої розгубленості, вислизнувши з хватки Погибелі лише волею випадку."},{t="Розірвати хватку Крижаного Трону",b="Перш ніж дістатися каплиці, щойно пробуджені мерці мають усвідомити похмуру правду: колись вони були безтямними знаряддями Короля-Ліча. Саме Леді Сильвана Віндраннер зламала те психічне рабство, дозволивши решткам колишньої людяності повернути собі самостійну думку. Вийти з гробниці й спуститися до Похоронного Подзвону — перший крок у світ, де і живі, і Погибель бачать у вас мерзоту, яку треба знищити."}},fp="14,297,17.438.0,38.437.0,21.234.0,24.224.0,52.222.0,32.260.0,38.192.0,38.215.0"}
P.entries["quest:364"] = {n="Безтямні",s="Жрець Тіні Сарвіс доручає щойно пробудженим Відступникам винищити Безтямних Зомбі та Жалюгідних Зомбі, які блукають північними околицями Похоронного Подзвону. Ці шкандибаючі трупи — раби Погибелі, позбавлені вільної волі й цілковито підвладні наказам Короля-Ліча.",h="Жрець Тіні Сарвіс доручає щойно пробудженим Відступникам винищити Безтямних Зомбі та Жалюгідних Зомбі, які...",kw={"безтямні","зомбі","сарвіс","похоронний подзвін","нер'зул","крижаний трон"},ang={["class:Priest"]="Служба під началом Жерця Тіні Сарвіса знайомить вас із прагматичною, забарвленою Тінню філософією, яку Відступники прийняли замість Святого Світла, що їх покинуло.",["faction:Horde"]="Існування таких рабів пояснює, чому Орда дивилася на Відступників з такою глибокою підозрою, перш ніж прийняти їх до своїх лав.",["race:Undead"]="Кожен зомбі на околицях села міг за життя бути вашим сусідом, родичем чи другом — живе нагадування про те, чого ви уникли, і про те, що станеться, якщо Відступники впадуть."},sec={{t="Раби Крижаного Трону",b="Не всі, хто повстає з лордеронської землі, повертають собі розум. Відступники скинули ментальне панування Нер'зула, коли його сила ослабла, та незліченні трупи лишаються порожніми оболонками, прикутими до його волі. На півночі Похоронного Подзвону ці Безтямні та Жалюгідні Зомбі тиняються без жодної мети, крім сліпого насильства. Для новопіднятої нежиті упокоїти їх — перше гірке випробування існування: довести власну волю, розірвавши ланцюги тих, хто так і не вирвався."},{t="Милосердя через знищення",b="Жрець Тіні Сарвіс шкодує, що ці незліченні легіони мерців не можна залучити до відчайдушної боротьби Відступників, та зцілити їх неможливо. Безтямна нежить — назавжди зламані знаряддя різанини. Лишити їх блукати означає запросити хаос до порога Похоронного Подзвону й подарувати Королю-Лічу легку поживу. Їх знищення — і тактична необхідність, і акт похмурого завершення для полеглого народу Лордерону."}},fp="17,262,27.477.0,25.437.0,62.279.0,33.243.0,56.225.0,60.214.0,48.185.0,31.204.0"}
P.entries["quest:365"] = {n="Поля скорботи",s="Поля скорботи — раннє завдання Відступників від Вартового Смерті Сіммера на дорозі на північ від Похоронного Подзвону. Воно велить новакам здійснити наліт на хутір живих людей і зібрати тірісфальські гарбузи для Королівського Аптекарського Товариства у Бріллі.",h="Поля скорботи — раннє завдання Відступників від Вартового Смерті Сіммера на дорозі на північ від Похоронного...",kw={"поля скорботи","гарбузи","сіммер","йогаан","аптекарське товариство","хутір","наліт"},ang={["faction:Horde"]="Щоб убезпечити Галявини Тірісфалю, треба зламати залишкову присутність людей і підірвати вплив Багряного Хрестового Походу вздовж південних доріг.",["profession:Herbalism"]="Аптекарі покладаються на покручену флору Тірісфалю, творячи свої смертоносні суміші, тож кожен місцевий корінець і плід — реагент війни.",["race:Undead"]="Це завдання — ваше перше бойове доручення за межами Похоронного Подзвону; воно доводить вашу готовність позбавити колишніх смертних родичів засобів до існування заради Королівського Аптекарського Товариства."},sec={{t="Урок виживання",b="Для нових шукачів пригод із Відступників, щойно піднятих зі склепів Похоронного Подзвону, перший крок на туманні дороги Галявин Тірісфалю — негайний урок ворожості. Вартовий Смерті Сіммер утілює прагматичну злобу сил Сильвани Віндраннер: вижити означає відбирати те, чим володіють живі, і спрямовувати це на темні справи Андерсіті."},{t="Наліт на живих",b="Ціль нальоту — смертні селяни-люди, що намагаються обробляти спустошену землю на захід від дороги, на північ від Похоронного Подзвону. Вартовий Смерті каже, що вони заполонили край, як пліснява труп; ці селяни чіпляються за свої обійстя під непевним захистом сусідніх веж, які тримає Багряний Хрестовий Похід. Викрадення їхнього врожаю — злісний удар по їхніх запасах і водночас пожива для нескінченного попиту Королівського Аптекарського Товариства на реагенти."},{t="Припаси для Товариства",b="Викрадені гарбузи доставляють просто до Аптекаря Йогаана, який проводить експериментальні дослідження у Бріллі. Королівське Аптекарське Товариство часто бере місцеві плоди й трави за основу для алхімічних варив, отрут і досліджень чуми, покликаних зміцнити хистку опору Відступників на півночі Лордерону."}},fp="15,240,20.345.0,18.441.0,24.328.1,36.150.0,38.113.0,55.243.0,41.195.0,31.164.0,33.241.0"}
P.entries["quest:366"] = {n="Повернути книгу",s="Бетор Айсшард зачаровує викрадену книгу заклять Ґунтера Аркануса, щоб довести власну свободу і залучити колишнього колегу з Кірін-Тору до справи Відступників. Повернення фоліанта на острівний прихисток Ґунтера відкриває: жоден із колишніх чарівників не є рабом Короля-Ліча.",h="Бетор Айсшард зачаровує викрадену книгу заклять Ґунтера Аркануса, щоб довести власну свободу і залучити...",kw={"повернути книгу","бетор айсшард","ґунтер арканус","кірін-тор","озеро світлої води","книга заклять"},ang={["class:Mage"]="Цей обмін підкреслює глибокі зв'язки між колишніми магами Кірін-Тору, які й крізь завісу нежиття впізнають неповторні магічні підписи одне одного.",["faction:Horde"]="Залучення незалежних чаклунів-нежиті на кшталт Ґунтера зміцнює магічну силу Андерсіті проти Погибелі й Багряного Хрестового Походу.",["race:Undead"]="Доля Ґунтера віддзеркалює засадничу боротьбу Відступників: прокинутися від кошмару безтямного рабства — лише щоб опинитися в самотньому, ворожому світі."},sec={{t="Послання таємним чорнилом",b="Дізнавшись, що відступник-некромант на Озері Світлої Води — його давній товариш Ґунтер Арканус, Бетор Айсшард вигадав дотепний спосіб зв'язку. Раніше він наказав викрасти книгу заклять Ґунтера, щоб установити особу некроманта; тепер Бетор вплітає в її сторінки хитромудрі чари. Це не вимога й не збройні перемовини — зачарування слугує магічним підписом і доводить, що Бетор не лише діє в Лордероні, а й цілком вільний від ментального ярма Короля-Ліча."},{t="Давнє коло Даларана",b="До того як Третя війна спустошила Лордерон, Бетор Айсшард, Ґунтер Арканус і Тул Рейвенклов разом учились і дружили в Кірін-Торі в Даларані. Усі троє впали жертвами жахіть Чуми, та в смерті їхні шляхи різко розійшлися. Тул прийняв Погибель і досі служить Королю-Лічу, а Бетор вирвався на волю разом із королевою Сильваною. Бетор вважав Ґунтера мертвим або поневоленим, тож відкриття, що той теж здобув нежиття з власною волею, спонукало його негайно спробувати залучити друга до Відступників."},{t="Недовіра на острові",b="Коли до Ґунтера навідуються на його самотній острів, він спершу вибухає люттю, вважаючи кожного, хто ступив на Озеро Світлої Води, агентом Погибелі, що прийшов знову його поневолити, або злодієм, який пограбував його магію. Вигляд власного гримуара, пройнятого знайомим магічним відлунням Бетора, заскочує відлюдного мага зненацька. Усвідомлення, що хтось із його смертного минулого розірвав кайдани Погибелі, змушує Ґунтера переглянути свою цілковиту самоізоляцію."}},fp="15,264,23.517.0,25.541.0,22.469.1,43.260.0,39.214.0,42.244.0,23.240.0,45.256.0,43.282.1"}
P.entries["quest:367"] = {n="Нова чума",s="Нова чума — вступне завдання у Бріллі, яке відкриває головну стратегічну амбіцію Відступників. Аптекар Йогаан доручає новобранцям зібрати кров диких темних гончаків, щоб закласти основу для згубного збудника, замовленого особисто Леді Сильваною Віндраннер.",h="Нова чума — вступне завдання у Бріллі, яке відкриває головну стратегічну амбіцію Відступників.",kw={"нова чума","йогаан","темні гончаки","кров","аптекарське товариство","брілл","сильвана"},ang={["faction:Horde"]="Хоч Відступники й приєдналися до Орди, їхні алхімічні зусилля у Тірісфалі цілком зосереджені на похмурій біологічній зброї, націленій на Нортренд.",["race:Undead"]="Це завдання — ваш перший прямий внесок у головний проєкт Королівського Аптекарського Товариства: створення зброї, яку Сильвана планує обернути проти Артаса."},sec={{t="Королівський наказ",b="У вогкому селищі Брілл Аптекар Йогаан працює від імені Королівського Аптекарського Товариства за прямим наказом Темної Леді. Сильвана Віндраннер доручила своїм алхімікам створити хворобу, якої Азерот ще не бачив. Якщо первісна чума нежиті служила Королю-Лічу, винищуючи людство й сковуючи душі, то це нове творіння призначене саме для того, щоб знищити Артаса Менетіла й спустошити легіони його Погибелі."},{t="Сировина",b="Створення біологічної зброї, здатної знищувати нежить, вимагає похмурих експериментів. Йогаан вірить, що кров місцевих звірів — передусім лютих темних гончаків, які нишпорять у мороці Галявин Тірісфалю, — має важливі хімічні властивості. Збираючи склянки цієї зараженої звіриної крові, Йогаан починає виділяти складники, щоб перевірити, чи може природна витривалість і хижацька біологія місцевих істот стати каталізатором смертельної зарази."}},fp="12,280,15.467.0,15.451.0,35.200.0,25.185.0,37.199.0,54.223.0,40.179.0,39.187.0"}
P.entries["quest:368"] = {n="Нова чума",s="За дорученням Аптекаря Йогаана з Брілла треба зібрати луску мурлоків Темноплавців, що нишпорять узбережжям Тірісфалю. Королівське Аптекарське Товариство прагне використати унікальні біологічні реагенти, щоб удосконалити свою нову заразу — аби вона поширювалася не на поодиноких жертв, а охоплювала цілі народи.",h="За дорученням Аптекаря Йогаана з Брілла треба зібрати луску мурлоків Темноплавців, що нишпорять узбережжям...",kw={"нова чума","мурлоки","мерзенний плавець","луска","йогаан","узбережжя","зараза"},ang={["faction:Horde"]="Хоч аптекарі Відступників відкрито варять свої темні суміші в Галявинах Тірісфалю, справжня мета й сила чуми — делікатна тема, яку здебільшого замовчують перед менш безжальними союзниками з Орди.",["race:Undead"]="Для Відступників допомога Аптекарю Йогаану — прямий внесок у головну зброю і захист їхньої раси: створення смертоносної чуми, покликаної захистити їхнє суверенне королівство і знищити ворогів."},sec={{t="Розмах зарази",b="Отруїти одну ціль — проста алхімія, та щоб вивести чуму, здатну прокотитися цілими землями, потрібні складніші компоненти. Поточні дослідження Аптекаря Йогаана у Бріллі тримаються на створенні хвороби, яка сама себе поширює і живе в дикій природі. Щоб досягти такої заразності, він звертає увагу на прибережну живність Галявин Тірісфалю і бачить у витривалій біології мурлоків Темноплавців перспективне джерело сировини."},{t="Реагенти Темноплавців",b="Північне й західне узбережжя Галявин Тірісфалю заполонили агресивні племена мурлоків, відомі як Темноплавці. Їхня луска дає Йогаану органічні сполуки, пристосовані до вологих, суворих умов. Додаючи слизьку, стійку луску мурлоків до свого казана, аптекар сподівається посилити згубність і стійкість у довкіллі нової чуми Королівського Аптекарського Товариства."}},fp="12,324,24.478.0,21.415.0,49.271.0,48.303.0,40.162.0,37.170.0,42.194.0,52.205.0"}
P.entries["quest:369"] = {n="Нова чума",s="У Бріллі Аптекар Йогаан зосереджується на створенні потужного нового біологічного агента для Відступників. Вивчаючи стародавні тексти, він з'ясовує, що давня смертоносна чума вціліла в отруті павуків нічної павутини зі сходу Тірісфалю, — і це спонукає до термінової вилазки по зразки.",h="У Бріллі Аптекар Йогаан зосереджується на створенні потужного нового біологічного агента для Відступників.",kw={"нова чума","павуки","отрута","долина отруйного павутиння","йогаан","давня пошесть"},ang={["faction:Horde"]="Дослідники Відступників радо приймають допомогу союзників-орків і тауренів, та нутряна природа їхніх біологічних експериментів нерідко бентежить решту Орди.",["race:Undead"]="Для Відступників власна оригінальна зброя — єдина тривка запорука безпеки проти невпинних недобитків Погибелі й багряних хрестоносців біля самого порога."},sec={{t="Розкопуючи давні зарази",b="Працюючи над алхімією для Королівського Аптекарського Товариства у Бріллі, Аптекар Йогаан перериває старі фоліанти в пошуках смертоносніших сумішей. Він знаходить записи про стародавню пошесть, що колись забрала тисячі життів. І головне: тексти вказують, що смертельний збудник пережив покоління, причаївшись у місцевих павуках Галявин Тірісфалю, тож їхня отрута — безцінний біологічний реагент."},{t="Полювання в Долині Отруйного Павутиння",b="Щоб роздобути життєздатний зразок збудника, Йогаан скеровує агентів на схід Галявин Тірісфалю. На південь від Багряного Монастиря лежить Долина Отруйного Павутиння — оповита туманом улоговина, що кишить лютими павуками нічної павутини. Збирачам доводиться лізти в їхні лігва, щоб добути свіжі отруйні залози — останній інгредієнт, потрібний, щоб довершити експериментальне вариво Йогаана."},{t="Остаточна формула",b="Отримавши здобуту отруту, Йогаан додає її до киплячого казана разом із зібраними раніше реагентами. Коли суміш уварено й підготовлено, заразний складник від павуків довершує сполуку, наближаючи Королівське Аптекарське Товариство ще на крок до польових випробувань."}},fp="12,290,29.416.0,25.374.0,29.310.1,45.238.0,44.104.0,65.174.0,25.203.0,42.163.1,49.187.0"}
P.entries["quest:37"] = {n="Знайди зниклих стражників",s="«Знайди зниклих стражників» — розслідування, яке доручає Вартовий Томас біля східного мосту в Лісі Елвінн. Вартові Рольф і Малакай, послані патрулювати береги річки від мурлоків, зникли, і Томасу відчайдушно потрібно дізнатися про їхню долю.",h="«Знайди зниклих стражників» — розслідування, яке доручає Вартовий Томас біля східного мосту в Лісі Елвінн.",kw={"зниклі стражники","вартовий томас","рольф","малакай","мурлоки","озеро кам'яного кургану","медальйон"},ang={["class:Paladin"]="Ушанувати полеглих захисників і повернути їхні особисті знаки — означає дати спокій і справедливість солдатам, що стережуть кордони королівства.",["faction:Alliance"]="Гірка втрата піхотинців так близько від Стормвінда підкреслює, якими вразливими перед нападами звірів і мурлоків стали зовнішні кордони Елвінну."},sec={{t="Зниклий патруль",b="Вартовий Томас несе варту на східній переправі Лісу Елвінн, де королівський тракт підходить до Редріджу. Місцеві води стають дедалі небезпечнішими через вторгнення мурлоків. Кілька днів тому Томас послав двох вартових Стормвінда, Рольфа й Малакая, на північ уздовж берегів — розвідати загрозу й зачистити кубла. Коли жоден із солдатів не повернувся, Томасу довелося визнати, що їхню місію обірвало щось жорстоке."},{t="Похмура знахідка",b="Шлях уздовж річки на північ, до берегів Озера Кам'яного Кургану, веде просто в край, що кишить мурлоками. Біля самої води шукачі пригод натрапляють на моторошну картину: напівз'їдене тіло, покинуте в багнюці. Поруч із понівеченими рештками лежить гравірований медальйон з іменем піхотинця Малакая Стоуна — він підтверджує похмуру долю одного з вартових, тоді як місцеперебування Рольфа лишається невідомим."}},fp="20,276,17.435.0,14.405.1,47.161.0,27.149.0,28.162.1,20.112.1,22.144.1,35.178.0"}
P.entries["quest:370"] = {n="У війні з Багряним хрестовим походом",s="Екзекутор Зиґанд посилає поборників Відступників убити Капітана Перріна та його гарнізон у зруйнованій вежі на південний захід від Брілла. Спираючись на відомості, здобуті в Похоронному Подзвоні, Відступники прагнуть відкинути ревних хрестоносців, що загрожують їхнім кордонам.",h="Екзекутор Зиґанд посилає поборників Відступників убити Капітана Перріна та його гарнізон у зруйнованій вежі...",kw={"багряний хрестовий похід","зиґанд","капітан перрін","вежа","брілл","фанатики"},ang={["faction:Horde"]="Опора Орди у Східних Королівствах тримається на тому, чи зуміють Відступники захистити Галявини Тірісфалю від ворожих людських фанатиків.",["race:Undead"]="Для Відступників знищення Багряного Хрестового Походу — питання існування: фанатики не розрізняють вільну нежить і Погибель."},sec={{t="Відомості в ділі",b="Документи, які Екзекутор Аррен відбив у Багряного Хрестового Походу в Похоронному Подзвоні, розкрили активні пересування військ по Галявинах Тірісфалю. Замість чекати, поки фанатики підуть у наступ на щойно укріплений Брілл, Екзекутор Зиґанд використовує захоплені відомості для упереджувальних ударів по їхніх польових командирах."},{t="Загроза в зруйнованій вежі",b="Розташувавшись у напівзруйнованій сторожовій вежі на південний захід від Брілла, Капітан Перрін командує загоном Багряних Фанатиків і Місіонерів. Із цієї позиції Хрестовий Похід намагається стежити за пересуваннями Відступників і поширювати свій вплив углиб Тірісфалю, тож смерть Перріна критично важлива для захисту молодого королівства Темної Леді."}},fp="31,261,23.348.0,30.322.0,23.195.0,58.176.0,53.254.0,62.220.0,58.188.0,23.179.0"}
P.entries["quest:371"] = {n="У війні з Багряним хрестовим походом",s="Ця військова операція доручає захисникам Відступників ударити по табору Багряного Хрестового Походу біля Хутора Балнірів на південному сході Галявин Тірісфалю. За наказом Екзекутора Зиґанда гравці знищують Капітана Вашона та його ченців, щоб зупинити рейди хрестоносців, які загрожують володінням Темної Леді.",h="Ця військова операція доручає захисникам Відступників ударити по табору Багряного Хрестового Походу біля...",kw={"багряний хрестовий похід","капітан вашон","зиґанд","хутір балнірів","ченці","рейди"},ang={["class:Priest"]="Сутичка з Багряними Ченцями зіштовхує вашу владу над Тінню та викривленою святою силою з догматичним, непохитним фанатизмом людей.",["faction:Horde"]="Знешкодження багряних фанатиків тримає підступи до Андерсіті відкритими й убезпечує шляхи зв'язку Орди через північ Лордерону.",["race:Undead"]="Кожен зачищений пост хрестоносців довкола Галявин Тірісфалю убезпечує кордони вашої новонародженої нації і захищає володіння Леді Сильвани від живих «очищувачів»."},sec={{t="Загроза, що насувається",b="Поки Відступники намагаються убезпечити периметр довкола Брілла й Андерсіті, Багряний Хрестовий Похід тримає укріплені осередки по всій окрузі. Донесення, що стікаються до міста від Екзекутора Аррена, попереджають командування про вилазки хрестоносців із напівзруйнованої сторожової вежі на південному сході Галявин Тірісфалю — зовсім поруч лежить покинутий Хутір Балнірів."},{t="Розірвати ланцюг командування",b="Розуміючи, що розрізнені фанатики куди менш небезпечні за злагоджені загони, Екзекутор Зиґанд зосереджує удар на їхньому польовому керівництві. Знищивши Капітана Вашона разом із Багряними Ченцями, які підтримують його людей святою магією, Відступники прагнуть зламати злагодженість цього осередку й придушити рейди людей на сусідні землі Відступників."}},fp="31,311,22.384.0,29.365.0,23.197.0,32.149.0,60.235.0,48.217.0,61.221.0,43.184.0"}
P.entries["quest:372"] = {n="У війні з Багряним хрестовим походом",s="Ця місія — вершина ранньої кампанії Екзекутора Зиґанда за безпеку Галявин Тірісфалю від вторгнень Багряного Хрестового Походу. Діючи з Брілла, агенти Відступників отримують наказ ударити просто по Капітану Мелрашу та його особистому авангарду у зруйнованій сторожовій вежі за Спочинком Фаола.",h="Ця місія — вершина ранньої кампанії Екзекутора Зиґанда за безпеку Галявин Тірісфалю від вторгнень Багряного...",kw={"багряний хрестовий похід","капітан мелраш","зиґанд","спочинок фаола","вежа","авангард"},ang={["class:Rogue"]="Пробратися глибоко в тил ворога й відрізати командира від його війська — квінтесенція роботи Скрадачів Смерті.",["faction:Horde"]="Захист периметра Тірісфалю оберігає вразливу опору Орди у Східних Королівствах.",["race:Undead"]="Для Відступників кожен убитий хрестоносець — на одного фанатика менше з тих, хто заперечує їхнє право існувати на землі, де вони жили за життя."},sec={{t="Удар по авангарду",b="Поки Відступники зміцнюють владу над руїнами Лордерону, Багряний Хрестовий Похід невпинно промацує кордони Тірісфалю. Зі сторожової вежі на узвишші в північному Тірісфалі, за Спочинком Фаола, ревні хрестоносці споряджають рейдові загони проти патрулів і земель Відступників. Замість чекати на черговий напад, Екзекутор Зиґанд обирає обезголовлення: знищити командну структуру, що керує місцевими рейдами."},{t="Твердиня Капітана Мелраша",b="Цим північним табором командує Капітан Мелраш — безкомпромісний офіцер, якого невідступно супроводжують двоє присяжних охоронців. Позиція Мелраша дає Хрестовому Походу огляд прибережних доріг і довколишніх лісів. Його смерть ламає узгодженість дій хрестоносців поблизу Брілла, усуває пряму загрозу молодому королівству Леді Сильвани й відкидає фанатиків до їхніх міцніших укріплень далі на схід."}},fp="31,296,24.448.0,23.443.0,24.239.0,34.157.0,44.236.0,60.234.0,62.196.0,20.205.0"}
P.entries["quest:374"] = {n="Доказ загибелі",s="Доказ загибелі — військова директива Вартового Смерті Берджесса у Бріллі, покликана прорідити лави Багряного Хрестового Походу в Галявинах Тірісфалю. Започаткована за наказом Варіматраса, жахолорда-заступника Сильвани Віндраннер, вона перевіряє вірність солдата справі Відступників. Новобранцям наказано знімати персні-печатки з полеглих хрестоносців як речовий доказ різанини.",h="Доказ загибелі — військова директива Вартового Смерті Берджесса у Бріллі, покликана прорідити лави Багряного...",kw={"доказ загибелі","берджесс","варіматрас","персні","багряний хрестовий похід","жахолорд"},ang={["faction:Horde"]="Це завдання показує безжальну настанову на тотальну війну, властиву режиму Сильвани на півночі, — настанову, яку почасти визначає жахолорд Варіматрас.",["race:Undead"]="Для Відступників кожен перстень хрестоносця, принесений до Брілла, — на одного фанатика менше з тих, хто присягнув очистити Лордерон від вільної нежиті."},sec={{t="Наказ жахолорда",b="Кампанія на півночі Галявин Тірісфалю — не просто оборона; це злагоджена війна на винищення. Варіматрас, жахолорд, що здався й присягнув клинком Сильвані Віндраннер, керує багатьма наступальними операціями Відступників проти живих. Його директиви спускаються до командирів на кшталт Екзекутора Зиґанда й передових офіцерів, як-от Вартового Смерті Берджесса. Берджесс висловлюється прямо: людський рід — паразити, яких слід вичистити з Лордерону, а ревні хрестоносці поблизу — найближча ціль."},{t="Трофеї різанини",b="Самих слів командирам у Бріллі замало. Щоб довести послух Темній Леді та її заступнику, солдати мають знімати Багряні Персні-Відзнаки просто з пальців убитих фанатиків. На цих перснях — знаки, якими Багряний Хрестовий Похід таврує своїх: вони позначають власників як присяжних ворогів Відступників. Жменя таких трофеїв — неспростовний доказ мертвих хрестоносців і демонстрація безкомпромісної вірності."}},fp="15,380,28.552.0,19.449.0,44.188.0,60.252.0,43.285.0,54.187.0,50.270.0,65.325.0"}
P.entries["quest:375"] = {n="Холод смерті",s="У містечку Брілл кравчиня з Відступників на ім'я Ґретхен Дедмар бореться з повзучим холодом смертності й тління. Боячись, що безтямність, яка насувається, позбавить її змоги служити Леді Сильвані, вона просить простих матеріалів, щоб пошити собі теплу ковдру.",h="У містечку Брілл кравчиня з Відступників на ім'я Ґретхен Дедмар бореться з повзучим холодом смертності й...",kw={"холод смерті","ґретхен дедмар","кравчиня","ковдра","сутінкові кажани","брілл"},ang={["profession:Tailoring"]="Ґретхен покладається на скромне шиття: вона шила мішки для тіл для армії Сильвани, перш ніж узятися голкою за просту ковдру зі шкурок.",["race:Undead"]="Боротьба Ґретхен — похмуре нагадування для всіх Відступників: звільнення від Короля-Ліча не захищає ні від тілесної гнилі, ні від постійної загрози безтямності."},sec={{t="Повзуча паморозь",b="Для Відступників нежиття — не застиглий стан вічної збереженості. Як каже Ґретхен Дедмар, залишкова Чума Нежиті в'ється її тілом крижаною змією, висмоктує тепло з кінцівок і загрожує затягнути її в ту безтямність, яка вразила стількох блукаючих трупів у Галявинах Тірісфалю. Її тремтливі руки роблять звичайну роботу майже неможливою."},{t="Служба Темній Леді",b="Попри згасання сил, Ґретхен відмовляється облишити свій обов'язок перед королівством Відступників. Коли Сильвана Віндраннер уперше згуртувала звільнених мерців, Ґретхен долучилася тим, що шила савани й мішки для тіл полеглих солдатів. Зібравши міцні шкурки сутінкових кажанів і грубу нитку, мандрівники допомагають їй утримати руки досить твердими, щоб пошити ковдру і продовжити корисну службу справі Відступників."}},fp="18,278,16.386.0,24.401.0,23.174.0,44.231.0,43.190.0,43.180.0,28.92.0,53.146.0"}
P.entries["quest:376"] = {n="Проклятий",s="Проклятий — раннє завдання, яке щойно пробудженим Відступникам дає Послушниця Елрет у каплиці Похоронного Подзвону. В обмін на матеріали для грубого одягу й польових пов'язок Елрет видає вцілілу броню, щоб захистити молоду нежить від небезпек довкола цвинтаря.",h="Проклятий — раннє завдання, яке щойно пробудженим Відступникам дає Послушниця Елрет у каплиці Похоронного...",kw={"проклятий","елрет","броня","шкури","сутінкові кажани","похоронний подзвін"},ang={["profession:Tailoring"]="Послушниця Елрет наочно показує жорстоку необхідність польового кравецтва в Лордероні, де перетинки крил і здерті шкури заміняють чисте полотно.",["race:Undead"]="Для свіжих Відступників це завдання — рання демонстрація похмурої практичності їхнього народу: вижити означає знімати спорядження з полеглих попередників і жити з того, що дає спустошена земля."},sec={{t="Прагматичний обмін",b="Пробудження в нежитті не лишає місця ні марнославству, ні сентиментам. Послушниця Елрет, чий наставник — Жрець Тіні Сарвіс, дбає про безперервний потік свіжих Відступників, витягнутих із землі Похоронного Подзвону. Між доглядом за побитими солдатами й латанням одягу припаси тануть загрозливо швидко. Щоб новоприбулі не розсипалися під час перших випробувань, Елрет посилає їх у довколишні галявини полювати на місцевих сутінкових кажанів і вовків-падложерів, обмінюючи вцілілу броню на сирі шкури, крила й жили, без яких табір не протримається."},{t="Успадкований захист",b="Броня, яку пропонує Елрет, далека від бездоганної ковальської роботи: це ношені речі, зняті з тих, хто не пережив свого пробудження. Її похмурі слова на прощання — побажання, щоб одяг послужив новому власникові краще, ніж попередньому, — відображають холодний розрахунок виживання Відступників. У Галявинах Тірісфалю ніщо не пропадає марно, і кожен клапоть шкіри та іржавої кольчуги вже пережив щонайменше один труп."}},fp="10,296,17.566.0,20.411.0,21.233.0,54.223.0,37.205.0,30.144.0,54.230.0,41.231.0"}
P.entries["quest:380"] = {n="Лощина Нічної Павутини",s="Лощина Нічної Павутини — раннє доручення Екзекутора Аррена: вичистити павуків, що заполонили сусідню золоту шахту на північний захід від Похоронного Подзвону. Потерпаючи від гострої нестачі сировини, молоді Відступники потребують багатств шахти, щоб утримувати поселення й вести війну. Новопіднятих новобранців посилають у заплутану печеру — крок за кроком винищувати павучу заразу.",h="Лощина Нічної Павутини — раннє доручення Екзекутора Аррена: вичистити павуків, що заполонили сусідню золоту...",kw={"лощина нічної павутини","павуки","шахта","золото","аррен","похоронний подзвін"},ang={["faction:Horde"]="Надійні джерела ресурсів у Галявинах Тірісфалю критично важливі, щоб закріпити за Відступниками роль надійного північного бастіону Орди.",["profession:Mining"]="Печера — одне з небагатьох близьких до Похоронного Подзвону джерел золотої руди, хоч густа павутина й хижі павуки роблять розвідку небезпечною.",["race:Undead"]="Це завдання показує сувору дійсність повернутих мерців Лордерону: щоб вижити, треба добувати буденні речі — метал і монету, — а не лише шукати помсти живим і Погибелі."},sec={{t="Нації потрібна монета",b="Виживання новопіднятих Відступників — це не лише оборона від Погибелі й багряних хрестоносців. Щоб збудувати молоде суспільство, потрібна сировина, а коштовні метали на кшталт золота були рідкістю на півночі Лордерону навіть за розквіту Альянсу. Екзекутор Аррен, що керує справами в Похоронному Подзвоні, розуміє: без надійного джерела багатства Відступникам не озброїтися, не спорядитися і не утвердитися."},{t="Заражена шахта",b="Просто на північний захід від цвинтаря лежить Лощина Нічної Павутини — природна печера з багатою золотою жилою. На біду, тунелі захопили потворні павуки, заповнивши глибини густим павутинням і смертельною отрутою. Не маючи загартованих бійців для повної зачистки, Аррен покладається на свіжих новобранців: ті мають проріджувати молодих і дорослих павуків, доки шахтарські бригади нарешті зможуть випалити павутину й добути руду."}},fp="18,377,24.436.0,17.440.0,35.318.0,22.269.0,36.168.0,68.238.0,71.289.0,33.262.0"}
P.entries["quest:381"] = {n="Багряний хрестовий похід",s="Це раннє доручення Екзекутора Аррена велить щойно пробудженим Відступникам влаштувати засідку на сусідній табір фанатиків Багряного Хрестового Походу на південний схід від Похоронного Подзвону. Воно стає похмурим знайомством з одним із найфанатичніших і найупертіших ворогів Відступників.",h="Це раннє доручення Екзекутора Аррена велить щойно пробудженим Відступникам влаштувати засідку на сусідній...",kw={"багряний хрестовий похід","аррен","фанатики","засідка","пов'язки","похоронний подзвін"},ang={["class:Priest"]="Протистояння з Багряним Хрестовим Походом змушує жерців Відступників побачити, як Святе Світло, яке вони колись шанували в Лордероні, викривилося у фанатичну ненависть.",["faction:Horde"]="Невпинна агресія, яку виявляє Багряний Хрестовий Похід, пояснює, чому Відступники шукали взаємного захисту й оборони, що їх пропонує Орда.",["race:Undead"]="Для щойно пробуджених Відступників ця місія — ранній урок того, як їх бачать живі: потворами, що заслуговують лише винищення, незалежно від вільної волі."},sec={{t="Фанатична загроза",b="Щойно нагальну небезпеку павуків нічної павутини усунуто, Екзекутор Аррен звертає увагу Похоронного Подзвону на загрозу, що насувається. Загін Багряного Хрестового Походу закріпився просто на південний схід від поселення. Ці фанатики відмовляються бачити різницю між безтямними прислужниками Погибелі та вільними Відступниками, тож їхня присутність на кордоні — смертельна загроза для новопіднятих мерців."},{t="Упереджувальна відплата",b="Розуміючи, що діалог зі святими фанатиками, які вважають усяку мертву плоть мерзотою, неможливий, Аррен наказує завдати упереджувального удару. Шукачів пригод посилають вирізати Багряних Послушників і Навернених, перш ніж табір переросте в організований наступ на Похоронний Подзвін. Принесені трофеї — їхні малинові пов'язки — суворий доказ того, що виживання у Тірісфалі треба виборювати силою."}},fp="19,246,18.444.0,22.407.0,28.300.0,51.242.0,50.244.0,47.220.0,42.238.1,22.164.0"}
P.entries["quest:382"] = {n="Червоний гонець",s="Екзекутор Аррен доручає новопіднятим Відступникам перехопити гінця, відправленого з Багряного Монастиря до табору хрестоносців біля Похоронного Подзвону. Перехоплення гінця дає важливі відомості про пересування багряних у долині, перш ніж фанатики закріпляться там. Ця місія — одна з перших наступальних операцій, здійснених заради безпеки молодого притулку Відступників.",h="Екзекутор Аррен доручає новопіднятим Відступникам перехопити гінця, відправленого з Багряного Монастиря до...",kw={"червоний гонець","мевен корґал","аррен","депеші","багряний монастир","документи"},ang={["class:Rogue"]="Проникнути в табір Хрестового Походу, вбити Мевена Корґала й викрасти його депеші — квінтесенція таємної роботи для щойно пробуджених розбійників.",["faction:Horde"]="Руйнуючи операції багряних на кордонах Похоронного Подзвону, новобранці захищають північний периметр щойно здобутої опори Орди у Східних Королівствах.",["race:Undead"]="Перехоплення цього гінця — важливий удар по фанатиках, які прагнуть стратити вас удруге, перш ніж ви бодай зіпнетеся на ноги в Лордероні."},sec={{t="Очі на сході",b="Чутки швидко розлітаються Галявинами Тірісфалю, навіть серед мертвих. Начальство з Брілла попередило Екзекутора Аррена, що Багряний Хрестовий Похід відправив посланця зі своєї твердині, Багряного Монастиря, на захід, до Похоронного Подзвону. Хрестоносці й так тримають агресивну присутність по всьому Лордерону, та гонець, посланий просто на край земель, де пробуджуються Відступники, свідчить про організований намір винищити новопідняту нежить, перш ніж та зуміє зібрати організовану оборону."},{t="Перехоплення гінця",b="Гонець, Мевен Корґал, затесався в невеликий табір багряних на схід від Похоронного Подзвону без помітних знаків розрізнення. Екзекутор Аррен наказав здійснити точковий удар: убити Корґала і вилучити його депешу. Позбавивши гінця послань, Відступники відрізали місцевих фанатиків від подальшої тактичної координації зі східним штабом."},{t="Важливі депеші",b="Перебравши здобуті Документи Багряного Хрестового Походу, можна знайти суміш пропаганди, розвідувальних нотаток і прямих наказів фанатикам розширити табір поблизу зруйнованої столиці. Головне ж — у документах є стратегічна мапа з позиціями польових командирів та агентів по всіх галявинах; відкриття настільки цінне, що його слід негайно доставити вищому начальству в Бріллі."}},fp="17,410,16.474.0,24.344.0,16.406.1,25.200.0,34.144.0,44.217.1,37.215.1,62.261.0,52.170.0"}
P.entries["quest:383"] = {n="Життєво важливі відомості",s="Життєво важливі відомості — завершення вишколу щойно піднятого Відступника в Похоронному Подзвоні. Отримавши перехоплені документи Багряного Хрестового Походу, гонець вирушає в Галявини Тірісфалю — доповісти Екзекутору Зиґанду в Бріллі.",h="Життєво важливі відомості — завершення вишколу щойно піднятого Відступника в Похоронному Подзвоні.",kw={"життєво важливі відомості","зиґанд","аррен","документи","брілл","похоронний подзвін"},ang={["faction:Horde"]="Зібрані тут відомості допомагають Відступникам закріпити владу над Галявинами Тірісфалю й захистити північну браму Андерсіті від вторгнень, які готує Багряний Хрестовий Похід.",["race:Undead"]="Доставка перехоплених планів — обряд посвяти: довівши свою життєздатність після повстання з могили, ви вирушаєте з колиски Похоронного Подзвону у велику війну за Лордерон."},sec={{t="Вихід із Похоронного Подзвону",b="Знешкодивши місцеві загрози й перехопивши гінця Багряного Хрестового Походу, новобранці Відступників вважаються готовими до ширшої служби. Екзекутор Аррен довіряє здобуті відомості гравцеві й скеровує його з затишного каньйону Похоронного Подзвону на схід, дорогою до Брілла, повз Маєток Холодного Вогнища."},{t="Рішучий удар",b="Прибулого до Брілла зустрічає Екзекутор Зиґанд, який вивчає захоплене листування. У документах — списки й подробиці, що викривають командирів Багряного Хрестового Походу, які діють по всіх Галявинах Тірісфалю; це закладає основу для точкових убивств, покликаних розколоти керівництво фанатиків і підірвати їхній дух."}},fp="18,224,18.335.0,17.310.1,57.238.0,33.112.0,38.199.0,49.254.0,22.140.0,46.226.0"}
P.entries["quest:384"] = {n="Кабанячі ребра в пивному соусі",s="Раґнару Тандербрю з Ґуральні Тандербрю в Хараносі потрібні свіжі ребра скелястих вепрів і кухоль Солоду Рапсодії, щоб нагодувати голодних відвідувачів таверни. Його постійний постачальник м'яса пішов воювати в Королівській армії, тож Раґнар покладається на перехожих мандрівників, аби його славетні ребра не зникли з меню.",h="Раґнару Тандербрю з Ґуральні Тандербрю в Хараносі потрібні свіжі ребра скелястих вепрів і кухоль Солоду...",kw={"харанос","тандербрю","ребра","вепр","ель","таверна","дун мороґ"},ang={["faction:Alliance"]="Навіть нестача харчів у таверні Хараноса — відлуння великої війни Альянсу: гірський люд кидає своє ремесло, щоб відгукнутися на заклик до зброї.",["profession:Cooking"]="Шукачі пригод, яких цікавить кухня біля домашнього вогнища, можуть перейняти секрет поєднання солодового напою з дичиною просто в одного з найславетніших броварів Дун Мороґу.",["race:Dwarf"]="Для дворфів міцний ель і смажений вепр — підвалини гірської гостинності, тож поповнити запаси ґуральні — справа місцевої гордості."},sec={{t="Таверна в скруті",b="Ґуральня Тандербрю в Хараносі славиться міцним дворфійським елем і ситними стравами. Головна з них — легендарні Кабанячі ребра в пивному соусі. Та господар таверни Раґнар Тандербрю потрапив у халепу: місцевий мисливець, який зазвичай наповнював комору свіжим м'ясом, нещодавно записався до Королівської армії, щоб підсилити фронт Альянсу, і лишив Раґнара з юрбою охочих гостей і геть порожніми коморами."},{t="Таємний інгредієнт",b="Щоб приготувати цю страву, потрібне свіже м'ясо жилавих скелястих вепрів, що блукають засніженими передгір'ями довкола Хараноса. Але справжня магія рецепта — у соусі. Раґнар наполягає на свіжому Солоді Рапсодії, націдженому просто з кранів ґуральні. Солод розм'якшує жорстку дичину, перетворюючи грубе гірське м'ясо на смаковиту учту, гідну похвали дворфа."}},fp="21,285,16.444.0,21.389.0,40.191.0,35.147.0,36.133.0,42.154.0,55.187.0,44.132.0"}
P.entries["quest:39"] = {n="Доставити звіт Томаса",s="«Доставити звіт Томаса» — доручення віднести похмурі відомості зі сходу Лісу Елвінн командуванню гарнізону в Ґолдширі. Вартовий Томас доручає шукачеві пригод сповістити Маршала Дуґана про загибель двох вартових і нестримне розростання місцевих племен мурлоків. Звіт показує, якою небезпечно тонкою є військова присутність Стормвінда в самому серці його земель.",h="«Доставити звіт Томаса» — доручення віднести похмурі відомості зі сходу Лісу Елвінн командуванню гарнізону в...",kw={"звіт томаса","вартовий томас","маршал дуґан","мурлоки","ґолдшир","малакай","рольф"},ang={["class:Warrior"]="Для воїнів, що служать королівству, загибель Малакая й Рольфа підкреслює сувору правду гарнізонної служби на прикордонні проти невблаганних нелюдських ворогів.",["faction:Alliance"]="Доставлений звіт Томаса оголює вразливість у самому серці головного королівства Альянсу: навіть дороги поза столицею вислизають з-під контролю гарнізону.",["race:Human"]="Захисники з людей відчувають ці втрати на собі: безпеку їхньої батьківщини підточують нестача людей і дедалі зухваліші ворожі вторгнення."},sec={{t="Лихі вісті зі сходу",b="Вартовий Томас, що стоїть на мостах, які ведуть у нетрі східного Елвінну, дійшов до межі. Його загін мав стежити за рухом на річці й заворушеннями на прикордонні, та зазнав тяжких втрат: від лап агресивних племен мурлоків загинули вартові Малакай і Рольф. Людей у Томаса дедалі менше, стримати водяну навалу він не може, тож змушений спорядити термінового гінця назад дорогою до Ґолдшира."},{t="Гарнізон на межі",b="Коли Маршал Дуґан отримує звіт у Корчмі «Лев'яча Гордість», новини підтверджують його найгірші стратегічні побоювання. Ґолдшир і так ледве підтримує звичайні патрулі, борючись із засиллям кобольдів, бандитами Дефіас і цілковитою відсутністю підкріплень зі Стормвінда. Втрата двох досвідчених вартових і розуміння, що мурлоки невдовзі можуть загрожувати самому Ґолдширу, показують, як близько оборона краю підійшла до повного краху."}},fp="22,365,25.464.0,33.463.0,25.231.0,63.236.0,45.270.0,57.314.0,51.250.0,32.191.0"}
P.entries["quest:3901"] = {n="Струснути Брязкунів",s="Струснути Брязкунів — раннє випробування, яке Жрець Тіні Сарвіс призначає щойно пробудженим Відступникам в Похоронному Подзвоні. Знищивши дванадцять Скелетів-Брязкунів, свіжа нежить доводить свою стійкість проти Погибелі й показує, що має силу волі захищати щойно здобуту свободу.",h="Струснути Брязкунів — раннє випробування, яке Жрець Тіні Сарвіс призначає щойно пробудженим Відступникам в...",kw={"брязкуни","скелети","сарвіс","випробування","похоронний подзвін","новобранці"},ang={["class:Priest"]="Робота безпосередньо на Жерця Тіні Сарвіса дає новопіднятим жерцям ранній погляд на безжальний прагматизм, що визначає духовний шлях Відступників.",["faction:Horde"]="Випробування в Похоронному Подзвоні гартують нових солдатів Відступників у вправних бійців, готових захищати свою молоду фракцію і тримати Галявини Тірісфалю.",["race:Undead"]="Зіткнення з Брязкунами — суворе нагадування про те, що чекає на кожного Відступника, чий розум зісковзне: ваша тяжко здобута воля проти безтямного рабства Погибелі."},sec={{t="Випробування рішучості",b="Винищивши безтямних зомбі, що шкандибають Похоронним Подзвоном, новопідняті Відступники одразу стикаються з суворішим випробуванням. Жрець Тіні Сарвіс посилає новобранців проти Скелетів-Брязкунів, які блукають околицями поселення. У цих оживлених кістках немає й сліду розуму чи самовладання, та б'ють вони сильніше і люті в бою більше, ніж гниючі трупи поблизу. Пережити їхні брязкітливі засідки означає довести, що новобранець не здригнеться під раптовим тиском."},{t="Захист щойно здобутої свободи",b="Для Сарвіса й очільників Похоронного Подзвону винищення скелетів служить подвійній меті. Воно береже крихкий притулок від навали залишкової хватки Короля-Ліча — і відсіває новобранців, яким це не до снаги. Ті, хто зазнає невдачі чи завагається, ризикують розділити долю безтямних нещасних, що блукають лісами. Подолавши Брязкунів, новобранець доводить Сарвісу, що має гарт, потрібний, аби вижити у світі, який ненавидить саме його існування."}},fp="24,308,17.519.0,27.476.0,30.195.0,59.198.0,41.132.0,41.200.0,63.280.0,28.203.0"}
P.entries["quest:3902"] = {n="Нишпорення в Похоронному Подзвоні",s="Нишпорення в Похоронному Подзвоні — раннє господарське завдання, яке щойно пробудженим Відступникам дає Вартовий Смерті Салтейн у Похоронному Подзвоні. Поки свіжопіднята нежить видряпується з землі, Відступники мусять обнишпорити покинуті ящики й скрині по всьому спустошеному поселенню, щоб спорядити новобранців. Це показує, у якій злиденній скруті живе молодий народ Сильвани, змушений підбирати викинуте добро, аби просто вижити.",h="Нишпорення в Похоронному Подзвоні — раннє господарське завдання, яке щойно пробудженим Відступникам дає...",kw={"нишпорення","салтейн","ящики","припаси","похоронний подзвін","збиральництво"},ang={["faction:Horde"]="Хоч Відступники й у союзі з далекою Ордою за морем, застави на кшталт Похоронного Подзвону мусять виживати день у день відчайдушним збиральництвом на місці, а не завдяки чужоземній допомозі.",["race:Undead"]="Це завдання показує сувору етику вашого щойно прийнятого нежиття: ніхто в Азероті не запропонує ні жалю, ні милостині, тож Відступники мусять видерти своє майбутнє з землі власноруч."},sec={{t="Прагматичне воскресіння",b="Новопідняті Відступники прокидаються в похмуру дійсність тління й нестатків. На відміну від усталених держав із жвавими лініями постачання й арсеналами, вільна нежить у Похоронному Подзвоні не має майже нічого. Пряма вимога Вартового Смерті Салтейна відображає безжальну практичність, потрібну, щоб збудувати армію з цвинтарної землі: кожен придатний клапоть тканини, шкіри й заліза треба притягти назад, щоб одягти й озброїти тих, хто ще виповзає зі своїх могил."},{t="Перебиватися у Тірісфалі",b="Поселення Похоронний Подзвін усіяне рештками його колишніх мешканців-людей і припасами, покинутими під час падіння королівства перед Погибеллю. Замість лишити придатні матеріали гнити в ящиках по всьому містечку, Вартові Смерті залучають новонароджену нежить як збирачів. Як ясно дає зрозуміти Салтейн, Відступники не чекають милостині від світу живих і мусять цілком покладатися на власну працьовитість, щоб стати на ноги."}},fp="21,412,24.448.0,23.443.0,49.247.0,36.164.0,26.178.0,60.245.0,40.192.0,58.221.0"}
P.entries["quest:3903"] = {n="Міллі Осворт",s="«Міллі Осворт» — коротке доручення, яке Помічник Віллем біля Абатства Нортшира довіряє перспективним новобранцям. Воно посилає шукачів пригод через землі абатства допомогти Міллі, місцевій жінці, чиї віз і засоби до існування опинилися під загрозою. Завдання знаменує перехід від зачистки земель абатства до допомоги знедоленим мирним мешканцям Лісу Елвінн.",h="«Міллі Осворт» — коротке доручення, яке Помічник Віллем біля Абатства Нортшира довіряє перспективним...",kw={"міллі осворт","помічник віллем","нортшир","віз","стайня","допомога"},ang={["faction:Alliance"]="Це завдання показує, як напружені місцеві сили Альянсу в Нортширі: вартові мусять покладатися на шукачів пригод, що проходять повз, аби захистити містян від нових загроз.",["race:Human"]="Для молодих людей, що починають свій шлях у Нортширі, підмінити Віллема — це вияв духу спільноти, без якого Елвінн не втримати вкупі."},sec={{t="Надійні руки",b="Довівши свою доблесть у боротьбі зі злодіями Дефіас, що лізуть у Долину Нортширу, новобранці привертають увагу Помічника Віллема. Побачивши здібну й охочу допомогу, Віллем направляє шукачів пригод до своєї подруги Міллі Осворт. Це не офіційна гарнізонна справа, а особиста послуга: допомогти мирній мешканці, яку затисло дедалі більше безладдя в долині."},{t="Клопіт біля стаєнь",b="Міллі Осворт чекає біля свого воза з іншого боку Абатства Нортшира, неподалік стаєнь. Помічник Віллем прив'язаний до свого поста на захисті абатства, а клопоти Міллі вимагають рішучих дій просто в долині — на які розтягнутий до краю гарнізон варти просто не має людей."}},fp="13,339,26.360.0,22.301.0,42.163.0,33.141.0,43.184.0,45.127.0,31.158.0,38.141.0"}
P.entries["quest:3904"] = {n="Урожай Міллі",s="«Урожай Міллі» — просте доручення, породжене дедалі гострішою кризою з бандитами в Нортширі. Головорізи Дефіас змусили місцеву фермерку Міллі Осворт покинути зібраний виноград просто на виноградниках, тож шукачеві пригод доведеться пройти захопленими полями й урятувати її заробіток, поки його не вкрали чи не потоптали.",h="«Урожай Міллі» — просте доручення, породжене дедалі гострішою кризою з бандитами в Нортширі.",kw={"урожай міллі","міллі осворт","виноград","дефіас","виноградники","нортшир"},ang={["faction:Alliance"]="Порятунок урожаю Міллі дає молодим новобранцям Альянсу перший тверезий погляд на проблему Дефіас, що гноїться за якихось кілька миль від Стормвінда.",["race:Human"]="Для людей, що починають свій шлях у Нортширі, захист дрібних фермерів на кшталт Міллі — це серцевина обов'язку оберігати трудовий люд Елвінну."},sec={{t="Покинутий урожай",b="Збираючи виноград на південно-східних полях Долини Нортширу, Міллі Осворт мусила рятуватися втечею, коли розбійники Дефіас заполонили виноградні ряди. У паніці вона покинула зібраний урожай — відра й ящики, розставлені по захоплених рядах. Місцевий гарнізон розтягнутий до краю, тож Міллі боїться: навіть якщо варта зрештою прожене зайд, важкі чоботи й безладна бійка розчавлять усе, чого бандити ще не встигли винести."},{t="Нортшир під тиском",b="Бандити, що зухвало окупують робочі виноградники, показують, якою крихкою стала безпека Нортширу. Поки увага Стормвінда прикута до іншого, а в долині бракує вартових, звичайним мешканцям на кшталт Міллі лишається покладатися на новобранців і мандрівників, щоб захистити своє майно й зберегти харчі та вино, якими живе абатство."}},fp="15,286,18.474.0,25.381.0,21.225.0,53.229.0,43.180.0,29.189.0,46.191.1,45.188.0"}
P.entries["quest:3905"] = {n="Опис Винограду",s="Коли врожай Міллі Осворт урятовано від злодіїв Дефіас, вона складає опис, у якому обліковує повернутий виноград. Доставлений Брату Нілзу в Абатство Нортшира, цей реєстр дає братству змогу поповнити свої уславлені запаси вина. Це маленька, але солодка перемога для добробуту обложеної долини.",h="Коли врожай Міллі Осворт урятовано від злодіїв Дефіас, вона складає опис, у якому обліковує повернутий...",kw={"опис винограду","брат нілз","міллі осворт","вино","нортшир","абатство"},ang={["class:Priest"]="Вино в Абатстві Нортшира має і гостинну, і священну цінність, пов'язуючи повсякденне землеробство з обрядами братства.",["faction:Alliance"]="Захищені запаси харчів у Нортширі допомагають зберегти самодостатність головного прихистку Стормвінда для набору й одужання.",["race:Human"]="Для молодих людей, що починають свій шлях, допомога Міллі та Брату Нілзу береже одну з найдорожчих сільських традицій королівства."},sec={{t="Вино долини",b="Долина Нортширу славиться на весь Елвінн родючим ґрунтом і тихими садами, а її виноградники дають урожай, важливий і для прожитку, і для церковних обрядів. Захопивши східні поля, злодії та бандити поставили під загрозу не просто ягоди — вони перерізали абатству постачання вина й харчів. Тепер, коли врожай витягнуто з окупованих ділянок, опис винограду офіційно обліковує кожен повернутий кошик."},{t="Чарка на дзвіниці",b="Брат Нілз відає в Абатстві Нортшира харчами й напоями, хоч найбільше він відомий любов'ю куштувати нортширські вина високо на тихій дзвіниці. Поки загроза розбійників нависає просто за брамою, свіжий виноград дає братству привід підняти чарку за Світло й на мить зітхнути з полегшенням."}},fp="14,327,20.445.0,22.363.0,27.228.0,21.183.0,30.103.0,44.209.0,36.181.0,53.170.0"}
P.entries["quest:398"] = {n="Розшукується: Маґґот Ай",s="«Розшукується: Маґґот Ай» — офіційна нагорода за голову, вивішена на дошці оголошень у Бріллі очільниками Відступників. Горезвісний гнол грабує довколишні цвинтарі й ферми, постачаючи мертві тіла просто Погибелі Короля-Ліча. Екзекутор Зиґанд вимагає доказу страти потвори, щоб убезпечити землі довкола Лігва Гаррена.",h="«Розшукується: Маґґот Ай» — офіційна нагорода за голову, вивішена на дошці оголошень у Бріллі очільниками...",kw={"розшукується","червиве око","маґґот ай","гнол","нагорода","зиґанд","лігво гаррена"},ang={["faction:Horde"]="Північні кордони Тірісфалю треба замирити, якщо Орда хоче втримати надійну опору в Лордероні проти решток Погибелі.",["race:Undead"]="Кожен труп, викрадений Червивим Оком, — полеглий брат чи сестра, знову обернені на поневолену маріонетку Короля-Ліча. Знищити його — справа і оборони нації, і особистої помсти."},sec={{t="Могильний злочин",b="У Галявинах Тірісфалю мертві аж ніяк не спочивають у мирі. Гнол, відомий як Червиве Око, заслужив смертний вирок не просто за мародерство, а за діяльну співпрацю з Королем-Лічем. Гнолів зазвичай мають за диких тварюк, яких жене простий голод, та Червиве Око планомірно викопує трупи й збирає останки, щоб поповнювати лави армії Погибелі."},{t="Правосуддя у Бріллі",b="Для Відступників, чиє існування цілком тримається на звільненні з-під влади Короля-Ліча, годувати мертвими родичами воєнну машину Погибелі — один із найтяжчих можливих злочинів. Екзекутор Зиґанд, що відповідає за військовий порядок у Бріллі, призначив цю нагороду, щоб покласти край розграбуванню могил біля Лігва Гаррена. Щоб отримати винагороду, кат мусить відтяти Червивому Оку лапу — безпомильний доказ того, що звір більше не турбуватиме Тірісфаль."}},fp="18,338,13.390.0,16.470.0,18.197.0,34.185.0,34.117.0,35.144.0,38.156.0,35.185.0"}
P.entries["quest:40"] = {n="Риб'яча загроза",s="«Риб'яча загроза» — коротке кур'єрське завдання від Ремі «Двічі» на сході Лісу Елвінн. Стривожений чутками про земноводних хижаків, що лізуть у річки, Ремі посилає мандрівників попередити Маршала Дуґана в Ґолдширі. Доручення показує, як важко виснаженому місцевому гарнізону Стормвінда реагувати на нові загрози з диких земель.",h="«Риб'яча загроза» — коротке кур'єрське завдання від Ремі «Двічі» на сході Лісу Елвінн.",kw={"риб'яча загроза","мурлоки","ремі двічі","маршал дуґан","ґолдшир","ліс елвінн"},ang={["faction:Alliance"]="Це доручення показує бюрократичне й логістичне напруження домашньої варти Стормвінда, через яке містечко мусить покладатися на незалежних шукачів пригод, щоб перевіряти чутки.",["race:Human"]="Для людей, що боронять рідний край, вторгнення у східні річки б'є по найближчому: знайомі струмки стають небезпечними мисливськими угіддями водяних тварюк."},sec={{t="Благання зі сходу",b="Торгуючи на східних дорогах Лісу Елвінн, Ремі «Двічі» натрапляє на дивну нову напасть, яка не дає йому спокою. Мурлоки почали підійматися струмками та внутрішніми мілинами, зриваючи рибальство й загрожуючи мирним подорожнім. Переконаний, що місцева варта не помічає назріваючої катастрофи, Ремі благає перехожих віднести звістку в серце містечка."},{t="Виснажений гарнізон",b="Отримавши донесення в Ґолдширі, Маршал Дуґан ставиться до нього скептично. Йому доручено берегти королівство, поки королівські сили розтягнуті деінде, і Дуґан уже поглинутий жорстоким відродженням гнолів Річколапів і розбійників Дефіас. Без підтверджених військових відомостей маршал відмовляється відривати своїх нечисленних людей заради чуток про рибо-людей у східних струмках."}},fp="13,347,20.389.0,19.388.0,34.118.0,46.140.0,49.208.0,32.157.0,44.98.0,53.204.0"}
P.entries["quest:400"] = {n="Інструменти для Стілґрілла",s="«Інструменти для Стілґрілла» — раннє доручення Альянсу з доставки, яке знайомить мандрівників, що покидають Харанос, із сусідньою майстернею на Складі Стілґрила. Тарек Блекстоун посилає вас дорогою на північний схід зі свіжим ящиком важкого спорядження для Белдіна Стілґрілла — майстра облогових машин, який зношує гайкові ключі й тріскачки швидше, ніж міські постачальники встигають їх підвозити.",h="«Інструменти для Стілґрілла» — раннє доручення Альянсу з доставки, яке знайомить мандрівників, що покидають...",kw={"стілґрілл","харанос","інструменти","облогова машина","блекстоун","склад","дун мороґ"},ang={["profession:Engineering"]="Ремесло Белдіна тримається на точних інженерних інструментах — дугових ключах та ікло-тріскачках, і це показує, якого навантаження зазнає виготовлене знаряддя в механізованій війні.",["race:Dwarf"]="Дворфійська броньована війна цілком залежить від польових ремонтних станцій на кшталт Складу Стілґрила, завдяки яким могутні облогові машини Айронфорджа долають замерзлі перевали.",["race:Gnome"]="Дугові ключі й хитромудрі тріскачки, які Белдін зношує одну за одною, — ознака точної інженерії гномського взірця, пристосованої до грубої дворфійської броні."},sec={{t="Майстер, що не шкодує інструментів",b="Белдін Стілґрілл має в Дун Мороґу беззаперечну славу найкращого механіка облогових машин у горах, та його шалений запал у роботі дорого обходиться майстерні. За словами Тарека Блекстоуна з Хараноса, Стілґрілл ламає дугові ключі та трощить інструменти майже так само швидко, як прибувають ящики з припасами. Щойно в Хараносі збирають нову партію міцного знаряддя, кожного, хто прямує на північний схід, хутко вмовляють тягти важкий пакунок на склад."},{t="Щоб машини не спинялися",b="Прибувши на Склад Стілґрила, мандрівники бачать подвір'я, повне диму, мастила та залізних бойових машин на холостому ходу. Белдіна завалено невідкладними військовими ремонтами, зокрема важливою роботою над облоговою машиною Пілота Стоунґіра. Останню свою ікло-тріскачку Белдін зламав за кілька годин до вашого прибуття, тож доставлений ящик стає справжнім порятунком для гусеничного броньованого парку Айронфорджа."}},fp="20,365,26.482.0,27.390.0,26.185.0,25.237.0,36.265.0,36.176.0,27.222.0,59.214.0"}
P.entries["quest:403"] = {n="Охоронюване Барило Тандербрю",s="Охоронюване Барило Тандербрю стоїть у погребі Ґуральні Тандербрю в Хараносі. Це найцінніший запас славетної дворфійської броварської родини, за яким пильнують удень і вночі, щоб злодії та суперники не дісталися до їхнього ремесла.",h="Охоронюване Барило Тандербрю стоїть у погребі Ґуральні Тандербрю в Хараносі.",kw={"барило","тандербрю","погріб","ель","харанос","джарвен"},ang={["class:Rogue"]="Прослизнути в погріб і поцупити барило міцного дворфійського елю — класична робота, та пильний дворф біля бочки робить тиху крадіжку значно складнішою.",["race:Dwarf"]="Кожен дворф розуміє, що таємне родинне пиво варто боронити до останнього, тож уперта варта Джарвена в погребі видається цілком природною."},sec={{t="Погріб під вартою",b="Серед холодних снігів Дун Мороґу мало що бережуть так ревно, як добрий ель. Під мостинами Ґуральні Тандербрю в Хараносі спокійно визрівають міцні барила хмільного пива. Родина не ризикує своїм запасом і ставить просто біля барил пильних вартових, як-от Джарвена Тандербрю, щоб жодна крапля не була зіпсована чи відлита."},{t="Родинна гордість і суперництво",b="Дворфійське броварство — ремесло не менш поважне, ніж ковальство чи гірнича справа. Тандербрю надзвичайно пишаються своїми власними рецептами, а надто міцними партіями Громового Елю. Поки довкола Дун Мороґу шастають жадібні троги, а по всьому Альянсу точиться запекле броварське суперництво, пильна присутність Джарвена гарантує, що рідке золото родини лишиться недоторканим, доки його не наточать як годиться."}},fp="26,247,20.375.0,26.375.0,29.170.0,26.228.0,29.117.0,51.213.0,30.165.0,32.197.0"}
P.entries["quest:404"] = {n="Гнила робота",s="Гнила робота — раннє бойове доручення Вартового Смерті Діллінджера у Бріллі. Воно велить шукачам пригод відкинути безтямно агресивну Погибель, що насідає на старий міст на захід від поселення. Докази знищення потвор убезпечують дорогу і полегшують тягар захисників Тірісфалю.",h="Гнила робота — раннє бойове доручення Вартового Смерті Діллінджера у Бріллі.",kw={"гнила робота","діллінджер","міст","пазурі","погибель","брілл"},ang={["faction:Horde"]="Безпека Брілла гарантує, що молода присутність Орди у Східних Королівствах зберігає надійну опору проти Погибелі.",["race:Undead"]="Для Відступників знищення Погибелі — глибоко особиста справа, помста невблаганній силі, що колись тримала в полоні їхній розум."},sec={{t="Утримати міст",b="Брілл стоїть на важливому перехресті на сході Галявин Тірісфалю, тож будь-який підхід ворога — пряма загроза осередку влади Відступників. Безтямна Погибель невпинно просочується на захід через водойми, скупчуючись біля зруйнованих решток старого кам'яного мосту. Без регулярних патрулів, які відкидають їх назад, шкандибаючі трупи швидко перекрили б сполучення між Бріллом і західними хуторами."},{t="Злість на безтямних",b="Для Відступників Погибель, що блукає їхніми кордонами, — не просто стратегічна прикрість, а образа. Кожен безтямний гуль і гниючий труп утілює рабство й муки, від яких відірвалися послідовники Леді Сильвани Віндраннер. Вартові Смерті на кшталт Діллінджера з похмурою втіхою трощать колишніх поневолювачів і вимагають відтяті пазурі як жорстокий доказ того, що безтямних мерців упокоєно назавжди."}},fp="13,320,18.395.0,29.415.0,21.135.0,48.186.0,33.121.0,41.206.0,40.159.1,52.202.0"}
P.entries["quest:407"] = {n="Поля скорботи",s="Поля скорботи завершують експеримент Аптекаря Йогаана з перетворення звичайних гарбузів із Хутора Соллідена на зброю. Насичивши врожай своєю найновішою алхімічною сумішшю, Йогаан відсилає вас згодувати отруєний овоч полоненому багряному хрестоносцю, який чахне у Бріллі.",h="Поля скорботи завершують експеримент Аптекаря Йогаана з перетворення звичайних гарбузів із Хутора Соллідена...",kw={"поля скорботи","гарбуз","йогаан","отрута","багряний фанатик","таверна","брілл"},ang={["faction:Horde"]="Біохімічні дослідження Королівського Аптекарського Товариства часто бентежать нових союзників Відступників, та лишаються осердям боротьби за Галявини Тірісфалю для Орди.",["race:Undead"]="Для Відступників цей експеримент демонструє безжальний прагматизм, потрібний, щоб вижити між смертними фанатиками на півдні та арміями Короля-Ліча на півночі."},sec={{t="Зброя винахідливості",b="Аптекар Йогаан із Королівського Аптекарського Товариства вважає, що Відступники мусять використати кожну тактичну перевагу, щоб відбиватися від Погибелі з півночі й людських вторгнень із півдня. Замість покладатися лише на клинок чи темне чаклунство, Товариство прагне обернути собі на користь звичайні плоди землі. Отруївши гарбузи, відібрані у смертних селян, чиї поля — це Хутір Соллідена, Йогаан має намір довести: навіть простий урожай можна перетворити на знаряддя смерті в ім'я Темної Леді."},{t="Випробування в підвалі",b="Піддослідний чекає під мостинами Таверни «Шибеничний Кінець» у Бріллі. Закутий і зголоднілий полонений Багряний Фанатик зустрічає гостей із Відступників звичним фанатичним викликом, закликаючи Святе Світло очистити нежить. Та голод швидко ламає рішучість хрестоносця. Сприйнявши отруєний гарбуз за справжню поміч, бранець жадібно його поглинає — і за лічені миті обертається на гниючого гуля, перш ніж бездиханно впасти на землю."}},fp="15,285,21.512.0,15.454.1,56.294.0,41.226.0,60.216.1,40.175.0,60.263.0,53.268.0"}
P.entries["quest:408"] = {n="Родинна крипта",s="Родинна крипта — завдання Орди, яке велить гравцям зіткнутися з Погибеллю всередині Родинного Склепу Аґамандів. За наказом Магістрата Севрена з Брілла шукачі пригод мають знищити піднятих предків Аґамандів і вбити скелетного командира Погибелі, Капітана Дарґола.",h="Родинна крипта — завдання Орди, яке велить гравцям зіткнутися з Погибеллю всередині Родинного Склепу...",kw={"родинна крипта","склеп аґамандів","капітан дарґол","предки","севрен","погибель"},ang={["faction:Horde"]="Безпека Галявин Тірісфалю життєво важлива, щоб закріпити присутність Орди у Східних Королівствах, усунувши безпосередні загрози її північній твердині.",["race:Undead"]="Для Відступників Капітан Дарґол утілює все, від чого вони боролися втекти: рабство волі Короля-Ліча. Упокоєння піднятих предків — і самозахист, і похмурий обов'язок зламати хватку Погибелі над батьківщиною."},sec={{t="Тривожні маневри в Тірісфалі",b="Хоч Відступники й вирізали собі крихке володіння в Галявинах Тірісфалю, недобитки Погибелі Короля-Ліча досі глибоко вкорінені в окрузі. Млини Аґаманда, колись квітуче борошняне серце Лордерону, стали небезпечною твердинею Погибелі. Магістрат Севрен у Бріллі стежить за цим нарощуванням сил із глибокою тривогою, знаючи: кожна п'ядь, віддана безтямній нежиті, підриває незалежність Відступників."},{t="Осквернення гробниці",b="Осередок місцевої окупації Погибелі — Родинний Склеп Аґамандів, де влаштував свій штаб скелетний командир Капітан Дарґол. Темною некромантією Дарґол витяг зі спочинку покоління мертвих Аґамандів, обернувши їх на Гниючих і Голосливих Предків, щоб поповнити свої лави. Севрен відряджає агентів Відступників очистити склеп, повернути потривожених мерців до спокою і відтяти Дарґолу голову, щоб зламати координацію Погибелі на півночі Тірісфалю."}},fp="16,263,21.443.0,17.474.0,22.229.0,56.241.0,42.242.0,36.258.1"}
P.entries["quest:409"] = {n="Довести відданість",s="Довести відданість — вирішальне випробування від Ґунтера Аркануса, яке має з'ясувати, кому ви насправді служите: вільним Відступникам чи Королю-Лічу. Щоб заслужити довіру відлюдного некроманта, вас посилають прикликати й знищити Лілліт Нефару — небезпечну агентку Погибелі, що чаїться біля його острова.",h="Довести відданість — вирішальне випробування від Ґунтера Аркануса, яке має з'ясувати, кому ви насправді...",kw={"довести відданість","ґунтер арканус","лілліт нефара","свічка прикликання","озеро світлої води","вівтар"},ang={["class:Mage"]="Бетор Айсшард і Ґунтер Арканус — визначні таланти таємної магії та некромантії в Лордероні; продемонструвавши свою вправність, ви здобуваєте фахову повагу могутнього побратима-заклинача.",["race:Undead"]="Для Відступників зламати самоізоляцію Ґунтера — особиста справа: це доводить братові по нежитті, що нікому з них не доведеться самотужки протистояти гніву Погибелі чи живих."},sec={{t="Підозри відлюдника",b="Відколи Ґунтер Арканус повстав у нежитті, він усамітнився на острові посеред Озера Світлої Води, затято чіпляючись за свою незалежність. Хоч чари Бетора Айсшарда на книзі заклять Ґунтера підтвердили, що посланець не несе мерзенної скверни Погибелі, для параноїдального відлюдника слів і чарів замало. Щоб здобути його довіру, чужинець мусить довести діяльну ворожість до прислужників Короля-Ліча — рішучим насильством."},{t="Убивство Лілліт Нефари",b="Просто на південь від прихистку Ґунтера стоїть заплямований кров'ю ритуальний вівтар, яким користується Лілліт Нефара — грізна агентка Погибелі, що діє в Галявинах Тірісфалю. За допомогою особливої Свічки Прикликання прохач будить Лілліт із тіней, щоб зустрітися з нею у відкритому бою. Знищення агентки розбиває давнє переконання Ґунтера, що він — єдина істота з нежиті, здатна вирватися із залізної хватки Короля-Ліча."}},fp="18,296,22.459.0,29.425.1,36.262.0,22.209.0,32.209.0,60.227.1,41.156.0,43.205.1"}
P.entries["quest:410"] = {n="Приспана примара",s="«Приспана примара» — темний ритуал, який здійснюють серед зруйнованих обійсть Галявин Тірісфалю. Поставивши містичну свічку на старий, просякнутий кров'ю стіл, мандрівник прикликає неспокійного духа, пов'язаного з темними обрядами вірності Відступників.",h="«Приспана примара» — темний ритуал, який здійснюють серед зруйнованих обійсть Галявин Тірісфалю.",kw={"приспана примара","свічка прикликання","лілліт нефара","вівтар","ритуал","стіл"},ang={["class:Priest"]="Жерці Тіні впізнають у поклику свічки вправу з тіньового єднання: неспокійну душу, що затрималася між світами, знову втягують у тілесну сутичку.",["class:Warlock"]="Чорнокнижники розуміють відлунну силу прив'язування духів до просякнутих кров'ю вівтарів, тож цей ритуал для них — знайома вправа з маніпулювання межею між життям і смертю.",["race:Undead"]="Для Відступників ритуали над закривавленими руїнами колишніх домівок Лордерону — похмуре нагадування, що їхнє нове існування виковане зі смерті, темної магії та непохитної вірності Темній Леді."},sec={{t="Моторошний вівтар",b="Серед спустошених руїн Галявин Тірісфалю стоїть побитий, закривавлений обідній стіл. Це аж ніяк не звичайна занедбана домашня річ: він слугує фізичним осердям зловісного прикликання. Заплямований засохлою кров'ю і покинутий у тінях, стіл править за саморобну ритуальну плиту, де досі витають смерть і темна магія."},{t="Свічка Прикликання",b="Щоб розбудити те, що прив'язане до цього місця, слід поставити Свічку Прикликання на закривавлену поверхню і запалити її. Світло свічки прорізає тірісфальський морок, викликаючи з-за завіси смерті примару Лілліт Нефари. Це навмисне некромантське потривоження, покликане випробувати тих, хто прагне довести свій гарт і відданість."}},fp="17,242,16.332.0,23.379.1,56.146.0,31.106.0,59.199.0,34.124.0,28.139.0,31.177.0"}
P.entries["quest:412"] = {n="Операція «Рекомбобуляція»",s="Операція «Рекомбобуляція» — зухвалий інженерний задум Раззла Спрайспрокета в Хараносі. У відповідь на трагедію Гномреґану Раззл та Оззі Тоґлвольт прагнуть повернути назад жахливе перетворення своїх уражених родичів на прокажених гномів за допомогою експериментального пристрою, відомого як Рекомбобулятор.",h="Операція «Рекомбобуляція» — зухвалий інженерний задум Раззла Спрайспрокета в Хараносі.",kw={"рекомбобулятор","гномреґан","прокажені гноми","раззл","харанос","інженерія"},ang={["profession:Engineering"]="Інженери оцінять нетрадиційну майстерню Раззла з її хитромудрими Шестернями Рестабілізації, корбо-тріскачками та в'язким електрогумовим гелем для керування біофізичною радіацією.",["race:Gnome"]="Для гномів це завдання — відчайдушна, щира надія врятувати втрачених рідних і друзів, яких падіння столиці перетворило на люті порожні оболонки."},sec={{t="Ліки від лиха",b="Коли Гномреґан затопили радіацією, щоб вигубити трогів, вона не знищила загарбників, а натомість перетворила більшість гномського населення на божевільних, хворобливих прокажених гномів. Відмовляючись визнати цю трагічну мутацію остаточною, винахідник Раззл Спрайспрокет об'єднався з Оззі Тоґлвольтом, аби розробити технологічні ліки — Рекомбобулятор. Їхня зухвала мета — ні більше ні менше як повернути спотвореним побратимам здоров'я і розум."},{t="Деталі з уражених",b="Для тонкого прототипу потрібні точні компоненти — Шестерні Рестабілізації та Гіромеханічні Передачі. За іронією долі, ці необхідні деталі видобувають просто з ворожих прокажених гномів, що блукають біля запечатаних брам Гномреґану. Збираючи механічні уламки зі своїх спотворених братів і сестер, Раззл сподівається скласти той самий пристрій, який скасує їхню спільну трагедію."}},fp="25,321,23.462.0,29.415.0,42.202.0,38.259.0,46.255.0,52.187.0,38.271.0"}
P.entries["quest:413"] = {n="Мерехтливий Портер",s="Створивши свій експериментальний Мерехтливий Портер у Селі Брюнолл, Реджолд Барліброу просить мандрівників віднести свіже барило його братові Велларту. Велларт служить дворфійським горянином на південній сторожовій вежі, що охороняє прохід до Лох Модану, де на холодному посту міцний напій особливо до речі.",h="Створивши свій експериментальний Мерехтливий Портер у Селі Брюнолл, Реджолд Барліброу просить мандрівників...",kw={"портер","барліброу","брюнолл","лох модан","горянин","барило","пиво"},ang={["faction:Alliance"]="Постачання пильних горян допомагає підтримувати мережу вартових, що охороняють шлях між Дун Мороґом і Лох Моданом.",["race:Dwarf"]="Для дворфів ділитися елем із ріднею — обов'язок не менш важливий, ніж стерегти гірські перевали, тож ця доставка — сама суть прикордонного життя Айронфорджа."},sec={{t="Родинний рецепт на кордоні",b="Реджолд Барліброу довів до ладу свій новий витвір — Мерехтливий Портер, зварений із мерехтливого зілля, зібраного на крижаних скелях Дун Мороґу. Поки решта родини Барліброу віддає своє ремесло чанам і бочкам Села Брюнолл, брат Реджолда Велларт обрав життя горянина. Знаючи, яка самотня варта на кордоні, Реджолд передає свіже барило з перехожими мандрівниками — і як братню послугу, і як справжню дегустацію."},{t="Сторожова вежа Південної Брами",b="Велларт Барліброу стоїть на південній сторожовій вежі обіч Проходу Південної Брами, що веде в Лох Модан. Високо на гірському перевалі горяни терплять пронизливі вітри та випадкові напади звірів, пильнуючи мандрівників на гірській дорозі. Велларт, якому бракує питва і кортить хоч якоїсь розваги, виявляє, що Мерехтливий Портер б'є в голову неабияк — аж так, що, здається, прояснює зір у тьмяній гірській ночі."}},fp="13,336,31.460.0,26.445.0,30.240.0,42.161.0,33.223.0,44.176.1"}
P.entries["quest:414"] = {n="Стаут для Кадрелла",s="«Стаут для Кадрелла» — завдання Альянсу з доставки, що виводить мандрівників із замерзлих висот Дун Мороґу в помірну долину Лох Модану. Отримавши барило щойно вдосконаленого Мерехтливого Портеру Реджолда Барліброу, ви несете міцний напій через кордон, щоб почастувати Горянина Кадрелла, який патрулює Телсамар.",h="«Стаут для Кадрелла» — завдання Альянсу з доставки, що виводить мандрівників із замерзлих висот Дун Мороґу в...",kw={"кадрелл","телсамар","лох модан","портер","барліброу","горянин","доставка"},ang={["faction:Alliance"]="Це завдання — природна провідна нитка, що виводить героїв Альянсу зі снігових початкових земель Дун Мороґу на ширший кордон Лох Модану.",["race:Dwarf"]="Пронести барило гірського елю через кордон — класичне дворфійське побратимство, що єднає броварів Села Брюнолл із прикордонними патрулями, які стережуть Каз Модан."},sec={{t="Смак за горами",b="Скуштувавши щойно завершений Мерехтливий Портер свого брата Реджолда, Горянин Барліброу переконаний: напій надто добрий, щоб лишати його тільки в Дун Мороґу. Стоячи на східному прикордонному посту, що стереже гірські перевали, Барліброу поглядає в бік родичів, які охороняють сусідні землі. Служба дворфійського горянина — холодна й виснажлива, а міцному серцю потрібен міцний напій. Бажаючи почути чесну оцінку від товариша по службі, Барліброу відправляє барило на схід із перехожими, що прямують до Лох Модану."},{t="Дорога до Телсамару",b="Ця подорож — природний обряд переходу для юних дворфійських і гномських шукачів пригод, що провели перші дні серед засніжених скель Дун Мороґу. Проминувши на південний схід Заставу Південної Брами та довгі тунелі, прорубані в гірській породі, мандрівники раптом виходять у тепліший, лісистий басейн Лох Модану. Горянин Кадрелл, що патрулює дорогу через селище Телсамар, радо відривається від варти, щоб наточити барило, і виявляє, що новий рецепт Барліброу має приголомшливий удар."}},fp="16,342,28.538.0,21.546.0,27.167.0,22.186.0,42.233.0,49.233.0,36.180.0,38.204.0"}
P.entries["quest:415"] = {n="Нове пиво Реджолда",s="«Нове пиво Реджолда» — доручення Альянсу в Дун Мороґу, що кличе шукача пригод назад до Села Брюнолл. Довівши до ладу нове вариво із зібраного мерехтливого зілля, бровар Реджолд Барліброу хоче, щоб перевірений друг скуштував його найновіший рецепт. Це місток між збиранням броварських припасів і розвезенням його цінного Мерехтливого Портеру по гірському краю.",h="«Нове пиво Реджолда» — доручення Альянсу в Дун Мороґу, що кличе шукача пригод назад до Села Брюнолл.",kw={"реджолд","брюнолл","пиво","портер","зілля","бровар","дун мороґ"},ang={["faction:Alliance"]="Міцні дворфійські елі живлять гарнізони Альянсу по всіх Східних Королівствах, підтримуючи бойовий дух на суворих прикордонних заставах, як-от у Дун Мороґу.",["race:Dwarf"]="Для дворфа навряд чи є вища честь, ніж особисте запрошення від шанованого бровара зробити перший ковток зі свіжого барила."},sec={{t="Поклик до Брюноллу",b="Чутки ширяться Дун Мороґом швидко, коли дворфійський бровар знаходить золоту жилу у своєму погребі. Після того як мерехтливе зілля зібрано на суворих схилах, місцеві знайомі на кшталт Тарека Блекстоуна чи Пілота Беловфіза вмовляють перехожих шукачів пригод повернутися до Села Брюнолл. Реджолд Барліброу завершив бродіння своїх експериментальних партій і прагне поділитися здобутком із мандрівником, завдяки якому це стало можливим."},{t="Скуштувати плід праці",b="Село Брюнолл живе самобутнім броварським ремеслом, і найновіша партія Барліброу — напій незвичайний. Настоявши сусло на місцевих травах, він отримав особливе питво, відоме як Мерехтливий Портер. Перш ніж відправляти барила до сусідніх застав і спраглих гостей у Лох Модані, Реджолд наполягає: шукач пригод, який ризикував життям заради трав, має честь зробити перший ковток."}},fp="17,374,21.398.0,26.387.0,39.158.0,26.112.0,35.166.0,37.214.1,47.180.0,39.118.0"}
P.entries["quest:4161"] = {n="Рецепт калдорей",s="«Рецепт калдорей» — урок рівноваги, що його дає Заррін, наставник кухарів у Доланаарі. Збираючи точно відміряну кількість павучих лапок по всьому Тельдрассилу, кухарі-початківці засвоюють: годуватися від природи означає виявляти стриманість і повагу.",h="«Рецепт калдорей» — урок рівноваги, що його дає Заррін, наставник кухарів у Доланаарі.",kw={"рецепт","калдореї","заррін","кулінарія","павучі лапки","доланаар","тельдрассил"},ang={["profession:Cooking"]="Це завдання — раннє знайомство з похідною кухнею Тельдрассила, і в нагороду за нього дають рецепт Калдорейських павучих шашличків.",["race:NightElf"]="Урок закріплює осердя світогляду калдорей: злагода з природою через стриманість — брати лише те, що необхідно."},sec={{t="Діти зірок",b="За корчмою в Доланаарі Заррін порається біля булькотливого казана й навчає юних шукачів пригод традицій свого народу. Задовго до нинішньої доби нічні ельфи називали себе калдореями — «дітьми зірок». Для Зарріна розуміння цієї спадщини предків починається не на полі бою, а у зв'язку між мисливцем, його їжею та довколишнім гіллям Тельдрассила."},{t="Брати лише потрібне",b="Суть уроку — у стриманості. Заррін доручає учням зібрати маленькі павучі лапки з лісових павуків за межами Тінедола, але суворо наказує взяти лише сім — і ні однієї більше. У культурі нічних ельфів життя в злагоді з природою вимагає брати тільки необхідне й віддячувати дикій природі добром. Цю тонку рівновагу треба берегти навіть у буремні часи — і ця філософія перетворює звичайний павучий шашличок на моральну дисципліну."}},fp="22,251,21.408.0,26.479.0,14.195.0,63.221.0,35.166.0,35.128.0,45.165.0,51.189.0"}
P.entries["quest:417"] = {n="Помста пілота",s="Слід зниклого дворфійського пілота облогової машини приводить до замерзлого тіла в нетрях Дун Мороґу. Знайдений серед решток особистий щоденник Гілделва описує його смертельну сутичку з горезвісним хижаком на ім'я Дробкіготь і лишає передсмертне бажання помсти.",h="Слід зниклого дворфійського пілота облогової машини приводить до замерзлого тіла в нетрях Дун Мороґу.",kw={"гілделв","дробкіготь","ведмідь","пілот","помста","гаммерфут","дун мороґ"},ang={["class:Hunter"]="Вистежити незвично лютого звіра-ватажка, як-от Дробкіготь, на крижаних вітрах Дун Мороґу — справжнє випробування гірського виживання.",["faction:Alliance"]="Пілоти Айронфорджа — важлива ланка оборони дворфів і Альянсу, тож пошук зниклих пілотів — неодмінний обов'язок.",["race:Dwarf"]="Помститися за полеглого брата з Облогової Бригади Айронфорджа — справа честі: пам'ять Гілделва буде вшанована, а його вбивцю покарано."},sec={{t="Останній запис",b="Пілот Гілделв не пережив поневірянь серед суворих засніжених скель. Знайшовши його рештки, мандрівники бачать поряд щоденник. В останніх рядках Гілделв описав люту сутичку з величезним ведмедем Крижаним Кігтем, якого він назвав Дробкіготь. Спершу йому вдалося відігнати страховисько, та рани виявилися тяжкими, і згодом звір повернувся добити ослаблого пілота."},{t="Передсмертне бажання пілота",b="Відчуваючи близький кінець, Гілделв записав у щоденнику останнє прохання: відплатити чудовиську, що відібрало йому життя. Повернення щоденника й кігтя, вирваного у вбитого звіра, Пілоту Гаммерфуту приносить Облоговій Бригаді Айронфорджа гірке заспокоєння — вшановує загиблого товариша і прибирає смертельну загрозу з гірських стежок."}},fp="17,284,13.421.0,20.347.0,17.276.0,18.193.0,24.239.0,46.214.0,34.187.0,46.159.0"}
P.entries["quest:420"] = {n="Спостереження Сеніра",s="Це доручення завершує розвідувальну лінію з Долини Холодного Хребта: готовий звіт Ґреліна Вайтбірда треба пронести через захоплений трогами прохід до його брата Сеніра в Хараносі. Воно єднає відлюдні тренувальні землі Анвілмару з ширшими бідами Дун Мороґу. Відвертий прийом Сеніра дає мандрівникам перший погляд на політичні тертя між польовими розвідниками та Сенатом Айронфорджа.",h="Це доручення завершує розвідувальну лінію з Долини Холодного Хребта: готовий звіт Ґреліна Вайтбірда треба...",kw={"сенір","ґрелін","вайтбірд","харанос","звіт","сенат","троги"},ang={["faction:Alliance"]="Допомога розвідникам у збиранні відомостей береже Дун Мороґ у час, коли Стормвінд паралізований внутрішніми чварами й не може прислати допомогу північним союзникам.",["race:Dwarf"]="Перехід із затишної тренувальної долини до Хараноса — ваше справжнє посвячення в оборону Каз Модану й перший смак того, як польові розвідники сперечаються з обережним Сенатом Айронфорджа.",["race:Gnome"]="Шлях через прохід до Хараноса наближає гномів-вигнанців до головних осередків Дун Мороґу і до спільної справи підтримки їхніх дворфійських господарів."},sec={{t="Тунелем до Хараноса",b="Повернувши свій викрадений щоденник у тролів Морозогривів, Ґрелін Вайтбірд готує для брата Сеніра докладний звіт про загрози долини. Горянин Талос, що стереже браму з Долини Холодного Хребта, доручає перехожим шукачам пригод віднести цю депешу. Покинути відносно затишну початкову долину означає пройти тунелем, прорубаним у горі, який нещодавно заполонили люті троги, що нападають на всіх подорожніх. Хто проб'ється, виходить на заметені снігом шляхи центрального Дун Мороґу й головною дорогою прямує до затишного Хараноса."},{t="Буркотливий прийом і сенатська політика",b="Сенір Вайтбірд, який гріється за чаркою у Ґуральні Тандербрю в Хараносі, зустрічає новоприбулих із грубуватою гостинністю горянина. Читаючи висновки Ґреліна, Сенір посміюється з войовничої риторики брата. Ґрелін щедро згадує ім'я Короля Маґні Бронзбірда, вимагаючи негайних дій, — напориста тактика, яка, як зауважує Сенір, неодмінно роздратує впертий Сенат Айронфорджа. Сенір зізнається, що через лютий холод занедбав власні спостереження, та депеша Ґреліна повертає його до служби й відкриває подальшу роботу зі стеження за ворожими силами на снігових полях."}},fp="20,421,30.616.0,36.628.0,63.254.0,24.192.0,27.234.0,70.252.0,66.193.0,55.260.0"}
P.entries["quest:426"] = {n="Захоплені млини",s="За дорученням Вартового Смерті Діллінджера з Брілла ця місія посилає солдатів Відступників зламати плацдарм Погибелі на сусідніх Млинах Аґаманда. Безтямна нежить збирається серед зруйнованих вітряків, загрожуючи створити передову базу небезпечно близько до поселень Галявин Тірісфалю. Щоб зупинити це скупчення, новобранці мають розтрощити лави скелетних солдатів і заклиначів кісток.",h="За дорученням Вартового Смерті Діллінджера з Брілла ця місія посилає солдатів Відступників зламати плацдарм...",kw={"захоплені млини","млини аґаманда","скелети","діллінджер","брязкуни","заклиначі кісток"},ang={["class:Warrior"]="Сутичка з броньованими скелетами на Млинах Аґаманда — жорстоке бойове випробування проти невпинних ворогів, які не відчувають болю й не дають пощади.",["faction:Horde"]="Утримання Галявин Тірісфалю критично важливе для єдиної опори Орди на півночі Лордерону, тож знищення плацдармів Погибелі — тактичний пріоритет.",["race:Undead"]="Для Відступників вигнати Погибель із Млинів Аґаманда — глибоко особиста справа: це захищає їхні нові суверенні землі й трощить безтямних рабів Короля-Ліча, які колись тримали в рабстві їх самих."},sec={{t="Загроза над млинами",b="Млини Аґаманда колись були землеробським серцем Галявин Тірісфалю, та після Третьої війни їхні вітряки дивляться на значно похмуріші жнива. Сили Погибелі, підвладні Королю-Лічу, почали збиратися на цих землях. Якщо безтямні раби закріпляться на млинах, то здобудуть укріплену базу, з якої зможуть просуватися вглиб Тірісфалю і бити просто по молодих володіннях Відступників."},{t="Доказ знищення",b="Вартовий Смерті Діллінджер не марнує часу на сентименти. Відповідаючи за укріплення Брілла і порядок на його землях, Діллінджер наказує новобранцям вистежувати Солдатів-Брязкунів і Солдатів Тріснутого Черепа разом із Темноокими Заклиначами Кісток. Вимагаючи зазубрені ребра й почорнілі черепи як доказ знищення, Діллінджер пересвідчується, що скелетні лави справді розбивають на друзки, відкидаючи безтямні рештки назад до Чумних Земель, перш ніж їхній наступ по-справжньому почнеться."}},fp="17,379,29.436.0,20.469.0,47.249.0,28.232.0,36.199.0,40.228.0,67.234.0,42.239.0"}
P.entries["quest:427"] = {n="У війні з Багряним хрестовим походом",s="Екзекутор Зиґанд у Бріллі керує кампанією Відступників проти Багряного Хрестового Походу в Галявинах Тірісфалю. Спираючись на відомості, здобуті Екзекутором Арреном, ви вирушаєте знищити Багряних Воїнів у сторожовій вежі на захід від Хутора Соллідена. Цей штурм — перша наступальна операція війська Відступників, покликана вичистити ревних хрестоносців зі своїх кордонів.",h="Екзекутор Зиґанд у Бріллі керує кампанією Відступників проти Багряного Хрестового Походу в Галявинах...",kw={"багряний хрестовий похід","зиґанд","багряні воїни","хутір соллідена","вежа","наступ"},ang={["faction:Horde"]="Надійний кордон довкола Галявин Тірісфалю й Андерсіті — запорука того, що Орда матиме постійну опору у Східних Королівствах.",["race:Undead"]="Для Відступників Багряний Хрестовий Похід — гірка іронія: живі колишні земляки, які таврують їх потворами й прагнуть винищити, замість оплакувати трагічне падіння Лордерону."},sec={{t="Війна на два фронти",b="Молода держава Відступників під рукою Леді Сильвани Віндраннер стикається із загрозами одразу на кількох фронтах. Поки Вартові Смерті насторожено пильнують за зростанням армій Короля-Ліча, фанатичні смертні з Багряного Хрестового Походу оскаржують владу Відступників над їхньою колишньою батьківщиною. Хрестовий Похід вважає всю нежить мерзотою, яку слід вичистити вогнем і клинком, сліпий до того, що Відступники вирвалися з-під влади Погибелі."},{t="Удар по західній заставі",b="Завдяки розвідувальним документам, які Екзекутор Аррен здобув у Похоронному Подзвоні, Екзекутор Зиґанд тепер точно знає, які табори й застави тримають фанатики по всіх Галявинах Тірісфалю. Оскільки регулярні гарнізони Вартових Смерті зайняті стримуванням Погибелі, бити напряму доручають незалежним поборникам Відступників. Перша ціль — сторожова вежа західніше: поруч лежить Хутір Соллідена, а у вежі збираються Багряні Воїни, загрожуючи західним підступам до Брілла."}},fp="31,374,15.451.0,28.465.0,55.294.0,23.263.0,59.270.0,39.141.0,55.272.0,55.181.0"}
P.entries["quest:432"] = {n="Ці кляті троги!",s="Наглядач Стоунброу у відчаї: троги геть захопили його роботи в Кар'єрі Гол'Болар. Руйнівні й агресивні тварюки потрощили його гірниче обладнання та барила з порохом, і він лютує, вимагаючи відплати. Сам битися він не може — підводить око, — тож платить відважним шукачам пригод, щоб ті спустилися в кар'єр і проредили грубих Черепотрощів.",h="Наглядач Стоунброу у відчаї: троги геть захопили його роботи в Кар'єрі Гол'Болар.",kw={"троги","гол'болар","кар'єр","стоунброу","наглядач","черепотрощі","дун мороґ"},ang={["profession:Mining"]="Кар'єр Гол'Болар — важливий осередок дворфійського каменярства й видобутку руди. Вигнати загарбників — перший крок до того, щоб кирки знову замахали.",["race:Dwarf"]="Нашестя трогів у Каз Модані болить кожному дворфу. Бачити, як безмозкі грубі троги виганяють каменярів Гол'Болару, означає, що помста в кар'єрі стає особистою."},sec={{t="Хаос у кар'єрі",b="Кар'єр Гол'Болар був гордою, продуктивною дворфійською копальнею серед засніжених пагорбів східного Дун Мороґу. Процвітання раптово урвалося, коли підземні троги пробилися крізь породу й затопили нижні тераси. Дикуни не просто зайняли тунелі — вони чинять безглузде спустошення, трощать риштування і підривають цінні барила з вибуховим порохом."},{t="Кипуча лють Стоунброу",b="Споглядання руїни справи всього життя з безпечного гребеня довело Наглядача Стоунброу до нестями. Роздратований власними старечими руками й поганим прицілом, він покладається на перехожих мандрівників і новобранців Альянсу, щоб ті вчинили сувору відплату. Прорідження лав кремезних Черепотрощів із племені Кам'янощелепів дає йому коротку мить полегші, хоч по-справжньому його гнів вгамує лише цілковите винищення."}},fp="21,380,19.389.0,24.414.0,26.196.0,40.201.0,25.198.0,31.181.0,45.201.0,45.165.0"}
P.entries["quest:433"] = {n="Слуга народу",s="Сенатор Мер Стоунгаллов з Айронфорджа особисто прибув до Кар'єру Гол'Болар, щоб дати раду раптовому нашестю трогів, яке загрожує гірничій справі Дун Мороґу. Прагнучи повернути копальню, він наймає шукачів пригод, аби ті вирубали агресивних Костоломів із племені Кам'янощелепів і гірники змогли повернутися до роботи.",h="Сенатор Мер Стоунгаллов з Айронфорджа особисто прибув до Кар'єру Гол'Болар, щоб дати раду раптовому нашестю...",kw={"сенатор","стоунгаллов","гол'болар","троги","кар'єр","ліга дослідників","айронфордж"},ang={["faction:Alliance"]="Ресурси Айронфорджа вкрай важливі для всього Альянсу, тож оборона кар'єрів Дун Мороґу — економічна необхідність.",["profession:Mining"]="Гірники відчувають біль від зупинки Гол'Болару: багаті жили каменю й руди лежать покинуті під кийками трогів-загарбників.",["race:Dwarf"]="Прорив трогів у Гол'Боларі б'є просто по промисловості вашої батьківщини, ще раз доводячи, як дорого обходиться зустріч глибоких розкопок із підземними жахіттями."},sec={{t="Сенатор у полі",b="Нечасто побачиш члена Сенату Айронфорджа в сльоті й багнюці захопленої копальні, та Сенатор Мер Стоунгаллов — не звичайний політик. Належачи водночас до правлячого органу дворфів і до вченої Ліги Дослідників, Стоунгаллов узяв на себе особисту відповідальність за відсіч трогам у Кар'єрі Гол'Болар. Замість чекати на повільні законодавчі заходи він напряму наймає здібних найманців і мандрівників, щоб проредити загарбників."},{t="Лихо в Гол'Боларі",b="Кар'єр Гол'Болар був важливим джерелом каменю та мінеральних багатств Дун Мороґу, та глибокі розкопки пробилися до раніше запечатаних підземних порожнин. Первісні дикі троги з племені Кам'янощелепів ринули в кар'єр, трощачи тонке гірниче обладнання й виганяючи цивільних робітників. Мета Стоунгаллова — вичистити лютих Костоломів, щоб гарнізони горян змогли закріпитися в кар'єрі та відновити роботу копальні."}},fp="18,290,22.491.0,25.474.0,32.261.0,44.230.0,30.186.0,47.196.0,43.203.0,34.155.0"}
P.entries["quest:4495"] = {n="Добрий друг",s="Діранія Сілвершайн непокоїться, коли її постійний гість Іверрон не з'являється вчасно в Алдрассилі. Знаючи, що він часто навідується на пагорби біля кишенної павуками Печери Тіньової Нитки на півночі, вона просить перехожих шукачів пригод розшукати його.",h="Діранія Сілвершайн непокоїться, коли її постійний гість Іверрон не з'являється вчасно в Алдрассилі.",kw={"іверрон","діранія сілвершайн","печера тіньової нитки","павуки","тінедол","алдрассил"},ang={["class:Druid"]="Друїди, що пильнують природну рівновагу, упізнають в агресивних павуках Вебвуда біля Печери Тіньової Нитки симптом ширшого зіпсуття, яке вразило велике гілля.",["race:NightElf"]="Для юних калдорей, що починають свій шлях під Алдрассилом, відгукнутися на прохання Діранії — ранній урок громадської відповідальності й знайомство із загрозами, що тривожать колись мирну долину."},sec={{t="Зниклий гість",b="У тихому гіллі Тінедола щоденний лад укорінений глибоко, тож будь-яке відхилення від звички одразу впадає в око. Діранія Сілвершайн, що порається у своїх справах під захисною кроною Алдрассила, звикла до відвідин Іверрона — щодня, як за годинником. Коли минають години, а від нього ні звістки, тривога змушує її шукати допомоги в тих, хто вирушає в дикі хащі курганного гілля."},{t="Небезпека біля Печери Тіньової Нитки",b="Усі знають, що Іверрон любить блукати біля північних западин Тінедола, попри дедалі ближчу загрозу павуків Вебвуда. Печера Тіньової Нитки кишить агресивними павуками, тож сходити з утоптаних стежок для необачних мандрівників стає все небезпечніше. Обшукавши кам'янисті схили на захід від входу до печери, можна знайти Іверрона, який сховався там і відчайдушно потребує допомоги."}},fp="13,242,17.400.0,26.395.0,27.205.0,15.221.0,27.147.0,46.204.0,35.181.1,48.196.0"}
P.entries["quest:45"] = {n="З'ясуй долю Рольфа",s="«З'ясуй долю Рольфа» — завдання Альянсу в Лісі Елвінн, що йде слідом двох зниклих вартових Стормвінда. Знайшовши понівечені рештки вартового Малакая на березі Озера Кам'яного Кургану, ви рушаєте слідом перетинчастих відбитків на схід, у вороже селище мурлоків, щоб дізнатися, що сталося з його товаришем Рольфом.",h="«З'ясуй долю Рольфа» — завдання Альянсу в Лісі Елвінн, що йде слідом двох зниклих вартових Стормвінда.",kw={"рольф","малакай","мурлоки","озеро кам'яного кургану","вартовий томас","медальйон"},ang={["class:Warrior"]="Стояти над тілом Рольфа Гартфорда — суворе нагадування про криваву правду, з якою стикаються піхотинці передової, що служать королівству.",["faction:Alliance"]="Знайдений Рольф підтверджує вразливість сільських кордонів Стормвінда, де через нестачу людей у гарнізонах навіть звичайні патрулі беззахисні перед смертоносними нападами диких істот."},sec={{t="Слід перетинчастих лап",b="Вартовий Томас розіслав патрулі східним Лісом Елвінн, щоб стримати зростання загроз, але двоє вартових — Малакай і Рольф — зникли біля берегів Озера Кам'яного Кургану. Оглянувши напівз'їдені рештки Малакая, ви помічаєте перетинчасті сліди, вдавлені в багнюку: вони ведуть на схід уздовж води просто до занедбаного табору мурлоків."},{t="Кінець патруля",b="Сліди приводять вас у серце прибережного поселення мурлоків. Там лежить ще один труп, обібраний тварюками. На шиї полеглого солдата висить гравірований медальйон, що підтверджує його особу: піхотинець Рольф Гартфорд. Отже, жоден із вартових не пережив засідки."}},fp="20,314,24.348.0,17.298.1,13.206.1,29.137.1,46.199.0,46.115.1,32.168.1,54.175.0"}
P.entries["quest:456"] = {n="Рівновага природи",s="«Рівновага природи» — вступне завдання для щойно пробуджених нічних ельфів у Тінедолі. Консерватор Ілталайн доручає юним шукачам пригод прорідити надмірно розплоджених молодих нічних шаблезубів і будякових вепрів. Завдання знайомить нових героїв із давнім обов'язком калдорей — опікуватися природною злагодою Тельдрассила й берегти її.",h="«Рівновага природи» — вступне завдання для щойно пробуджених нічних ельфів у Тінедолі.",kw={"рівновага природи","консерватор ілталайн","нічні шаблезуби","будякові вепри","тінедол","тельдрассил"},ang={["class:Druid"]="Для майбутніх друїдів це проріджування — прямий урок суворої правди опіки Кола Кенарія: щоб уберегти дику природу, іноді доводиться проливати кров заради цілого.",["class:Hunter"]="Уміння вистежувати й проріджувати агресивну живність — підмурок єднання кожного мисливця зі звірами Калімдору.",["race:NightElf"]="Це завдання — перший крок вашого шляху як дорослого захисника калдорей: ви засвоюєте, що рівновага природи вимагає діяльного втручання й поваги."},sec={{t="Тендітна злагода",b="Тельдрассил може здаватися диким і древнім, але його екосистеми молоді й крихкі. У Тінедолі, захищеному розлогим гіллям Великого Дерева, рясні весняні дощі порушили тонкий лісовий цикл. Деякі види розплодилися понад те, що здатна прогодувати земля, і загрожують оголити долину й ввергнути всю екосистему в голод. Щоб уберегти ліс, потрібна діяльна опіка."},{t="Поклик Консерватора",b="Консерватор Ілталайн наглядає за лісами Тінедола, дбаючи, щоб жодна ланка не взяла гору над іншою. Щоб відвернути масовий голод серед звірів, він посилає юних нічних ельфів у гай проріджувати будякових вепрів і хижих нічних шаблезубів. Це непоказний, але життєво важливий обов'язок, що закладає основу філософії калдорей: злагода з природою вимагає діяльної рівноваги й непростих рішень."}},fp="21,366,18.438.0,22.425.0,51.232.0,30.178.0,33.157.0,43.162.0"}
P.entries["quest:457"] = {n="Рівновага природи",s="Це завдання продовжує зусилля Консерватора Ілталайна зберегти крихку екологію Тінедола: тепер треба прорідити дорослих будякових вепрів і шолудивих нічних шаблезубів. Поки живність Тельдрассила плодиться без упину, захисники нічних ельфів мають утрутитися, щоб надмір хижаків і травоїдів не оголив гілля.",h="Це завдання продовжує зусилля Консерватора Ілталайна зберегти крихку екологію Тінедола: тепер треба прорідити...",kw={"рівновага природи","консерватор ілталайн","нічні шаблезуби","будякові вепри","тінедол","алдрассил"},ang={["class:Druid"]="Друїдське вчення ставить злагоду вище сентиментів: проріджування розрослих зграй береже велике плетиво життя.",["class:Hunter"]="Полювання на прудких шаблезубів і впертих вепрів учить вистежувати й проріджувати — навичок, без яких природу не втримати в межах.",["race:NightElf"]="Для юних нічних ельфів це завдання — найперший урок суворої правди про опіку над дикою природою Тельдрассила."},sec={{t="Тягар опіки",b="Проріджування молодняку стабілізує майбутній ріст, але й дорослі популяції Тінедола становлять безпосередню загрозу для екосистеми Світового Дерева. Консерватор Ілталайн посилає юних захисників глибше в ліс — полювати на дорослих будякових вепрів і старих шолудивих нічних шаблезубів, перш ніж їхній ненаситний апетит вичерпає скінченні запаси рослин і дичини."},{t="Хижак і здобич",b="На північ від Алдрассила ліс змінюється: молодих дитинчат заступають плямисті нічні шаблезуби й агресивні вепри, що риють землю. Хоч убивати диких створінь — похмурий обов'язок, учення калдорей розглядає кероване полювання як неодмінну відповідальність, що береже весь ліс від екологічного краху."}},fp="21,315,23.352.0,17.307.0,57.207.0,58.197.0,30.197.0,54.205.0,47.185.0,43.168.0"}
P.entries["quest:458"] = {n="Захисниця лісу",s="«Захисниця лісу» — вступне завдання в Тінедолі від друїда Мелітара Стаґгелма. Стривожений шепотом лісових духів, Мелітар просить вас розшукати Тариндреллу — невловиму дріаду, яка несподівано повернулася до гаю. Її поява натякає, що під кроною Тельдрассила ворушиться щось тривожне.",h="«Захисниця лісу» — вступне завдання в Тінедолі від друїда Мелітара Стаґгелма.",kw={"захисниця лісу","тариндрелла","дріада","мелітар стаґгелм","тінедол","алдрассил"},ang={["class:Druid"]="Друїди глибоко шанують дріад як рідню в природі; відгукнутися на появу Тариндрелли — ранній поклик зважати на рівновагу Смарагдового Сну й лісів.",["race:NightElf"]="Для юних нічних ельфів, що виходять з Алдрассила, зустріч з однією з доньок Кенарія стає першим безпосереднім обов'язком у збереженні злагоди їхнього молодого Світового Дерева."},sec={{t="Шепіт у долині",b="Навчаючи новачків під гіллям Алдрассила, Мелітар Стаґгелм одержує тривожні знамення від лісових духів. Дріада Тариндрелла, яку шанують як захисницю дикої природи, знову з'явилася в Тінедолі після багатьох років відсутності в лісах Калімдору. Дріади рідко виходять без причини, тож Мелітар побоюється, що природний лад порушено."},{t="У пошуках дріади",b="Керуючись звітом розвідки Вартових, щойно пробуджені захисники вирушають на південний захід від Алдрассила, у довколишні ліси. Зустріч із Тариндреллою підтверджує чуття Мелітара: донька Кенарія справді повернулася, щоб дати раду скверні, яка підступає до кургану й сусідніх галявин."}},fp="22,332,20.372.0,17.314.1,22.148.0,29.106.0,19.222.0,43.198.0,39.182.0,59.238.0"}
P.entries["quest:459"] = {n="Захисниця лісу",s="Тариндрелла, дріада, що опікується Тінедолом, прагне з'ясувати, звідки взялися раптова агресія місцевих створінь і зникнення сусідніх фурболґів. Розслідуючи поведінку диких ґреллів і збираючи зразки зіпсутого Моху Скверни, шукачі пригод підтверджують: у корінні Світового Дерева почала гноїтися темна магія.",h="Тариндрелла, дріада, що опікується Тінедолом, прагне з'ясувати, звідки взялися раптова агресія місцевих...",kw={"захисниця лісу","тариндрелла","мох скверни","ґрелли","вузлошкіри","тінедол","доланаар"},ang={["class:Druid"]="Друїдів пов'язують священні узи з духами й дріадами лісу; дослідити заражений Мох Скверни конче потрібно, щоб розпізнати духовну хворобу, яка вразила Світове Дерево.",["race:NightElf"]="Для юних калдорей, що вирушають з Алдрассила, це завдання — раннє й тривожне усвідомлення, що їхня священна нова домівка вразлива до зіпсуття зсередини."},sec={{t="Пошесть на галявині",b="Навіть у відлюдних висотах Тінедола спокійна природа Тельдрассила почала тріскатися. Дріади, як-от Тариндрелла, помітили темний злам, що прокотився лісами. Колись сумирні фурболґи покинули лігва предків і згуртувалися в агресивне плем'я Вузлошкірів, а здичавілі ґрелли та ґреллкіни заполонили лісові стежки."},{t="Заражений ріст",b="Тариндрелла підозрює, що ворожість лісу живить неприродне зіпсуття. Винищуючи зграї ґреллів і збираючи зразки Моху Скверни, ви здобуваєте незаперечний доказ темних чарів, що чіпляються за гілля Тельдрассила. Коли гірку правду підтверджено, Тариндрелла скеровує юних захисників до села Доланаар — на раду з друїдом Атрідасом Бермантлом."}},fp="22,329,21.359.0,14.372.0,19.237.0,17.205.0,44.231.0,40.255.0,29.210.0,40.231.0"}
P.entries["quest:46"] = {n="Винагорода за мурлоків",s="Армія Стормвінда оголосила публічну винагороду за племена мурлоків, що розповзаються східним Лісом Елвінн. Гарнізон розтягнутий до краю, тож Вартовий Томас покладається на мандрівних шукачів пригод: ті мають винищити прибережні табори довкола Озера Кам'яного Кургану та південних річок, поки мурлоки не заполонили ферми й дороги краю.",h="Армія Стормвінда оголосила публічну винагороду за племена мурлоків, що розповзаються східним Лісом Елвінн.",kw={"винагорода","мурлоки","вартовий томас","озеро кам'яного кургану","плавці","ліс елвінн"},ang={["class:Hunter"]="Багнисті береги й зарослі очеретом узбережжя Озера Кам'яного Кургану — ідеальне місце, щоб вправлятися у вистежуванні спритних водяних хижаків, які діють зграєю.",["faction:Alliance"]="Зачищені річки бережуть життєво важливі лінії постачання й сільські садиби між Ґолдширом і кордоном із Редріджем.",["race:Human"]="Для підданих Стормвінда цей контракт — суворе нагадування про те, якою тонкою стала оборона їхнього королівства просто біля серця столиці."},sec={{t="Загроза на річках",b="Західні дороги Лісу Елвінн порівняно безпечні, та у східних водах шириться земноводна навала. Мурлоки-причаєнці та мурлоки-збирачі заклали агресивні прибережні поселення довкола Озера Кам'яного Кургану й уздовж розвилки південних струмків. Те, що спершу здавалося дрібною прикрістю, швидко перетворилося на захоплення територій: озброєні мурлоки нападають на подорожніх і підступають до людських поселень."},{t="Розтягнута оборона",b="Вартовий Томас, що стоїть на східному мосту біля кордону з Горами Редріджу, опиняється між зовнішніми небезпеками й місцевим безладом. Король Варіан Рінн зник, військове командування Стормвінда загрузло в бюрократичному паралічі, тож міські гарнізони рідко отримують підкріплення, про які просять. Маршал Дуґан і місцеві офіцери вдалися до офіційних винагород — платять монетою за відрубані плавці, щоб стримати водяний приплив."}},fp="17,321,25.447.0,18.433.0,43.252.0,29.203.0,41.164.0,54.267.0,49.126.0,66.180.0"}
P.entries["quest:466"] = {n="Пошуки інцендициту",s="Пілот Стоунґір зі Складу Стілґрила шукає зразки летючої руди інцендициту, знайденої в Багнокраї. Вірячи, що її вибухові властивості можуть докорінно змінити артилерійські боєприпаси, він доручає гірникам вирушити на північ і видобути небезпечний мінерал з усамітненої печери.",h="Пілот Стоунґір зі Складу Стілґрила шукає зразки летючої руди інцендициту, знайденої в Багнокраї.",kw={"інцендицит","руда","стоунґір","багнокрай","брама алґаз","артилерія","вибухівка"},ang={["profession:Engineering"]="Вибухові сполуки, що загрожують підірвати власних творців, — щоденна справа для інженерів-винахідників у пошуках наступного великого вибуху.",["profession:Mining"]="Видобуток інцендициту потребує досвідчених рук із киркою: летючість мінералу робить обережне виймання жили справжнім випробуванням майстерності гірника.",["race:Dwarf"]="Дворфійські інженери й артилеристи славляться тим, що рухають порохову справу вперед, і снаряди з інцендициту цілком вписуються в облогові традиції Каз Модану."},sec={{t="Небезпечне відкриття",b="Чутка про рідкісний і нестабільний мінерал, відомий як інцендицит, дійшла до авіаторів і механіків Складу Стілґрила. Подейкують, що багаті жили лежать у печері на північний захід від Брами Алґаз, серед просяклих вологою боліт Багнокраю. Надзвичайно реактивний і небезпечний у руках, інцендицит зажив слави тим, що вибухає просто в обличчя необережним гірникам."},{t="Боєприпаси майбутнього",b="Там, де інші бачать гірничу небезпеку, Пілот Стоунґір бачить військовий потенціал. Якщо належно його очистити, інцендицит може стати руйнівним метальним зарядом або начинкою для дворфійської артилерії — гарматними снарядами, здатними трощити укріплення. Стоунґір хоче роздобути сирі зразки, щоб відважні — або нерозважливі — дослідники могли почати випробування способів виплавки, не зрівнявши склад із землею."}},fp="22,275,20.352.0,21.392.0,33.191.0,27.125.0,23.168.0,47.204.0,30.135.0,44.188.0"}
P.entries["quest:47"] = {n="Обмін Золотого Пилу",s="«Обмін Золотого Пилу» — одна з перших винагород, яку пропонує Ремі «Двічі» з Ґолдшира. Нервовий посередник платить шукачам пригод за те, щоб вони відбирали сирий золотий пил у кобольдів, які заполонили копальні по всьому Лісі Елвінн. Для мандрівників-початківців це чесний заробіток, та дивні зв'язки Ремі натякають, що за його метушнею криється щось більше за просту роботу з металом.",h="«Обмін Золотого Пилу» — одна з перших винагород, яку пропонує Ремі «Двічі» з Ґолдшира.",kw={"золотий пил","ремі двічі","кобольди","фарґодіп","яшмова копальня","ґолдшир","обмін"},ang={["class:Rogue"]="Притишена манера Ремі та знак від безіменних «партнерів» мають безпомильний запах підпільних синдикатів, що діють під спокійною поверхнею Ґолдшира.",["faction:Alliance"]="Те, що життєво важливі поклади золота й мінералів Елвінну тримають здичавілі кобольди, а не королівські рудокопи, показує, наскільки виснажені військові сили королівства.",["profession:Mining"]="Рудокопи, що обшукують Фарґодіп і Яшмову копальню, знайдуть кобольдів просто на найбагатших мідних жилах, тож без зачистки руди не добути."},sec={{t="Містечко кишень і кайл",b="Ґолдшир стоїть на перехресті Лісу Елвінн, де змішуються купці, міська варта й утомлені подорожні. Серед них — Ремі «Двічі», підозрілий тип, чия невідчепна звичка повторювати власні слова приховує гостре око на зиск. Замість наймати дорогі бригади рудокопів, Ремі користається з мандрівних шукачів пригод, що плинуть через Корчму «Лев'яча Гордість». Його пропозиція проста: заберіть золотий пил, який накопичили місцеві шкідники, і обміняйте його просто на монети."},{t="Здобич кобольдів",b="Кобольди цілком захопили найцінніші підземні розробки Елвінну — Копальню Фарґодіп на півдні та Яшмову копальню на північному сході. Довбаючи темряву заради своїх улюблених свічок і блискучих цяцьок, ці щуроподібні землерийки збирають у торбини крихти й пил неочищеної руди. Відганяти їх — в інтересах королівства, а збирати їхній пил означає перетворити винищення шкідників на прибуткову справу."},{t="Тіні за прилавком",b="Ремі запевняє, що платить щедро з чисто купецьких міркувань, та його винагороди несуть ледь помітне застереження. Отримавши пил, він тицяє помічникам маленький знак від своїх «партнерів». В Елвінні, який дедалі міцніше душать організовані бандити, несплачені каменярі й таємні мережі, що діють у тіні Стормвінда, тихі посередники Ремі можуть мати на це золото плани, які сягають значно далі за звичайну сільську торгівлю."}},fp="18,350,27.491.0,18.444.0,26.430.1,24.246.0,31.255.0,45.216.0,56.269.0,45.222.0"}
P.entries["quest:475"] = {n="Тривожний вітер",s="«Тривожний вітер» — раннє завдання від Атрідаса Бермантла в Тельдрассилі: з'ясувати, чому припинилися звістки із Села Зоряного Вітерця. Великий Наглядач Ґеролас Талветрен стереже неподалік Друїдів Кігтя, що сплять у зимовому сні, і його раптове мовчання підказує, що Світовим Деревом повзе неприродна небезпека.",h="«Тривожний вітер» — раннє завдання від Атрідаса Бермантла в Тельдрассилі: з'ясувати, чому припинилися звістки...",kw={"тривожний вітер","атрідас бермантл","ґеролас талветрен","село зоряного вітерця","друїди кігтя","тельдрассил"},ang={["class:Druid"]="Друїди з глибоким трепетом ставляться до Курганного Лігва Бан'етіл і сплячих, пов'язаних з Ізерою, тож будь-яка загроза їхнім наглядачам — нагальна особиста справа.",["race:NightElf"]="Для нічних ельфів охорона священного спочинку Друїдів Кігтя — запорука збереження тонкої рівноваги їхньої нової домівки на Тельдрассилі."},sec={{t="Мовчазний вартівник",b="У поселеннях на гіллі Тельдрассила звістки зазвичай ходять швидко й розмірено. Атрідас Бермантл покладається на вісті від Ґероласа Талветрена — Великого Наглядача, якому довірено пильнувати Друїдів Кігтя, що спочивають у Курганному Лігві Бан'етіл. Ці сплячі друїди підтримують священну угоду з Ізерою у Смарагдовому Сні, тож їхнє святилище життєво важливе для духовної рівноваги молодого Світового Дерева. Коли звістки зі сходу урвалися, лісовою кроною розлилося тривожне передчуття."},{t="Неспокій у Зоряному Вітерці",b="Атрідас просить мандрівників вирушити лісом на схід, до Села Зоряного Вітерця, і розшукати Ґероласа особисто. Відсутність гінців — не просто недогляд: у хащах заворушилися мерзенне зіпсуття й збурена живність. Діставшись Ґероласа, ви переконуєтеся, що чуття Атрідаса не підвело: на село впало лихо, яке загрожує безпеці сусідніх курганних лігв."}},fp="18,302,16.513.0,20.392.1,27.190.0,27.198.0,33.181.0,32.200.0,32.215.1,51.177.0"}
P.entries["quest:476"] = {n="Зіпсуття Вузлошкірів",s="«Зіпсуття Вузлошкірів» — нагальне кур'єрське завдання в Тельдрассилі від імені пораненого Великого Наглядача Ґероласа Талветрена. Воно попереджає проводирів нічних ельфів у Доланаарі, що фурболґи Вузлошкіри піддалися демонічному зіпсуттю й захопили Село Зоряного Вітерця. Ця доповідь готує ґрунт для військового й друїдського втручання, щоб скверна не дісталася сплячих друїдів Курганного Лігва Бан'етіл.",h="«Зіпсуття Вузлошкірів» — нагальне кур'єрське завдання в Тельдрассилі від імені пораненого Великого Наглядача...",kw={"зіпсуття вузлошкірів","ґеролас талветрен","атрідас бермантл","урсал гамаїло","мох скверни","село зоряного вітерця","доланаар"},ang={["class:Druid"]="Загроза Курганному Лігву Бан'етіл — питання життя й смерті для Кола Кенарія, адже сплячі брати беззахисні перед зіпсутим плем'ям Вузлошкірів.",["race:NightElf"]="Падіння Села Зоряного Вітерця — трагічне потрясіння: воно доводить, що навіть щойно вирощене Світове Дерево вже вразливе до демонічної скверни, яку нічні ельфи так тяжко викорінювали."},sec={{t="Відчайдушне попередження",b="Ґеролас Талветрен лежить тяжко поранений біля руїн Села Зоряного Вітерця: на нього напали з засідки колишні союзники. Фурболґи Вузлошкіри, яких довго мали за мирних сусідів і опікунів дикої природи, раптово здичавіли. Надто скалічений, щоб самому донести звістку до своїх, Ґеролас довіряє шукачеві пригод чимшвидше передати слово Атрідасові Бермантлу в Доланаар, поки безумство не розповзлося гіллям Тельдрассила ще далі."},{t="Пошесть Моху Скверни",b="Доповідь, доставлена Атрідасові, відкриває тривожну правду: фурболґи не просто стали неспокійними — їх навмисне піддають магії Скверни. Їхній вождь Урсал Гамаїло приборкав зіпсутий Мох Скверни, що гноїться у Світовому Дереві, і ввергнув своє плем'я в кривавий шал. Це відкриття загрожує не лише поселенням на кшталт Зоряного Вітерця — воно безпосередньо ставить під удар сусіднє Курганне Лігво Бан'етіл, де сплячі друїди цілком беззахисні перед знавіснілим плем'ям."}},fp="20,418,19.457.0,23.506.1,36.218.0,47.226.0,27.272.0,27.205.0,59.211.0,17.186.0"}
P.entries["quest:483"] = {n="Реліквії Пробудження",s="«Реліквії Пробудження» — нагальна рятувальна місія: врятувати Друїдів Кігтя, що сплять у Курганному Лігві Бан'етіл. Зіпсуті фурболґи Вузлошкіри захопили священні кургани й загрожують сплячим друїдам, чиї духи блукають Смарагдовим Сном. Без чотирьох особливих ритуальних реліквій сплячих не вдасться безпечно повернути до світу яви.",h="«Реліквії Пробудження» — нагальна рятувальна місія: врятувати Друїдів Кігтя, що сплять у Курганному Лігві...",kw={"реліквії пробудження","друїди кігтя","курганне лігво бан'етіл","вузлошкіри","атрідас бермантл","смарагдовий сон"},ang={["class:Druid"]="Для юних друїдів напад на Бан'етіл — прямий удар по братах із Кола Кенарія. Здобувши реліквії, ви доводите свій обов'язок берегти священний міст між смертною землею і Смарагдовим Сном.",["race:NightElf"]="Осквернення курганного лігва на самому гіллі Тельдрассила підкреслює, з якою тривожною швидкістю зіпсуття спотворює плем'я Вузлошкірів і розхитує рівновагу вашої нової домівки."},sec={{t="Осквернене святилище",b="Курганні лігва — відлюдні святилища, де друїди нічних ельфів лежать у глибокому сні, блукаючи Смарагдовим Сном. На захід від Доланаара звивисті коридори Курганного Лігва Бан'етіл опинилися під навалою зіпсутих фурболґів Вузлошкірів. Доведені до безумства мерзенною скверною, що шириться Тельдрассилом, ці колишні союзники осквернили святилище й загрожують беззахисним сплячим, які й не підозрюють про небезпеку, що нависла над їхніми тілами."},{t="Знаряддя повернення",b="Друїда, що зайшов у Сон, не можна просто розбудити струсом: грубо урвати його сон без належного духовного якоря означає розтрощити розум або назавжди лишити дух у блуканні. Щоб провести тонкий обряд пробудження, Атрідасові Бермантлу потрібні чотири священні реліквії, замкнені у скринях по всьому лігву: Талісман Воронячого Пазура, Чорне Перо, Сапфір Небес і Руна Гніздування. Повернути їх — єдина надія розбудити Друїдів Кігтя, перш ніж Вузлошкіри переріжуть або викрадуть їх усіх."}},fp="22,369,17.479.0,19.520.0,42.283.0,32.253.0,56.265.0,41.207.0,27.214.0,38.120.0"}
P.entries["quest:486"] = {n="Урсал Гамаїло",s="«Урсал Гамаїло» — вінець зусиль Атрідаса Бермантла пробудити сплячих Друїдів Кігтя в Тельдрассилі. Щоб розірвати неприродний сон, який скував його братів у Курганному Лігві, треба вбити зіпсутого вождя фурболґів, винного в тому, що їхній поклик урвався.",h="«Урсал Гамаїло» — вінець зусиль Атрідаса Бермантла пробудити сплячих Друїдів Кігтя в Тельдрассилі.",kw={"урсал гамаїло","вузлошкіри","друїди кігтя","атрідас бермантл","ущелина","тельдрассил","смарагдовий сон"},ang={["class:Druid"]="Зберегти священні обряди Смарагдового Сну — понад усе. Втручання Урсала у справи Друїдів Кігтя — тяжке осквернення єднання Кола Кенарія.",["faction:Alliance"]="Убезпечення внутрішніх доріг Тельдрассила й відновлення кола друїдів зміцнює твердиню нічних ельфів, поки вони вливаються до ширшого Альянсу.",["race:NightElf"]="Фурболґи Вузлошкіри колись були давніми союзниками калдорей. Убити їхнього знавіснілого ватажка Урсала — трагічна необхідність, щоб захистити ваших родичів і сплячих друїдів."},sec={{t="Сон, що став жахіттям",b="Друїди Кігтя усамітнилися в Курганному Лігві Бан'етіл, щоб спати й єднатися зі Смарагдовим Сном. Та їхній мирний транс обернувся на в'язницю без виходу. Атрідас Бермантл визначив, що саме фурболґи Вузлошкіри — а надто їхній лютий ватажок Урсал Гамаїло — втрутилися у священний обряд друїдів і лишили їх у пастці між явою і Сном."},{t="Лігво в Ущелині",b="Зібрати Реліквії Пробудження було лише половиною справи. Щоб обряд пробудження Атрідаса пробився крізь духовний туман, що скував друїдів, джерело втручання треба було погасити. Урсал Гамаїло влаштував собі лігво глибоко в Ущелині — запалій, зіпсутій розколині на північ від головної дороги через Тельдрассил. Здолавши фурболґа-воєначальника, ви розриваєте його владу над розумом сплячих."},{t="Симптом глибшої гнилі",b="Хоч смерть Урсала дає Атрідасові змогу провести обряд і врятувати Друїдів Кігтя, вона не лікує недуги Тельдрассила. Як зауважує Атрідас, коли ви повертаєтеся, дикий фурболґ лише діяв під впливом темнішого зіпсуття, що шириться гіллям Світового Дерева. Поразка Урсала звільняє сплячих, але першопричина безумства, яке труїть плем'я Вузлошкірів, і далі чаїться в тіні."}},fp="16,285,26.408.0,20.400.0,23.413.1,24.223.0,46.247.0,36.149.0,58.193.1,32.216.0,27.176.0"}
P.entries["quest:487"] = {n="Дорога до Дарнасуса",s="Головна дорога, що з'єднує поселення Доланаар зі столицею нічних ельфів Дарнасусом, перебуває під постійною загрозою зіпсутих фурболґів Вузлошкірів. Місячна Жриця Амара координує розвідників і мандрівників, щоб уберегти цей важливий торговий і поштовий шлях від засідок.",h="Головна дорога, що з'єднує поселення Доланаар зі столицею нічних ельфів Дарнасусом, перебуває під постійною...",kw={"дорога до дарнасуса","місячна жриця амара","вузлошкіри","засідки","доланаар","дарнасус","тельдрассил"},ang={["class:Priest"]="Допомога Місячній Жриці Амарі — служіння Сестринству Елуни, яке дає молодому дереву і духовний провід, і ратний захист.",["faction:Alliance"]="Дарнасус — серце присутності Альянсу на півночі Калімдору; безпечний рух торгівлі й звісток його головним шляхом конче потрібен.",["race:NightElf"]="Вузлошкіри колись були шляхетною ріднею дикої природи; нищити зіпсутих засідників уздовж шляху до Дарнасуса — похмура необхідність, породжена хворобою Тельдрассила."},sec={{t="Життєва артерія в облозі",b="Дорога, що тягнеться на захід від Доланаара до Дарнасуса, — головна сухопутна артерія Тельдрассила. Нею щодня мають рухатися життєво важливі товари, політичні послання й мандрівники, щоб підтримувати зв'язок між столицею і гіллям великого дерева. Оскільки Тельдрассил ще молодий і дикий, безпечні дороги критично важливі для юних громад калдорей."},{t="Загроза Вузлошкірів",b="Плем'я фурболґів Вузлошкірів у Тельдрассилі — уже не мирні лісові мешканці: воно стало жертвою мерзенного зіпсуття. Збожеволілі від хвороби, що мучить гілля Світового Дерева, вони вдаряють назовні з потаємних лігв під хребтами. Нишпорячи вздовж узлісся при дорозі, засідники Вузлошкірів полюють на необачних кур'єрів і мандрівників, перетворюючи мирну лісову прогулянку на смертельний прохід крізь стрій."},{t="Варта Вартових",b="Щоб протистояти засідникам, Місячна Жриця Амара тримає варту за межами Доланаара. Поєднуючи духовний авторитет жрецтва Елуни з військовою пильністю Вартових, вона скеровує здібних шукачів пригод нищити засідників біля їхніх лігв нижче від дороги, щоб забезпечити безпечний шлях до брам Дарнасуса."}},fp="21,269,22.385.0,20.418.0,20.319.0,60.230.0,28.272.0,42.264.0,31.172.0,70.246.0,57.234.0"}
P.entries["quest:488"] = {n="Доручення Зенна",s="«Доручення Зенна» — завдання Альянсу від Зенна Фаулгуфа, самотнього сатира, що чаїться на північ від дороги між Тінедолом і Доланааром. Він підбиває завзятих шукачів пригод полювати на місцеву живність і збирати для його невідомих задумів частини звірів, користаючись із довірливості й наївності новачків на Тельдрассилі.",h="«Доручення Зенна» — завдання Альянсу від Зенна Фаулгуфа, самотнього сатира, що чаїться на північ від дороги...",kw={"доручення зенна","зенн фаулгуф","сатир","обман","нічні шаблезуби","тінедол","доланаар"},ang={["class:Druid"]="Друїди присягнули берегти рівновагу природи. Браконьєрство на нічних шаблезубів, сов і павуків на догоду спотвореному створінню зіпсуття — наруга над ученням Кола Кенарія.",["race:NightElf"]="Для юного нічного ельфа виконувати накази сатира — глибока ганьба. Сатири — зрадники предків, зіпсуті Палаючим Легіоном, і допомагати одному з них на гіллі Тельдрассила — злочин проти природи й спадщини калдорей."},sec={{t="Сумнівна угода",b="Мандрівники, що виходять із Тінедола стежкою до Доланаара, можуть натрапити на Зенна Фаулгуфа, який невимушено стоїть під гіллям Великого Дерева. Замість відкритої ворожості сатир обіцяє щедру винагороду й таємниці в обмін на буденні доручення. Він просить шукачів пригод добути ікла нічних шаблезубів, пера сов-стригідів і шовк павуків Вебвуда з навколишніх лісів, змовницьки шепочучи, щоб домовленість лишилася між ними."},{t="Жарт сатира",b="Сатири — давні вороги калдорей, спотворені демонічною магією під час Війни Древніх, тож сама присутність Зенна на Тельдрассилі — зухвалість. Довірливі шукачі пригод, виконавши його доручення, швидко виявляють, що з них поглузували. Замість скарбів чи глибоких одкровень Зенн відверто регоче з того, яким легковірним треба бути, щоб служити сатирові, і тішиться, що обдурив наївного чужинця й змусив його зробити брудну роботу."}},fp="14,313,17.484.0,16.443.1,21.242.0,43.271.0,53.232.0,46.278.0,45.230.1,31.116.0"}
P.entries["quest:489"] = {n="Шукай спокути!",s="«Шукай спокути!» — завдання, яке в Доланаарі дають шукачам пригод, що дали себе обдурити й зробили брудну роботу за сатира Зенна Фаулгуфа. Рада Лісу вимагає покаяння за шкоду лісовим звірам і посилає вас обхитрити підступного сатира — підсунути йому зіпсуті шишки Скверни.",h="«Шукай спокути!» — завдання, яке в Доланаарі дають шукачам пригод, що дали себе обдурити й зробили брудну...",kw={"шукай спокути","зенн фаулгуф","сатир","рада лісу","шишки скверни","жаба","доланаар"},ang={["class:Druid"]="Друїди вважають рівновагу Тельдрассила священною; полювати на хижаків і падложерів за наказом вигнанця, заплямованого демонами, — пряме порушення заповідей опіки Кола Кенарія.",["race:NightElf"]="Для калдорей допомагати сатирові — глибоке приниження. Сатири — давні вороги, спотворені Палаючим Легіоном під час Війни Древніх, тож спокута перед Радою Лісу — справа честі всього народу."},sec={{t="Виправлена помилка",b="Зенн Фаулгуф, самотній сатир, що чаїться одразу за Доланааром, обманом змушує перехожих виконувати його волю. Шукачі пригод, які мимоволі вирізали нічних шаблезубів, сов-стригідів і павуків Вебвуда задля його збочених апетитів, незабаром накликають на себе гостре невдоволення Ради Лісу. Рада не терпить наруги над природою — а надто від власних союзників."},{t="Ціна спокути",b="Хто б не застеріг вас — Сірал Блейдліф, Вартова Кіра Старсонг чи Вартова Шайла Найтбріз, — суть одна: щоб лишатися бажаним гостем на Тельдрассилі, треба загладити провину. Замість іти на Фаулгуфа з голою сталлю, охоронці Доланаара велять вам скористатися його ницою ненажерливістю. Зібравши з лісової підстилки роздуті зіпсуті шишки Скверни, ви пригощаєте нічого не підозрюване створіння його ж мерзенними ліками."},{t="Квакуча відплата",b="Удаючи ще одного вірного посильного, що приніс солодкий гостинець, ви вручаєте Фаулгуфові отруйні шишки. Не здогадуючись про друїдську пастку, що зімкнулася довкола нього, Зенн жадібно поглинає підношення — і тут-таки обертається на безпорадну жабу, позбавлену своїх підлих задумів і принижену перед дикою природою, яку хотів осквернити."}},fp="16,274,22.393.0,22.426.0,22.331.1,47.287.0,27.247.0,19.236.0,41.153.1,49.292.0,65.204.0"}
P.entries["quest:492"] = {n="Нова чума",s="Це завдання — похмура кульмінація початкових досліджень Аптекаря Йогаана у Бріллі від імені Королівського Аптекарського Товариства. Зібравши по всіх Галявинах Тірісфалю отруту, кров і мерзенні суміші, Йогаан посилає вас у підвал Таверни «Шибеничний Кінець» — випробувати його смертоносне вариво на полоненому дворфі-горянині.",h="Це завдання — похмура кульмінація початкових досліджень Аптекаря Йогаана у Бріллі від імені Королівського...",kw={"нова чума","йогаан","дворф","горянин","отрута","таверна","айронфордж"},ang={["faction:Alliance"]="Доля полоненого горянина показує абсолютну безжальність Відступників до зайд з Альянсу, викритих у Лордероні.",["faction:Horde"]="Поки ваші союзники з Калімдору б'ються за честь і виживання, Відступники йдуть до перемоги через холоднокровну алхімічну війну, що не щадить ні друга, ні ворога.",["race:Dwarf"]="Нещасний бранець утілює далекосяжну присутність Горян Айронфорджа, які ризикують смертю й таємними допитами, щоб наглядати за Галявинами Тірісфалю.",["race:Undead"]="Виконання експерименту Йогаана дає з перших рук побачити безкомпромісну доктрину виживання Відступників і смертоносну працю Королівського Аптекарського Товариства."},sec={{t="Смертельна суміш",b="Увесь час, допомагаючи Аптекарю Йогаану, ви крок за кроком наближали створення смертельної отрути. Королівське Аптекарське Товариство переслідує амбітну й тіньову мету від імені Леді Сильвани Віндраннер: створити нову чуму, яка омине біологію нежиті, та знищить живих. На цьому останньому етапі Йогаан варить те, що евфемістично називає «особливим напоєм», і доручає вам власноруч дати його ув'язненому ворогові Відступників."},{t="Підвал «Шибеничного Кінця»",b="Під Таверною «Шибеничний Кінець» у Бріллі Вартові Смерті тримають вогкий підвал — саморобну камеру для бранців, що чекають на допит чи ліквідацію. Серед них сидить полонений Дворф-Горянин, боєць розвідувальних загонів Айронфорджа, який незаконно проник у Галявини Тірісфалю. Непокірний і спраглий, він радо приймає напій, навіть не підозрюючи про його справжнє алхімічне начиння."},{t="Моторошна демонстрація",b="Отримавши пляшку, горянин охоче п'є, з тугою порівнюючи напій із Солодом Рапсодії й вихваляючись, що дворфійські парові танки вже йдуть його рятувати. Отрута діє майже миттєво і вбиває його на місці. Прощальні слова Йогаана звучать із моторошною ясністю: цей смертельний ковток — лише проба того, що Темна Леді готує решті Азероту."}},fp="12,317,19.467.0,23.389.0,24.367.1,25.277.0,39.263.0,50.226.1,47.243.0,42.138.0,49.258.0"}
P.entries["quest:52"] = {n="Захист рубежу",s="«Захист рубежу» — доручення Альянсу, яке Вартовий Томас дає біля східного мосту через річку в Лісі Елвінн. Що ближче до кордону, то рідша військова присутність Стормвінда, і дикі хижаки знахабніли — нападають на подорожніх і робітників Лісозаготівельного Табору Східної Долини. Вартовий Томас шукає здібних шукачів пригод, щоб винищити вовків і ведмедів, які загрожують східному рубежу.",h="«Захист рубежу» — доручення Альянсу, яке Вартовий Томас дає біля східного мосту через річку в Лісі Елвінн.",kw={"захист рубежу","вовки","ведмеді","вартовий томас","східна долина","лісозаготівля","ліс елвінн"},ang={["class:Hunter"]="Вовки й ведмеді, що никають східним Лісом Елвінн, — рання перевірка вміння вистежувати й влучно стріляти по лютій місцевій дичині.",["faction:Alliance"]="Безпечні східні дороги забезпечують постачання деревини зі Східної Долини, що підтримує відбудову й оборону по всіх землях Альянсу."},sec={{t="Оборона, що рідшає",b="Ґолдшир і Долина Нортширу мають помітний гарнізон Стормвінда, а от далекий східний край Лісу Елвінн захищений значно гірше. Вартовий Томас несе варту біля мосту через річку — один із небагатьох чатових між обжитими землями й небезпечними нетрями. Ресурси королівства розтягнуті до краю, тож самотнім вартовим лишається покладатися на добровольців, що проходять повз, аби тримати відкритими життєво важливі шляхи постачання."},{t="Хижа загроза",b="Лісозаготівельний Табір Східної Долини вкрай важливий для постачання деревини до Стормвінда, та рубання дерев на узліссі зводить лісорубів віч-на-віч із місцевою звіриною. Вовки-причаєнці, сірі лісові вовки й молоді лісові ведмеді стають дедалі агресивнішими й блукають біля доріг і лісоскладів. Прорідити їх означає на якийсь час полегшити життя місцевим робітникам, хоч Вартовий Томас підозрює, що звірів до поселень жене якась невидима тривога глибше в лісі."}},fp="20,389,18.434.0,20.498.0,41.186.0,48.288.0,35.155.0,46.294.0,45.152.0,41.219.0"}
P.entries["quest:5261"] = {n="Іґан Пелтскіннер",s="Це коротке вступне завдання посилає щойно прибулих у Долину Нортширу новобранців поговорити з Іґаном Пелтскіннером, місцевим хутровиком, що працює біля Абатства Нортшира. Хижаків на околицях долини дедалі більше, тож Іґану потрібні здібні шукачі пригод, щоб полювати на лісових вовків і збирати шкури.",h="Це коротке вступне завдання посилає щойно прибулих у Долину Нортширу новобранців поговорити з Іґаном...",kw={"іґан пелтскіннер","хутровик","вовки","шкури","нортшир","помічник віллем"},ang={["faction:Alliance"]="Кожне дрібне завдання в Нортширі допомагає убезпечити рідні землі Стормвінда, поки основна армія королівства розтягнута деінде.",["race:Human"]="Для молодих людей, що виходять із Абатства Нортшира, допомога місцевим ремісникам на кшталт Іґана — найперший урок захисту батьківщини."},sec={{t="Розмова з хутровиком",b="Долина Нортширу може здаватися ідилічною, та її тихі сади й поля межують із дикими лісами, що кишать лісовими вовками. Помічник Віллем часто направляє новобранців за мури абатства до Іґана Пелтскіннера, який працює поруч, на землях абатства. Іґан залюбки дає новачкам роботу: проріджувати агресивні зграї й здобувати цінні шкури для його ремесла."},{t="Клопіт на околицях",b="Вовки, яких довкола Нортширу дедалі більшає, — не просто прикрість: вони загрожують робітникам, послушникам і обозам, що входять у долину й виходять із неї. Направляючи молодих героїв до Іґана, маршали Стормвінда вбивають двох зайців: ближні стежки стають безпечними, а нечисленні вартові гарнізону, які й так мають справу зі зростанням напруги по всьому Лісі Елвінн, лишаються вільними."}},fp="17,299,23.367.0,24.376.0,46.176.0,35.153.0,43.185.0,51.164.0,50.219.0,50.146.0"}
P.entries["quest:5481"] = {n="Завдання Ґордо",s="Завдання Ґордо — доручення в Галявинах Тірісфалю від Ґордо, мандрівної гидоти, яка намагається збирати трави вздовж дороги до Брілла. Непридатний до тонкої польової роботи, він наймає мандрівників рвати Похмуру Траву й нести її своєму наглядачеві, Молодшому Аптекарю Голланду.",h="Завдання Ґордо — доручення в Галявинах Тірісфалю від Ґордо, мандрівної гидоти, яка намагається збирати трави...",kw={"завдання ґордо","ґордо","гидота","похмура трава","голланд","аптекар"},ang={["profession:Herbalism"]="Для навчених травників це завдання — дрібниця: їхнє чуття легко виявляє зарості Похмурої Трави серед спустошеної трави.",["race:Undead"]="Для новопіднятих Відступників, що виходять із Похоронного Подзвону, це завдання — перша зустріч із незграбною дійсністю праці гидот і гострим норовом Королівського Аптекарського Товариства."},sec={{t="Незграбний робітник",b="Ґордо — гидота, що тупає туди-сюди сільськими дорогами між Похоронним Подзвоном і Бріллом. Гидоти неперевершені в грубому бою і важкому перенесенні, та їхні величезні зшиті руки роблять тонку роботу майже неможливою. Посланий на луки збирати інгредієнти для Королівського Аптекарського Товариства, Ґордо швидко з'ясовує, що його тупі пальці більше чавлять стебел, ніж рвуть, тож він залякуванням чи підкупом змушує перехожих робити нудну роботу замість нього."},{t="Аптекарське роздратування",b="Молодший Аптекар Голланд чекає на доставку на цвинтарі за ратушею Брілла, та доручення йде шкереберть. Ґордо геть неправильно зрозумів наказ і скерував мандрівників збирати нешкідливу Похмуру Траву замість летючого Зілля Приречення, потрібного для алхімічних досліджень. Голланд украй роздратований недолугістю зшитого велетня: він має помилкову доставку за доказ нікчемності гидоти — і одразу доручає гравцеві виправити помилку."}},fp="12,264,16.465.0,23.484.1,13.201.0,41.229.0,22.218.0,54.217.1,30.150.0,43.198.1"}
P.entries["quest:5482"] = {n="Зілля приречення",s="Зілля приречення — завдання від Молодшого Аптекаря Голланда у Бріллі: зібрати отруйне зілля, що проростає біля північних братських могил Тірісфалю. Голланд наймає перехожих шукачів пригод, розчарувавшись у незграбних спробах гидоти Ґордо збирати трави.",h="Зілля приречення — завдання від Молодшого Аптекаря Голланда у Бріллі: зібрати отруйне зілля, що проростає...",kw={"зілля приречення","голланд","братська могила","гноли","трави","брілл"},ang={["faction:Horde"]="Моторошні алхімічні експерименти у Бріллі показують, наскільки інакше діють Відступники порівняно з їхніми шаманськими й кочовими союзниками в Калімдорі.",["profession:Herbalism"]="Звичайні трави ростуть по всіх галявинах, та спотворені різновиди на кшталт Зілля Приречення показують протиприродні зміни рослинності, спричинені чумою Погибелі.",["race:Undead"]="Служба молодшим членам Королівського Аптекарського Товариства — звичний обряд посвяти для щойно пробуджених Відступників, які прагнуть довести свою корисність володінням Сильвани."},sec={{t="Аптекарські амбіції",b="Молодший Аптекар Голланд проводить дослідження від імені Королівського Аптекарського Товариства в поселенні Брілл. Щоб просунути свої експерименти, йому потрібна чимала кількість Зілля Приречення — мерзенної рослини, що вкорінилася у спустошеній землі Галявин Тірісфалю. Переконавшись, що Ґордо нездатен розрізнити потрібні реагенти, Голланд звертається до вправніших рук, щоб урятувати свій урожай."},{t="Жнива на братській могилі",b="Зілля Приречення буяє в місцях, глибоко отруєних смертю і чумою, і густо розростається довкола братської могили просто на північ від цвинтаря Брілла. Збирати його небезпечно через агресивних гнилошкірих гнолів, які нишпорять оскверненими могильними курганами, порпаються в останках і боронять зарослі рови."}},fp="9,259,20.366.0,22.333.0,50.278.0,43.266.0,26.209.0,45.201.0,66.262.0,39.211.0"}
P.entries["quest:5541"] = {n="Набої для Рамблшота",s="У зброяра Геґнара Рамблшота закінчуються дріб і порох для стрільців, що вправляються біля Анвілмару. Ящик із набоями покинуто в засніжених нетрях біля Сивого Лігва, коли голодні вендіго розігнали кур'єра.",h="У зброяра Геґнара Рамблшота закінчуються дріб і порох для стрільців, що вправляються біля Анвілмару.",kw={"рамблшот","набої","порох","зброяр","анвілмар","вендіго","лослор"},ang={["class:Hunter"]="Кожен стрілець у Холодному Хребті добре знає крамницю Геґнара; якщо його полиці повні свіжого пороху й дробу, ви ніколи не вийдете в нетрі з порожньою рушницею.",["profession:Engineering"]="Дворфійські рушниці й міномети вимагають тонко змеленого пороху й однакового дробу, тож запаси Рамблшота конче потрібні місцевим винахідникам і стрільцям.",["race:Dwarf"]="Дворфійське ремесло тримається на непорушному ланцюгу постачання між кузнями Анвілмару та зброярами на передовій, як-от Рамблшот."},sec={{t="Втеча кур'єра",b="Лослор Радж зі Складу Стілґрила підтримує постачання ремісників по всьому Дун Мороґу, та місцева звірина часто втручається. Його остання партія важких набоїв так і не дісталася придорожньої майстерні Геґнара Рамблшота. Отаборившись біля печер, відомих як Сиве Лігво, наляканий кур'єр натрапив на тутешніх вендіго й кинувся навтьоки, покинувши важкий дерев'яний ящик у снігу."},{t="Порох і дріб",b="Геґнар Рамблшот тримає збройну крамницю просто біля головної дороги, що веде від Анвілмару. На галявині перед його кузнею не вщухає рух: стрільці Айронфорджа, горяни та дворфійські мінометні загони приходять пристріляти зброю і повправлятися бойовими набоями. Без постійних ящиків пороху й свинцю від постачальників, як-от Лослор, вишкіл стрільців миттю заходить у глухий кут."}},fp="19,236,18.424.0,15.410.0,30.174.0,25.197.0,31.148.0,43.156.0,20.122.0,44.165.0"}
P.entries["quest:5545"] = {n="Купа клопоту",s="Наглядачка Рейлен із Лісозаготівельного Табору Східної Долини має терміново здати партію деревини, а часу обмаль. Місцеві ведмеді й вовки відігнали її робітників від свіжозрубаного лісу, і цінні в'язки колод лишилися покинутими в північних хащах. Вона покладається на охочих шукачів пригод, які рушать у ліс, що кишить звіриною, і повернуть колоди, поки контракт не втрачено.",h="Наглядачка Рейлен із Лісозаготівельного Табору Східної Долини має терміново здати партію деревини, а часу...",kw={"купа клопоту","наглядачка рейлен","деревина","лісозаготівля","східна долина","вовки","ведмеді"},ang={["class:Hunter"]="Пробиратися гаями, повними хижаків, забирати припаси й давати раду небезпечним звірам — це саме те, на чому ґрунтуються інстинкти виживання слідопита.",["faction:Alliance"]="Деревина зі Східної Долини — запорука того, що відбудова Стормвінда й утримання прикордонних застав триватимуть без дорогих перебоїв у постачанні."},sec={{t="Строк підпирає",b="Лісозаготівельний Табір Східної Долини постачає деревину, конче потрібну для відбудови й оборони Королівства Стормвінд. Вести промислову лісозаготівлю на краю диких земель небезпечно, і Наглядачка Рейлен саме потрапила в халепу. Її бригада відстала від графіка з важливим вантажем зрубаного лісу, і час спливає."},{t="Хижаки серед колод",b="Річ не в нестачі повалених дерев, а в агресивній місцевій звірині. Голодні вовки й ведмеді, що бережуть свою територію на північ від табору, розігнали лісорубів, і ті покинули акуратно перев'язані в'язки дров, розкидані лісом. Міську владу про звірину вже сповістили, та Рейлен не може чекати, поки варта убезпечить місцевість: доводиться наймати мандрівних героїв, щоб ті прошмигнули в ліс і зібрали деревину."}},fp="19,381,18.366.0,23.444.0,25.223.0,39.217.0,38.302.0,27.225.0,50.248.0,39.188.0"}
P.entries["quest:5621"] = {n="Шати Місяця",s="«Шати Місяця» — вступний обряд служіння для юних жерців нічних ельфів у Доланаарі. Наставниця жерців Лаурна Морнінґлайт доручає посвяченому подбати про Вартову Шаю — поранену захисницю, що патрулює ліси на південь від поселення. Виконання цього обов'язку знаменує офіційне визнання посвяченого в Сестринстві Елуни.",h="«Шати Місяця» — вступний обряд служіння для юних жерців нічних ельфів у Доланаарі.",kw={"шати місяця","жрець","лаурна морнінґлайт","вартова шая","сестринство елуни","доланаар"},ang={["class:Priest"]="Цей обряд показує два стовпи жрецтва: зцілення поранених союзників відновлювальною молитвою і захист їх від майбутньої небезпеки божественними оберегами.",["race:NightElf"]="Для калдорей Сестринство Елуни й Вартові тисячоліттями працюють пліч-о-пліч, захищаючи ліси й народ від навислої темряви."},sec={{t="Священне покликання",b="У гіллі Тельдрассила Сестринство Елуни дбає і про духовне життя калдорей, і про практичний захист їхніх кордонів. Коли Вартова Шая зазнає поранень, патрулюючи небезпечні хащі на південь від Доланаара, наставниця жерців Лаурна Морнінґлайт не може покинути свій пост, щоб допомогти. Натомість вона доручає щойно навченому посвяченому довести свою відданість: загоїти рани Шаї й зміцнити її захисними чарами."},{t="Облачення Сестринства",b="Жерці, що відновлюють сили Вартової Шаї, повертаються до Доланаара по свої перші офіційні шати. Це вбрання засвідчує, що молодий послушник перейшов від класних настанов до практичного, рятівного служіння під благодаттю місяця. У суспільстві калдорей підтримувати Вартових — не просто військове завдання: це акт єднання з Елуною й неодмінний обов'язок заради безпеки Тельдрассила."}},fp="20,354,16.470.0,27.414.0,42.124.0,32.135.0,46.140.0,30.119.0,36.178.0,66.208.0"}
P.entries["quest:5622"] = {n="В ім'я Елуни",s="«В ім'я Елуни» — обряд переходу для юних жерців нічних ельфів, готових вийти з-під затишного гілля Тінедола. За настановою Жриці Шанди послушники спускаються стежкою до Доланаара, щоб шукати подальших настанов і вишколу в Лаурни Морнінґлайт.",h="«В ім'я Елуни» — обряд переходу для юних жерців нічних ельфів, готових вийти з-під затишного гілля Тінедола.",kw={"в ім'я елуни","жрець","шанда","лаурна морнінґлайт","тінедол","доланаар"},ang={["class:Priest"]="Це завдання — ваш перехід від простих послушницьких студій до повноцінного служіння, що виводить вас на шлях до перших освячених шат.",["race:NightElf"]="Сестринство Елуни — духовне серце й історичний провід суспільства калдорей, тож подорож до Доланаара — глибоко традиційна віха для відданих."},sec={{t="Прощання з галявиною",b="Для посвяченого, що служить Елуні в затишному прихистку Алдрассила, навчання починається з простих молитов і захисних заклинань під пильним оком Жриці Шанди. Та відлюдне життя Тінедола не підготує жрицю чи жерця до сум'яття, що охопило ширший світ. Щойно посвячений виявляє тверду віру й дисципліну, Шанда відсилає його тінистою лісовою стежкою до Доланаара — продовжувати науку."},{t="Крок у жрецтво",b="Прибуття до Доланаара — важлива віха в божественному покликанні нічного ельфа. Там чекає Лаурна Морнінґлайт, шанована жриця, якій доручено готувати учнів до випробувань, що постали перед Тельдрассилом. Окрім поглибленої науки місячного чародійства, прихід до Доланаара готує послушника до перших офіційних шат, що засвідчують його становище в Сестринстві Елуни."}},fp="17,264,17.441.0,26.398.0,29.166.0,50.172.0,30.142.0,50.194.0,52.189.0,55.201.0"}
P.entries["quest:5623"] = {n="В ім'я Світла",s="«В ім'я Світла» — рання віха для жерців-новачків, що навчаються в Долині Нортширу. Жриця Анетта посилає молодого служителя за межі відлюдного абатства до Ґолдшира. Там на нього чекає Жриця Джозетта, щоб поглибити його духовну дисципліну й повести далі шляхом віри у Святе Світло.",h="«В ім'я Світла» — рання віха для жерців-новачків, що навчаються в Долині Нортширу.",kw={"в ім'я світла","жрець","жриця анетта","жриця джозетта","ґолдшир","святе світло"},ang={["class:Priest"]="Цей обряд посвяти з'єднує ваші затишні студії в Нортширі з живою пастирською працею серед мешканців і гарнізонів Лісу Елвінн.",["faction:Alliance"]="Церква Святого Світла — одна з ключових опор Альянсу: вона плекає відданих цілителів, здатних підтримувати захисників на передовій.",["race:Human"]="Для людей Стормвінда звернутися по настанови до жрецтва в Ґолдширі — важливий крок у підтримці моральної та духовної опори королівства."},sec={{t="Крок за межі Нортширу",b="Абатство Нортшира дає новачкам прихисток і початкову науку, але духовний вишкіл у Церкві Святого Світла вимагає служіння просто серед людей. Щойно посвячений показує основи молитви й божественного зцілення, Жриця Анетта посилає його на південь сонячними дорогами до Ґолдшира. Ця подорож знаменує перехід від відлюдного учня до діяльного парафіяльного служителя серед щоденних випробувань мешканців Елвінну."},{t="Наука в Ґолдширі",b="У Корчмі «Лев'яча Гордість» у Ґолдширі Жриця Джозетта дбає про духовні потреби місцевих і наглядає за послушниками, що зростають у вірі. Джозетта будує просто на підвалинах, закладених в абатстві: перевіряє, чи вміє посвячений розраджувати, оберігати вірних і зцілювати поранених. Під її проводом молодий жрець знайомиться з обов'язками, які чекають на служителів Церкви по всьому королівству."}},fp="21,329,26.447.0,21.407.0,45.123.0,51.268.0,50.104.0,45.199.0,36.131.0,59.170.0"}
P.entries["quest:5624"] = {n="Шати Світла",s="«Шати Світла» — раннє випробування для жерців-новачків у Ґолдширі, яке дає Жриця Джозетта. Замість абстрактної перевірки віри церква посилає послушника на схід, до Кришталевого Озера, зцілити й зміцнити пораненого Вартового Робертса. Виконаний обов'язок доводить, що учень опанував зцілення, і приносить йому перші офіційні шати, визнані Церквою Святого Світла.",h="«Шати Світла» — раннє випробування для жерців-новачків у Ґолдширі, яке дає Жриця Джозетта.",kw={"шати світла","жрець","жриця джозетта","вартовий робертс","кришталеве озеро","зцілення","ґолдшир"},ang={["class:Priest"]="Цей обряд посвяти з'єднує богослов'я з класів Нортширу зі службою в полі й нагадує: найвище покликання жерця — зберігати життя союзників на передовій зціленням і зміцнювальними оберегами.",["faction:Alliance"]="Поки армія Стормвінда виснажена й відсутня в місцевих селищах, міська варта значною мірою покладається на допомогу церковних учнів, щоб вистояти перед загрозами.",["race:Human"]="Людська культура глибоко шанує Церкву Святого Світла, тож шати, отримані від жриці містечка, — важлива громадська й духовна віха в житті послушника."},sec={{t="Практичне випробування віри",b="За традиціями Церкви Святого Світла новачків рідко підносять лише за знання доктрини. Жриця Джозетта, що навчає послушників, які прибувають до Ґолдшира з Абатства Нортшира, перевіряє, чи вміє посвячений володіти божественною силою на ділі, перш ніж дати йому офіційне церковне визнання. Коли до містечка доходить звістка, що Вартовий Робертс лежить поранений біля озера на схід від Ґолдшира, Джозетта обертає буденне нещастя на випробування й посилає молодого жерця доглянути його."},{t="Опора королівства",b="Завдання вимагає більшого, ніж просто стулити рану: послушник має загоїти рани вартового відновлювальними молитвами й зміцнити його витривалість благословенням стійкості. У ці неспокійні часи, коли військо Стормвінда розтягнуте до краю, а місцеві гарнізони знемагають від кобольдів і бандитів, Джозетта наголошує: обов'язок жрецтва безпосередньо стосується виживання на війні. Повернутий до служби Вартовий Робертс одразу стає в пригоді містечку, а посвячений доводить, що здатен підтримувати захисників під ударами."},{t="Шати ордену",b="Повернувшись до Корчми «Лев'яча Гордість» після лікування солдата, молодий жрець отримує перше офіційне вбрання. Ці шати — знак схвалення й братерства з боку жрецтва Стормвінда. Носити їх у подальшому навчанні не обов'язково, та вони стоять зримим свідченням того, що церква визнає їхнього власника висвяченим служителем Святого Світла."}},fp="21,390,25.489.0,20.527.0,22.402.0,31.190.0,48.185.0,25.224.0,49.260.0,38.157.0,52.271.0"}
P.entries["quest:5625"] = {n="Шати Світла",s="«Шати Світла» — ранній обряд переходу для молодих дворфійських жерців у Дун Мороґу. За вказівкою наставника жерців Максана Анвола з Хараноса, посвячуваний має допомогти пораненому горянину одразу за містом, щоб заслужити свої шати.",h="«Шати Світла» — ранній обряд переходу для молодих дворфійських жерців у Дун Мороґу.",kw={"жрець","шати","світло","анвол","харанос","дольф","горянин"},ang={["class:Priest"]="Цей обряд переходу знаменує ваш шлях від неперевіреного новачка до визнаного служителя Святого Світла, якому довіряють життя товаришів на передовій.",["faction:Alliance"]="Святе Світло — духовний хребет Альянсу, що дарує розраду й зцілення на полі бою воїнам, які тримають оборону проти трогів, звірів і гіршого.",["race:Dwarf"]="Горяни Айронфорджа стережуть небезпечні перевали Дун Мороґу; турбота про поранених розвідників, як-от Дольф, зміцнює життєво важливий зв'язок між дворфійською вірою та військовою обороною."},sec={{t="Нагальне випробування",b="За традицією, послушники Святого Світла проходять урочисті випробування, щоб довести, що гідні носити церковні шати. Проте в Хараносі наставник жерців Максан Анвол цінує практичний результат вище за церемонію. Коли місцеві патрулі ледве стримують трогів і диких звірів, теоретичні іспити відходять на другий план, бо справжні захисники стікають кров'ю на снігу."},{t="Допомога горянам",b="Щоб заслужити шати, молодих жерців посилають на південь від міста знайти Горянина Дольфа, пораненого на службі. Зцілюючи рани Дольфа відновлювальними молитвами й зміцнюючи його тіло Словом Сили: Стійкість, посвячуваний доводить, що його відданість напряму обертається виживанням захисників Айронфорджа."},{t="Шати Церкви",b="Коли горянину надано допомогу, Максан Анвол вручає послушнику офіційні шати. Окрім теплого захисту від холоду Дун Мороґу, ці шати слугують видимим знаком сану, сповіщаючи пораненим мандрівникам і місцевій варті, що поряд є служитель Світла, готовий допомогти."}},fp="21,246,15.353.0,23.345.0,19.304.0,34.274.0,19.237.0,24.223.0,58.268.0,38.304.0,41.237.0"}
P.entries["quest:5626"] = {n="В ім'я Світла",s="«В ім'я Світла» знаменує для молодого жерця обряд переходу від відлюдних тренувальних земель Долини Холодного Хребта до ширших просторів Дун Мороґу. За настановою Бранстока Калдера новіціїв посилають гірським тунелем до Хараноса — продовжити навчання в наставника жерців Максана Анвола. Це знак, що послушник готовий узяти на себе справжню відповідальність і заслужити традиційні шати свого покликання.",h="«В ім'я Світла» знаменує для молодого жерця обряд переходу від відлюдних тренувальних земель Долини Холодного...",kw={"жрець","світло","калдер","анвол","харанос","холодний хребет","шати"},ang={["class:Priest"]="Це завдання — віха для молодих жерців: офіційний випуск із базового вишколу в дієве служіння і здобуття перших шат.",["race:Dwarf"]="Дворфійське жрецтво поєднує духовну відданість із практичною витривалістю, посилаючи послушників просто від вогнищ Холодного Хребта на суворі крижані вітри Дун Мороґу."},sec={{t="Залишаючи Ковадло",b="У відлюдній колисці Долини Холодного Хребта дворфійські жерці починають навчання під пильним оком наставників, як-от Бранстока Калдера. Щойно новачок виявляє достатню відданість і розуміння святої магії, його попередній вишкіл добігає кінця. Замість тримати учнів під захистом Анвілмару, Калдер спрямовує обдарованих за гори, до Хараноса, де потреби служіння та оборони переплітаються з щоденними турботами мешканців Дун Мороґу."},{t="Крок до Хараноса",b="Щоб дістатися Хараноса, треба пройти тунелем Перевалу Холодного Кряжа у продуті вітрами сніги центрального Дун Мороґу. У селищі чекає Максан Анвол — старший жрець, що веде учнів далі за прості молитви. Анвол твердо переконаний: відданість Святому Світлу вимагає рівною мірою моральної чистоти, тілесного гарту й незламної волі. Послушникам, які доведуть свою рішучість під його опікою, Анвол готується вручити перші офіційні шати сану."}},fp="21,430,17.478.0,22.495.0,30.192.0,19.195.0,40.178.0,49.222.0,41.181.0,51.211.0"}
P.entries["quest:5636"] = {n="Відчайдушна молитва",s="«Відчайдушна молитва» — завдання для жерців Альянсу, що скеровує мандрівних служителів Святого Світла назад до Стормвінда. Його починає жриця нічних ельфів Лаурна Морнінґлайт у Доланаарі: вона кличе людських жерців, що гостюють на Тельдрассилі, додому — завершити важливий духовний вишкіл у Верховної Жриці Лаурени.",h="«Відчайдушна молитва» — завдання для жерців Альянсу, що скеровує мандрівних служителів Святого Світла назад...",kw={"відчайдушна молитва","жрець","лаурна морнінґлайт","верховна жриця лаурена","собор світла","стормвінд"},ang={["class:Priest"]="Це завдання — важливий обряд переходу на 10-му рівні: воно повертає жерців до Собору Світла, щоб вивчити особливі расові благословення віри.",["faction:Alliance"]="Виклик свідчить про дедалі тіснішу співпрацю в Альянсі: жриці нічних ельфів охоче узгоджують дії з церковним проводом Стормвінда.",["race:NightElf"]="Хоч нічні ельфи шанують богиню місяця Елуну, Жриця Лаурна Морнінґлайт виявляє ввічливу повагу до чужоземних прихильників Святого Світла, що ходять під гіллям Тельдрассила."},sec={{t="Звістка з дому",b="Відвідуючи прадавнє гілля Тельдрассила, жерці, вірні Святому Світлу, можуть привернути увагу місцевого Сестринства Елуни. У Доланаарі Жриця Лаурна Морнінґлайт стає несподіваною посередницею: вона переказує, що один з ваших побратимів-жерців перетнув континенти, шукаючи вас. Розуміючи нагальність виклику, Лаурна радить вам без зволікань повернутися на батьківщину й дає благословення Елуни разом із добрими побажаннями вашій власній вірі."},{t="Виклик до Стормвінда",b="Дорога веде через Велике Море до величного Собору Світла в самому серці Стормвінда. Там Верховна Жриця Лаурена наглядає за духовним зростанням вірян Альянсу. Послушників, які рано виявили хист, кличуть до неї опанувати глибші таємниці відданості — зокрема рятівне звернення, відоме як Відчайдушна молитва: дар, що дарують лише відданим учням для їхньої найтемнішої години."}},fp="16,300,19.476.0,24.457.0,52.185.0,27.129.0,51.279.0,45.188.0,47.204.0,52.254.0"}
P.entries["quest:5648"] = {n="Шати Духовності",s="Шати Духовності — обряд посвяти для жерців-початківців Орди в Дуротарі, який доручає Тай'джин у Гострому Пагорбі. Новачків посилають у поле знайти й зцілити рани пораненого піхотинця, що стоїть на варті проти вцілілих із Кул Тірасу. Виконавши завдання, жрець здобуває свої перші обрядові шати й офіційне визнання серед духовних служителів Орди.",h="Шати Духовності — обряд посвяти для жерців-початківців Орди в Дуротарі, який доручає Тай'джин у Гострому...",kw={"жрець","тай'джин","шати духовності","гострий пагорб","кор'я","зцілення"},ang={["class:Priest"]="Цей обряд посвяти — головне раннє випробування для жерців Орди в Дуротарі: він підтверджує ваші навички зцілення в полі й дарує перші шати.",["faction:Horde"]="Порятунок Піхотинця Кор'ї напряму зміцнює оборону Гострого Пагорба проти людей Кул Тірасу, що досі окопалися поблизу.",["race:Troll"]="Наставництво Тай'джина вплітає духовність тролівських предків у практичний бойовий обов'язок, щоб молоді воїни Темного Списа своєю вірою захищали союзників."},sec={{t="Випробування цілителя",b="У посушливих чагарях на південь від Гострого Пагорба Орда веде невпинні сутички з рештками війська великого адмірала Деліна Праудмура. Замість того щоб відправляти майбутніх жерців на відірвані від життя ритуали, наставник-троль Тай'джин перевіряє їхню дисципліну в справжній бойовій медицині. Новачкам доручають розшукати воїтельку, тяжко поранену під час відбиття людських лазутчиків, — це Піхотинець Кор'я, і її рани треба обробити, а сили підкріпити, перш ніж вона згасне."},{t="Шати вірних",b="Повернувши Кор'ю до бойової готовності, молодий жрець доводить, що готовий нести мантію духовної традиції Орди. На знак порятунку захисниці передової Тай'джин дарує Шати Духовності. І для орків-союзників, і для тролів Темного Списа ці шати означають, що їхній носій — не просто учень, який зубрить заклинання, а надійна опора, здатна зберігати життя воїнам Орди в бою."}},fp="24,382,16.462.0,25.429.0,50.208.0,25.154.0,40.154.0,53.209.0,49.192.0,45.157.0"}
P.entries["quest:5649"] = {n="В ім'я духовності",s="«В ім'я духовності» — основоположний обряд посвяти для молодих жерців Темного Списа, що покидають Долину Випробувань. За наказом Кен'джая новачки вирушають до наставника жерців Тай'джина в Гострий Пагорб і роблять перші справжні кроки за межі усамітненого тренувального лігва назустріч ширшим викликам Дуротару. Ця подорож показує тонку рівновагу, яку Темний Спис тримає між шаною до тролівської спадщини предків і входженням до новоствореної Орди.",h="«В ім'я духовності» — основоположний обряд посвяти для молодих жерців Темного Списа, що покидають Долину...",kw={"жрець","кен'джай","тай'джин","темний спис","гострий пагорб","духовність"},ang={["class:Priest"]="Це завдання знаменує ваш вихід із каньйону новачків до справжнього навчання й перших шат від Тай'джина в Гострому Пагорбі.",["faction:Horde"]="Воно показує, як різні культури співпрацюють у Дуротарі, поєднуючи дикі традиції Островів Відлуння з військовою заставою Гострого Пагорба.",["race:Troll"]="Ця місія відображає напругу, з якою Темний Спис живе щодня: рівновагу між вірністю Орді та збереженням давньої племінної духовності."},sec={{t="Прощання з червоним каньйоном",b="Опанувавши основні обряди під проводом Кен'джая в усамітненій Долині Випробувань, послушники Темного Списа готові залишити тренувальні землі позаду. Звивисті стежки виводять у Дуротар і ведуть просто до поселення на роздоріжжі — Гострого Пагорба. Для молодого жерця ця подорож — важлива віха: від простих вправ на виживання в пилюці до духовної та культурної відповідальності за плем'я."},{t="Стара віра й нові союзи",b="Кен'джай відверто говорить про становище Темного Списа в Орді Тралла. Тролі глибоко цінують вірність орків та їхні уроки честі, та не кожна традиція предків легко вписується під пильним поглядом союзників. Духовні провідники Темного Списа навчають учнів тихо берегти свою спадщину — міцно триматися своєї сутності й водночас служити Орді. Тай'джин у Гострому Пагорбі приймає цих послушників у це глибше розуміння й веде їх до самодостатності та сили громади."}},fp="24,462,22.427.0,28.509.0,45.105.0,25.114.0,35.86.0,58.247.0,54.233.0,56.142.0"}
P.entries["quest:5650"] = {n="Шати Темряви",s="Шати Темряви — засадничий обряд посвяти для молодих жерців Відступників у Бріллі. Темна Клірикиня Берил доручає посвяченим зцілити й зміцнити пораненого Вартового Смерті, перевіряючи їхнє володіння магією підтримки, перш ніж вони зануряться глибше в тіні.",h="Шати Темряви — засадничий обряд посвяти для молодих жерців Відступників у Бріллі.",kw={"шати темряви","берил","жрець","зцілення","вартовий смерті кел","брілл"},ang={["class:Priest"]="Цей обряд утілює філософію жрецтва Відступників: урівноважити похмуру користь Тіні з незамінним обов'язком зміцнювати й зцілювати союзників.",["race:Undead"]="Для Відступників магія зцілення — прагматичне знаряддя виживання, яким підтримують бійців передової на кшталт Вартового Смерті Кела проти гнолів і недобитків Погибелі."},sec={{t="Рівновага темряви і світла",b="Хоч жрецтво Відступників завдячує славою і своєрідністю тіні й темряві, його старійшини визнають незмінну практичну потребу у відновленні. Темна Клірикиня Берил навчає: щоб розуміти темряву, треба розуміти світло й мистецтво зцілення. Жерцю, який прагне лише руйнування, радять натомість вивчати таємну магію; справжнє покликання жрецтва — зміцнювати й берегти товаришів не менше, ніж уражати ворогів."},{t="Обов'язок на цвинтарі",b="Щоб довести майстерність, посвяченого посилають на північ від цвинтаря Брілла — на поміч Вартовому Смерті Келу. Стоячи проти зграй гнолів, що нишпорять поблизу, Кел зазнав поранень, утримуючи рубіж. Загоївши його рани зцілювальними заклинаннями й зміцнивши витривалість захисними чарами, учень доводить, що здатен підтримувати захисників Галявин Тірісфалю, і здобуває від Берил облачення та допуск до вищих таїнств жрецтва."}},fp="20,264,27.460.0,23.433.0,77.263.0,22.212.0,21.158.0,52.170.0,41.134.0,50.174.0"}
P.entries["quest:5651"] = {n="В ім'я Темряви",s="В ім'я Темряви знаменує перехід жерця Відступників від початкових склепів Похоронного Подзвону до поглибленого навчання у Бріллі. За дорученням Темного Клірика Дюстена молодий учень вирушає вчитися в Темної Клірикині Берил — опановувати тонку рівновагу між Святим Світлом і Тінню.",h="В ім'я Темряви знаменує перехід жерця Відступників від початкових склепів Похоронного Подзвону до...",kw={"в ім'я темряви","дюстен","берил","жрець","світло","тінь","брілл"},ang={["class:Priest"]="Це завдання втілює засадничу філософію жрецтва Відступників: володіти і Святим Світлом, і Тінню з холодною розважливістю, а не з релігійним благоговінням.",["race:Undead"]="Шлях від Похоронного Подзвону до Брілла — звична перша вилазка в ширші володіння Відступників; вона показує посвяченим, як їхній народ відбудовується на руїнах Лордерону."},sec={{t="Шлях, прокладений у гнилі",b="Жерці інших рас шанують Святе Світло як незаплямоване джерело моральної чесноти, а Відступники підходять до віри крізь суворий досвід власного нежиття. Як навчає Темний Клірик Дюстен, Відступників викувано у скверні й викинуто, наче падло. Щоб вижити, їм треба розуміти і Світло, і Тінь — без сентиментів. «В ім'я Темряви» виводить нових учнів із замкненого цвинтаря Похоронного Подзвону назустріч ширшій дійсності, що чекає на них у Галявинах Тірісфалю."},{t="Навчання у Бріллі",b="Дорога на північний схід від Похоронного Подзвону веде молодого жерця через критий дерев'яний міст у зруйноване містечко Брілл. Там, у горішніх кімнатах місцевого заїзду, Темна Клірикиня Берил чекає, щоб випробувати рішучість посвяченого. Берил цінує амбіції й холодну практичність понад сліпу відданість і вимагає, щоб жрець Відступників володів божественною силою як зброєю і знаряддям, а не моральною милицею."}},fp="20,304,20.495.0,20.409.0,34.199.0,63.260.0,34.172.0,31.192.0,27.187.0,43.232.0"}
P.entries["quest:59"] = {n="Полотняна і шкіряна броня",s="«Полотняна і шкіряна броня» — доручення Вартового Томаса біля східного мосту в Лісі Елвінн. Вражений службою шукача пригод, Томас видає офіційний військовий талон на обладунок, який можна обміняти в місцевої майстрині Сари Тімберлейн. Завдання веде новобранців далі на схід, до Лісозаготівельного Табору Східної Долини, по належне спорядження для захисту королівства.",h="«Полотняна і шкіряна броня» — доручення Вартового Томаса біля східного мосту в Лісі Елвінн.",kw={"броня","талон на обладунок","вартовий томас","сара тімберлейн","східна долина","кравецтво"},ang={["faction:Alliance"]="Спорядження захисників через місцеві замовлення показує, як сільські громади Елвінну тримають Альянс на ходу, попри політичний параліч у столиці.",["profession:Tailoring"]="Армійське замовлення Сари Тімберлейн доводить, що кравецтво — важливе й офіційно підтримуване військове ремесло в королівстві.",["race:Human"]="Служба Вартовому Томасу й торгівля з Сарою Тімберлейн відображають спільні громадські зв'язки, що тримають укупі невеликі садиби Лісу Елвінн."},sec={{t="Знак від вартового",b="Вартовий Томас несе варту на східній переправі через річку в Елвінні, тримаючи кордон проти ворожих мурлоків і мандрівних гнолів. Цінуючи зусилля здібних мандрівників, що допомагають його самотньому посту, він дає їм офіційний Талон на Обладунок Стормвінда замість віддавати спорядження зі своїх убогих польових запасів. Цей талон — військовий реквізиційний документ, який офіційно визнає службу власника короні."},{t="Ткаля Східної Долини",b="За мостом на схід лежить Лісозаготівельний Табір Східної Долини — головна лісозаготівля Елвінну. Саме звідти працює Сара Тімберлейн, яка має офіційне замовлення від армії Стормвінда на виготовлення спорядження з тканини та шкіри. Централізовані арсенали королівства виснажені й розтягнуті до краю, тож такі місцеві майстри, як Сара, незамінні, коли треба спорядити війська й допоміжних розвідників на прикордонні."}},fp="23,360,15.429.0,22.402.0,33.259.0,23.223.0,35.202.0,51.242.0,54.211.0,38.202.0"}
P.entries["quest:590"] = {n="Угода з пройдисвітом",s="Угода з пройдисвітом — сутичка з Келвіном Монтеґ'ю в Похоронному Подзвоні. Запропонувавши щойно пробудженим Відступникам роботу з обіцянкою багатства, хитрий розбійник виказує справжні наміри, коли від нього вимагають платню.",h="Угода з пройдисвітом — сутичка з Келвіном Монтеґ'ю в Похоронному Подзвоні.",kw={"угода з пройдисвітом","келвін монтеґ'ю","розбійник","платня","дуель","похоронний подзвін"},ang={["class:Rogue"]="Зустріч із Келвіном Монтеґ'ю дає молодим розбійникам миттєвий урок професійного ризику: нікому не вірте, пильнуйте гаманець і ніколи не дозволяйте іншому пройдисвіту піти з вашою часткою.",["race:Undead"]="Пробудження в Похоронному Подзвоні швидко доводить: смерть не позбавляє людство найдрібніших вад; шахраї з Відступників так само охоче дурять своїх, як і живі розбійники."},sec={{t="Безчесна обіцянка",b="Келвін Монтеґ'ю тиняється біля склепів Похоронного Подзвону, пропонуючи новопіднятим Відступникам на позір легку роботу. Запевняючи, що за доставку листа можна заробити добру монету, Монтеґ'ю посилає зелених шукачів пригод у небезпеку. Та щойно доручення виконано, Монтеґ'ю зручно забуває про обіцяну платню, вдаючи цілковите невідання щодо будь-якої домовленості чи боргу."},{t="Розплата",b="Коли від нього вимагають дотримати слова, Монтеґ'ю показує своє справжнє обличчя. Замість розлучатися зі своїм сріблом він береться за зброю, розраховуючи легко зарубати недосвідченого новачка. Лише добряче відлупцювавши розбійника, його можна змусити поступитися. Ґрунтовно побитий, він викашлює частку монет і відверто визнає, що збрехав про винагороду просто тому, що думав: йому це зійде з рук."}},fp="14,216,22.368.0,16.390.1,55.244.1,41.145.0,51.177.1,33.183.1,39.153.1,54.183.0"}
P.entries["quest:6"] = {n="Винагорода за Ґарріка Педфута",s="«Винагорода за Ґарріка Педфута» — контракт Альянсу на винагороду, виданий Помічником Віллемом біля Абатства Нортшира. Він посилає молодих новобранців вистежити сумнозвісного місцевого злодія, який із відлюдної халупи біля виноградників тероризує фермерів і купців Елвінну.",h="«Винагорода за Ґарріка Педфута» — контракт Альянсу на винагороду, виданий Помічником Віллемом біля Абатства...",kw={"ґаррік педфут","винагорода","злодій","помічник віллем","нортшир","халупа"},ang={["class:Rogue"]="Ґаррік Педфут дає розбійникам перше уявлення про те, як злочинці діють у тіні Елвінну, і показує, що погано прихована схованка притягує швидкі клинки.",["faction:Alliance"]="Розправа з Ґарріком Педфутом — одна з перших прямих послуг, які майбутній шукач пригод Альянсу робить, щоб повернути стабільність Королівству Стормвінд.",["race:Human"]="Для людей, що виросли в королівстві, очистити Нортшир від головорізів на кшталт Педфута — особиста справа захисту священної землі батьківщини та її фермерів."},sec={{t="Пошесть у долині",b="Долину Нортширу колись вважали безпечним прихистком для вишколу новобранців і догляду за священними виноградниками, та нещодавній занепад закону й порядку по всьому Елвінну лишив її беззахисною. У долину прокралися зграї злодіїв, і головоріз на ім'я Ґаррік Педфут швидко став їхнім ватажком. Уже кілька тижнів Ґаррік зі своєю бандою грабує обози, обирає купців на дорогах і залякує місцевих фермерів."},{t="Правосуддя Помічника Віллема",b="Варта Стормвінда розтягнута між захистом столиці й зовнішніх кордонів, тож місцевим маршалам і помічникам лишається покладатися на завзятих добровольців, щоб тримати мир у Нортширі. Помічник Віллем призначає публічну винагороду за голову Ґарріка, аби раз і назавжди позбавити долину його банди. Розправа з Педфутом у його занедбаній халупі на схід від річки — перший удар по ширшому беззаконню, що просочується в серце людських земель."}},fp="25,260,22.420.0,23.419.0,23.227.0,35.152.0,33.181.0,63.236.0,33.147.0,38.157.0"}
P.entries["quest:60"] = {n="Кобольдські свічки",s="«Кобольдські свічки» — одне з перших доручень Вільяма Пестла з Корчми «Лев'яча Гордість» у Ґолдширі. Алхімік, що навідався сюди зі своєї крамниці в Стормвінді, шукає густий віск великих свічок, які носять кобольди, що заполонили місцеві копальні Лісу Елвінн. Для шукачів пригод це раннє знайомство з підземними шкідниками, які зазіхають на цінні золоті жили королівства.",h="«Кобольдські свічки» — одне з перших доручень Вільяма Пестла з Корчми «Лев'яча Гордість» у Ґолдширі.",kw={"кобольдські свічки","кобольди","вільям пестл","віск","фарґодіп","яшмова копальня","ґолдшир"},ang={["faction:Alliance"]="Поки королівська армія виснажена внутрішніми політичними чварами, а сили корони відсутні, захист місцевого господарства лягає на добровольців і мандрівних шукачів пригод.",["profession:Mining"]="Зачищаючи кобольдів заради свічок, рудокопи-початківці потрапляють просто на найбагатші мідні й золоті жили Елвінну, покинуті людьми-рудокопами.",["race:Human"]="Повернути захоплені копальні Елвінну й постачати товар стормвіндським ремісникам — ранні обов'язки молодих підданих королівства."},sec={{t="Доручення аптекаря",b="Вільям Пестл разом із братом тримає «Аптеку Пестла» в Торговому Кварталі Стормвінда. Коли вариш ліки, мазі й настої, такої сировини, як віск, завжди бракує. Замість купувати гарні свічки в міських торговців, Пестл помітив, що шкідники, які плюндрують Елвінн, носять на лобі напрочуд важкі грудки лою й воску — бери задарма, якщо знайдеться шукач пригод, готовий їх віддерти."},{t="Копальні Елвінну",b="Кобольди цілком заполонили і Копальню Фарґодіп на південь від Ґолдшира, і Яшмову копальню на північному сході. Ці сопучі підземні створіння цінують свої свічки понад усе: мерехтливе світло веде їх темними штольнями, поки вони риють у пошуках золота й блискучих дрібничок. Відбирати ці свічки означає не лише поповнити алхімічні запаси Пестла, а й потроху вибивати шкідників, що душать дорогоцінні рудні ділянки королівства."}},fp="14,393,20.450.0,19.454.0,44.223.0,36.205.0,41.253.0,22.204.0,52.216.0,56.187.0"}
P.entries["quest:6061"] = {n="Приборкання звіра",s="«Приборкання звіра» — основоположний обряд посвяти для молодих мисливців-тауренів у Селі Бладгуф. Під проводом наставника Ява Шарпмейна мисливець вирушає в Малгор, щоб приборкати дорослого довгоступа, і робить перший крок до духовного зв'язку зі створіннями Земної Матері.",h="«Приборкання звіра» — основоположний обряд посвяти для молодих мисливців-тауренів у Селі Бладгуф.",kw={"приборкання","довгоступ","мисливець","яв шарпмейн","село бладгуф","малгор","звір-супутник"},ang={["class:Hunter"]="Цей обряд знаменує перехід від недосвідченого слідопита до справжнього повелителя звірів і вчить вас спілкуватися з тваринами під проводом Земної Матері.",["race:Tauren"]="Приборкання звіра — прадавній звичай, осердя кочового мисливського спадку Малгору, що зміцнює зв'язок між мисливцем і природою."},sec={{t="Священний зв'язок із дикою природою",b="Для тауренів полювання ніколи не зводилося до вбивства звірів заради м'яса й шкур. Прадавні перекази кажуть: здолавши дику звірину Малгору й поєднавшись із нею, мисливець вбирає її дух і наближається до Земної Матері. Приборкання звіра-супутника підносить цей зв'язок ще вище: той, хто міг стати супротивником, обертається на довічного партнера, суголосного з природною рівновагою рівнин."},{t="Перше випробування",b="Яв Шарпмейн починає навчання посвяченого не з лютих верховних хижаків, а зі швидких і сторожких довгоступів, що блукають травами Малгору. Озброєний зачарованим жезлом приборкання, мисливець має стати віч-на-віч із дорослим довгоступом, угамувати його дикі інстинкти й заслужити довіру. Це перше випробування доводить рішучість мисливця й готує його до вибагливіших звірів, які чекають попереду."}},fp="16,289,27.405.0,14.390.0,34.268.0,48.125.0,45.233.0,52.239.0,39.118.0,28.198.0"}
P.entries["quest:6062"] = {n="Приборкання звіра",s="Це випробування — перший крок молодого мисливця Орди в мистецтві приборкання звірів. Під проводом ветерана Тотара в Гострому Пагорбі майбутні мисливці за допомогою зачарованого жезла приборкання впокорюють лютого плямистого вепра й пов'язують його з собою.",h="Це випробування — перший крок молодого мисливця Орди в мистецтві приборкання звірів.",kw={"мисливець","тотар","приборкання","вепр","гострий пагорб","улюбленець"},ang={["class:Hunter"]="Цей обряд посвяти — міст між простим стрільцем і справжнім володарем звірів: він відкриває визначальний для мисливця зв'язок зі звіриними супутниками.",["race:Orc"]="Для орків влада над звіром — відображення сили волі й панування над суворою дикою землею їхнього нового дому в Дуротарі.",["race:Troll"]="Мисливці Темного Списа через це навчання налаштовують свій дух на сувору дику природу Калімдору, продовжуючи свої давні традиції вистежування."},sec={{t="Обряд посвяти мисливця",b="Для мисливців-орків і тролів Темного Списа, що зростають у Дуротарі, вижити самотою в дикій природі — лише половина справи. Справжній мисливець, володар дикої землі, має навчитися підкоряти своїй волі саму природу, перетворюючи ворожих звірів на вірних союзників. Наставник мисливців Тотар довіряє новачкам зачарований жезл приборкання й кидає їм виклик: стати віч-на-віч із лютим диким вепром, не вдаючись до смертоносної стріли."},{t="Вепри Дуротару",b="Люті плямисті вепри блукають посушливими чагарями довкола Гострого Пагорба. Хоч вони грубі й злі, їхня витривалість і лють роблять їх ідеальними для першого приборкання. Витримати їхні наскоки й стерпіти їхню агресію, водночас спрямовуючи силу жезла, — для цього потрібні терпіння й залізна рішучість, чесноти, без яких не обійтися жодному слідопитові Орди."}},fp="16,222,26.396.0,20.350.0,34.185.0,21.138.0,39.121.0,50.195.0,27.150.0,46.246.0"}
P.entries["quest:6063"] = {n="Приборкання звіра",s="Це завдання — перше випробування на шляху мисливця нічних ельфів до мистецтва звіриного товариства. За настановою Дазалара з Доланаара мисливець-початківець має зачарованим жезлом приборкання встановити зв'язок із диким павуком, що зветься Причаєнець Плетива Лісу. Воно перевіряє, чи здатен мисливець поважати природу й єднатися з нею, а не підкоряти її силою.",h="Це завдання — перше випробування на шляху мисливця нічних ельфів до мистецтва звіриного товариства.",kw={"приборкання звіра","мисливець","дазалар","причаєнець плетива лісу","жезл приборкання","доланаар"},ang={["class:Hunter"]="Цей обряд переходу знаменує перетворення мисливця з самотнього лучника на справжнього партнера дикої природи, пов'язаного з лісовими звірами.",["race:NightElf"]="Відображаючи філософію калдорей, приборкання звірів робить наголос на єднанні й шанобі до природи, а не на підкоренні й пануванні."},sec={{t="Священний зв'язок",b="Для калдорей полювання — не просто вистежування здобичі чи виживання в хащах; це священні стосунки з природою. Наставники мисливців, такі як Дазалар, навчають, що природа незмірно більша за будь-кого зі смертних. Тварини — не в'ючна худоба й не знаряддя, які можна силоміць зігнути під свою волю, а самостійні створіння, що потребують взаємної поваги. Щоб довести готовність до звіра-супутника на все життя, мисливці-новачки мають приборкати первісні інстинкти місцевої живності давніми прийомами, а не грубою силою."},{t="Перше випробування",b="Випробування починаються з велетенських павуків, що заполонили гілля Тельдрассила. Дазалар довіряє мисливцеві особливий жезл приборкання й велить розшукати Причаєнця Плетива Лісу. Заглибившись у тінисті хащі, мисливець має зустрітися з отруйним павуком і встановити з ним чуттєвий зв'язок, витримуючи його напади. Успішно наведений тимчасовий міст між розумами доводить, що мисливець здатен єднатися навіть із моторошними хижаками Світового Дерева, які шурхотять у темряві."}},fp="16,332,13.537.0,15.474.0,34.242.0,21.181.0,42.138.0,41.209.0,51.235.0,38.190.1"}
P.entries["quest:6064"] = {n="Приборкання звіра",s="«Приборкання звіра» — перше випробування на шляху дворфійського мисливця до володіння звірами-супутниками в Дун Мороґу. Під проводом Ґріфа Вайлдгарта з Хараноса юні слідопити вчаться втихомирити лютого Великого Скелястого Вепра й зріднитися з ним за допомогою зачарованого жезла приборкання.",h="«Приборкання звіра» — перше випробування на шляху дворфійського мисливця до володіння звірами-супутниками в...",kw={"приборкання","мисливець","вепр","вайлдгарт","жезл","харанос","звір"},ang={["class:Hunter"]="Це завдання — вирішальний поріг, за яким новачок-стрілець стає справжнім володарем звірів, і початок низки випробувань, що відкривають постійних тваринних супутників.",["race:Dwarf"]="Горяни Айронфорджа шанують звірів, здатних витримати пронизливий холод Дун Мороґу; починати з витривалого скелястого вепра — у дусі дворфійської поваги до впертості й стійкості."},sec={{t="Супутник мисливця",b="Доти дворфійські горяни й слідопити покладалися лише на стрілецьку майстерність, пастки та чуття дикої природи. Та справжня душа мисливця — у довічному партнерстві з диким звіром. Ґріф Вайлдгарт, що стоїть біля Ґуральні Тандербрю в Хараносі, наглядає за цим обрядом переходу. Замість вимагати, щоб новачок назавжди прив'язав до себе першого-ліпшого звіра, Ґріф велить йому випробувати терпіння й рішучість на кількох тутешніх видах Дун Мороґу."},{t="Скелястий Вепр",b="Перше випробування зводить слідопита з Великим Скелястим Вепром — одним із витривалих товстошкурих кабанів, що блукають засніженими передгір'ями Дун Мороґу. Укриті щетинистим хутром і жорсткою плоттю, ці звірі вперті й агресивні, тож ідеально підходять для першого випробування волі. Жезлом Приборкання, який дає Ґріф, мисливець має витримати натиск вепра і вгамувати його лють, доки той не скориться."}},fp="16,251,20.493.0,13.427.0,22.127.0,38.231.0,35.190.0,34.124.0,38.144.0,29.209.0"}
P.entries["quest:6065"] = {n="Шлях мисливця",s="«Шлях мисливця» — важлива віха для молодих мисливців-тауренів у Малгорі, що спрямовує їх до поглибленого навчання дружби зі звірами. Щойно новачки доведуть основи влучності й вистежування, місцеві наставники відсилають їх до Села Бладгуф по пораду до наставника мисливців Ява Шарпмейна. Ця подорож відкриває духовні та практичні випробування, потрібні, щоб приборкати дикого звіра й зріднитися з ним.",h="«Шлях мисливця» — важлива віха для молодих мисливців-тауренів у Малгорі, що спрямовує їх до поглибленого...",kw={"шлях мисливця","яв шарпмейн","село бладгуф","малгор","таурени","приборкання звірів","озеро кам'яного бика"},ang={["class:Hunter"]="Це завдання позначає мить, коли лучник чи стрілець стає справжнім повелителем звірів і робить перший крок до вірного бойового супутника.",["faction:Horde"]="Мисливці Орди значною мірою покладаються на лютих звірів прикордоння як на передових захисників і слідопитів у суворих нетрях Калімдору.",["race:Tauren"]="Для шу'хало вміння приборкувати диких звірів — духовне продовження їхньої шани до природи й творіння Земної Матері."},sec={{t="Обряд посвяти",b="Для кочових шу'хало полювання — священнодійство, а не розвага. Мисливець має розуміти рівновагу природи, шанувати духів рівнин і виявляти повагу до тварин, які годують племена. Коли молодий мисливець доводить, що вміє вижити в дикому краю й володіє луком чи рушницею, старійшини визнають: він готовий піти далі самотнього вистежування. Наказ розшукати досвідчених наставників позначає поріг справжньої зрілості в культурі тауренів."},{t="Дорога до Села Бладгуф",b="Шлях веде новачків через розлогі трави Малгору до Села Бладгуф — осередку громади, що притулився біля Озера Кам'яного Бика. Там чекає Яв Шарпмейн, бувалий ловець, який добре знає норов тутешньої звірини. Розмова з Шарпмейном — не проста формальність: вона засвідчує, що мисливець готовий до непростих випробувань приборкання звірів і до того, щоб учитися єднатися з хижаками, а не лише полювати на них."}},fp="17,421,17.483.0,29.455.0,41.243.0,28.201.0,21.207.0,41.250.0,68.203.0,52.228.0"}
P.entries["quest:6068"] = {n="Шлях мисливця",s="Шлях мисливця — обряд посвяти, що скеровує молодих мисливців-орків і тролів до Гострого Пагорба. Під проводом майстра-мисливця Тотара слідопити-початківці опановують життєво важливу науку — підкоряти диких хижаків своїй волі.",h="Шлях мисливця — обряд посвяти, що скеровує молодих мисливців-орків і тролів до Гострого Пагорба.",kw={"мисливець","тотар","шлях мисливця","гострий пагорб","приборкання","дуротар"},ang={["class:Hunter"]="Цей виклик — найважливіший поріг у вашій подорожі: від самотнього стрільця до справжнього володаря звірів.",["faction:Horde"]="Орда покладається на своїх розвідників і слідопитів, які приборкують тутешніх хижаків і перетворюють безжальну природу Дуротару на свою перевагу.",["race:Orc"]="Для орків союз із лютим супутником відлунює давніми традиціями, що сягають вовчих вершників Дренору.",["race:Troll"]="Мисливці Темного Списа вважають уміння приборкувати місцевих рапторів і вепрів необхідним, щоб закріпитися в підступних нетрях Дуротару."},sec={{t="Пробудження мисливця",b="Досі учень-мисливець у Дуротарі покладався лише на власний лук і кмітливість. Вистежування здобичі серед каньйонів червоної глини й суворих чагарів навчає терпіння, та справжня майстерність в Орді вимагає зв'язку з неприборканою звіриною цього краю. Класові наставники бачать, коли учень досить виріс, щоб ступити на цю дорогу, і посилають його просто до Гострого Пагорба."},{t="Майстер у Гострому Пагорбі",b="У Гострому Пагорбі чекає Тотар — мисливець-ветеран, що глибоко знає дику мудрість Дуротару. Тотар — той наставник, який навчає новачків небезпечного ритуалу: впокорити лютих звірів, не зламавши їхнього духу. Зустріч із ним — перший крок до того, щоб ходити дикими землями з вірним супутником поруч."}},fp="17,222,20.376.0,24.320.0,41.131.0,14.145.0,46.220.0,42.159.0,39.141.0,36.131.0"}
P.entries["quest:6074"] = {n="Шлях мисливця",s="«Шлях мисливця» — обряд переходу для дворфійських мисливців-новачків по всьому Дун Мороґу, щойно вони опанують основи вистежування та стрільби. Місцеві наставники посилають учнів до Ґріфа Вайлдгарта в Харанос, щоб ті почали вчитися мистецтва приборкання диких звірів як постійних супутників.",h="«Шлях мисливця» — обряд переходу для дворфійських мисливців-новачків по всьому Дун Мороґу, щойно вони...",kw={"мисливець","шлях","вайлдгарт","харанос","приборкання","звір","наставник"},ang={["class:Hunter"]="Це завдання знаменує вирішальний перехід від самотнього слідопита до справжнього володаря звірів, здатного керувати дикими хижаками.",["race:Dwarf"]="Дворфійські горяни здавна тримають ведмедів і вепрів як надійних розвідницьких супутників на засніжених вершинах Дун Мороґу."},sec={{t="Справжнє покликання мисливця",b="Доки мисливець не опанує мистецтво єднання зі звіром, він ходить засніженими скелями Дун Мороґу сам, покладаючись лише на сокиру, рушницю чи лук. Наставники, як-от Олмін Бернінґбірд і Трістан Шедоустоун, пильно стежать за учнями, доки ті не виявлять витримки, потрібної, щоб зустріти дикого звіра й не вбити його. Щойно новачок доводить достатню дисципліну, його посилають гірськими дорогами до Хараноса."},{t="Прибути до Ґріфа Вайлдгарта",b="У Хараносі Ґріф Вайлдгарт наглядає за останніми випробуваннями дворфійського мисливства. Приборкати звіра вважають значно складнішим, ніж убити його заради м'яса чи шкури: це потребує терпіння, фізичної витривалості й чуттєвого зв'язку з дикими хижаками гір. Вайлдгарт — брама до цих випробувань, що готує мисливця до виснажливої перевірки сили волі проти найлютішої звірини Дун Мороґу."}},fp="17,296,23.404.0,27.430.0,34.124.0,26.164.0,32.114.0,45.184.0,47.153.0,40.129.0"}
P.entries["quest:6081"] = {n="Навчання звіра",s="Навчання звіра — завершальний обряд посвяти для молодих мисливців-орків і тролів у Дуротарі. Довівши владу над дикими звірами рівнин, мисливці вирушають із Гострого Пагорба до Оргріммару вчитися в майстра-мисливця Ормака Ґрімшота. Ця подорож навчає новачка доглядати, годувати й відточувати вміння звіриного супутника на все життя.",h="Навчання звіра — завершальний обряд посвяти для молодих мисливців-орків і тролів у Дуротарі.",kw={"мисливець","ормак ґрімшот","оргріммар","долина честі","улюбленець","навчання звіра"},ang={["class:Hunter"]="Це завдання — мить, коли ваш улюбленець стає постійним, надійним союзником, а не скороминущим прикликанням: воно відкриває необхідні вміння «Годування улюбленця» й «Оживлення улюбленця».",["faction:Horde"]="Орда покладається на своїх розвідників і звірів, щоб берегти крихкі кордони Дуротару й Пусток від набігів кентаврів, шипогривів та Альянсу.",["race:Orc"]="Орки вважають зв'язок із мисливським супутником справою воїнської честі й обов'язку — союзом, що гартується в боях на суворих рубежах Дуротару.",["race:Troll"]="Для тролів Темного Списа, що облаштовують новий дім у Калімдорі, уміння порозумітися з дикими створіннями Дуротару життєво важливе для розвідки й виживання на незнайомій землі."},sec={{t="Подорож за межі дикої землі",b="У посушливих каньйонах Дуротару опанувати лук і вистояти проти суворої природи — лише половина обов'язку мисливця. Довівши свою стійкість приборканням лютих вепрів Дуротару, прибійних крабів і броньованих скорпідів, молоді мисливці готові до справжньої відповідальності — опіки над звіром. Тотар, що стоїть у Гострому Пагорбі, посилає їх на північ через яри червоної глини просто до укріплених воріт Оргріммару."},{t="Долина Честі",b="У велелюдній столиці майбутні майстри-слідопити мають розшукати Долину Честі — осередок, де войовничі душі й досвідчені слідопити відточують своє ремесло. Там живе Ормак Ґрімшот, один із найшанованіших майстрів-мисливців Орди. Ормак дивиться крізь зелену юність, щоб побачити, чи має мисливець терпіння не лише командувати звіром, а й підтримувати та плекати його крізь голод, битви та втрати."},{t="Зв'язок із дикою природою",b="Звір, здобутий силою волі, лишається диким, доки між мисливцем і супутником не постане порозуміння. Ормак передає священні традиції, потрібні, щоб берегти цей зв'язок: знання про те, яка їжа живить дух кожної істоти, дисципліну, щоб навчити їх смертоносних прийомів, і духовну зосередженість, щоб оживити полеглого звіра, якщо він впаде, виконуючи обов'язок."}},fp="18,382,31.428.0,19.411.0,21.391.0,40.164.0,32.156.0,42.174.0,62.190.0,48.167.0,60.188.0"}
